def reparse_tag_str(tag):
    """A reparse tag in TEXT output (K14, K16; 1.14.0): the tag word first, padded to its 32 bits, then its name --
    `0xa000000c (IO_REPARSE_TAG_SYMLINK)`; the hex alone for a tag with no name."""
    name = REPARSE_TAGS.get(tag)
    return f"0x{tag:08x} ({name})" if name else f"0x{tag:08x}"


def reparse_tag_name(tag):
    """A reparse tag in a machine field (K14): its name, or the tag word in hex (`0x%08x`) when it has none."""
    return REPARSE_TAGS.get(tag) or f"0x{tag:08x}"

# ─── Helpers ──────────────────────────────────────────────────────────
# ─── One form per kind of value (1.14.0, decisions 35 and 38; CONSISTENCY_CHOICES K1-K29) ────────────────────────────
# Every output of both tools writes a value of one kind through ONE function of this block (refsanalysis imports them),
# so a value reads the same in every command and every format. The rule sheet: E2a_NOTES section 0 (the release's
# reports); the forms: text `0x2874`, `2026-05-16T16:55:20.9805996Z`, `4 KiB`; CSV/JSON the same strings, integers for
# counts and byte sizes, null (JSON) / an empty cell (CSV) for a value that is absent.
_FT_EPOCH_1601 = datetime.datetime(1601, 1, 1)


def ft_iso(ft):
    """B10 / K5: THE FILETIME converter of both tools. A FILETIME (100 ns ticks since 1601-01-01, UTC) as
    `2026-05-16T16:55:20.9805996Z`: all seven digits of the fraction, UTC, ISO 8601, so it sorts as text. None when the
    field holds no time (0, or all ones). Past 9999-12-31, which no calendar form can hold, the raw value `0x%016x`: a
    value the volume holds is never dropped. Counted from the 1601 epoch, so a time before 1970 renders on every
    platform (Windows' `fromtimestamp` refuses one)."""
    if not ft or ft >= 0xFFFFFFFFFFFFFFFF:
        return None
    try:
        dt = _FT_EPOCH_1601 + datetime.timedelta(seconds=ft // 10 ** 7)
    except OverflowError:
        return "0x%016x" % ft
    return dt.strftime("%Y-%m-%dT%H:%M:%S") + ".%07dZ" % (ft % 10 ** 7)


def ft_text(ft):
    """A FILETIME in TEXT output: `ft_iso`'s form, `(none)` when the field holds no time (K20)."""
    return ft_iso(ft) or "(none)"


def filetime_to_iso(ft):
    """A FILETIME in a CSV cell: `ft_iso`'s form, '' when the field holds no time (K20)."""
    return ft_iso(ft) or ""


def now_iso():
    """The run's own clock (a manifest's or a log's time) in the one date-time form (K5): the host's UTC time to the
    microsecond, so the seventh digit is 0."""
    t = datetime.datetime.now(datetime.timezone.utc)
    return t.strftime("%Y-%m-%dT%H:%M:%S") + ".%07dZ" % (t.microsecond * 10)


def hexid(v):
    """K1 / K9 / K10 / K14 (decisions 35, 38): an identifier, an LCN or VCN, a byte offset or a flag word in hex,
    lower case, unpadded -- `0x2874` -- in every output, JSON included (a string there). None stays None (absent)."""
    return None if v is None else "0x%x" % v


def security_id_text(sid):
    """K3: a SecurityId in TEXT output, the hex then the decimal reading aid: `0x103 (259)`; `(none)` for 0."""
    return "0x%x (%d)" % (sid, sid) if sid else "(none)"


def csv_bool(v):
    """K19: a boolean in a CSV cell: `true` / `false`, as JSON writes it."""
    return "true" if v else "false"


def csv_list_cell(names):
    """K25 + E-4 (1.14.0): a list of names in ONE CSV cell, joined with ';'. A ';' inside a name is written `\\;` and a
    backslash `\\\\`, so the cell splits back into the same names (a stream named `a;b` is legal). JSON carries the list
    itself."""
    return ";".join(n.replace("\\", "\\\\").replace(";", "\\;") for n in (names or []))


def flag_names(v, table):
    """K14: the names of the bits of flag word `v` from `table` ({bit: name}), '|'-joined, in the table's order; a set
    bit the table does not name is written as its hex among them (`Archive|0x80000`), so no bit is dropped. '' for 0."""
    names = [n for b, n in table.items() if v & b]
    rest = v
    for b in table:
        rest &= ~b
    if rest:
        names.append("0x%x" % rest)
    return "|".join(names)


def flag_text(v, table):
    """K14 / E-3: a flag word in TEXT output, the hex first and the names in parentheses: `0x20 (Archive|Directory)`;
    `0x0 (none set)` when no bit is set."""
    if not v:
        return "0x0 (none set)"
    n = flag_names(v, table)
    return "0x%x (%s)" % (v, n) if n != "0x%x" % v else "0x%x" % v


def flag_cells(v, table):
    """K14 A (Q-A answered A1, 1.14.0): a flag word in a CSV / JSON output is two fields, (names, hex): the names
    (`flag_names`; `0x0` when the word was read and no bit is set) and the word in hex (`0x20`). ('', '') when no word
    was read (None)."""
    if v is None:
        return "", ""
    return flag_names(v, table) or "0x0", "0x%x" % v


def reparse_tag_cells(tag):
    """K14 A (Q-A answered A1, 1.14.0): a reparse tag in a CSV / JSON output is two fields, (name, hex `0x%08x`); the
    name of a tag with none is its hex (`reparse_tag_name`). ('', '') when the object carries no tag (0 or None)."""
    if not tag:
        return "", ""
    return reparse_tag_name(tag), "0x%08x" % tag


def filetime_to_unix(ft):
    if ft == 0 or ft >= 0xFFFFFFFFFFFFFFFF:
        return 0
    try:
        # integer // (not float /) — float division rounds up at ~0.9999999 s, giving a Unix second
        # 1 too high; filetime_to_iso already uses //. (fix 2026-06-20)
        return (ft - 116444736000000000) // 10000000
    except (ValueError, OverflowError) as _e:
        _skip_note("FILETIME conversion", f"raw 0x{ft:x}", _e)
        return 0

# ── Timestamp-anomaly (timestomp) detection ────────────────────────────────
# A FILETIME tick is 100 ns; one day = 24*3600*1e7 ticks. The default margin
# tolerates normal close-in-time metadata ops while catching the year-scale
# back-dating that timestomping produces.
TS_MARGIN_100NS = 24 * 3600 * 10**7  # 1 day

def _ft_valid(ft):
    return 0 < ft < 0xFFFFFFFFFFFFFFFF

def timestomp_intrinsic_flags(create, modify, change, access,
                              vol_create=0, margin=TS_MARGIN_100NS):
    """Intrinsic ($SI-only) timestamp-anomaly indicators for one file.

    Returns a list of short flag strings. These are SUGGESTIVE, not proof. The
    metadata-change time ($SI+0x10) is an ordinary timestamp, but the high-level
    APIs timestomp tools usually use (Win32 SetFileTime, PowerShell, .NET) expose
    only Creation/Write/Access — NOT the change time — so after such a stomp the FS
    leaves the change time at the real write moment while B/M/A are back-dated:
    `change >> max(create, modify)` (CHANGE_LATE) is the tell. This is a heuristic
    against common tooling, NOT tamper-proof: the change time CAN be set via the
    native NtSetInformationFile(FILE_BASIC_INFORMATION.ChangeTime) or a raw-disk
    edit, which defeats CHANGE_LATE. Also trips on a creation-time-preserving copy
    (robocopy /COPY:T, restore) or a legitimate late rename/ACL change on an aged
    file. Corroborate with the USN journal (`timestomp` reads it).

    B4 (1.14.0, PLAN section 7.4): no signal compares Created with the volume's modify time ($VOLUME_INFORMATION
    +0xa0, updated on mount): 1.13.1's FUTURE called that field "the volume's last metadata write" (K080), which it is
    not, and tiered a file created after it MEDIUM. Reinstating such a signal needs a verified reference (F6)."""
    flags = []
    if not _ft_valid(create):
        return flags
    base = max(create, modify) if _ft_valid(modify) else create
    if _ft_valid(change) and change > base + margin:
        flags.append("CHANGE_LATE")        # metadata-change time post-dates created/modified
    if _ft_valid(modify) and create > modify + margin:
        flags.append("CREATE_GT_MODIFY")   # created after last write
    if _ft_valid(vol_create) and create < vol_create - margin:
        flags.append("PRE_FORMAT")         # created before the volume existed
    return flags

# ─── timestomp verdict — ONE source for both surfaces ────────────────────────
# HISTORY, kept because it explains why this function exists at all. The `files` TimestompFlags column
# (removed in v1.11.0) and the `timestomp` command each computed their own tier. They disagreed on
# 40-55 % of flagged files (101/184, 62/151, 50/114 on three volumes): the column called
# CHANGE_LATE|PRE_FORMAT "MEDIUM", the command called it "HIGH — two independent intrinsic signals".
#
# Measured over the full corpus -- 96 images / 521,060 files -- the command's premise is false. The two are
# NOT independent:
#
#     PRE_FORMAT        22.67 % of all files   (created before the volume existed)
#     CHANGE_LATE       22.32 %                (change time post-dates create/modify)
#     CREATE_GT_MODIFY   1.04 %
#     HARDLINK_MACB_MISMATCH 0.04 %
#
#     CHANGE_LATE together with PRE_FORMAT : 115,936
#     CHANGE_LATE WITHOUT PRE_FORMAT       :     384  (0.33 %, all on one real Windows volume)
#
# A program that writes a file with older create/modify times and leaves the change time to the file system --
# Windows servicing and application updates extracting files with their package dates (MD_TS_RA_011), an
# installer -- gives create/modify before this volume existed and the change time of the write. That fires BOTH
# signals, which is why they seldom appear apart. (A copy instead keeps its source's change time,
# MD_TS_RA_010.) They are two halves of ONE event, not corroborating
# evidence, and tiering their co-occurrence HIGH marks 12 % of an ordinary volume as tampered.
#
# But the pair does NOT identify that event as legitimate. Deliberately backdating a creation time produces the
# same two signals, and a lab volume whose generator log records 74 SetCreationTimeUtc calls carries exactly
# this signature -- so "INFO = legitimate" asserts a cause the bytes cannot establish. INFO means AMBIGUOUS:
# one event that a legitimate time-setting and a backdated creation both produce, to be separated by the journal, not by the
# timestamps. It is a lowered tier, never an exoneration. What DOES survive as evidence is
# CHANGE_LATE *without* PRE_FORMAT -- born on this volume, metadata altered afterwards, which a copy cannot
# produce -- plus the ReFS-specific per-name HARDLINK_MACB_MISMATCH and journal corroboration. (A 27-image
# subset showed 0 of that residual and an earlier draft called the rule witness-less; the full corpus has
# 384, so measure on everything before describing a cohort as empty.)
TIMESTOMP_TIERS = ("HIGH", "MEDIUM", "LOW", "INFO", "NONE")
_TS_COPY_SIGNATURE = {"PRE_FORMAT", "CHANGE_LATE", "CREATE_GT_MODIFY", "ROUND_TIMESTAMPS"}


def timestomp_verdict(flags, usn_conf=False, hl_conf=False, round_ts=False):
    """(tier, signals) for one file. The ONLY place a timestomp tier is decided.

    `flags`    intrinsic signals from timestomp_intrinsic_flags(), plus any USN_* the caller established.
    `usn_conf` the change journal corroborates (authoritative, independent source).
    `hl_conf`  two of the file's hard-link names disagree on Created (structural, journal-independent).
               Which name is authentic is NOT established -- see the F6 note below.
    `round_ts` whole-second Created AND Modified -- a weak hint that never lifts a tier on its own.

    A caller with less evidence gets a tier no HIGHER than one with more: the column passes usn_conf=False
    because the walk does not read the journal, so its verdict is the command's minus journal corroboration.
    """
    sig = list(flags)
    if round_ts and "ROUND_TIMESTAMPS" not in sig:
        sig.append("ROUND_TIMESTAMPS")
    if hl_conf and "HARDLINK_MACB_MISMATCH" not in sig:
        sig.append("HARDLINK_MACB_MISMATCH")
    has = set(sig)
    if not has:
        return "NONE", sig
    if hl_conf or "HARDLINK_MACB_MISMATCH" in has:
        return "HIGH", sig                      # ReFS-only, journal-independent
    if usn_conf:
        return "HIGH", sig                      # the journal is an independent source
    if "CHANGE_LATE" in has and "PRE_FORMAT" not in has:
        return "MEDIUM", sig                    # created on THIS volume, metadata altered later
    if has <= _TS_COPY_SIGNATURE:
        return "INFO", sig                      # ambiguous: a copy AND a backdate both produce this
    return "LOW", sig


def attrs_to_str(attrs, full=True, hex_if_empty=False):
    """Render file-attribute bits as 'Flag|Flag'. full=False uses the short subset.
    hex_if_empty=True renders no-flags as '0x..' (refsanalysis behaviour); the forefst
    default renders no-flags as '' (unchanged)."""
    table = FILE_ATTR_FLAGS if full else FILE_ATTR_SIMPLE
    flags = [name for bit, name in table.items() if attrs & bit]
    if flags:
        return "|".join(flags)
    return f"0x{attrs:x}" if hex_if_empty else ""

def attrs_to_mode(attrs, is_dir):
    """The bodyfile's mode field in The Sleuth Kit's form (N167, 1.14.0): the name type, '/', the meta type and the
    permissions -- `r/rrwxrwxrwx` for a file, `d/drwxrwxrwx` for a directory, `l/lrwxrwxrwx` for a reparse point; the
    read-only attribute (0x1) clears the write bits (`r/r-xr-xr-x`), as TSK writes it for NTFS. (The type letter was
    `-`, and read-only replaced it, so mactime-style readers saw a file of no type.)"""
    t = "d" if is_dir else ("l" if attrs & 0x400 else "r")
    perm = "r-xr-xr-x" if attrs & 0x01 else "rwxrwxrwx"
    return f"{t}/{t}{perm}"

def parse_sid(data, offset):
    """Parse a SECURITY_DESCRIPTOR SID at offset -> (sid_string, sid_len). On a
    malformed/truncated SID returns the sentinel '(invalid)'/'(truncated)' (single
    canonical behaviour; refsanalysis imports this)."""
    if offset + 8 > len(data): return "(invalid)", 0
    revision = data[offset]
    sub_count = data[offset + 1]
    # A structurally valid SID has revision == 1 (SID_REVISION) and <= 15 sub-authorities
    # (SID_MAX_SUB_AUTHORITIES). Reject impossible values so a corrupt SD can't emit a fake
    # 'S-88-...' into the OwnerSid column (review E13). reference_table FS_SECD_RA_001: all SDs revision=1.
    if revision != 1 or sub_count > 15: return "(invalid)", 0
    authority = int.from_bytes(data[offset+2:offset+8], "big")
    sid_len = 8 + sub_count * 4
    if offset + sid_len > len(data): return "(truncated)", sid_len
    subs = [le32(data, offset + 8 + i * 4) for i in range(sub_count)]
    return f"S-{revision}-{authority}" + "".join(f"-{s}" for s in subs), sid_len

def sid_name(sid_str):
    """Friendly NAME for a SID (name only; callers append ' (SID)'). '' = unknown
    (callers then show the raw SID). Domain RIDs keep the RID for non-builtin users."""
    if sid_str in WELL_KNOWN_SIDS:
        return WELL_KNOWN_SIDS[sid_str]
    if sid_str.startswith("S-1-5-21-"):
        rid = sid_str.rsplit("-", 1)[-1]
        try:
            rid_int = int(rid)
            if rid_int == 500: return "Administrator"
            if rid_int == 501: return "Guest"
            if rid_int == 512: return "Domain Admins"
            if rid_int == 513: return "Domain Users"
            if rid_int == 514: return "Domain Guests"
            return f"DomainUser (RID={rid_int})"
        except ValueError: pass
        return "DomainUser"
    return ""

def ext_from_name(name):
    if "." in name:
        e = name.rsplit(".", 1)[-1]
        if len(e) <= 10: return f".{e}"
    return ""

# ─── GPT + VBR + SUPB + CHKP ─────────────────────────────────────────

# ─── N344: the boot sector the volume is read from (wave C, Q19-Q21; decision 36 Q3 A) ───────────────
# refs.sys tests a boot sector with `RefsIsBootSectorOurs` (WAVEC_READING_bounds V4: read on 17134, 26100.8115, .8521,
# .8972, .9444, .9549 and Insider 29574, and earlier by FS_VBR_SA_013 -- twice) and reads the backup copy only when the
# READ of sector 0 fails (K1-K2, twice): a sector 0 that reads but fails a test is not mounted. This tool reads such a
# volume anyway: from a backup boot sector that passes the same tests and whose own length ends at it, found at a
# bounded set of positions (Q20), and says so (exit 2 in every command). `boot_sector_copy` is the one place that
# decides which copy that is; every reader of the boot-sector fields takes the copy it returns.
_MIB64 = 64 << 20
_BOOT_SECTOR_SPC = (1, 4, 8, 16, 32, 64, 128, 256, 512)
# the `_finding` kind of N344's statements (a volume read from a backup boot sector, or from a primary that fails a test)
_BOOT_SECTOR_FINDING = "boot sector copy"


def oem_id_text(bs):
    """N142 (Q23; single_source.tsv row `oem_id_text`): THE quoted form of a boot sector's 8-byte OEM id, bytes 3..10 --
    printable ASCII as it is, any other byte as \\xNN, so no control byte reaches the examiner. 1.13.1 quoted bytes
    3..14: on an NTFS boot sector the id 'NTFS    ' and then a NUL and the bytes 0x02 0x08 (the first bytes of its
    bytes-per-sector and sectors-per-cluster fields)."""
    return "".join(chr(c) if 0x20 <= c < 0x7F else "\\x%02x" % c for c in bytes(bs[3:11]))


def boot_sector_checksum(bs):
    """C2-6 (1.14.0, the conformance batch): (stored u16 +0x16, computed) of ONE boot-sector copy -- the checksum
    `boot_sector_failures` tests, over bytes 3..(+0x14)-1 skipping +0x16/+0x17, made over the copy's own length. `bs`
    is the copy as `_boot_copy_read` returns it (its first +0x14 bytes when +0x14 is above 512). `computed` is None when
    +0x14 is not a length it can be made over (88..len(bs)); `boot_sector_failures` names that copy's length. 1.13.1's
    redundancy scan and refsanalysis `boot` computed it over min(+0x14, 512) bytes -- a different sum for a copy whose
    +0x14 is above 512 (legal on a 4Kn device; refsanalysis raised IndexError there) -- while the test used +0x14."""
    if len(bs) < 0x18:
        return None, None
    n = le16(bs, 0x14)
    return le16(bs, 0x16), (_vbr_checksum(bs, n) if 0x57 < n <= len(bs) else None)


def boot_sector_failures(bs, ss, rounded):
    """N344 (Q19; single_source.tsv row `boot_sector_tests`): THE test of one boot-sector copy, both tools -- the
    `RefsIsBootSectorOurs` tests an image can answer, in the driver's order (WAVEC_READING_bounds V4): bytes 3..10 are
    `ReFS` and four zero bytes; 0x57 < u16 +0x14 <= ss; the ROR1+ADD checksum over bytes 3..(+0x14)-1 (skipping +0x16,
    +0x17) equals u16 +0x16, tested only over a valid +0x14; 0x200 <= u32 +0x20 <= 0x1000; u32 +0x24 is one of 1, 4, 8,
    ..., 512; 0 < u64 +0x18 <= the partition length in ss-byte sectors rounded down to 64 MiB. Returns [(test, text)],
    empty when the copy passes.

    `ss`: the GPT's LBA size where a GPT entry starts at the partition start, else the copy's own +0x20 (512 when that
    is out of range). `rounded`: None where no GPT entry records the partition length -- the total-sectors test is
    then made for 0 only (S-D: a raw image's length is not its partition's; an image that ends before the volume is
    B3's truncation, not a damaged boot sector). Not made: the device tests (sector size above 0xff; the physical
    sector size against +0x24 x ss), which need the device. The version is not tested here: `RefsMountVolume` tests it
    after this function (V3), and `version_findings` reports it. `bs` must hold +0x14 bytes when +0x14 is above 512."""
    if not any(bs[:512]):
        return [("zero", "it is all zeros" if len(bs) >= 512 else "the image ends inside it")]
    if len(bs) < 512:
        return [("read", "the image ends inside it (%d of 512 bytes read)" % len(bs))]
    out = []
    if bs[3:11] != b"ReFS\x00\x00\x00\x00":
        out.append(("oem", "its OEM id (bytes 3..10) is '%s', not 'ReFS' followed by four zero bytes" % oem_id_text(bs)))
    n = le16(bs, 0x14)
    if not (0x57 < n <= ss) or n > len(bs):
        out.append(("length", "its checksummed length (+0x14), %d bytes, is not in 88..%d" % (n, ss)))
    else:
        stored, computed = le16(bs, 0x16), _vbr_checksum(bs, n)
        if stored != computed:
            out.append(("checksum", "it fails its checksum: stored 0x%04x, computed 0x%04x" % (stored, computed)))
    bps = le32(bs, 0x20)
    if not (0x200 <= bps <= 0x1000):
        out.append(("bytes_per_sector", "its bytes per sector (+0x20), %d, is not in 512..4096" % bps))
    spc = le32(bs, 0x24)
    if spc not in _BOOT_SECTOR_SPC:
        out.append(("sectors_per_cluster", "its sectors per cluster (+0x24), %d, is not one of 1, 4, 8, 16, 32, 64, "
                                           "128, 256 or 512" % spc))
    t = le64(bs, 0x18)
    if t == 0:
        out.append(("total_sectors", "its total sectors (+0x18) is 0"))
    elif rounded is not None and t > rounded:
        out.append(("total_sectors", "its total sectors (+0x18), %d, are more than the %d sectors of %d bytes its "
                                     "partition holds rounded down to 64 MiB" % (t, rounded, ss)))
    return out


def _boot_copy_read(f, off):
    """One boot-sector copy at `off`: its 512 bytes, and its first +0x14 bytes when +0x14 is above 512 (the checksum
    covers them; at most 4096). Raises OSError when the read fails."""
    b = _seek_read(f, off, 512)
    n = le16(b, 0x14) if len(b) >= 0x16 else 0
    if 512 < n <= 0x1000 and len(b) == 512:
        b = _seek_read(f, off, n)
    return b


def _boot_sector_geometry(f, ps):
    """The partition the boot sector at `ps` is tested against: {ss, P, rounded, entry, image_end}. A GPT entry that
    STARTS at ps (`gpt_partition_detail(start=ps)`) gives ss (its LBA size) and P (its length), and `rounded` = P in
    ss-byte sectors rounded down to 64 MiB; without one, ss is None (the search tries 512 and 4096), P is the image
    after ps and `rounded` None (S-D)."""
    image_end = None
    try:
        image_end = os.fstat(f.fileno()).st_size
    except (AttributeError, OSError, ValueError, io.UnsupportedOperation):
        try:
            image_end = f.seek(0, 2)
        except (AttributeError, OSError, ValueError):
            image_end = None
    path = getattr(f, "name", None)
    entry = gpt_partition_detail(path, start=ps) if isinstance(path, str) and os.path.isfile(path) else None
    if entry and entry.get("size_bytes") and entry.get("lba_size"):
        ss, p = entry["lba_size"], entry["size_bytes"]
        return {"ss": ss, "P": p, "rounded": (p // _MIB64) * (_MIB64 // ss), "entry": entry, "image_end": image_end}
    p = max(0, image_end - ps) if image_end is not None else None
    return {"ss": None, "P": p, "rounded": None, "entry": None, "image_end": image_end}


def _boot_sector_ss(geo, b):
    """The sector size a copy's +0x14 test takes: the GPT's LBA size, else the copy's own +0x20 when in range."""
    if geo["ss"]:
        return geo["ss"]
    bps = le32(b, 0x20) if len(b) >= 0x24 else 0
    return bps if 0x200 <= bps <= 0x1000 else 512


def _boot_sector_positions(ps, geo, prim):
    """Q20's positions, in order, as (offset, position): (1) the partition's end rounded down to 64 MiB, less one
    sector (ss from the GPT; without one 512, then 4096); (2) a readable primary's own last sector, ps + (T-1) x its
    bytes per sector; (3) every 64 MiB boundary below (1), top down to the partition start, 512 and 4096 bytes before
    it. Only positions inside the partition (the image after ps without a GPT entry), each once. A generator: the
    search stops at the first copy it accepts."""
    p, ss = geo["P"], geo["ss"]
    end = ps + p if p is not None else None
    seen = set()

    def take(off):
        if off > ps and (end is None or off + 512 <= end) and off not in seen:
            seen.add(off)
            return True
        return False
    top = p // _MIB64 if p else 0
    if top:
        for s in ((ss,) if ss else (512, 4096)):
            if take(ps + top * _MIB64 - s):
                yield ps + top * _MIB64 - s, 1
    if len(prim) >= 0x28:
        t, bps = le64(prim, 0x18), le32(prim, 0x20)
        if t > 1 and 0x200 <= bps <= 0x1000 and take(ps + (t - 1) * bps):
            yield ps + (t - 1) * bps, 2
    for k in range(top - 1, 0, -1):
        for s in (512, 4096):
            if take(ps + k * _MIB64 - s):
                yield ps + k * _MIB64 - s, 3


def _boot_sector_where(geo):
    """What position (1) is computed from: 'GPT partition #2', or 'the image' (counted from the partition start)."""
    e = geo.get("entry")
    return ("GPT partition #%d" % e["index"]) if e else "the image"


def _boot_sector_boundary(ps, off):
    """The 64 MiB boundary (an absolute offset) that a position 512 or 4096 bytes before it belongs to."""
    return (off - ps + 4096) // _MIB64 * _MIB64 + ps


def _boot_sector_how(ps, geo, off, pos, refused):
    """How the copy the volume is read from was found (Q20: the output says how)."""
    if pos == 1:
        how = "at the end of %s rounded down to 64 MiB%s, less %d bytes" % (
            _boot_sector_where(geo), "" if geo.get("entry") else " from the partition start",
            ps + (geo["P"] // _MIB64) * _MIB64 - off)
    elif pos == 2:
        how = "in the last sector of the volume the primary boot sector describes (its total sectors x bytes per sector)"
    else:
        b = _boot_sector_boundary(ps, off)
        how = ("by the search down the 64 MiB boundaries below the end of %s rounded down to 64 MiB: %d bytes before "
               "the boundary at offset 0x%x" % (_boot_sector_where(geo), b - off, b))
    for r_off, r_end in refused[:3]:
        how += ("; the copy at offset 0x%x passes every test, but its own last sector would be at offset 0x%x, so it "
                "is not used" % (r_off, r_end))
    return how


def _boot_sector_searched(ps, tried):
    """The range searched, from the positions tried: '(1) ..., (2) ... and 512 and 4096 bytes before each 64 MiB
    boundary from offset X down to offset Y'."""
    parts = ["offset 0x%x" % o for o, p in tried if p in (1, 2)]
    low = [o for o, p in tried if p == 3]
    if low:
        hi_b, lo_b = _boot_sector_boundary(ps, max(low)), _boot_sector_boundary(ps, min(low))
        parts.append("512 and 4096 bytes before each 64 MiB boundary from offset 0x%x down to offset 0x%x"
                     % (hi_b, lo_b))
    if not parts:
        return "no position: the partition is shorter than 64 MiB and the primary boot sector gives no volume length"
    return ", ".join(parts[:-1]) + (" and " if len(parts) > 1 else "") + parts[-1]


def _boot_sector_choose(f, ps, prim, perr):
    """`boot_sector_copy`'s decision (see there) for the primary bytes `prim` read at ps (`perr`: the read's error)."""
    geo = _boot_sector_geometry(f, ps)
    rec = {"ps": ps, "primary": prim, "primary_error": str(perr) if perr is not None else None, "geometry": geo,
           "bytes": None, "offset": None, "source": None, "position": None, "failures": [], "refused": [],
           "tried": [], "foreign": None, "text": None, "error": None, "backup_offset": None, "decoded": None}
    if perr is not None:
        rec["failures"] = [("read", "it cannot be read: %s" % perr)]
    else:
        rec["failures"] = boot_sector_failures(prim, _boot_sector_ss(geo, prim), geo["rounded"])
    if not rec["failures"]:
        rec.update(bytes=prim[:512], offset=ps, source="primary", backup_offset=_boot_sector_t_minus_1(prim, ps))
        return rec
    signed = prim[3:7] == b"ReFS"
    if perr is None and not signed:
        # Q23 / N142: a recognised foreign file system is refused as before (exit 1), with no search
        if b"NTFS" in prim[:16]:
            rec["foreign"] = "NTFS"
            rec["error"] = "partition contains NTFS, not ReFS (signature: '%s')" % oem_id_text(prim)
            return rec
        if b"-FVE-FS-" in prim[:16]:
            rec["foreign"] = "BitLocker"
            rec["error"] = "partition is BitLocker-encrypted (signature: -FVE-FS-)"
            return rec
    for off, pos in _boot_sector_positions(ps, geo, prim):
        rec["tried"].append((off, pos))
        try:
            b = _boot_copy_read(f, off)
        except OSError:
            continue
        if len(b) < 512 or b[3:7] != b"ReFS" or boot_sector_failures(b, _boot_sector_ss(geo, b), geo["rounded"]):
            continue
        own_end = ps + (le64(b, 0x18) - 1) * le32(b, 0x20)
        if own_end != off:                       # Q20: only a self-consistent copy
            rec["refused"].append((off, own_end))
            continue
        rec.update(bytes=b[:512], offset=off, source="backup", position=pos, backup_offset=off)
        break
    _what = ("cannot be read (%s)" % rec["failures"][0][1][len("it cannot be read: "):] if perr is not None
             else "is damaged (%s)" % "; ".join(t for _k, t in rec["failures"]))
    if rec["bytes"] is not None:
        # C2-2 (1.14.0): a backup can carry the version from before an upgrade (A113: the backup of each of the three
        # upgraded corpus volumes does), so the checkpoint tests that depend on the version are not made with it
        # (`_chkp_volume_version`); 1.13.2-dev called every copy with the indirect offset table rejected there
        rec["text"] = ("the primary boot sector at offset 0x%x %s; the volume was read from the backup boot sector "
                       "found at offset 0x%x (%s); refs.sys reads the backup boot sector only when reading sector 0 "
                       "fails; a backup boot sector can carry the version the volume had before an upgrade, so the "
                       "checkpoint tests that depend on the volume's version are not made with its version (%d.%d)"
                       % (ps, _what, rec["offset"], _boot_sector_how(ps, geo, rec["offset"], rec["position"],
                                                                     rec["refused"]), b[0x28], b[0x29]))
    elif perr is None and signed:
        # S-C (decision 26's rule at the boot sector): a signed primary is read when no backup passes, and said
        rec.update(bytes=prim[:512], offset=ps, source="primary", backup_offset=_boot_sector_t_minus_1(prim, ps))
        rec["text"] = ("the primary boot sector at offset 0x%x %s, and no backup boot sector that passes the same tests "
                       "was found (searched %s); the volume is read from the primary boot sector anyway"
                       % (ps, _what, _boot_sector_searched(ps, rec["tried"])))
    else:
        rec["error"] = ("the primary boot sector at offset 0x%x %s and no backup boot sector was found (searched %s)"
                        % (ps, _what, _boot_sector_searched(ps, rec["tried"])))
    return rec


def _boot_sector_t_minus_1(bs, ps):
    """The backup position the tools have always shown for a copy that is read: its own last sector, ps + (T-1) x
    `_vbr_bytes_per_sector` (A4), or None when it gives no length."""
    t = le64(bs, 0x18) if len(bs) >= 0x20 else 0
    return ps + (t - 1) * _vbr_bytes_per_sector(bs) if t > 1 else None


_BOOT_SECTOR_COPY = {}     # N344: (image path, partition start) -> the record boot_sector_copy returned for it
_BOOT_SECTOR_SAID = set()  # N344: (image path, partition start, statement) pairs this run has printed


def boot_sector_copy(f, ps, fresh=False):
    """N344 (wave C, Q19-Q21; decision 36 Q3 A; single_source.tsv row `boot_sector_copy`): THE boot sector the volume
    at `ps` is read from -- one decision for every reader of the boot-sector fields in both tools (`parse_vbr`, the
    volume length, the backup superblock slots, the redundancy scan, the summaries, integrity, the export, refsanalysis
    boot / supb / summary / chkp / containers).

      the primary passes every `boot_sector_failures` test   the primary (`text` None; 117 of 117 corpus volumes, MR-V)
      it fails one (or cannot be read)                       the first copy at Q20's positions (`_boot_sector_positions`)
                                                             that passes the same tests and whose own last sector is
                                                             where it was found; `text` = the statement (exit 2)
      no such copy, the primary signed                       the primary anyway (S-C), `text` says so (exit 2)
      no such copy, no signature                             `bytes` None; `error` names the range searched (exit 1)
      an NTFS or BitLocker boot sector                       `bytes` None, no search; `error` = the refusal (Q23)

    Keys: bytes (512), offset, source ('primary' / 'backup'), position (1-3), primary (the bytes at ps), failures
    [(test, text)], refused [(offset, own last sector)], text, error, backup_offset (the backup the tools show: the copy
    read when it is a backup, else the primary's own T-1), decoded (Q-M2, set by `bootstrap`). Cached per image and
    partition start while the primary's bytes are the same; `fresh` decides again (`parse_vbr`: every volume read
    starts there). An OffsetTooLarge at ps propagates (no copy can be read there either); another read error of the
    primary is K1's case: the search runs, and when it had no position to try, that error is raised again
    (`parse_vbr`, `boot_sector_bytes`). The file position is kept."""
    name = getattr(f, "name", None)
    key = (name, ps) if isinstance(name, str) else None    # the name the image was opened by (as _TRUNCATION_SAID)
    pos = None
    try:
        pos = f.tell()
    except (AttributeError, OSError, ValueError):
        pos = None
    try:
        try:
            prim, perr = _boot_copy_read(f, ps), None
        except OffsetTooLarge:
            raise
        except OSError as _e:
            prim, perr = b"", _e
        old = _BOOT_SECTOR_COPY.get(key) if key is not None else None
        if (not fresh and old is not None and old["primary"] == prim
                and old["primary_error"] == (str(perr) if perr is not None else None)):
            return old
        rec = _boot_sector_choose(f, ps, prim, perr)
        rec["key"], rec["primary_exc"] = key, perr
        if key is not None:
            _BOOT_SECTOR_COPY[key] = rec
        return rec
    finally:
        if pos is not None:
            try:
                _seek_read(f, pos, 0)        # back where the caller was (through the guard)
            except (OSError, ValueError):
                pass


def boot_sector_bytes(f, ps):
    """The 512 bytes of the boot sector the volume at ps is read from (`boot_sector_copy`). When there is no such copy
    (parse_vbr has refused such a volume before any command's reader runs; an in-process caller may still ask), the
    bytes read at ps, as before N344; the read's OSError when they could not be read."""
    rec = boot_sector_copy(f, ps)
    if rec["bytes"] is not None:
        return rec["bytes"]
    if rec.get("primary_exc") is not None:
        raise rec["primary_exc"]
    return rec["primary"][:512]


def _say_boot_sector_copy(rec):
    """N344: the statement of `rec` (a volume read from a backup boot sector, or from a primary that fails a test) on
    stderr once per run and image, and as a finding (exit 2 in every command, rc_escalate) once per run."""
    t = rec.get("text")
    if not t or rec.get("bytes") is None:
        return
    k = (rec.get("key"), t)
    if k not in _BOOT_SECTOR_SAID:
        _BOOT_SECTOR_SAID.add(k)
        print("[%s] WARNING: %s." % (PROG, t), file=sys.stderr)
    if t not in _findings(_BOOT_SECTOR_FINDING):
        _finding(_BOOT_SECTOR_FINDING, t)


def boot_sector_decode_version(rec, vmaj, vmin, chkp_flags, vol_info):
    """Q-M2 (PLAN_1.13.2 decision 43): the version the volume is DECODED as, (major, minor, reason). When the volume is
    read from a backup boot sector whose version is below 3.14 and both $VOLUME_INFORMATION (its volume stamp,
    +0x80/+0x81) and the checkpoint copy in use (flags 0x600 set) show 3.14, the version-dependent decoding (the MLog
    redo tables) uses 3.14 and `reason` says why; otherwise the boot sector's own version, reason None. The version
    printed stays the one recorded in the copy."""
    if (rec is None or rec.get("source") != "backup" or vmaj != 3 or vmin >= 14
            or (chkp_flags & 0x600) != 0x600 or not vol_info
            or (vol_info.get("vol_major"), vol_info.get("vol_minor")) != (3, 14)):
        return vmaj, vmin, None
    return 3, 14, ("the backup boot sector the volume is read from (offset 0x%x) records ReFS version %d.%d; "
                   "$VOLUME_INFORMATION (ReFS 3.14) and the checkpoint copy in use (flags 0x%x, 0x600 set) show 3.14, so "
                   "the version-dependent decoding (the MLog redo tables) uses ReFS 3.14: refs.sys writes a version "
                   "upgrade to sector 0 only, so a backup boot sector can keep an earlier version"
                   % (rec["offset"], vmaj, vmin, chkp_flags))


def vbr_cluster_size(bs, offset):
    """The cluster size a boot sector declares (bytes/sector x sectors/cluster), validated before any caller divides by
    it or seeks with it (audit 2.1: cs == 0 -> ZeroDivisionError in bootstrap; N383: refsanalysis `supb` took it
    unchecked and ended in a traceback or CPython's "cannot fit 'int'" text). Real ReFS clusters are a power of two
    (4096 or 65536); 0, a non-power-of-two or an absurd value raises ValueError, which every handler reports."""
    bps = le32(bs, 0x20)
    spc = le32(bs, 0x24)
    cs = bps * spc
    if cs <= 0 or cs > (2 << 20) or (cs & (cs - 1)):
        raise ValueError(
            f"implausible ReFS cluster size: {bps} B/sector x {count_noun(spc, 'sector')}/cluster = {cs} B "
            f"(expected a power of two such as 4096 or 65536). The VBR at offset 0x{offset:x} is damaged, or "
            f"this is not the partition start — check --partition-start, or run "
            f"`refsanalysis.py <image> bootedit repair --dry-run`.")
    return cs


def parse_vbr(f, ps):
    """The boot-sector fields the volume at ps is read with: (cluster size, major, minor, checksum type, bytes per
    container). N344 (wave C): from the copy `boot_sector_copy` chooses (the primary, or a backup when the primary
    fails a test, said and a finding); an NTFS / BitLocker boot sector, or no copy at all, raises ValueError (exit 1).

    N378 (4w): the guarded read (N371). A partition start no file can be read at -- a GPT entry's first LBA from the
    disk -- ended the run with CPython's "cannot fit 'int' into an offset-sized integer", naming no offset; it is now an
    OffsetTooLarge (OSError and ValueError, so every caller's handler reports it) that names the offset."""
    try:
        rec = boot_sector_copy(f, ps, fresh=True)
    except OffsetTooLarge:
        raise OffsetTooLarge("the partition start, offset 0x%x, is beyond the largest file offset (0x%x): no boot "
                             "sector can be read there" % (ps, _MAX_FILE_OFFSET))
    bs = rec["bytes"]
    if bs is None:
        if rec.get("primary_exc") is not None and not rec["tried"]:
            raise rec["primary_exc"]
        raise ValueError(rec["error"])
    _say_boot_sector_copy(rec)
    cs = vbr_cluster_size(bs, rec["offset"])
    vmaj = bs[0x28]
    vmin = bs[0x29]
    chk_algo = le16(bs, 0x2A)   # C6: VBR 0x2A is a u16 selector (vbr.md); low byte carries 0/2/4, 0x2B==0 on all corpus images
    bpc = vbr_container_size(bs)[0]
    # B3 (Q18): every command reads the boot sector here first (bootstrap; refsanalysis chkp and containers), so a
    # volume the image ends inside is said on stderr once per run, whatever the command reads afterwards
    _say_volume_truncation(f, ps, cs)
    return cs, vmaj, vmin, chk_algo, bpc


def vbr_container_size(bs):
    """(bytes per container, read_from_vbr). N153: VBR+0x40 holds the container size; `refsutil fixboot` writes
    0 there (one witness: step3c fixboottest; the same volume before fixboot holds 0x4000000). When the field is 0
    this tool computes with 64 MiB, the value the driver puts there: refs.sys 26100.8115 `RefsMountVolume`
    @14028d380 (decompilation :427410-427411; 26100.9549 :426735-426736) and 17134 `RefsMountVolume` @1c016bd38
    (:265780-265782, :265828-265829) store 0x4000000 at +0x40 of their copy of the boot sector when it holds 0,
    before `InitializeVcbFromBootSector` (which does not read +0x40, 26100.8115 :487415-487470); what reads the
    field after that was not traced, so nothing more is claimed. Every site that PRINTS the value says when it is
    the default and not the VBR's own (1.13.1 printed "Container size: 0x4000000 (64 MiB)" over a field that held 0
    -- the silent-default class); N354 (decision 29): the zero itself is a finding (`container_size_zero_text`)."""
    v = le64(bs, 0x40) if len(bs) >= 0x48 else 0
    return (v, True) if v else (0x4000000, False)


def container_size_zero_text(vbr_offset):
    """N354 (PLAN_1.13.2 decision 29): THE text of the finding "the boot sector's container size is 0" -- one
    definition, printed by forefst `summary`, `fastsummary` and `integrity` (through `_redundancy_findings`) and by
    refsanalysis `summary` and `boot --verify`, which exit 2 for it; every other command keeps its exit code. Worded
    neutrally (decision 29: never FAIL, corrupt or damaged): the value, what writes it, the default. The driver fact is
    the one `vbr_container_size` cites (read on 26100.8115/.9549 and 17134)."""
    return ("the boot sector (VBR) at offset 0x%x holds 0 as its container size (+0x40), the value `refsutil fixboot` "
            "writes there; when it mounts the volume, the refs.sys driver puts 64 MiB (0x4000000) in that field of its "
            "copy of the boot sector (as read in builds 26100 and 17134), and this tool computes with 64 MiB too"
            % vbr_offset)


# N153: what a container size taken from the driver's default is called -- the JSON key `container_size_from`
# carries the long form, every printed container-size line the short one.
CONTAINER_SIZE_DEFAULT_NOTE = "driver default (VBR+0x40 is zero): 64 MiB, not a value read from the volume"
CONTAINER_SIZE_DEFAULT_TAG = ", default (VBR+0x40 is zero)"


def root_table_counts(f, ps, cs, tr, roots, stage):
    """Row count of each of the (up to 13) global root tables: ({index: count or None}, {unreadable indices}).

    B3/K044: a root whose walk RAISES, or whose pages could not be read (the walk records them in _WALK_DAMAGE),
    is not a root with 0 rows; its count is None ("unreadable") and the failure is recorded, so no fabricated
    census is reported. One definition for forefst `summary`/`fastsummary` and refsanalysis `summary` (A3: the
    latter substituted 0 for an exception and never read the damage register, VOL-11). E3: the real-addressed
    roots are {7, 8, 12} (_CT_ROOT_INDICES) -- read without translation."""
    counts, unreadable = {}, set()
    for idx in range(min(13, len(roots))):
        vlcns = roots[idx]
        if not vlcns:
            counts[idx] = 0                                  # genuinely no root: 0 is the truth
            continue
        use_tr = None if idx in _CT_ROOT_INDICES else tr
        counts[idx], _bad = table_row_count(lambda: walk_bplus(f, ps, cs, use_tr, vlcns), "%s: root table" % stage,
                                            "index %d" % idx)
        if _bad:
            unreadable.add(idx)
    return counts, unreadable


def table_row_count(walk, stage, where):
    """THE row count of one table walk, in A3's convention (N338; `root_table_counts` uses it for every root, both
    summaries for the security, reparse-index and trash tables): (count, unreadable).

      the walk RAISED                         (None, True)   -- the skip is recorded (`_skip_note(stage, where, e)`)
      the walk recorded pages it could not   (rows read, True) -- a partial count, not a census
      read (`_walk_note_damage`)
      otherwise                               (rows, False)

    Whether the walk recorded damage is decided by the monotonic damage count (N336), never by the length of the
    capped `_WALK_DAMAGE`. `walk` is a no-argument callable that returns the rows, so each caller keeps its own walk
    arguments (forefst passes `oid=` to verify the table's root page; refsanalysis does not)."""
    _before = _walk_damage_count()
    try:
        n = len(list(walk()))
    except Exception as _e:
        _skip_note(stage, where, _e)
        return None, True
    return n, _walk_damage_count() > _before


def count_text(summary, key, unit=""):
    """N338: the printed value of one table count of `summary` in A3's convention -- "unreadable" (never 0) when the
    count is None (the walk raised) or the key is listed in `counts_unreadable` (pages could not be read)."""
    v = summary.get(key, 0)
    if v is None or key in (summary.get("counts_unreadable") or ()):
        return "unreadable (pages could not be read — NOT an empty table)"
    # N596: one entry, one row ... -- the unit in the number the count takes
    return "%s%s" % (v, _SINGULAR_UNITS.get(unit, unit) if v == 1 else unit)


_SINGULAR_UNITS = {" entries": " entry", " rows": " row", " records": " record", " files": " file"}

# A6/K034: set when a redundancy finding (a MISSING/DAMAGED/INVALID bootstrap copy) was reported, so
# `rc_escalate` turns an otherwise-successful run into exit 2. Mirrors _SKIP_FINDING / _WALK_DAMAGE.
_REDUNDANCY_FINDING = []

# A5/K033: set when the primary SUPB was unusable and a backup copy was used instead. `summary` reports it
# and the run exits 2 -- losing the primary superblock is a finding about the volume, not a detail.
# N425 / LB64 (1.14.0): it says which superblock copy the CURRENT volume view is read from, so it is cleared when a view
# starts (N426: a `view` register of `_MODULE_REGISTERS`, reset by `_new_view`, the first step of `parse_supb`); a
# fallback of an earlier view of the same run stays a finding of the run (`_SUPB_EARLIER_VIEW`), so the exit code is
# what it was.
_SUPB_FELL_BACK = {}

# N425 / LB64 (1.14.0): the `_finding` kind under which `_view_carry` keeps, for the run's exit code and its
# escalation texts, the superblock fallback of a volume view this run read before the current one.
_SUPB_EARLIER_VIEW = "an earlier volume view of this run read from a backup superblock"

# N426 (1.14.0): the `_finding` kind under which `_view_carry` keeps, for the run's exit code and its escalation texts,
# the checkpoint conditions (`_CHKP_STALE`) of a volume view this run read before the current one.
_CHKP_EARLIER_VIEW = "a checkpoint condition of an earlier volume view of this run"

# PLAN_1.13.2 decisions 26 and 27.1: the `_finding` kind `parse_supb` records when NO superblock copy is valid (B15:
# passes ValidateSuperBlock's tests) and the volume is read from a copy that is not -- the primary when it carries the
# signature (26), otherwise the first signed backup in slot order, end-2 then end-3 (27.1; `_SUPB_FELL_BACK` names that
# backup as the copy read, `none_valid`). The sink
# `_FINDINGS` gives exit 2 in every command (rc_escalate); refsanalysis `supb` prints the recorded text.
_SUPB_NONE_VERIFIES = "no verified superblock copy"

# Decision 27.3: the `_finding` kind `parse_supb` records when the superblock copy the volume is read from cannot be
# verified (`supb_validate` cksum_ok None: an unknown checksum type) -- exit 2 in every command, the copy said to be
# "cannot be verified", never "failed".
_SUPB_UNVERIFIED = "superblock copy read cannot be verified"
# N470 (decision 49 point 8): the words of a clean checksum verdict -- one wording in every output that states one
_NO_TAMPER_DETECTED = "no tampering or corruption detected"
_CHECKSUM_LIMIT = "(a checksum cannot prove the absence of a deliberate edit)"


def volume_length(vbr):
    """B3 (wave C, Q16; single_source.tsv row `volume_length`): THE length in bytes of the volume a boot sector
    describes -- total sectors (+0x18) x bytes per sector (+0x20, `_vbr_bytes_per_sector`) -- or None when the sector
    is too short to hold both fields. refs.sys counts the volume's clusters as (total sectors x bytes per sector) >>
    log2(cluster size) (WAVEC_READING_bounds V5, read twice) and places the backup superblocks at the last clusters of
    THAT count. Every site that needs where the volume ends takes it from here (`volume_clusters`, `volume_extent`, the
    summaries' volume size, the backup slots). 1.13.1 took the IMAGE's length at five sites -- the capacity, the
    extent plausibility bound, both orphan-page scans, refsanalysis allocators -- so the bytes an image holds after the
    volume (50331648 on base A, a tail on every GPT image of the corpus, MR-V 117 of 117) were counted as the volume's,
    and an image cut short was counted as a shorter volume."""
    if len(vbr) < 0x20:
        return None
    return le64(vbr, 0x18) * _vbr_bytes_per_sector(vbr)


def volume_clusters(f, ps, cs):
    """B3 (Q16; single_source.tsv row `volume_clusters`): N, the clusters of the volume whose boot sector is at `ps` --
    `volume_length` // cs, never the image's length. The capacity (`alloc_capacity`: the allocator's summary is
    refused only when it covers more than N clusters, S-A), the extent plausibility bound of every decoded run (N217 is
    told; `_volume_ncl`, the decoders' name for it), both orphan-page scans (`_orphan_scan_bound`) and refsanalysis
    `allocators` take it. The file position is kept. Raises OSError when the boot sector cannot be read, a read the image
    ends inside included (parse_vbr has refused such a volume before any caller runs). N344: the boot sector is the
    copy the volume is read from (`boot_sector_bytes`: the primary, or the backup when the primary fails a test)."""
    pos = f.tell() if hasattr(f, "tell") else None
    try:
        n = volume_length(boot_sector_bytes(f, ps))
    finally:
        if pos is not None:
            _seek_read(f, pos, 0)        # back where the caller was (through the guard: N371's lint sees no raw seek)
    if n is None:
        raise OSError("the boot sector at offset 0x%x cannot be read: the image ends inside it" % ps)
    return n // cs


# The extent decoders' name for N (the plausibility bound of a decoded run; N217, wave D, is told): the one definition,
# under the name the decoders and the tests that stand in for it use.
_volume_ncl = volume_clusters


def volume_extent(f, ps, cs, image_path=None):
    """B3 (Q17, Q18; single_source.tsv row `volume_extent`): the volume against the image it is read from.

      volume_end           ps + `volume_length` of the boot sector at ps (an absolute offset)
      image_end            the image's length
      truncated            image_end < volume_end; missing_bytes = volume_end - image_end, and backup_supb_missing the
                           backup superblock slots (`_supb_backup_lcns`) that are not wholly in the image
      tail_after_volume    the image's bytes after the volume's end (0 when it is truncated)
      partition            with `image_path`: the GPT entry that STARTS at ps (`gpt_partition_detail(start=ps)`), else
                           None; then tail_in_partition = the image's bytes after the volume inside that partition and
                           tail_after_partition = its bytes after the partition (both None without an entry)

    The tail is not a finding: it is not the volume's. refs.sys mounts only a volume whose boot sector gives no more
    sectors than its device holds, rounded down to 64 MiB, and reads nothing after the volume's last cluster
    (WAVEC_READING_bounds V4, V9). Returns None when the boot sector gives no length. The file position is kept."""
    pos = f.tell() if hasattr(f, "tell") else None
    try:
        vlen = volume_length(boot_sector_bytes(f, ps))       # N344: the copy the volume is read from
        if vlen is None:
            return None
        image_end = f.seek(0, 2)
        vol_end = ps + vlen
        out = {"volume_end": vol_end, "image_end": image_end, "truncated": image_end < vol_end,
               "missing_bytes": max(0, vol_end - image_end), "backup_supb_missing": [],
               "tail_after_volume": max(0, image_end - vol_end),
               "partition": None, "tail_in_partition": None, "tail_after_partition": None}
        if out["truncated"]:
            out["backup_supb_missing"] = [l for l in _supb_backup_lcns(f, ps, cs) if ps + (l + 1) * cs > image_end]
        if image_path is not None:
            g = gpt_partition_detail(image_path, start=ps)
            if g:
                pend = ps + g["size_bytes"]
                out["partition"] = g
                out["tail_in_partition"] = max(0, min(pend, image_end) - vol_end)
                out["tail_after_partition"] = max(0, image_end - max(pend, vol_end))
        return out
    finally:
        if pos is not None:
            _seek_read(f, pos, 0)        # back where the caller was (through the guard)


def volume_truncation_text(image_end, volume_end, backup_supb_missing):
    """B3 (Q18; single_source.tsv row `volume_truncation`): the one sentence for an image that ends inside the volume --
    the stderr note of every command (`_say_volume_truncation`) and the redundancy list of summary, fastsummary,
    integrity and refsanalysis summary (`_redundancy_findings`, exit 2 there). `backup_supb_missing`: how many of the
    two backup superblock slots are not wholly in the image; the backup boot sector the tool reads is in the volume's
    last sector, so it is always among the bytes missing."""
    _sb = {0: "", 1: " and one of its two backup superblocks"}.get(backup_supb_missing, " and both backup superblocks")
    return ("truncated image: the image ends at offset 0x%x, before the volume's end at offset 0x%x (total sectors x "
            "bytes per sector): the last %s of the volume %s not in the image, with its backup boot sector%s"
            % (image_end, volume_end, count_noun(volume_end - image_end, "byte"), "is" if volume_end - image_end == 1 else "are", _sb))


_TRUNCATION_SAID = set()   # B3: (image, partition start) pairs whose truncation note this run has printed


def _say_volume_truncation(f, ps, cs):
    """B3 (Q18): a volume the image ends inside is said on stderr, once per image and partition start in a run. Not a
    finding by itself (a command whose reads stay inside the image exits 0); summary, fastsummary, integrity and
    refsanalysis summary list it (exit 2), and an orphan-page scan that meets the image end records its own finding.
    A cluster size that is not a power of two (a damaged boot sector a caller reads anyway) is left to the caller."""
    if not cs or cs < 0 or cs & (cs - 1):
        return
    try:
        ext = volume_extent(f, ps, cs)
    except (OSError, ValueError) as _e:
        _skip_note("volume length", "comparing the volume's end with the image's", _e)
        return
    if not ext or not ext["truncated"]:
        return
    key = (getattr(f, "name", None), ps)
    if key in _TRUNCATION_SAID:
        return
    _TRUNCATION_SAID.add(key)
    print("[%s] note: %s" % (PROG, volume_truncation_text(ext["image_end"], ext["volume_end"],
                                                          len(ext["backup_supb_missing"]))), file=sys.stderr)


def _supb_backup_lcns(f, ps, cs):
    """The two secondary SUPB slots, by ADDRESS, in refs.sys's order: end_lcn-2, then end_lcn-3.

    B15 (wave C, closure B-4.1 row 1): `CmsVolume::ReadSuperBlock` reads the slots 0x1e, N-2, N-3 in that order
    (17134, 26100.8115, .9444, .9549, Insider 29574; read twice, WAVEC_READING_bootstrap S1). This is the one choice
    order: `parse_supb`'s (a later valid copy replaces the chosen one only with a strictly higher +0x68) and decision
    27.1's "first signed backup in slot order". Until 1.14.0 it was (end-3, end-2), so the tool read end-3 where refs.sys
    reads end-2 (win11refsmini_aftercorruption, _openedwith34). The redundancy list keeps its ascending-LCN display
    order (`_scan_backup_copies`; Q3: a listing, not a second choice order).

    Same slots `_scan_backup_copies` uses: measured over the corpus the copies sit at those two slots on
    102 of 102 ReFS volumes (every cluster size, every version, 2 GiB to 2 TiB). Located by address rather
    than by scanning for the signature, because a copy whose signature is destroyed must read as DAMAGED,
    not as absent.
    """
    try:
        vbr = boot_sector_bytes(f, ps)            # N344: the copy the volume is read from (N371: guarded reads)
        if vbr[3:7] != b"ReFS":
            return []
        total_sectors = le64(vbr, 0x18) if len(vbr) >= 0x20 else 0
        if total_sectors <= 1:
            return []
        end_lcn = volume_length(vbr) // cs                               # B3: the one volume length
        return [l for l in (end_lcn - 2, end_lcn - 3) if l > SUPB_LCN]               # B15: refs.sys's order
    except (OSError, OverflowError, ValueError) as _e:
        # Returning [] here would say "this volume has no backup SUPB slots", which is a MEASUREMENT.
        # What actually happened is that the VBR geometry could not be read, so we could not look --
        # and a redundancy check that cannot look must not report absence. Recorded with its type and
        # location so the exit status says the work was not done (B4).
        _skip_note("SUPB backup location", "reading VBR geometry for the backup slots", _e)
        return []


def supb_validate(blk, cs, lcn=None, n=None):
    """THE test of one superblock (SUPB) copy -- one definition, used by forefst and imported by refsanalysis
    (A11: single_source.tsv row `supb_validate`).

    B15 (wave C, Q2): a copy is VALID when it passes the tests of refs.sys's `CmsVolume::ValidateSuperBlock`, made here in
    the driver's order (17134 refs_win10.decomp.c :121683-121716; 26100.8115 refs_win11.decomp.c :216504-216535;
    26100.9549 refs.decomp.c :215732-215763; Insider 29574 winsider-refs.decomp.c :284703-284733 -- read twice,
    WAVEC_READING_bootstrap S5):
      size      the copy is at least 0xc0 bytes (a cluster always is; a read the image ends inside may not be)
      checksum  its own self-checksum, from the descriptor its +0x78/+0x7c declares (`_verify_self_checksum`)
      tuple     the 32 bytes +0x20..+0x3f are {its own LCN, 0, 0, 0} (made when `lcn` is given)
      b04       byte +0x04 is not 0
      cnt74     u32 +0x74 (the checkpoint reference count) is 2
      off70     u32 +0x70 (the checkpoint reference offset) is at least 0xc0, and +0x70 + 0x10 is inside the cluster
      ckpt      both references at +0x70, read as SIGNED 64-bit LCNs, lie in [0x1f, N - 3], N = `n`, the volume's clusters
                (26100.8115 :216530-216536: `lVar2 < 0x1f || N - 3 < lVar2` rejects); made only when off70 passes (the
                driver reads them there), both of them whatever +0x74 says (its loop runs twice); without `n` only the
                lower bound is tested
    The tests are all made (the driver stops at the first failure), so a statement can name every one a copy fails.
    There is NO signature test (S5): the `SUPB` signature does not make a copy valid or invalid (C2 S-F). It selects,
    among copies that are not valid, the copy decisions 26 / 27.1 read (`parse_supb`), and the redundancy scanner keeps
    classifying a copy without it as missing or damaged (`_scan_backup_copies`).

    Returns a dict:
      sig_ok       the block starts with b"SUPB"
      cksum_ok     the copy's own self-checksum: True / False, or None when no algorithm can check it --
                   None is "not checkable" (decision 27.3), NOT a failure
      ckname       the checksum's name (or why none applies)
      self_lcn     SUPB+0x20, the LCN the copy says it lives at (None without a signature)
      self_lcn_ok  self_lcn == lcn (None when `lcn` is not given, or without a signature)
      cksum_ok_restored  K041: with +0x20 set back to `lcn`, does the copy verify? (only when self_lcn_ok is
                   False; None otherwise)
      failures     [(test, text)]: the tests above the copy fails, in the driver's order ("checksum" only when the
                   self-checksum FAILS)
      ok           no test fails: the copy is valid
    1.13.1 / 1.13.2 accepted a copy on its signature and self-checksum alone, so a re-sealed copy with another own
    LCN, +0x74 = 3 or a checkpoint reference outside the volume was read (B15; RED_C2_supb.md N-4).
    """
    sig_ok = blk[:4] == b"SUPB"
    out = {"sig_ok": sig_ok, "cksum_ok": None, "ckname": "-", "self_lcn": None, "self_lcn_ok": None,
           "cksum_ok_restored": None, "failures": [], "ok": False}
    fails = out["failures"]
    if len(blk) < 0xC0:
        fails.append(("size", "it is 0x%x bytes, shorter than 0xc0" % len(blk)))
        return out
    out["cksum_ok"], out["ckname"] = _verify_self_checksum(blk, cs, b"SUPB")          # S-F: no signature needed
    if out["cksum_ok"] is False:
        fails.append(("checksum", "self-checksum FAILED (%s)" % out["ckname"]))
    if sig_ok:
        out["self_lcn"] = le64(blk, 0x20)
        if lcn is not None:
            out["self_lcn_ok"] = (out["self_lcn"] == lcn)
            if out["self_lcn_ok"] is False:
                out["cksum_ok_restored"] = _verify_with_own_lcn(blk, cs, lcn, b"SUPB")   # K041
    if lcn is not None and bytes(blk[0x20:0x40]) != struct.pack("<4Q", lcn, 0, 0, 0):
        _p = []
        if le64(blk, 0x20) != lcn:
            _p.append("+0x20 (its own LCN) is 0x%x, not 0x%x" % (le64(blk, 0x20), lcn))
        if any(blk[0x28:0x40]):
            _p.append("+0x28..+0x3f are not zero")
        fails.append(("tuple", " and ".join(_p)))
    if blk[4] == 0:
        fails.append(("b04", "byte +0x04 is 0"))
    if le32(blk, 0x74) != 2:
        fails.append(("cnt74", "+0x74 (the checkpoint reference count) is %d, not 2" % le32(blk, 0x74)))
    o = le32(blk, 0x70)
    if o < 0xC0:
        fails.append(("off70", "+0x70 (the checkpoint reference offset) is 0x%x, below 0xc0" % o))
    elif o + 0x10 > cs:
        fails.append(("off70", "+0x70 (the checkpoint reference offset) is 0x%x: its two references would end at 0x%x, "
                               "past the end of the cluster (0x%x)" % (o, o + 0x10, cs)))
    elif o + 0x10 > len(blk):
        fails.append(("ckpt", "the checkpoint references at +0x%x lie past the 0x%x bytes read" % (o, len(blk))))
    else:
        _p = []
        for i in range(2):
            c = struct.unpack_from("<q", blk, o + 8 * i)[0]
            if c < 0x1F or (n is not None and c > n - 3):
                _p.append("checkpoint reference %d (+0x%x) is %s, outside 0x1f..%s"
                          % (i + 1, o + 8 * i, ("-0x%x" % -c) if c < 0 else "0x%x" % c,
                             "0x%x (N - 3)" % (n - 3) if n is not None else "the volume"))
        if _p:
            fails.append(("ckpt", " and ".join(_p)))
    out["ok"] = not fails
    return out


def supb_volume_guid(blk, cs, lcn):
    """The volume GUID (+0x50) of the superblock copy the view is read from (`parse_supb`'s copy), for forefst
    `summary` / `fastsummary` and refsanalysis `summary`: shown when that copy carries the signature (decisions 26 /
    27.1 read a signed copy that is not valid: its GUID is shown and the finding says it is not verified) or passes the
    superblock tests (B15, C2 S-F: a copy without the signature that refs.sys accepts). Zeros only for a copy that is
    neither, which parse_supb never reads -- A5/K033: zeros are not rendered as a GUID read from the volume."""
    v = supb_validate(blk, cs, lcn)
    return bytes(blk[0x50:0x60]) if len(blk) >= 0x60 and (v["sig_ok"] or v["ok"]) else b"\x00" * 16


# C2-1 (decision 47): what is wrong with a superblock copy that passes refs.sys's tests without its signature -- one
# wording for the statements, the redundancy list and the export's warning (%r: the copy's first four bytes)
_SUPB_UNSIGNED_TEXT = "it passes refs.sys's superblock tests but carries no SUPB signature (its first bytes are %r)"


def _supb_damage_reason(blk, v):
    """Why a superblock copy is not valid, in words (`v` = its supb_validate result). A copy without the signature that
    does not verify keeps the words it had ("all zeros", its first bytes); a self-checksum that FAILS is named alone --
    the driver's first test after the size, so the copy's other fields are bytes that do not verify; otherwise every
    other test the copy fails, in the driver's order (B15)."""
    if v["ok"] and not v["sig_ok"]:
        # C2-1 (decision 47; WC-4): a copy that passes every test refs.sys makes but carries no SUPB signature is read,
        # as refs.sys reads it, and the reason says what is wrong with it (1.13.2 said "valid")
        return _SUPB_UNSIGNED_TEXT % bytes(blk[:4])
    if not v["sig_ok"] and v["cksum_ok"] is not True:
        return "all zeros" if blk and not any(blk) else "signature %r" % bytes(blk[:4])
    if v["cksum_ok"] is False:
        return "self-checksum FAILED (%s)" % v["ckname"]
    return "; ".join(t for _k, t in v["failures"]) or "valid"


def _supb_failed_phrase(blk, v):
    """B15: what a superblock copy that is read although it is not valid (decisions 26, 27.1) failed: "FAILED its
    self-checksum (<name>)" (the 1.13.x words) or "FAILED validation (<the tests>)"."""
    if v["cksum_ok"] is False:
        return "FAILED its self-checksum (%s)" % v["ckname"]
    return "FAILED validation (%s)" % _supb_damage_reason(blk, v)


def _supb_g68(blk):
    """SUPB+0x68, the u64 `ChooseSuperBlock` compares (unsigned; 0 for a block too short to hold it)."""
    return le64(blk, 0x68) if len(blk) >= 0x70 else 0


def _supb_choose(cands):
    """B15 (Q3): refs.sys's choice among the superblock copies `cands` = [(lcn, block, supb_validate verdict)] in slot
    order (primary first). `CmsVolume::ReadSuperBlock` keeps the first valid copy; a later valid copy replaces it only
    when `ChooseSuperBlock` finds its u64 +0x68 strictly higher (compared unsigned) AND the chosen copy is not slot 0
    (17134, 26100.8115, .9444, .9549, Insider 29574; read twice, WAVEC_READING_bootstrap S3-S4, the slot-0 test from the
    disassembly of all five). So a valid primary is read whatever the backups' +0x68 (N450), and of two valid backups
    end-2 is kept unless end-3's +0x68 is strictly higher. Returns the index of the copy chosen, or None (none valid:
    the driver fails the mount, 0xc0000032; the tool reads on under decisions 26 / 27.1)."""
    best = None
    for i, (_l, blk, v) in enumerate(cands):
        if not v["ok"]:
            continue
        if best is None or (best != 0 and _supb_g68(blk) > _supb_g68(cands[best][1])):
            best = i
    return best


def _supb_backup_how(cksum_ok, ckname, sig_ok=True):
    """N331 / decision 27.3 / N364 (B1): what this tool checked on the backup superblock copy it reads after a fallback,
    in one wording for parse_supb's statement and refsanalysis `supb`'s NOTE. No claim about the driver; a copy whose
    checksum cannot be verified is said to be one, never to "pass its checks". N375 (T3): only `cksum_ok is None` is
    "cannot be verified"; a copy whose self-checksum FAILED (no caller passes one today) is said to have failed.
    B15 (C2 S-F): a backup without the SUPB signature that passes every superblock test is read; it is said to carry
    no signature, never the signature it lacks."""
    sig = "which carries the SUPB signature" if sig_ok else "which carries no SUPB signature"
    if cksum_ok is None:
        return "%s; its checksum cannot be verified (%s)" % (sig, ckname)
    return ("%s and passes its self-checksum (%s)" % (sig, ckname) if cksum_ok else
            "%s but FAILED its self-checksum (%s)" % (sig, ckname))


def _supb_fell_back_text(d):
    """The sentence for one superblock fallback `d` (a `_SUPB_FELL_BACK` record), as `_escalation_texts` words it: one
    definition, so the fallback of an earlier view kept by `_view_carry` reads as the current view's does. B15: with
    two valid backups whose +0x68 differ, `rank` says the copy read has the higher one."""
    return ("the primary superblock (SUPB) at LCN 0x%x is not usable (%s); the volume is read from the backup copy at "
            "LCN 0x%x%s" % (d.get("primary_lcn", SUPB_LCN), d.get("reason", "damaged"), d.get("used_lcn", 0),
                            "; " + d["rank"] if d.get("rank") else ""))


def _supb_rank_text(cands, pick):
    """B15 (Q3, Q4): when the copy chosen is a backup and both backups are valid with different +0x68, the clause that
    says the copy read has the higher one -- `ChooseSuperBlock`'s comparison; None otherwise (end-2 is read on a tie,
    the driver's slot order: nothing to add)."""
    valid = [c for c in cands[1:] if c[2]["ok"]]
    if pick == 0 or len(valid) != 2 or _supb_g68(valid[0][1]) == _supb_g68(valid[1][1]):
        return None
    other = valid[1] if valid[0] is cands[pick] else valid[0]
    return ("of the two backups that pass validation it has the higher +0x68 (%d; LCN 0x%x has %d)"
            % (_supb_g68(cands[pick][1]), other[0], _supb_g68(other[1])))


def _supb_tried_text(blk, v):
    """A backup that is not read, in the words of the list a statement carries ("no SUPB signature" for a copy without
    it that does not verify, as 1.13.x said; otherwise `_supb_damage_reason`)."""
    if not v["sig_ok"] and v["cksum_ok"] is not True:
        return "no SUPB signature"
    return _supb_damage_reason(blk, v)


def parse_supb(f, ps, cs, say=True):
    """The checkpoint list of the superblock copy this tool reads (the rule below). The conditions it finds are
    recorded either way (`_SUPB_FELL_BACK`, `_finding`: exit 2); with say=False (N346) the three statements of a
    superblock condition -- a fallback to a backup, no copy valid (decisions 26, 27.1), the copy read cannot be
    verified (27.3) -- are not printed, because the caller says them in its own words (refsanalysis `supb`'s NOTE),
    so they are said once.
    N426 (1.14.0): reading the superblock is the first read of every volume view -- `bootstrap`'s and refsanalysis
    `supb` / `chkp` / `containers`', which read it without bootstrap -- so a new view starts here (`_new_view`): the
    view registers of `_MODULE_REGISTERS` are reset, and what the replaced view found stays a finding of the run."""
    _new_view()
    f.seek(ps + SUPB_LCN * cs); data = f.read(cs)
    # B15 (wave C, Q2-Q3; decision 27.4): the copy read is refs.sys's choice. A copy is VALID when it passes
    # ValidateSuperBlock's tests (`supb_validate`; no signature test). The copies are taken in the driver's slot order --
    # primary 0x1E, end-2, end-3 (`_supb_backup_lcns`) -- and `_supb_choose` keeps the first valid one; a later valid
    # one replaces it only with a strictly higher +0x68 and never replaces the primary (ReadSuperBlock /
    # ChooseSuperBlock, five builds, read twice: WAVEC_READING_bootstrap S1-S5, N450). A primary that is not valid is a
    # fallback (decision 27.2: said, exit 2 in every command). When NO copy is valid, refs.sys fails the mount
    # (0xC0000032); this tool reads on from the copy the SUPB signature selects -- the primary when it carries it
    # (decision 26), otherwise the first signed backup in slot order (decision 27.1) -- and records the finding (exit 2
    # in every command); a volume where no copy carries the signature is refused (exit 1). A copy read whose checksum
    # cannot be verified is recorded too (decision 27.3).
    # 1.13.1 tested the signature alone, so a primary whose GUID or checkpoint list had been altered was trusted;
    # 1.13.2 until B15 tested the signature and the self-checksum, read end-3 before end-2 and accepted a re-sealed
    # copy that fails a ValidateSuperBlock test (another own LCN, +0x74 = 3, a checkpoint reference outside the volume).
    try:
        _n = volume_clusters(f, ps, cs)                 # N for the checkpoint-reference bound (B3: the one length)
        _bsc_n = boot_sector_copy(f, ps)
        if _bsc_n["source"] == "primary" and any(k == "total_sectors" for k, _t in _bsc_n["failures"]):
            # C2-3 (1.14.0): the copy read fails its total-sectors test (S-C: read anyway), so N is not known: the
            # bound is "the volume" -- 1.13.2-dev computed N = 0 from total sectors 0 and failed every copy "outside
            # 0x1f..0x-3 (N - 3)"
            _n = None
    except (OSError, OverflowError, ValueError, ZeroDivisionError) as _e:
        _n = None
        _skip_note("superblock validity", "the volume's cluster count N for the checkpoint-reference bound N - 3", _e)
    _pv = supb_validate(data, cs, SUPB_LCN, _n)
    _read_lcn, _read_v = SUPB_LCN, _pv               # the copy read, and its supb_validate verdict
    if not _pv["ok"]:
        # ReFS keeps three superblock copies precisely so the loss of one is survivable, and the volume below is still
        # fully readable from a backup. Failing here reported a READABLE volume as unreadable and pointed the reader at
        # `--partition-start`, which is a different fault entirely (A5/K033).
        _why = _supb_damage_reason(data, _pv)
        _cands = [(SUPB_LCN, data, _pv)]
        for _lcn in _supb_backup_lcns(f, ps, cs):                         # end-2, end-3 (B15)
            try:
                _alt = _seek_read(f, ps + _lcn * cs, cs)                  # N371
            except (OSError, OverflowError):
                continue
            _cands.append((_lcn, _alt, supb_validate(_alt, cs, _lcn, _n)))
        _pick = _supb_choose(_cands)
        if _pick is not None:
            _lcn, _alt, _v = _cands[_pick]
            _rank = _supb_rank_text(_cands, _pick)
            _SUPB_FELL_BACK.update(primary_lcn=SUPB_LCN, used_lcn=_lcn, ckname=_v["ckname"], cksum_ok=_v["cksum_ok"],
                                   sig_ok=_v["sig_ok"], primary_all_zero=(not any(data)), reason=_why, rank=_rank,
                                   tried=[(c[0], _supb_tried_text(c[1], c[2])) for c in _cands[1:] if not c[2]["ok"]])
            _how = _supb_backup_how(_v["cksum_ok"], _v["ckname"], _v["sig_ok"])
            if say:
                print("[%s] WARNING: the primary superblock (SUPB) at LCN 0x%x (offset 0x%x) is not usable (%s); "
                      "the volume is read from the backup copy at LCN 0x%x (offset 0x%x), %s%s."
                      % (PROG, SUPB_LCN, ps + SUPB_LCN * cs, _why, _lcn, ps + _lcn * cs, _how,
                         "; " + _rank if _rank else ""), file=sys.stderr)
            data = _alt
            _read_lcn, _read_v = _lcn, _v
        else:
            _detail = ("; ".join("LCN 0x%x: %s" % (c[0], _supb_tried_text(c[1], c[2])) for c in _cands[1:])
                       if len(_cands) > 1 else "no backup slots could be located from the VBR")
            _signed = next((c for c in _cands[1:] if c[2]["sig_ok"]), None)   # 27.1: the first in slot order
            if not _pv["sig_ok"] and _signed is None:
                raise ValueError(
                    f"superblock (SUPB) not found at LCN 0x{SUPB_LCN:x} (offset 0x{ps + SUPB_LCN * cs:x}): expected "
                    f"'SUPB', got {data[:4]!r}, and no usable backup superblock was found ({_detail}). "
                    f"If this is a raw partition image, check --partition-start; to inspect the bootstrap chain "
                    f"run `refsanalysis.py <image> supb -v`.")
            if _pv["sig_ok"]:
                # Decision 26 (group 2 review F1): the primary carries its signature but is not valid, and no backup is.
                # Its checkpoint list can still be read, so read it -- as decision 20.8 reads a checkpoint copy that
                # fails -- say so, and record the finding (exit 2 in every command). Raising here reported a READABLE
                # volume as unreadable and pointed at --partition-start (the K033 defect above), in every command
                # including `refsanalysis supb`, the diagnostic its own message recommended.
                _text = ("no superblock copy passes validation (backups: %s); this view is read from the primary at "
                         "LCN 0x%x (offset 0x%x), which %s, so the volume GUID and the checkpoint list it supplies are "
                         "not verified" % (_detail, SUPB_LCN, ps + SUPB_LCN * cs, _supb_failed_phrase(data, _pv)))
            else:
                # Decision 27.1 (N330): the primary has NO signature (and is not valid), and no backup is valid. The
                # first signed backup in slot order (end-2, then end-3) still holds a checkpoint list, so it is read --
                # as decision 26 reads a primary that fails -- and the finding names it. It is a fallback to a backup,
                # so `_SUPB_FELL_BACK` names it as the copy read (the readers of the GUID and of the copy shown);
                # `none_valid` tells it from a fallback to a valid backup. Exit 1 with the --partition-start hint is
                # left for a volume where no copy carries a signature.
                _lcn, _alt, _v = _signed
                _SUPB_FELL_BACK.update(primary_lcn=SUPB_LCN, used_lcn=_lcn, ckname=_v["ckname"],
                                       cksum_ok=_v["cksum_ok"], sig_ok=True, primary_all_zero=(not any(data)),
                                       tried=[(c[0], _supb_tried_text(c[1], c[2])) for c in _cands[1:]],
                                       reason=_why, rank=None, none_valid=True)
                _text = ("no superblock copy passes validation (primary at LCN 0x%x (offset 0x%x): %s; backups: %s); "
                         "this view is read from the backup copy at LCN 0x%x (offset 0x%x), the first backup in slot "
                         "order that carries the SUPB signature, which %s, so the volume GUID and the checkpoint list "
                         "it supplies are not verified"
                         % (SUPB_LCN, ps + SUPB_LCN * cs, _why, _detail, _lcn, ps + _lcn * cs,
                            _supb_failed_phrase(_alt, _v)))
                data = _alt
                _read_lcn, _read_v = _lcn, _v
            if _text not in _view_findings(_SUPB_NONE_VERIFIES):          # N426: once per view
                _finding(_SUPB_NONE_VERIFIES, _text)
            if say:
                print("[%s] WARNING: %s" % (PROG, _text), file=sys.stderr)
    if _read_lcn == SUPB_LCN and _read_v["ok"] and not _read_v["sig_ok"] and say:
        # C2-1 (decision 47: "if you can read it, read it and output clearly that something is wrong"): the primary
        # passes every test refs.sys makes, so it is read as refs.sys reads it; its missing signature is said (exit
        # unchanged; the redundancy list calls it damaged). A backup read after a fallback is said by the fallback.
        print("[%s] WARNING: the primary superblock (SUPB) at LCN 0x%x (offset 0x%x) carries no SUPB signature (its first "
              "bytes are %r) but passes refs.sys's superblock tests: it is read, as refs.sys reads it."
              % (PROG, SUPB_LCN, ps + SUPB_LCN * cs, bytes(data[:4])), file=sys.stderr)
    if _read_v["cksum_ok"] is None:
        # Decision 27.3 (N238 / decision 22): the copy the volume is read from cannot be verified (a checksum type this
        # tool does not know, or none declared). Every command exits 2, as for a checkpoint copy in use that cannot be
        # verified; the copy is "cannot be verified", never "failed". A fallback already said it, naming the copy.
        _text = ("the superblock copy this view is read from (the %s at LCN 0x%x, offset 0x%x): checksum cannot be "
                 "verified (%s), so the volume GUID and the checkpoint list it supplies are not verified"
                 % ("primary" if _read_lcn == SUPB_LCN else "backup", _read_lcn, ps + _read_lcn * cs,
                    _read_v["ckname"]))
        if _text not in _view_findings(_SUPB_UNVERIFIED):                 # N426: once per view
            _finding(_SUPB_UNVERIFIED, _text)
        if _read_lcn == SUPB_LCN and say:
            print("[%s] WARNING: %s" % (PROG, _text), file=sys.stderr)
    off = le32(data, 0x70); cnt = le32(data, 0x74)
    # review E9: clamp the on-disk count (doc: always 2). A fuzzed/corrupt cnt (e.g. 0xFFFFFFFF) would build a
    # multi-billion-entry list and hang; also bound to the page so an out-of-range off can't over-read.
    if cnt > 8 or off + cnt * 8 > len(data):
        safe = max(0, min(cnt, 8, (len(data) - off) // 8 if off < len(data) else 0))
        if say:   # N346 (1.14.0): a caller that says it itself (refsanalysis `supb`) passes say=False -- it was said twice
            print(f"[{PROG}] WARNING: SUPB checkpoint-ref count {cnt} implausible (doc=2); clamped to {safe}",
                  file=sys.stderr)
        cnt = safe
    return [le64(data, off + i * 8) for i in range(cnt)]

def parse_chkp(f, ps, cs, lcn):
    # F11 / E118 (LB2): the checkpoint RECORD is one cluster -- the driver reads and writes `count` clusters with count
    # initialised to 1 on every build read, and the self-checksum covers one cluster (236 of 236 copies). 1.13.0 (N52)
    # read the 16 KiB page, three clusters of which are not the checkpoint. N371: a past-the-file offset still raises.
    raw = _seek_read(f, ps + lcn * cs, cs)
    if raw[:4] != b"CHKP":
        if raw and not any(raw):
            # N374 (S6, C8 = B): a page of zeros, or one the image stores as a hole, shows no cause -- the superblock's
            # pointer is not blamed for it
            raise ValueError(f"checkpoint (CHKP) not found at LCN 0x{lcn:x} (offset 0x{ps + lcn * cs:x}): "
                             f"{_chkp_unreadable_text(f, ps, cs, lcn, raw)}")
        raise ValueError(
            f"checkpoint (CHKP) not found at LCN 0x{lcn:x} (offset 0x{ps + lcn * cs:x}): expected 'CHKP', got "
            f"{raw[:4]!r}. The superblock's checkpoint pointer may be corrupt — run "
            f"`refsanalysis.py <image> chkp -v` to inspect.")
    vclock = le64(raw, 0x10)
    flags = le32(raw, 0x78)
    desc_len = le32(raw, 0x5c)
    indirect = bool(flags & 0x200)
    root_count = le32(raw, 0x90)
    # review E9: clamp a fuzzed count (13 on every record read); 32 is a bound of this tool, not a field of the record (E159:
    # +0x8C is the length of a 32-byte area). A fuzzed count would loop billions of times.
    if root_count > 32:
        print(f"[{PROG}] WARNING: CHKP root count {root_count} implausible (doc=13, cap=32); clamped to 32", file=sys.stderr)
        root_count = 32
    olb = le32(raw, 0x94) if indirect else 0x94
    roots = []
    for idx in range(root_count):
        oe = olb + idx * 4
        if oe + 4 > len(raw): roots.append([]); continue
        ro = le32(raw, oe)
        if ro == 0 or ro + desc_len > len(raw): roots.append([]); continue
        rec = raw[ro:ro+desc_len]
        slots = [le64(rec, i*8) for i in range(4)]
        roots.append([s for s in slots if s not in (0, 0xFFFFFFFFFFFFFFFF)])
    return vclock, flags, roots


def _chkp_unreadable_text(f, ps, cs, lcn, raw):
    """N374 (T1, T1a, S6; C8 = B): what a checkpoint copy that was read but carries no CHKP signature is, from its
    bytes and the image alone -- never a cause the bytes do not show (not the superblock's pointer, not a removal).
    A copy the image stores as a hole: C8 = B's hole sentence; written zeros: 'all zeros'; other bytes: what they
    begin with. One text for every form that prints the copy (`checkpoint_select`'s `unreadable`).
    N384 (Q25: said with its cause): a read that returns no byte is a copy that lies past the end of the image -- a read
    of a regular file returns nothing only at or after its end -- in the words N412 gives an MLog control copy there
    (`_mlog_control_unreadable_why`); 1.13.2-dev said "nothing could be read there", without the cause."""
    if not raw:
        return _CHKP_PAST_END_TEXT
    if any(raw):
        return "it carries no CHKP signature; its first bytes are %r" % bytes(raw[:4])
    st = _image_hole_state(f, ps, cs, ps + lcn * cs, ps + lcn * cs + len(raw))
    if st in ("hole", "source-hole", "bundle-absent"):
        return "it carries no CHKP signature: " + _hole_sentence(st)
    if st == "partial":
        # N368 (bundle mode): the rehydrated image's hole is bytes the bundle does not carry, not "the image"'s
        return ("it carries no CHKP signature: its cluster reads as all zeros, and this bundle does not carry part of it"
                if _bundle_of(f) is not None else
                "it carries no CHKP signature: its cluster reads as all zeros, and the image stores part of it as a hole")
    if st is None:
        return ("it carries no CHKP signature: its cluster reads as all zeros; whether this bundle carries all of it "
                "could not be checked" if _bundle_of(f) is not None else
                "it carries no CHKP signature: its cluster reads as all zeros; whether the image stores it as a hole "
                "could not be checked")
    return "it carries no CHKP signature: its cluster reads as all zeros"


# N384 / N394 (WAVEC_BRIEF Q25): the two causes of a checkpoint copy of which nothing was read, each in one wording --
# the read returned no byte (the copy lies past the end of the image), or the read failed (the host refused it, or the
# tool did: an offset past any file offset, N371). `checkpoint_select` records the text in `unreadable` for both, so
# every form that prints the copy -- the conditions, the summaries' copy rows, the per-copy JSON `Unreadable`,
# refsanalysis supb and chkp -- says the same cause, and no form says such a copy "carries no CHKP signature".
_CHKP_PAST_END_TEXT = "it lies past the end of the image"


def _chkp_read_error_text(e):
    """N394 (Q25): the words for a checkpoint copy whose read failed, with the error the read raised as its cause
    (OffsetTooLarge's "offset 0x... is beyond the largest file offset, ...", or the host's "[Errno 22] Invalid
    argument"). `checkpoint_select`'s `unreadable` of such a copy; the condition says the copy "could not be read"."""
    return "it could not be read (%s)" % e


def _chkp_rec_not_read(rec):
    """N384 / N394: nothing was read from the checkpoint copy of a per-copy record of the redundancy scanner
    (`_scan_backup_copies`) -- its read failed (`error`), or it lies past the end of the image (`Unreadable`). Such a copy
    is said with its cause and never said to carry no CHKP signature (refsanalysis `bootedit repair`)."""
    return bool(rec.get("error")) or rec.get("Unreadable") == _CHKP_PAST_END_TEXT


def _chkp_unreadable_hole(text):
    """The hole state ('hole', 'source-hole' or 'bundle-absent') an `_chkp_unreadable_text` states, or None when it
    states none -- read from the exact hole sentence it ends with, so a text that only mentions a hole (zeros whose
    hole state could not be checked, a page partly in a hole) is not taken for one. One test for both tools."""
    for st in ("hole", "source-hole", "bundle-absent"):
        if text and text.endswith(": " + _hole_sentence(st)):
            return st
    return None


def _chkp_unreadable_short(text):
    """The few words of `_chkp_unreadable_text` a status column carries (summary / integrity copy rows). N384: a copy
    past the end of the image (nothing was read) is "past the image end", never "no CHKP signature"."""
    if text == _CHKP_PAST_END_TEXT:
        return "past the image end"
    st = _chkp_unreadable_hole(text)
    if st == "bundle-absent":
        return "no CHKP signature, not in this bundle"
    if st is not None:
        return "no CHKP signature, stored in the %s as a hole" % ("source image" if st == "source-hole" else "image")
    if text and "all zeros" in text:
        return "no CHKP signature, all zeros"
    return "no CHKP signature"


# N205 (PLAN_1.13.2 decision 20.8 / 21): the global-table roots that refs.sys 26100.x reads and verifies, against
# the digest the checkpoint copy itself records for each, in the FIRST (strict) pass of ReadLatestCheckpoint
# (`ValidateCheckpointRecord`, 26100.8115 refs_win11.decomp.c:217188-217197, :217281; `ValidateGlobalTableRootBlock`
# compares the page with the reference's +0x22/+0x24/+0x28). Only if neither copy passes does a SECOND pass run
# without this check; the mount then fails only when neither copy passes that either. Insider 29574 rejects a copy
# here only on a read error; 17134 has no root check (F1_CHECKPOINT_TIE_READING.md).
_CHKP_STRICT_ROOTS = (0xC, 7, 8)


def _chkp_root_failures(f, ps, cs, raw, unchecked=None, unchecked_why=None, roots=_CHKP_STRICT_ROOTS, tr=None,
                        copy_words="this copy"):
    """N205: [(root index, why)] for roots 0xc, 7 and 8 of ONE checkpoint copy whose page cannot be read or does not
    match the digest this copy records for it. These roots use physical LCNs (_CT_ROOT_INDICES). A reference whose
    checksum type is neither CRC64 nor SHA-256 cannot be checked here and is not listed; N332: with `unchecked` (a
    list), the index of every such root -- and of a root without a reference -- is appended to it, so a caller that
    reports the check can say it could not be made; N362: with `unchecked_why` (a list), (index, why) of each such root
    is appended to it, for the text that says the root cannot be verified and why. Reads only; records no skip (the
    caller decides what to report).
    B2 (1.14.0): the one test of a checkpoint root page against the digest the checkpoint record holds for it, also for
    the Object Table's pair 0 / 5 (`object_table_copy`): `roots` are the indices tested, `tr` translates their VIRTUAL
    LCNs (the Object Table's roots; a read error then names the PLCN read), `copy_words` names the checkpoint copy in
    the texts ("this copy" in the per-copy lists of N205)."""
    out = []

    def _nc(idx, why):
        if unchecked is not None:
            unchecked.append(idx)
        if unchecked_why is not None:
            unchecked_why.append((idx, why))
    if len(raw) < 0x98:
        for idx in roots:
            _nc(idx, "%s is too short to hold its root references" % copy_words)
        return out
    dl = max(le32(raw, 0x5C), 0x30)
    olb = le32(raw, 0x94) if le32(raw, 0x78) & 0x200 else 0x94
    for idx in roots:
        oe = olb + idx * 4
        if oe + 4 > len(raw):
            # N369 (K-9 b) / E118: the record read is one cluster (F11); "the page" named the 16 KiB allocation
            _nc(idx, "%s's table of root offsets runs past the checkpoint record (one cluster)" % copy_words)
            continue
        ro = le32(raw, oe)
        if ro == 0 or ro + dl > len(raw):
            _nc(idx, "%s records no reference for it" % copy_words if ro == 0 else
                "its reference runs past the checkpoint record (one cluster)")
            continue
        rec = raw[ro:ro + dl]
        slots = [le64(rec, i * 8) for i in range(4)]
        slots = [s for s in slots if s not in (0, 0xFFFFFFFFFFFFFFFF)]
        if tr is not None:
            slots = [tr.tr(s) for s in slots]              # B2: the clusters read (a VIRTUAL reference, translated)
        ck, n = rec[0x22], le32(rec, 0x24)
        if not slots or ck not in (2, 4) or 0x28 + n > len(rec):
            _nc(idx, "its reference holds no LCN" if not slots else
                ("its reference declares checksum type 0x%x, %s" % (ck, _CK_NOT_COMPUTED[ck]) if ck in _CK_NOT_COMPUTED else
                 "its reference declares checksum type 0x%x, which this tool does not compute for a root page" % ck)
                if ck not in (2, 4) else "its reference's digest length (%d bytes) runs past the reference" % n)
            continue
        if (ck == 4 and n != 32) or (ck == 2 and n < 8):
            # RC3 (D's second correction): a declared length the algorithm's digest does not have is not compared with
            # it -- a SHA-256 digest is 32 bytes, a CRC64 one 8 -- so the page is not said to fail for it
            _nc(idx, "its reference declares a %d-byte digest for %s, whose digest is %d bytes"
                % (n, "SHA-256" if ck == 4 else "CRC64", 32 if ck == 4 else 8))
            continue
        pg = b""
        s = None
        try:
            for s in slots:
                chunk = _seek_read(f, ps + s * cs, cs)       # N371: an LCN past any file offset is a failed read
                if len(chunk) < cs:
                    raise OSError("short read")
                pg += chunk
        except (OSError, OverflowError) as _e:
            # N371: the LCN the reference holds (B2: the PLCN read for a translated root)
            out.append((idx, "cannot be read (%s 0x%x: %s)" % ("LCN" if tr is None else "PLCN", s, _e)))
            continue
        if ck == 2:
            stored = le64(rec, 0x28)
            good = stored == REFS_CRC64_SENTINEL or refs_crc64(pg) == stored
        else:
            good = hashlib.sha256(pg).digest() == bytes(rec[0x28:0x28 + n])
        if good:
            continue
        _hs = _page_hole_state(f, ps, cs, slots, None) if not any(pg) else None
        if _hs == "source-hole":
            # N368 (bundle mode, C8 = B): a hole of the SOURCE image, as the other bundle-mode hole sentences say (new
            # text: no parenthesised note, decision 35)
            out.append((idx, "is in a hole of the source image, as the bundle's manifest lists: %s; it reads as zeros, "
                             "so it does not match the digest %s records" % (HOLE_CAUSE_TEXT, copy_words)))
        elif _hs == "bundle-absent":
            out.append((idx, "is not carried by this bundle; it reads as zeros, so it does not match the digest %s "
                             "records" % copy_words))
        elif _hs is not None:
            out.append((idx, "reads as zeros inside an image hole (%s), so it does not match the digest %s records"
                        % (HOLE_CAUSE_TEXT, copy_words)))                                   # N406 (N11): one text
        else:
            out.append((idx, "does not match the digest %s records for it" % copy_words))
    return out


# ─── N373: the tests refs.sys makes of a checkpoint record ─────────────────────────────────────────────────────
# N373 (wave C; WAVEC_BRIEF Q7, decision 43 Q-M1; C2_LEAD_SETTLEMENTS ST-C1, ST-C2, N-1): CmsVolume::
# ValidateCheckpointRecord (17134; its lambda `ValidateCheckpointRecord'::<lambda_1>` on 26100.x and Insider 29574)
# tests every checkpoint copy in BOTH passes of ReadLatestCheckpoint, before and independently of the strict pass's
# root reads (V8). size = the record, one cluster (E118):
#   V1  the self-checksum (`_verify_self_checksum`; unchanged);
#   V2  the root count n = u32 +0x90: 4 < n <= size / 4;
#   V3  with flag +0x78 & 0x200 (the offset table at the u32 +0x94; 26100.x and Insider only): VersionCheck(0x30B) --
#       the volume version 3.11 or later --, +0x94 + +0x98 <= size, +0x98 >= 4 and +0x98 >= 4n;
#   V5  each of the n root offsets (SmsCheckpointRecord::GetGlobalTableOffset: the table at 0x94, or at the offset the
#       u32 +0x94 holds with flag 0x200): >= 4n + K, <= size, offset + 0x28 <= size, 8-byte aligned, the digest length
#       at descriptor +0x24 <= size and offset + 0x28 + length <= size; K = 0x98 (17134), 0xA8 (26100.x), 0xB0
#       (Insider 29574);
#   V7  the area +0x88 / +0x8C: 26100.x / Insider: length 0, or 4n + K <= offset and offset + length <= size; 17134:
#       length <= size, offset <= size, (4n + K <= offset or length 0), offset + length <= size;
#   V4, V6  26100.8972, .9444, .9549 and .9711 only (A124), each gated by a feature the volume does not record: n < 0x1B
#       (Feature_2834018616) and every root digest length <= 0x20 (Feature_1069541689) -- stated, never part of the
#       choice and no exit (decision 43; ST-C2 corrected its build list).
# Read twice (WAVEC_READING_bootstrap V1-V8, the chkp_a RED stage; KNOWLEDGE_INTAKE A62, A72): 17134
# refs_win10.decomp.c:118527-118583, 26100.8115 refs_win11.decomp.c:217196-217253, 26100.8972 refs.decomp.c:216238-
# 216267, 26100.9549 refs.decomp.c:216425-216467, Insider 29574 winsider-refs.decomp.c:285228-285291. A copy that any
# build whose tests apply rejects (V2, V3, V5, V7) leaves the choice as a self-checksum failure does (N-1, D-1). A
# build's tests apply only to volumes that build mounts (ST-C1): 17134 mounts version 3.4 or lower (RefsMountVolume,
# intake A68), so its tests apply only there, to a record without flag 0x200; elsewhere nothing is said about 17134.
# The volume version is the one the boot sector the volume is read from records (`boot_sector_copy`), the version
# RefsMountVolume tests. VersionCheck's operand (CmsVolume+0x844 / +0x845 on 26100.x, +0x894 / +0x895 on Insider) is
# that boot sector's +0x28 / +0x29 (Q40, read at instruction level on 26100.8115, 26100.9711 and Insider 29574: the
# call RefsMountVolume -> MsInitializeVolume -> the CmsVolume constructor; `LD/LD_NOTES.md`).
_CHKP_TEST_K = {"17134": 0x98, "26100": 0xA8, "29574": 0xB0}
_CHKP_BUILD_WORD = {"17134": "17134", "26100": "26100", "29574": "Insider 29574"}
_CHKP_FEATURE_BUILDS = "26100.8972, .9444, .9549 and .9711"     # A124 (Q4's second reading): .9711 has both


def chkp_record_builds(raw, version):
    """N373 (ST-C1): the refs.sys builds whose `ValidateCheckpointRecord` tests apply to this record: 26100.x and
    Insider 29574 always; 17134 only on a volume of version 3.4 or lower (the only volumes it mounts) and a record
    without flag 0x200 (17134 has no indirect offset table). `version` = (major, minor), or None when not known."""
    builds = ["26100", "29574"]
    if version is not None and tuple(version) <= (3, 4) and not le32(raw, 0x78) & 0x200:
        builds.insert(0, "17134")
    return builds


def _chkp_builds_words(builds):
    w = [_CHKP_BUILD_WORD[b] for b in ("17134", "26100", "29574") if b in builds]
    return w[0] if len(w) == 1 else ", ".join(w[:-1]) + " and " + w[-1]


def _chkp_root_word(i):
    """'root 2 (Container Allocator)', 'root 0xc (Small Allocator)' -- the index as `_root_fail_text` writes it."""
    lab = _ROOT_LABELS[i] if 0 <= i < len(_ROOT_LABELS) else None
    return ("root 0x%x" % i if i >= 10 else "root %d" % i) + (" (%s)" % lab if lab else "")


def _chkp_sum(a, b, build):
    """C2-7 (1.14.0, the conformance batch): the sum of two u32 fields as `build`'s test makes it -- in 32 bits on 17134
    and 26100.x, which wrap, in 64 bits on Insider 29574 (KNOWLEDGE_INTAKE A124: the offset table's +0x94 + +0x98 and
    the area's +0x88 + +0x8C; 26100.x read twice; 17134's area and Insider's widths read twice too -- the decompilation
    and the instructions: 17134 `add %ecx,%eax` (AT&T) at 0x1c00665ec, Insider `add %rdx,%rcx` / `add %rax,%rcx` (AT&T) of zero-extended
    u32 loads at 0x140128a88 / 0x140128bd6; the batch's review N2). The tool added them without
    a wrap, so a crafted record whose sum passes 2^32 was called rejected by 26100 where its test passes."""
    return a + b if build == "29574" else (a + b) & 0xFFFFFFFF


def _chkp_build_failures(raw, cs, build, version):
    """N373: [(key, text, bound)] of the tests of `build` (`chkp_record_builds`) this record fails, in the driver's
    order. `bound` is the 4n + K this build compares with ('4 x 13 + 0xa8 = 0xdc') when the text ends in it, else
    None.
    V5 and V7 are made only when V2 and V3 pass (the offsets they test depend on n and on the table); each root is
    named with the first of its tests it fails, as the driver stops there."""
    size = min(len(raw), cs)
    out = []
    n, flag = le32(raw, 0x90), le32(raw, 0x78) & 0x200
    if not 4 < n <= size // 4:
        out.append(("count", "its root count at +0x90 is %d, where more than 4 and at most %d (the record's size / 4) "
                    "are allowed" % (n, size // 4), None))
    if flag and build != "17134":
        t94, t98 = le32(raw, 0x94), le32(raw, 0x98)
        # V3's version clause, `!VersionCheck(0x30b)`: (major << 8 | minor) of CmsVolume+0x844 / +0x845 (26100.x;
        # +0x894 / +0x895 on Insider) below 3.11 rejects. Q40, read at instruction level in 26100.8115, 26100.9711
        # and Insider 29574 (`LD/LD_NOTES.md`): those bytes are the boot sector's +0x28 / +0x29 as RefsMountVolume
        # read it (26100.x: RefsReadWriteBootSector's buffer; Insider: ReadBootSectorForMount's, VCB+0x3400), passed
        # through MsInitializeVolume to the CmsVolume constructor -- the volume's version, not the driver's. (The
        # batch's review M2 had made the clause "not determined" while that operand was not traced.)
        if version is not None and tuple(version) < (3, 11):
            out.append(("table-version", "it uses the indirect offset table (+0x78 flag 0x200), which needs a volume "
                        "of version 3.11 or later; the boot sector records %d.%d" % tuple(version), None))
        if _chkp_sum(t94, t98, build) > size:                     # C2-7: the driver's width
            out.append(("table-end", "its indirect offset table at +0x94 = 0x%x with length +0x98 = 0x%x runs past "
                        "the end of the record (0x%x bytes)" % (t94, t98, size), None))
        if t98 < 4 or t98 < 4 * n:
            out.append(("table-short", "its indirect offset table length +0x98 = 0x%x is below %s"
                        % (t98, "4" if t98 < 4 else "4 x %d roots = 0x%x" % (n, 4 * n)), None))
    if out:
        return out
    k = _CHKP_TEST_K[build]
    lo = 4 * n + k
    bound = "4 x %d + 0x%x = 0x%x" % (n, k, lo)
    base = le32(raw, 0x94) if flag else 0x94
    for i in range(n):
        oe = base + 4 * i
        rw = _chkp_root_word(i)
        if oe + 4 > size:
            out.append((("root", i, "table"), "the offset table entry of %s (at 0x%x) lies past the end of the record "
                        "(0x%x bytes)" % (rw, oe, size), None))
            break
        off = le32(raw, oe)
        if off < lo:
            out.append((("root", i, "low"), "%s has its descriptor at offset 0x%x, below" % (rw, off), bound))
        elif off + 0x28 > size:
            out.append((("root", i, "past"), "%s has its descriptor at offset 0x%x, which runs past the end of the "
                        "record (0x%x + 0x28 > 0x%x)" % (rw, off, off, size), None))
        elif off % 8:
            out.append((("root", i, "align"), "%s has its descriptor at offset 0x%x, which is not a multiple of 8"
                        % (rw, off), None))
        else:
            ln = le32(raw, off + 0x24)
            if ln > size or off + 0x28 + ln > size:
                out.append((("root", i, "digest"), "the digest length of %s, 0x%x (descriptor +0x24), runs past the "
                            "end of the record (0x%x + 0x28 + 0x%x > 0x%x)" % (rw, ln, off, ln, size), None))
    a88, l8c = le32(raw, 0x88), le32(raw, 0x8C)
    area = "the area at +0x88 = 0x%x (length +0x8c = 0x%x)" % (a88, l8c)
    if build == "17134":
        past = l8c > size or a88 > size or _chkp_sum(a88, l8c, build) > size
        low = l8c != 0 and a88 < lo
    else:
        past = l8c != 0 and a88 >= lo and _chkp_sum(a88, l8c, build) > size
        low = l8c != 0 and a88 < lo
    if low:
        out.append(("area-low", "%s begins below" % area, bound))
    if past:
        out.append(("area-past", "%s runs past the end of the record (0x%x bytes)" % (area, size), None))
    return out


def _chkp_feature_failures(raw, cs):
    """N373 / decision 43 (Q-M1): [(feature, text)] of the two feature-gated tests (V4, V6) of 26100.8972, .9444 and
    .9549 this record fails. The volume does not record whether the feature is enabled, so neither is part of the
    choice."""
    size = min(len(raw), cs)
    out = []
    n, flag = le32(raw, 0x90), le32(raw, 0x78) & 0x200
    if n >= 0x1B:
        out.append(("Feature_2834018616", "its root count at +0x90 is %d, 0x1b or more" % n))
    base = le32(raw, 0x94) if flag else 0x94
    for i in range(min(n, size // 4)):
        oe = base + 4 * i
        if oe + 4 > size:
            break
        off = le32(raw, oe)
        if off + 0x28 <= size and le32(raw, off + 0x24) > 0x20:
            out.append(("Feature_1069541689", "the digest length of %s, 0x%x (descriptor +0x24), is more than 0x20"
                        % (_chkp_root_word(i), le32(raw, off + 0x24))))
    return out


def chkp_record_tests(raw, cs, version=None):
    """N373 (single_source.tsv row `chkp_record_tests`): THE tests refs.sys makes of one checkpoint record (V2, V3,
    V5, V7 per build; V4, V6 feature-gated; the block comment above). V1, the self-checksum, is
    `_verify_self_checksum`'s. Returns {builds: the builds whose tests apply (`chkp_record_builds`), fails: {build:
    [(key, text, bound)]}, rejected_by: the builds whose tests the record fails, feature: [(feature, text)]}."""
    builds = chkp_record_builds(raw, version)
    fails = {b: _chkp_build_failures(raw, cs, b, version) for b in builds}
    return {"builds": builds, "fails": fails, "rejected_by": [b for b in builds if fails[b]],
            "feature": _chkp_feature_failures(raw, cs)}


def _chkp_volume_version(f, ps):
    """N373: (major, minor) of the boot sector the volume at ps is read from (`boot_sector_copy`), or None.
    C2-2 (1.14.0): None too when that copy is a BACKUP: a backup can carry the version from before an upgrade (A113),
    and V3's version test made with it called every copy with the indirect offset table rejected by 26100 and Insider
    on an intact upgraded volume (REVIEW_C2_correctness N-1); the version-dependent tests (V3's version clause,
    17134's scope) are then not made, as the backup statement says (`_boot_sector_choose`)."""
    try:
        rec = boot_sector_copy(f, ps)
    except Exception:              # no boot sector this tool can read: the version-dependent tests are not made
        return None
    bs = rec["bytes"]
    if rec.get("source") == "backup":
        return None
    return (bs[0x28], bs[0x29]) if bs and len(bs) >= 0x2A else None


def chkp_reject_clause(t):
    """N373: 'refs.sys 26100 and Insider 29574 reject it: <each failed test>[; refs.sys 26100 accepts it]' for a
    `chkp_record_tests` result whose `rejected_by` is not empty -- one wording for every statement of a copy refs.sys
    rejects (the stale view, a copy not in use, no copy valid, refsanalysis supb's copy line, forefst deleted). A test
    only some of the rejecting builds fail names them; a bound that differs by build is given for each."""
    rej = t["rejected_by"]
    keys = []
    for b in rej:
        for key, _x, _bd in t["fails"][b]:
            if key not in keys:
                keys.append(key)
    parts = []
    for key in keys:
        hits = [(b, x, bd) for b in rej for kk, x, bd in t["fails"][b] if kk == key]
        bs = [b for b, _x, _bd in hits]
        text = hits[0][1]
        bounds = []
        for b, _x, bd in hits:
            if bd is not None and bd not in [y for y, _b in bounds]:
                bounds.append((bd, b))
        if len(bounds) == 1:
            text += " " + bounds[0][0]
        elif bounds:
            text += " " + " and ".join("%s (%s)" % (bd, _CHKP_BUILD_WORD[b]) for bd, b in bounds)
        if bs != rej:
            text += " (%s)" % _chkp_builds_words(bs)
        parts.append(text)
    acc = [b for b in t["builds"] if b not in rej]
    s = "refs.sys %s %s it: %s" % (_chkp_builds_words(rej), "rejects" if len(rej) == 1 else "reject", "; ".join(parts))
    if acc:
        s += "; refs.sys %s %s it" % (_chkp_builds_words(acc), "accepts" if len(acc) == 1 else "accept")
    return s


def chkp_feature_text(c, role_np):
    """N373 / decision 43 (Q-M1, ST-C2): the rc-neutral statement of a checkpoint copy that fails a feature-gated test
    (V4, V6) and that 26100 does not reject otherwise; `role_np` names the copy ('the checkpoint copy in use')."""
    feat = c["record_tests"]["feature"]
    names = []
    for name, _x in feat:
        if name not in names:
            names.append(name)
    return ("%s at LCN 0x%x (vclock %s): %s; refs.sys %s reject this copy when %s is enabled; the volume does not "
            "show whether %s" % (role_np, c["lcn"], c["vc"], "; ".join(x for _n, x in feat), _CHKP_FEATURE_BUILDS,
                                 " or ".join(names), "it is" if len(names) == 1 else "either is"))


def checkpoint_select(f, ps, cs, chkp_lcns, require_roots=False, version=None):
    """THE checkpoint selection: which checkpoint copy the driver uses, and what a caller needs to report a
    failed or stale copy. One definition (A11: single_source.tsv row `checkpoint_select`); refsanalysis
    imports it, and check_single_source.py fails on any checkpoint-clock comparison, max or sort outside it.

    The driver's rule (F1, read on refs.sys 17134, 26100.8115/.8521/.8972/.9444 and Insider 29574;
    F1_CHECKPOINT_TIE_READING.md): `ReadLatestCheckpoint` reads the copies in SUPERBLOCK LIST ORDER (slot 0
    first), skips a copy that fails validation, keeps the first valid copy and moves to a later one only when
    its CHKP+0x60 is STRICTLY greater (unsigned). On a tie the earlier slot stays chosen; the LCN value plays
    no part. "Valid" here (N373): the copy's own self-checksum does not fail, it has a root list that parses
    (with require_roots), and no refs.sys build whose tests apply rejects it (`chkp_record_tests`: the root count,
    the offset table, the root offsets, the area +0x88; `version` = the volume's (major, minor), by default the
    boot sector's). The feature-gated tests (V4, V6) are reported, never part of the choice (decision 43). Root
    blocks 0xc/7/8, which 26100.x also reads and verifies in its first pass, are checked for every copy
    (`root_fail`, N205) but do NOT change the choice: the copy is read if it can be read, and the caller says
    that the 26100 driver's first pass would reject it (PLAN_1.13.2 decision 20.8).

    Reads every listed copy and returns a dict:
      copies   one record per listed copy, in slot order: slot, lcn, raw (the bytes read: one cluster, the
               checkpoint record -- F11 / E118), sig_ok,
               vc (+0x60, the selection clock), vc_page (+0x10, the page-header clock), clock_divergence
               (+0x10 != +0x60: does not occur normally), flags (+0x78), cksum_ok (True / False, or None when
               no algorithm can check it -- None is NOT a failure), ckname, roots (parse_chkp's list, [] if
               it did not parse), read_error, parse_error, root_fail ([(root index, why)] for roots 0xc, 7, 8
               whose page does not read or does not match this copy's digest; `_chkp_root_failures`),
               root_unchecked (N332: the indices among 0xc, 7, 8 that could not be checked), root_unchecked_why
               (N362: [(root index, why)] for the same roots), role (decision 25.4: 'in use', 'tied', 'newest',
               'superseded', or None; N376: 'superseded' for every copy with a readable clock older than the copy in
               use, a candidate or not), unreadable (N374 / N384 / N394: the words for a copy of which nothing
               usable was read -- its read failed, with the cause; it lies past the end of the image; it carries no
               CHKP signature -- else None), record_tests (N373: `chkp_record_tests`, for a signed copy whose
               self-checksum does not fail; else None), rejected_by (N373: the builds whose tests reject the copy,
               [] when none or not tested)
      cands    the copies taken into account: a CHKP signature and a readable clock (and, with
               require_roots, a root list that parses -- bootstrap cannot read a volume without one)
      chosen   the driver's copy among the candidates whose self-checksum did not fail and that no refs.sys build
               rejects (N373); None if none is valid
      top      the candidates at the highest clock, in slot order; a tie is len(top) > 1
      newest   `chosen` when no candidate carries a higher clock than it; otherwise the first-listed
               candidate at the highest clock (a copy that failed). A failed copy TIED with a passing one is
               not "newer" than it.
      in_use   `chosen`, or `newest` when no copy is valid (the tool still reads that copy; the driver would
               refuse the mount)
      stale    a candidate that failed (its self-checksum, or a refs.sys test: N373) carries a strictly higher clock
               than `chosen`: the copy in use is older than the newest checkpoint on the volume
      ranked   the candidates newest first: `newest`, then the others by clock, earlier slot first on a tie
      newer_unused  (N361) the copies that are NO candidate because their root list cannot be read (with
               require_roots), whose +0x60 is strictly greater than the copy in use's: the volume is read from an
               older copy, so the view is stale whatever their self-checksum says. The first-listed one at the
               highest clock gets the role 'newest' when no candidate carries a clock as high as its own.
      version  (N373) the volume version the record tests were made with ((major, minor), or None)
      authoritative  (N369) the copy at the highest clock among the candidates AND `newer_unused`: `newest`, or
               the first-listed copy of `newer_unused` at the highest clock when its clock is above every
               candidate's (N361's shape: a newer copy whose root list cannot be read). The copy every label that
               names "the newest checkpoint" names -- `summary`'s PRIMARY, refsanalysis `supb`'s "newer" copy, the
               containers note, `deleted`'s header. None without a candidate. The volume is read from an older copy
               exactly when it is not `in_use` (`stale`, or N361's shape).
    """
    copies = []
    if version is None and chkp_lcns:
        version = _chkp_volume_version(f, ps)          # N373: the version-dependent tests (V3, 17134's scope)
    for slot, lcn in enumerate(chkp_lcns):
        rec = {"slot": slot, "lcn": lcn, "raw": b"", "sig_ok": False, "vc": None, "vc_page": None,
               "clock_divergence": False, "flags": 0, "cksum_ok": None, "ckname": None, "roots": [],
               "read_error": None, "parse_error": None, "root_fail": [], "root_unchecked": [],
               "root_unchecked_why": [], "offset": ps + lcn * cs, "unreadable": None, "record_tests": None,
               "rejected_by": []}
        copies.append(rec)
        try:
            # F11 / E118 (LB2): one cluster, the checkpoint record (see parse_chkp). N371: a reference past any file
            # offset raises
            raw = _seek_read(f, ps + lcn * cs, cs)
        except (OSError, OverflowError) as _e:
            rec["read_error"] = _e
            rec["unreadable"] = _chkp_read_error_text(_e)      # N394 (Q25): said with its cause in every form
            continue
        rec["raw"] = raw
        if 0 < len(raw) < cs:
            # WE-3 (N494, 1.14.0): the image ends inside the copy -- part of the record was read, so none of it is taken
            # (1.13.2-dev took the copy and called it "self-checksum FAILED" with no cause), in the boot sector's words
            rec["unreadable"] = "the image ends inside it (%d of %d bytes read)" % (len(raw), cs)
            continue
        rec["sig_ok"] = raw[:4] == b"CHKP"
        if not rec["sig_ok"]:
            # N374 (T1, T1a): a copy that was read but carries no signature has no clock and no field to decode;
            # what it is (a hole, all zeros, other bytes) is said once, in `_chkp_unreadable_text`'s words
            rec["unreadable"] = _chkp_unreadable_text(f, ps, cs, lcn, raw)
        try:
            _vc10, rec["flags"], rec["roots"] = parse_chkp(f, ps, cs, lcn)
        except Exception as _e:                  # a bad signature raises here too: the caller decides what to say
            rec["parse_error"] = _e
        try:
            if rec["sig_ok"] and len(raw) >= 0x18:
                rec["vc_page"] = le64(raw, 0x10)
                rec["vc"] = le64(raw, 0x60) if len(raw) >= 0x68 else rec["vc_page"]   # K037: the driver's clock
                rec["clock_divergence"] = rec["vc"] != rec["vc_page"]
                rec["cksum_ok"], rec["ckname"] = _verify_self_checksum(raw, cs)
        except Exception as _e:
            rec["parse_error"] = rec["parse_error"] or _e
        if rec["sig_ok"] and rec["cksum_ok"] is not False and len(raw) >= 0x98:
            # N373: refs.sys's record tests; not made for a copy whose self-checksum fails (V1 rejects it first, and
            # its bytes are not the record the volume wrote)
            rec["record_tests"] = chkp_record_tests(raw, cs, version)
            rec["rejected_by"] = rec["record_tests"]["rejected_by"]
        if rec["sig_ok"] and rec["parse_error"] is None and rec["roots"]:
            # N205: reported, never part of the choice (N332: and the roots that could not be checked)
            rec["root_fail"] = _chkp_root_failures(f, ps, cs, raw, rec["root_unchecked"], rec["root_unchecked_why"])

    cands = [c for c in copies if c["sig_ok"] and c["vc"] is not None and (c["roots"] or not require_roots)]

    def _driver_pick(seq):
        # F1: slot order; replace the kept copy only when the next one's +0x60 is STRICTLY greater.
        best = None
        for c in seq:
            if best is None or c["vc"] > best["vc"]:
                best = c
        return best

    # N373 (D-1, C2 N-1): a copy any applicable refs.sys build rejects leaves the choice, as a self-checksum failure does
    chosen = _driver_pick([c for c in cands if c["cksum_ok"] is not False and not c["rejected_by"]])
    top_vc = _driver_pick(cands)["vc"] if cands else None
    top = [c for c in cands if c["vc"] == top_vc]
    newest = chosen if (chosen is not None and chosen["vc"] == top_vc) else (top[0] if top else None)
    rest = [c for c in cands if c is not newest]
    ranked = ([newest] if newest is not None else []) + sorted(rest, key=lambda c: (-c["vc"], c["slot"]))
    in_use = chosen if chosen is not None else newest
    # N361 (A1/K035; decision 28's reason: the copy is chosen by +0x60): a signed copy with a readable clock that is no
    # candidate because its root list cannot be read, and whose +0x60 is strictly greater than the copy in use's, is
    # not used -- the volume is read from an older copy, so the view is stale. What the driver does with a copy without
    # a root list is not traced; this is what THIS tool reads. Computed here because it compares clocks (A11 lint).
    newer_unused = [c for c in copies if c["sig_ok"] and c["vc"] is not None and not any(c is x for x in cands)
                    and in_use is not None and c["vc"] > in_use["vc"]]
    _nu_top = _driver_pick(newer_unused)
    # Decision 25.4: each copy's role in words -- in use, tied, newest, superseded (None without a readable clock).
    # Computed HERE because it compares clocks, and no clock comparison may live outside this function (A11 lint).
    # N376 (Q26: `use` on every copy, K18's words): 'superseded' is every copy with a readable clock older than the copy
    # in use -- also one that is no candidate (its root list cannot be read); 1.13.2-dev gave such a copy no role (null
    # `use`). A copy without a readable clock keeps None (no word of 25.4 fits it: N376 RED D-6). A copy that is no
    # candidate and carries the same clock as the copy in use keeps None too (not 'tied': `top`, `checkpoint_tie` and
    # `tied_clock` are the candidates'; 0 corpus volumes, a note for the conformance batch).
    for c in copies:
        c["role"] = ("in use" if c is in_use else
                     "tied" if len(top) > 1 and any(c is t for t in top) else
                     "newest" if c is newest or (c is _nu_top and (top_vc is None or c["vc"] > top_vc)) else
                     "superseded" if c["vc"] is not None and in_use is not None and c["vc"] < in_use["vc"]
                     else None)
    # N369: the newest copy on the volume, the candidates' or a newer copy whose root list cannot be read (its role is
    # 'newest' above); computed here because it compares clocks (A11 lint)
    authoritative = _nu_top if (_nu_top is not None and (top_vc is None or _nu_top["vc"] > top_vc)) else newest
    return {"copies": copies, "cands": cands, "chosen": chosen, "top": top, "newest": newest,
            "in_use": in_use, "stale": chosen is not None and newest is not chosen, "ranked": ranked,
            "newer_unused": newer_unused, "authoritative": authoritative, "version": version}


def _chkp_copy_error(c):
    """The error a reader of the checkpoint copies records as a skip for copy `c` of checkpoint_select: its parse error
    when it carries a CHKP signature. N374: a copy that was read and carries NO signature is the `unreadable` view
    condition of `_checkpoint_conditions` (exit 2 there, worded without a cause), so the parse error of it -- which used
    to blame the superblock's pointer -- is not recorded a second time. N394 (Q25): neither is the read error of a copy
    whose read failed -- the same `unreadable` view condition, which names the copy and the cause (1.13.2-dev recorded
    it as an anonymous skip, "bootstrap skipped a bootstrap structure: OffsetTooLarge: ...", and only the summaries'
    redundancy lists named the copy)."""
    if c["read_error"] is not None:
        return None
    return c["parse_error"] if c["sig_ok"] else None


def _chkp_role(sel, c):
    """A checkpoint copy's role in words (PLAN_1.13.2 decision 25.4): 'in use', 'tied', 'newest', 'superseded',
    or None when the copy carries no readable clock -- as checkpoint_select assigned it."""
    return c.get("role")


def _chkp_not_used_why(sel, c):
    """N369: why the volume is not read from checkpoint copy `c` -- a copy newer than the copy in use, checkpoint_select's
    `authoritative` when it is not `in_use`: it FAILED its self-checksum (a stale view), its root list could not be read
    (N361's shape), or both; or (N373) refs.sys rejects it (`chkp_reject_clause`). A few words, one text for refsanalysis `supb` (-v, --verify), `containers` and forefst
    `deleted`; the whole condition is `_checkpoint_conditions`' (the stale view, N361's `newer-unused`)."""
    _rl = "its root list could not be read (%s)" % (c["parse_error"] or "no root references")
    rootless = any(c is x for x in sel.get("newer_unused", ()))
    if c["cksum_ok"] is False:
        return "FAILED its self-checksum" + (", and %s" % _rl if rootless else "")
    if c.get("rejected_by"):
        # N373: a copy refs.sys rejects (its root count, offset table, root offsets or area at +0x88) -- never said
        # to fail its self-checksum, which it passes or which cannot be verified
        return (_rl + ", and " if rootless else "") + chkp_reject_clause(c["record_tests"])
    return _rl


def _chkp_copy_np(role):
    """A checkpoint copy named with its role (decision 25.4): 'the newest checkpoint copy', 'the superseded ...', 'the
    tied ...', but 'the checkpoint copy in use' -- "in use" follows the noun (N334); 'the checkpoint copy' without one."""
    if role == "in use":
        return "the checkpoint copy in use"
    return "the %scheckpoint copy" % (role + " " if role else "")


def _root_fail_text(root_fail):
    """N205/N332: the roots 0xc, 7, 8 of one checkpoint copy that did not verify, in one wording for
    `_checkpoint_conditions` and refsanalysis `chkp --verify`: 'root 7 (Container Table) does not match ...'."""
    return "; ".join("root 0x%x (%s) %s" % (i, _ROOT_LABELS[i], why) if i == 0xC else
                     "root %d (%s) %s" % (i, _ROOT_LABELS[i], why) for i, why in root_fail)


def _root_unchecked_text(unchecked_why):
    """N362 (decision 27.3's rule, applied to roots): the roots 0xc, 7, 8 of one checkpoint copy that could not be
    checked, in one wording -- 'cannot be verified', never 'failed' -- with the reason: 'root 7 (Container Table)
    cannot be verified (its reference declares checksum type 0x03, which this tool does not compute for a root page)'.
    What the driver does with such a reference was not traced and is not claimed."""
    return _root_fail_text([(i, "cannot be verified (%s)" % why) for i, why in unchecked_why])


def _root_check(c):
    """N361 / N364 (R6): THE result and wording of the roots 0xc, 7, 8 check of one checkpoint copy (a record of
    checkpoint_select) -- one wording for refsanalysis `supb --verify` (one row per copy) and `chkp --verify` (the copy
    it decodes). Returns (result, text): 'OK'; 'FAIL' when a root does not read or does not match the digest the copy
    records for it; 'WARN' when the check cannot be made -- the copy could not be read, carries no CHKP signature, has
    no root list that can be read, or records a root that cannot be verified (N362)."""
    if c["read_error"] is not None:
        return "WARN", "roots 0xc, 7 and 8 cannot be verified: this copy could not be read (%s)" % c["read_error"]
    if not c["raw"]:
        # N384: nothing was read (the copy lies past the end of the image) -- not "carries no CHKP signature"
        return "WARN", "roots 0xc, 7 and 8 cannot be verified: this copy could not be read (%s)" % c["unreadable"]
    if not c["sig_ok"]:
        return "WARN", "roots 0xc, 7 and 8 cannot be verified: this copy carries no CHKP signature"
    if c["parse_error"] is not None or not c["roots"]:
        return "WARN", ("roots 0xc, 7 and 8 cannot be verified: this copy's root list could not be read (%s)"
                        % (c["parse_error"] or "no root references"))
    _why = c.get("root_unchecked_why") or [(i, "not checked") for i in c["root_unchecked"]]
    parts = ([_root_fail_text(c["root_fail"])] if c["root_fail"] else []) + \
        ([_root_unchecked_text(_why)] if _why else [])
    if c["root_fail"]:
        return "FAIL", "; ".join(parts)
    if parts:
        return "WARN", parts[0]
    return "OK", "roots 0xc, 7 and 8 match this copy's digests"


# N205/N343: the 26100 first-pass rule, said for the copy in use (a `view` condition) and for a copy NOT in use (a
# `redundancy` condition, V-a) -- one wording; the text of the copy in use is unchanged by the split.
_N205_RULE = "The 26100 driver's first (strict) pass rejects a copy whose root 0xc, 7 or 8 does not read or verify"
_N205_BUILDS = "(Insider 29574 rejects a copy here only on a read error; 17134 makes no such check)"


def _chkp_rejected_va(sel, c):
    """N373 (C2 N-1 (b)): copy `c` is a candidate refs.sys rejects that is NOT in use while another copy is valid -- the
    V-a condition (`_checkpoint_conditions`' key ('chkp', lcn, 'rejected'), level `redundancy`; refsanalysis supb marks
    it on the copy's line). The rejected newest copy of a stale view, and no copy valid, are `view` conditions."""
    return (bool(c.get("rejected_by")) and c["cksum_ok"] is not False and any(c is x for x in sel["cands"])
            and sel["chosen"] is not None and c is not sel["in_use"] and not (sel["stale"] and c is sel["newest"]))


def _checkpoint_notes(sel):
    """N373 / decision 43 (Q-M1, ST-C2): the rc-NEUTRAL statements of the checkpoint pair -- a copy that fails a test
    26100.8972, .9444, .9549 and .9711 make only when a feature is enabled (V4, V6), when 26100 does not reject it otherwise.
    `summary`, `fastsummary`, `integrity` and refsanalysis `summary` print them with the redundancy notes
    (`_redundancy_notes`); no exit code and no choice changes."""
    out = [chkp_feature_text(c, _chkp_copy_np(_chkp_role(sel, c))) for c in sel["copies"]
           if c.get("record_tests") and c["record_tests"]["feature"] and "26100" not in c["rejected_by"]
           and c["vc"] is not None]
    return out


def _checkpoint_conditions(sel, cs):
    """N250: every condition of the checkpoint pair, each worded ONCE, from checkpoint_select's result.

    `bootstrap` prints and registers the `view` conditions -- they change what EVERY command reads, so every
    command exits 2 (register _CHKP_STALE). `summary`, `fastsummary` and `integrity` list ALL of them through
    `_redundancy_findings`, with the same text. 1.13.1 worded the same condition two or three ways across
    bootstrap, the redundancy scanner and `integrity`'s own inline list (N250, N243).
    Returns [(key, level, text)]; level is 'view' or 'redundancy'. Copies are named by LCN and role (in use,
    newest, superseded, tied; decision 25.4), never by "the copy the driver would use" (N206).
    """
    out = []
    use, newest, cands = sel["in_use"], sel["newest"], sel["cands"]

    def _k041(c):
        # K041: a copy whose stored own-LCN (+0x20) is not its LCN fails for that reason alone -- say whether
        # that is all the damage (the same suffix `_restored_note` gives the scanner's records).
        raw = c["raw"]
        if len(raw) < 0x28 or le64(raw, 0x20) == c["lcn"]:
            return ""
        return _restored_note({"cksum_ok_restored": _verify_with_own_lcn(raw, cs, c["lcn"])})

    def _rootless_state(c):
        # N361 / N372: a signed copy with a readable clock whose root list cannot be read -- its checksum state and why
        # this tool cannot read the volume from it, in one wording for the stale view (N361 b) and N372's text. N373:
        # and the refs.sys builds that reject it (a root count of 0 is V2's), the census's "N361/N362 wording adjusted"
        _rl = "its root list could not be read (%s)" % (c["parse_error"] or "no root references")
        _rj = ", and %s" % chkp_reject_clause(c["record_tests"]) if c.get("rejected_by") else ""
        return ("passes its self-checksum, but %s%s" % (_rl, _rj) if c["cksum_ok"] is True else
                "failed its self-checksum (%s)%s, and %s" % (c.get("ckname") or "?", _k041(c), _rl)
                if c["cksum_ok"] is False else
                "has a checksum that cannot be verified (%s), and %s%s" % (c.get("ckname") or "-", _rl, _rj))

    def _rejected_state(c):
        # N373: a candidate refs.sys rejects -- its checksum state (never "failed": it passes it or it cannot be
        # verified) and the builds and tests, one wording for the stale view, a copy not in use and no copy valid
        return ("passes its self-checksum, but " if c["cksum_ok"] is True else
                "has a checksum that cannot be verified (%s), and " % (c.get("ckname") or "-")) + \
            chkp_reject_clause(c["record_tests"])

    def _unusable_state(c):
        # N372 / N373: why a candidate cannot be used as it is (no copy is valid): its failed self-checksum, or refs.sys
        return ("failed its self-checksum (%s)%s" % (c.get("ckname") or "?", _k041(c)) if c["cksum_ok"] is False
                else _rejected_state(c))

    # N372 (C1): the signed copies with a readable clock that are no candidate -- their root list cannot be read
    _rootless = [c for c in sel["copies"] if c["sig_ok"] and c["vc"] is not None and not any(c is x for x in cands)]
    _rej_cands = [c for c in cands if c["cksum_ok"] is not False and c["rejected_by"]]      # N373
    if sel["chosen"] is None and cands and _rootless:
        # N372 (C1): no copy can be used as it is, and one of them is unusable for its root list. "No checkpoint copy
        # passes its self-checksum" may then be false (that copy can pass it), and the candidate this view is read from
        # need not be the newest copy. Each copy is named with why this tool cannot read the volume from it, in slot
        # order. N373: a copy refs.sys rejects is named with the builds and tests (a root count of 0 is V2's); when a
        # candidate is one, the lead-in names refs.sys's tests too (that copy passes its self-checksum and has a root
        # list). Key `none-usable`: not one of the two conditions `said_failed` callers word themselves.
        _each = "; ".join("the copy at LCN 0x%x (vclock %s) %s"
                          % (c["lcn"], c["vc"], _rootless_state(c) if any(c is r for r in _rootless) else
                             _unusable_state(c))
                          for c in sel["copies"] if c["sig_ok"] and c["vc"] is not None)
        out.append((("chkp", "none-usable"), "view",
                    "no checkpoint copy %s: %s; this view is read from the copy at LCN 0x%x (vclock %s) anyway"
                    % ("passes its self-checksum, has a root list that can be read and passes the tests refs.sys makes "
                       "of a checkpoint record" if _rej_cands else
                       "both passes its self-checksum and has a root list that can be read", _each, use["lcn"],
                       use["vc"])))
    elif sel["chosen"] is None and _rej_cands:
        # N373 (closure B-4.2 row 10; C2 N-1 (c)): no candidate is valid and at least one passes its self-checksum (or
        # cannot be verified) but is rejected by refs.sys -- "no checkpoint copy passes its self-checksum" would be
        # false. Each copy is named with why; the builds that reject every candidate refuse the mount (C2: none valid ->
        # 0xC0000032, V1-V7 in both passes); the newest copy is read anyway (row 10). A `view` condition: exit 2 in
        # every command. Key `none-valid`: not one of the two conditions `said_failed` callers word themselves.
        _each = "; ".join("the copy at LCN 0x%x (vclock %s) %s" % (c["lcn"], c["vc"], _unusable_state(c))
                          for c in cands)
        _all = None
        for c in cands:
            # a copy whose self-checksum fails is rejected by every build whose tests apply (V1)
            _b = set(c["rejected_by"] if c["cksum_ok"] is not False else
                     chkp_record_builds(c["raw"], sel.get("version")))
            _all = _b if _all is None else _all & _b
        _refuse = ("refs.sys %s would refuse to mount this volume; " % _chkp_builds_words(_all)) if _all else ""
        out.append((("chkp", "none-valid"), "view",
                    "no checkpoint copy passes the tests refs.sys makes of a checkpoint record: %s; %sthis view is read "
                    "from the newest copy (LCN 0x%x, vclock %s) anyway" % (_each, _refuse, newest["lcn"], newest["vc"])))
    elif sel["chosen"] is None and cands:
        # N139 D-3: no copy passes. The driver refuses the mount (0xC0000032, F1); the tool still reads one.
        out.append((("chkp", "none-passes"), "view",
                    "no checkpoint copy passes its self-checksum (%s): the driver would refuse to mount this "
                    "volume; this view is read from the newest copy (LCN 0x%x, vclock %s) anyway"
                    % (", ".join("LCN 0x%x" % c["lcn"] for c in cands), newest["lcn"], newest["vc"])))
    elif sel["stale"] and newest["cksum_ok"] is not False:
        # N373 (C2 N-1 (a); A1/K035 + N206): the newest copy passes its self-checksum (or it cannot be verified) but
        # refs.sys rejects it, so the volume is read from the older valid copy and the view is stale -- a `view`
        # condition, every command exits 2, in the stale view's words; never "failed its self-checksum" (N372's rule)
        out.append((("chkp", newest["lcn"], "rejected"), "view",
                    "the newest checkpoint copy (LCN 0x%x, vclock %s) %s; this view is read from the copy at LCN 0x%x "
                    "(vclock %s): changes committed after vclock %s are not in it"
                    % (newest["lcn"], newest["vc"], _rejected_state(newest), use["lcn"], use["vc"], use["vc"])))
    elif sel["stale"]:
        # A1/K035 + N206: the newest copy failed; the driver skips it and uses the older one, as this tool does.
        out.append((("chkp", newest["lcn"], "cksum"), "view",
                    "the newest checkpoint copy (LCN 0x%x, vclock %s) failed its self-checksum (%s)%s; the driver "
                    "skips a copy that fails and uses the copy at LCN 0x%x (vclock %s), which this view is read "
                    "from: changes committed after vclock %s are not in it"
                    % (newest["lcn"], newest["vc"], newest.get("ckname") or "?", _k041(newest),
                       use["lcn"], use["vc"], use["vc"])))
    for c in sel["copies"]:
        role = _chkp_role(sel, c)
        _in_use_words = ((", read from the copy at LCN 0x%x with vclock %s," % (use["lcn"], use["vc"]))
                         if use is not None else "")
        if c["read_error"] is not None:
            # N394 (WAVEC_BRIEF Q25, T1; decision 28's reason): a copy whose read fails -- the host refuses it, or the
            # tool does (an offset past any file offset, N371) -- has no clock either, so whether the view is read from
            # the newest checkpoint cannot be known: the `view` condition of N374's copy without a signature, under the
            # same key (refsanalysis chkp says both in their own block), every command of both tools exits 2. Named
            # with its cause; 1.13.2-dev filed it as `redundancy` (key 'damaged'), so the commands that read through
            # the copy in use recorded an anonymous skip and refsanalysis supb exited 0.
            out.append((("chkp", c["lcn"], "unreadable"), "view",
                        "the checkpoint copy at LCN 0x%x (offset 0x%x) could not be read (%s). It has no clock this "
                        "tool can read, so whether this view%s is read from the newest checkpoint cannot be known"
                        % (c["lcn"], c.get("offset", 0), c["read_error"], _in_use_words)))
            continue
        if not c["sig_ok"]:
            # N374 (T1, settled by the lead; decision 28's reason): a copy that was read but carries no CHKP signature
            # -- an image hole, all zeros, other bytes -- has no clock either, and the copy in use is chosen by +0x60,
            # so whether the view is read from the newest checkpoint cannot be known: a `view` condition (every command
            # of both tools exits 2). No field is decoded from it (T1a); a hole is stated with C8 = B's sentence, zeros
            # as "all zeros" with no cause (S6) -- `_chkp_unreadable_text`. N384: a read that returned no byte is a copy
            # past the end of the image, said with that cause (Q25).
            out.append((("chkp", c["lcn"], "unreadable"), "view",
                        "the checkpoint copy at LCN 0x%x (offset 0x%x) is unreadable: %s. It has no clock this tool "
                        "can read, so whether this view%s is read from the newest checkpoint cannot be known"
                        % (c["lcn"], c.get("offset", 0), c.get("unreadable") or "it carries no CHKP signature",
                           _in_use_words)))
            continue
        if c["clock_divergence"]:
            # Decision 28: a +0x10/+0x60 divergence on EITHER copy is a `view` condition (every command exits 2). N361
            # (c): tested before the root-list branch below, which `continue`s for a newer copy -- a copy whose root list
            # cannot be read still carries both clocks, and its divergence went unsaid.
            out.append((("chkp", c["lcn"], "clocks"), "view",
                        "checkpoint copy at LCN 0x%x: clock mismatch, page header +0x10 = %s vs selection clock "
                        "+0x60 = %s (the driver compares +0x60; the two are equal on every corpus copy, so a "
                        "difference points to an edited page)" % (c["lcn"], c["vc_page"], c["vc"])))
        if c["parse_error"] is not None or not c["roots"]:
            _rl = "its root list could not be read (%s)" % (c["parse_error"] or "no root references")
            if any(c is x for x in sel.get("newer_unused", ())):
                # N361 (A1/K035; decision 28's reason: the copy is chosen by +0x60): a copy with a higher clock than
                # the copy in use that this tool cannot read the volume from (no root list) makes the view stale, as a
                # newer copy that fails its self-checksum does -- a `view` condition, every command exits 2. Worded as
                # the stale view is; nothing is claimed about the driver (its handling of such a copy is not traced).
                out.append((("chkp", c["lcn"], "newer-unused"), "view",
                            "%s (LCN 0x%x, vclock %s) %s, so this tool does not read the volume from it; this view "
                            "is read from the copy at LCN 0x%x (vclock %s): changes committed after vclock %s are not "
                            "in it" % (_chkp_copy_np(role), c["lcn"], c["vc"], _rootless_state(c), use["lcn"],
                                       use["vc"], use["vc"])))
                continue
            out.append((("chkp", c["lcn"], "damaged"), "redundancy",
                        "the checkpoint copy at LCN 0x%x: %s%s"
                        % (c["lcn"], _rl, ", and %s" % chkp_reject_clause(c["record_tests"]) if c.get("rejected_by")
                           else "")))
            # N372 (C3): no `continue` here -- the self-checksum tests below still apply to this older copy (its
            # failure, or a checksum that cannot be verified, was not listed); it has no roots to test (root_fail and
            # root_unchecked are computed only for a copy with a root list)
        if _chkp_rejected_va(sel, c):
            # N373 (C2 N-1 (b); V-a, decision 20.3, as a copy not in use that fails its self-checksum): a candidate not in
            # use that refs.sys rejects -- `summary`, `fastsummary`, `integrity`, refsanalysis `summary` and `supb` say
            # it and exit 2; the commands that only read through the copy in use keep their exit code
            out.append((("chkp", c["lcn"], "rejected"), "redundancy",
                        "%s at LCN 0x%x (vclock %s) %s; the copy in use is LCN 0x%x (vclock %s)"
                        % (_chkp_copy_np(role), c["lcn"], c["vc"], _rejected_state(c), use["lcn"], use["vc"])))
        if c["cksum_ok"] is False and sel["chosen"] is not None and not (sel["stale"] and c is newest):
            out.append((("chkp", c["lcn"], "cksum"), "redundancy",
                        "%s at LCN 0x%x (vclock %s) failed its self-checksum (%s)%s%s"
                        % (_chkp_copy_np(role), c["lcn"], c["vc"], c.get("ckname") or "?", _k041(c),
                           "; the copy in use is LCN 0x%x (vclock %s)" % (use["lcn"], use["vc"])
                           if role == "tied" else "")))
        if c["cksum_ok"] is None:
            # N238 / C10: not "failed" -- the checksum cannot be verified. Decision 22: a finding (exit 2) in
            # summary/integrity; what the driver does with such a copy was not traced and is not claimed.
            # Decision 27.3: when it is the copy IN USE -- the one the volume view is read from -- it is a `view`
            # condition (every command exits 2, as for a root failure of that copy); a copy not in use keeps V-a.
            out.append((("chkp", c["lcn"], "unverified"), "view" if c is use else "redundancy",
                        "%s at LCN 0x%x (vclock %s): checksum cannot be verified (%s)"
                        % (_chkp_copy_np(role), c["lcn"], c["vc"], c.get("ckname") or "-")))
        if c is not use and c["root_fail"]:
            # N343 (V-a, decision 20.3, as for a copy not in use that fails its self-checksum): a root 0xC, 7 or 8
            # that does not verify against this copy's digest is a redundancy condition -- `summary`, `fastsummary`,
            # `integrity` and refsanalysis `summary` list it and exit 2; the commands that only read through the copy
            # in use keep exit 0. 1.13.2-dev computed it (`root_fail`) and said it nowhere but `integrity --json`.
            out.append((("chkp", c["lcn"], "roots"), "redundancy",
                        "%s at LCN 0x%x (vclock %s): %s. %s %s"
                        % (_chkp_copy_np(role), c["lcn"], c["vc"], _root_fail_text(c["root_fail"]), _N205_RULE,
                           _N205_BUILDS)))
        _unchecked = c.get("root_unchecked_why") or [(i, "not checked") for i in c["root_unchecked"]]
        if _unchecked:
            # N362 (decision 27.3's rule, applied to roots): a root 0xC, 7 or 8 that cannot be checked -- no reference,
            # or a checksum type this tool does not compute for a root page -- "cannot be verified", never "failed".
            # On the copy in use the view is read through it: a `view` condition (every command exits 2); on a copy not
            # in use V-a (`redundancy`: summary, fastsummary, integrity and refsanalysis summary). 1.13.2-dev reported
            # it only in refsanalysis `supb --verify` and `chkp --verify`.
            out.append((("chkp", c["lcn"], "roots-unverified"), "view" if c is use else "redundancy",
                        "%s at LCN 0x%x (vclock %s): %s"
                        % (_chkp_copy_np(role), c["lcn"], c["vc"], _root_unchecked_text(_unchecked))))
    if use is not None and use["root_fail"]:
        # N205 (decision 20.8 / 21): read it if it can be read, say what the 26100 driver does with it, exit 2.
        _bad = [_root_fail_text(use["root_fail"])]
        others = [c for c in sel["copies"] if c is not use and c["sig_ok"] and c["roots"]]
        # N362: a copy with a root that could not be checked is not said to pass that pass
        if others and all(o["cksum_ok"] is True and not o["root_fail"] and not o["root_unchecked"] for o in others):
            _then = ("the other copy (LCN %s) passes that pass, so that driver would mount the volume from it, not "
                     "from the copy this view is read from" % ", ".join("0x%x" % o["lcn"] for o in others))
        elif others and all(o["cksum_ok"] is False or o["root_fail"] for o in others):
            _then = ("the other copy fails that pass too, so that driver accepts this copy only in its relaxed "
                     "second pass, which does not check these roots")
        else:
            _then = ("that driver uses the other copy when that one passes, and accepts this copy only in its "
                     "relaxed second pass when neither passes")
        out.append((("chkp", use["lcn"], "roots"), "view",
                    "the checkpoint copy in use (LCN 0x%x, vclock %s) %s, but %s. %s: %s %s"
                    % (use["lcn"], use["vc"],
                       "passes its self-checksum" if use["cksum_ok"] is True else "is read",
                       "; ".join(_bad), _N205_RULE, _then, _N205_BUILDS)))
    # Q40 (E134; the maintainer, 2026-11-06: say it, never block): after the choice, refs.sys 26100 and Insider fail
    # the mount (0xC000014F) when the record in use holds a u16 above 0xff at +0x50 or +0x52, or a version (+0x50,
    # +0x52) above the boot sector's (+0x28, +0x29: `VersionCheck`'s operand, read at instruction level in
    # 26100.8115, .9711 and Insider 29574). The volume is read as it is. `sel["version"]` is the primary boot
    # sector's (`_chkp_volume_version`: None from a backup, so nothing is said then); 17134's operand was not traced.
    ver = sel.get("version")
    if use is not None and ver is not None and len(use["raw"]) >= 0x54:
        rmaj, rmin = le16(use["raw"], 0x50), le16(use["raw"], 0x52)
        if rmaj > 0xFF or rmin > 0xFF or (rmaj, rmin) > tuple(ver):
            out.append((("chkp", use["lcn"], "record-version"), "view",
                        "the checkpoint copy in use (LCN 0x%x, vclock %s) records version %d.%d (+0x50, +0x52), above "
                        "the %d.%d its boot sector records: refs.sys 26100 and Insider 29574 fail the mount after "
                        "choosing it (0xC000014F); the volume is read as it is"
                        % (use["lcn"], use["vc"], rmaj, rmin, ver[0], ver[1])))
    return out


def _view_conditions(sel, cs, said_failed=False, register=True):
    """THE checkpoint conditions that change what EVERY command reads -- the `view` level of `_checkpoint_conditions`
    (a stale view -- a newer copy that fails its self-checksum, or one whose root list cannot be read (N361) --, no
    copy passing, a +0x10/+0x60 clock divergence, a copy in use whose root 0xc/7/8 fails or cannot be verified (N362)
    or whose checksum cannot be verified, a copy of which nothing usable was read -- its read failed, it lies past the
    end of the image, it carries no CHKP signature (N394, N384, N374) --, and whatever `view` condition comes next) --
    as their texts. `bootstrap`
    says them on stderr; refsanalysis `supb`, `chkp` and `containers`, which select the checkpoint themselves instead
    of through bootstrap, say them too (N332, N341: decision 21, every command exits 2). Taking the LEVEL, not a list
    of keys, is what keeps the two sets equal: N341's clock divergence was missed by a list. With `register` each text
    is recorded in `_CHKP_STALE` (rc_escalate: exit 2).

    said_failed (N341): the caller already says, in its own words and with exit 2 (N207), the two conditions that a
    checkpoint copy FAILED its self-checksum -- the newest copy failed and an older one is read (key `cksum`), and no
    copy passes (`none-passes`). They are left out of the result and not registered, so they are not said twice; the
    caller's own exit code covers them."""
    out = []
    for key, level, text in _checkpoint_conditions(sel, cs):
        if level != "view":
            continue
        if said_failed and (key == ("chkp", "none-passes") or key[2:] == ("cksum",)):
            continue
        out.append(text)
        if register and text not in _CHKP_STALE:
            _CHKP_STALE.append(text)
    return out

def _copy_redundancy_conditions(sel, cs, copy):
    """N578 (1.14.0): the `redundancy` conditions of ONE checkpoint copy, in `_checkpoint_conditions`' words -- what
    `summary` says of that copy as a copy not in use (it fails its self-checksum, its checksum cannot be verified,
    refs.sys rejects it, a root 0xC/7/8 does not verify). Matched on the copy's own LCN, the second element of each
    condition's key; no clock is read or compared (A11). For a command that reads that copy (`deleted`'s comparison)."""
    return [t for k, lvl, t in _checkpoint_conditions(sel, cs)
            if lvl == "redundancy" and len(k) >= 3 and k[1] == copy["lcn"]]


# ─── Container Table + Translator ─────────────────────────────────────
# ─── Allocator (schema 0xe010) ─────────────────────────────────────────
# Reference: structure_reference.md B.2 / B.2a / B.2b, erratum E74. The row is NOT a fixed 2,072 bytes and
# three of its fields were previously mis-documented; the notes below record only what the driver actually
# does, because a capacity figure built on the wrong field is worse than none at all.
_ALLOC_TIERS = ((1, "Medium", 0x21), (2, "Container", 0x20), (12, "Small", 0x22))
_POPCOUNT = bytes(bin(i).count("1") for i in range(256))


def alloc_decode_row(vd):
    """Decode one allocator row. Returns None if it is not one.

    E74: `flags` bit 0 — not the row length — says whether a bitmap follows, the bitmap offset is the BYTE at
    +0x14 (the byte at +0x15 is a tier/format marker, not part of a u16 "header size"), and the bitmap runs
    for ceil(range_length/8) bytes, so the row is variable-length. The count at +0x16 is a driver hint that
    disagrees with the bitmap on ~14% of rows and is deliberately NOT used for arithmetic here.
    """
    if len(vd) < 0x18:
        return None
    start, length = struct.unpack_from("<QQ", vd, 0x00)
    free_u16, flags, hdr, alloc_hint = struct.unpack_from("<4H", vd, 0x10)
    bmoff, fmt = hdr & 0xFF, hdr >> 8
    r = {"start": start, "length": length, "flags": flags, "bitmap_offset": bmoff, "format": fmt,
         "free_u16": free_u16, "alloc_hint": alloc_hint, "bitmap": None}
    if flags & 1:
        need = ((int(length) + 7) // 8 + 7) & ~7
        if not bmoff or bmoff + need > len(vd):
            return None
        r["bitmap"] = vd[bmoff:bmoff + need]
    return r


def alloc_row_counts(r):
    """(allocated, free) clusters for one decoded row — never reads a saturating field as a number.

    Bitmap row: popcount over exactly `length` bits. Compact row: uniform, and the discriminator is
    `free_u16` (0 = fully allocated, non-zero = fully free) — NOT the +0x16 hint (E74).
    """
    L = int(r["length"])
    bm = r["bitmap"]
    if bm is None:
        return (L, 0) if r["free_u16"] == 0 else (0, L)
    whole, rem = divmod(L, 8)
    pc = sum(_POPCOUNT[b] for b in bm[:whole])
    if rem:
        pc += _POPCOUNT[bm[whole] & ((1 << rem) - 1)]
    return pc, L - pc


def alloc_read_summary(f, ps, cs, tr, roots, root_idx, table_id=None, volume_clusters=None,
                       status=None):
    """The summary ReFS keeps in an allocator table's ROOT page (416 bytes, E110), first 48 u64s (or None).

    One page read — no tree walk — so a caller can report capacity for free. Slot 1 = clusters covered,
    slot 2 = clusters NOT ALLOCATED (E74 / B.2b / E114) -- Windows' free clusters plus the ones it holds in
    reserve, so more than Windows calls free; the rest are undecoded. This is the volume's OWN accounting.

    `table_id` makes the read refuse a root page that does not claim this tier's own table: a root INDEX is
    not a tier (root 12 has been seen carrying the Container Table on a damaged volume), and reading 384
    bytes out of the wrong table's page yields confident nonsense. `volume_clusters` adds the obvious
    plausibility bound.
    """
    try:
        if root_idx >= len(roots) or not roots[root_idx]:
            return _outcome(status, None)
        lcn = roots[root_idx][0]
        p = lcn if root_idx in _CT_ROOT_INDICES else (tr.tr(lcn) if tr else lcn)
        pg = _seek_read(f, ps + p * cs, cs)                              # N371
        if pg[:4] != b"MSB+" or len(pg) < 0x58:
            return _outcome(status, None)
        if table_id is not None and le64(pg, 0x48) != table_id:
            return _outcome(status, None)
        base = 0x50 + le16(pg, 0x54)
        if base + 384 > len(pg):
            return _outcome(status, None)
        s = struct.unpack_from("<48Q", pg, base)
        if s[2] > s[1]:                                   # free can never exceed the span
            return _outcome(status, None)
        if volume_clusters is not None and s[1] > volume_clusters:
            return _outcome(status, None)
        return s
    except (OSError, OverflowError, struct.error) as _e:
        # The read failed: the volume's own accounting could not be consulted. Returning a bare None here
        # made that indistinguishable from "this table has no summary", so a capacity figure went missing
        # with nothing said. (A2-R)
        _skip_note("allocator summary", f"root {root_idx}", _e)
        return _outcome(status, None, _e)


def alloc_capacity(f, ps, cs, tr, roots, status=None):
    """Volume capacity from the Medium allocator's persisted summary (one page read).

    Returns None when the summary is unreadable. `covered` is the space the allocator accounts for: the whole volume
    (E162: its summary equals the volume's length on 117 of 117 corpus volumes); what an image holds after the volume
    is the image's, reported as the image tail, never as free.

    B3 (Q16, S-A): the volume is `volume_clusters` (total sectors x bytes per sector // cs), not the image's length:
    1.13.1 counted the image's bytes after the volume as "outside the allocator" (50331648 on base A, where the
    allocator covers the whole volume: MR-V s1 == N on 117 of 117 volumes) and refused the summary of an image cut
    short (covered > the clusters the image holds). The plausibility refusal `covered > N` keeps that bound.
    """
    try:
        vol = volume_clusters(f, ps, cs)
    except (OSError, OverflowError) as _e:
        _skip_note("allocator capacity", "the volume length", _e)
        return _outcome(status, None, _e)      # unknown capacity, NOT "the allocator reports nothing"
    s = alloc_read_summary(f, ps, cs, tr, roots, 1, table_id=0x21, volume_clusters=None)
    if not s:
        return _outcome(status, None)
    covered, free = s[1], s[2]
    if not covered:
        return _outcome(status, None)
    if covered > vol:
        # CB-7 (1.14.0, the conformance batch): the summary was READ, and it covers more clusters than the boot sector
        # gives the volume -- not used (as before), and why is said, not "unreadable"
        if status is not None:
            status["outcome"] = UNREADABLE
            status["reason"] = ("the Medium allocator's summary covers %s, more than the %s the boot "
                                "sector gives the volume" % (count_noun(covered, "cluster"), count_noun(vol, "cluster")))
        return None
    out = {"volume_clusters": vol, "covered_clusters": covered, "free_clusters": free,
           "used_clusters": covered - free, "outside_allocator_clusters": vol - covered,
           "cluster_size": cs, "format": s[0]}
    if covered < vol:
        # CB-7: the summary covers fewer clusters than the volume -- the two lengths disagree (u64[1] equals N on 117 of
        # 117 ReFS corpus volumes, MR-V): said as that, never as an ordinary "past the last container" figure
        out["length_disagreement"] = ("the Medium allocator's summary covers %s, %d fewer than the %s "
                                      "the boot sector gives the volume; what those clusters hold is not read"
                                      % (count_noun(covered, "cluster"), vol - covered, count_noun(vol, "cluster")))
    return out


def _select_ct_root(f, ps, cs, roots, chkp_raw=None):
    """The Container Table root this tool reads: `container_table_copy`'s choice (CB-11, 1.14.0). With `chkp_raw`: root
    7, or root 8 when root 7 fails its check against that checkpoint copy and root 8 does not. Without it (nothing to
    check the pages against): root 7 when its page reads as a B+ page, else root 8. 1.13.1 took the root whose page
    carries table id 0x0b (finding #337)."""
    return container_table_copy(f, ps, cs, chkp_raw, roots)["vlcns"]

def _select_ot_root_index(f, ps, cs, tr, roots):
    """The index of the Object Table's PRIMARY root: 0, the first root of the pair {0, 5} that `object_table_copy`
    reads by index as refs.sys does (B2; CB-1, 1.14.0). 1.13.1 took the first root whose page carried table id 0x02,
    which made the pair's order depend on a page's content; root 0 carries 0x02 and passes its digest on all 117 ReFS
    volumes of the corpus (`fixes/CB_evidence/ct_census.jsonl`), so no output moves."""
    return 0


def _select_ot_root(f, ps, cs, tr, roots):
    """The Object Table's PRIMARY root (`_select_ot_root_index`: root 0, CB-1). Its VIRTUAL LCNs are read through
    the container translator `tr`. B2 (1.14.0): which copy is read -- the primary, or its duplicate when the primary
    fails its digest or cannot be read -- is `object_table_copy`'s."""
    ri = _select_ot_root_index(f, ps, cs, tr, roots)
    return roots[ri] if ri < len(roots) and roots[ri] else []


# B2 (1.14.0; decision 1, kept a wave-C must by decision 39; settlement Q8; closure table WAVEC_READING_bootstrap 4.3):
# the checkpoint's roots 0 and 5 are the Object Table and its duplicate.
_OT_ROOT_PAIR = (0, 5)
# D (1.14.0 RC3): the checkpoint's roots that neither a pair's copy logic nor N205's test of the copy in use (roots
# 0xc, 7, 8: `_CHKP_STRICT_ROOTS`) states -- 1-4, 6 and 9-11 (the Medium and Container Allocators, the Schema Table and
# its duplicate, the Parent-Child Table, Block RefCount, the Container Index, Integrity State) -- checked at bootstrap
# against the digest the checkpoint copy in use records for each (`_chkp_other_root_findings`)
_CHKP_OTHER_ROOTS = (1, 2, 3, 4, 6, 9, 10, 11)
# RC3 (D's second correction): the duplicates among them that the tool does not read, each with the root it reads --
# root 5 (the Object Table's, tested here only while root 0 is the copy read) and root 9 (the Schema Table's failover
# copy, refsanalysis `_ROOT_NAMES`): a failure is a redundancy condition, as a backup copy's is
_CHKP_DUP_ROOTS = {5: 0, 9: 3}


def _chkp_other_root_findings(f, ps, cs, tr, chkp_raw, roots, ot_state):
    """D (1.14.0 RC3, the auditor's RC2 check; decision 73): the texts of the checkpoint roots, other than the Object
    Table's and the Container Table's pairs, whose page does not match the digest the checkpoint copy in use records
    for it -- and of the Object Table's duplicate (root 5) when its primary is the copy read (`ot_state` 'primary': the
    duplicate is then not tested by `object_table_copy`). Each root is read as refs.sys reads it, by its index, translated
    (`_CT_ROOT_INDICES` are physical: 7, 8 and 12, which N205 states). A root that fails is stated, and the table is still
    read as it is. Measured (RC1D/rc3/root_census.jsonl, slot_probe.jsonl, 2026-11-20): on the 124 ReFS volumes of the
    corpus the roots read this way fail on the four win11refs2tmillionsofactions salvage volumes only (roots 4 and 6,
    in image holes); there roots 7, 8 and 12 fail too (N205 and the Container Table's pair state them); every root
    verifies on the other 120.
    A root that cannot be checked is stated in N362's words, "cannot be verified (why)", never "fails", and never left
    out: its reference holds no LCN or a checksum type this tool does not compute (`_chkp_root_failures`' unchecked
    list), or one of its VLCNs cannot be translated through the Container Table in use (`_vlcn_mappable`; then the page
    is not read, since `Translator.tr` would read the untranslated address and count a miss). Neither occurs on the
    corpus (RC1D/rc3/root_census2.jsonl: 1,116 roots of the 124 ReFS volumes, 0 of either).
    Returns (view, redundancy): a duplicate the tool does not read (`_CHKP_DUP_ROOTS`: 5 and 9) is a redundancy
    condition, said by the commands that report redundancy (`system_table_findings`), as the documented rule for a
    backup copy that fails has it; every other root is a condition of the view (exit 2 in every command)."""
    idx = [i for i in _CHKP_OTHER_ROOTS if i < len(roots) and roots[i]]
    if ot_state == "primary" and len(roots) > 5 and roots[5]:
        idx.append(5)
    view, red = [], []
    for i in sorted(idx):
        phys = i in _CT_ROOT_INDICES
        name = "checkpoint root %d (%s)" % (i, _ROOT_LABELS[i] if i < len(_ROOT_LABELS) else "root %d" % i)
        out, tail = view, "; the table is read as it is"
        if i in _CHKP_DUP_ROOTS:
            name += ", the duplicate of root %d," % _CHKP_DUP_ROOTS[i]
            out, tail = red, "; root %d is the copy read" % _CHKP_DUP_ROOTS[i]
        unmapped = [] if phys else [s for s in roots[i] if not _vlcn_mappable(tr, s)]
        if unmapped:
            out.append("the root page of %s cannot be verified (its address, VLCN 0x%x, cannot be translated through "
                       "the Container Table in use)%s" % (name, unmapped[0], "" if out is view else tail))
            continue
        uw = []
        for _i, why in _chkp_root_failures(f, ps, cs, chkp_raw, None, uw, roots=(i,), tr=None if phys else tr,
                                           copy_words="the checkpoint copy in use"):
            out.append("the root page of %s %s%s" % (name, why, tail))
        for _i, why in uw:
            out.append("the root page of %s cannot be verified (%s)%s" % (name, why, tail))
    return view, red


def object_table_copy(f, ps, cs, tr, chkp_raw, roots):
    """B2 (1.14.0): which copy of the Object Table this tool reads, and what it says about the other.

    The primary is `_select_ot_root`'s root (root 0, CB-1). Its page is checked against
    the digest the checkpoint copy in use (`chkp_raw`) records for it (`_chkp_root_failures`, the test of N205's
    roots). Only when it FAILS -- the page cannot be read, or does not match -- is the duplicate read: the other root of
    the pair {roots[0], roots[5]}, checked the same way. Returns {"vlcns": the root read, "index": its root index,
    "state": 'primary' | 'duplicate' | 'neither', "text": the statement or None}:
      primary    the primary matches, or its reference cannot be checked here and its page reads: nothing is said
      duplicate  the primary failed and the duplicate does not: the duplicate is read; the statement names the failed
                 primary (its PLCN and why) -- a finding (exit 2), made by the caller
      neither    both fail (or there is no duplicate root): the primary is read as it is, as before B2, and the
                 statement names both roots -- a finding (exit 2)
    Why: decision 1 (the duplicate is used only when the primary fails); the driver facts it rests on, read once
    (WAVEC_READING_bootstrap O1-O6, 26100.8115 and three more builds): roots[0] and roots[5] are one failover pair by
    index, both are opened at mount, the duplicate is used when the primary's open fails with a corruption status
    (0xc00001a8), and a writable mount repairs the failed copy; what raises that status beyond the digest was not
    traced (O6), so the tool's test is the digest and the read. Reads only; records nothing (`bootstrap` does)."""
    pi = _select_ot_root_index(f, ps, cs, tr, roots)
    pri = roots[pi] if pi < len(roots) and roots[pi] else []
    out = {"vlcns": pri, "index": pi, "state": "primary", "text": None, "flags": []}
    # CB-3 (1.14.0): a copy whose root descriptor carries bit 0x8 (`_root_flag_bit`, read once: a statement, never a
    # switch), as for the Container Table's and the system tables' pairs; clear on all 117 ReFS volumes of the corpus
    for _i in _OT_ROOT_PAIR:
        if _i < len(roots) and roots[_i] and _vlcn_mappable(tr, roots[_i][0]):     # N624 (b): never the identity address
            try:
                _pg = _seek_read(f, ps + tr.tr(roots[_i][0]) * cs, cs)                         # N371
            except Exception as _e:
                _skip_note("object_table_copy", "an object-table root page", _e)
                continue
            if _root_flag_bit(_pg):
                out["flags"].append("the Object Table's root %d page (PLCN 0x%x) has bit 0x8 set in its root descriptor's "
                                    "flags (page +0x58), a bit this tool does not decode; the copy is read as it is"
                                    % (_i, tr.tr(roots[_i][0])))
    if chkp_raw is None or pi not in _OT_ROOT_PAIR or not pri:
        return out

    def _unmapped(idx):
        # N624 (b) (1.14.0): a VLCN of the root that the Container Table in use cannot translate (`_vlcn_mappable`)
        return [s for s in (roots[idx] if idx < len(roots) and roots[idx] else []) if not _vlcn_mappable(tr, s)]

    def _check(idx):
        # ('ok' | 'fail' | 'unchecked', why): N205's test (`_chkp_root_failures`) of one root of the pair
        um = _unmapped(idx)
        if um:
            return ("unchecked", "its address, VLCN 0x%x, cannot be translated through the Container Table in use"
                    % um[0])
        uw = []
        fails = _chkp_root_failures(f, ps, cs, chkp_raw, None, uw, roots=(idx,), tr=tr,
                                    copy_words="the checkpoint copy in use")
        return ("fail", fails[0][1]) if fails else ("unchecked", uw[0][1]) if uw else ("ok", None)

    def _name(idx):
        if idx < len(roots) and roots[idx] and _unmapped(idx):
            return "root %d (VLCN 0x%x)" % (idx, roots[idx][0])                  # N624 (b): no PLCN to name
        return ("root %d (PLCN 0x%x)" % (idx, tr.tr(roots[idx][0])) if idx < len(roots) and roots[idx]
                else "root %d" % idx)
    st, why = _check(pi)
    if st == "unchecked":
        # C1-9 (g) (1.14.0): its reference cannot be checked here (a checksum type this tool cannot verify, or no
        # reference): the primary is read as it is, and that is said -- as N362 says of roots 0xc, 7 and 8 that cannot
        # be verified, in its words and as a condition of the view (the review N1: it was a note); 1.13.2-dev said
        # nothing
        out["note"] = ("Object Table: its primary root page, %s, cannot be verified against the checkpoint copy in "
                       "use (%s); it is read as it is" % (_name(pi), why))
    if st != "fail":
        return out
    di = _OT_ROOT_PAIR[1] if pi == _OT_ROOT_PAIR[0] else _OT_ROOT_PAIR[0]
    dup = roots[di] if di < len(roots) and roots[di] else []
    dst, dwhy = _check(di) if dup else ("fail", "has no reference in the checkpoint copy in use")
    if dst != "fail":
        out.update(vlcns=dup, index=di, state="duplicate", text=(
            "Object Table: its primary root page, %s, %s; the Object Table is read from its duplicate, %s, %s"
            % (_name(pi), why, _name(di),
               "which matches the digest the checkpoint copy in use records for it" if dst == "ok" else
               "whose page could not be checked (%s)" % dwhy)))
        return out
    out.update(state="neither", text=(
        "Object Table: both of its root pages fail their check against the checkpoint copy in use: the primary, %s, "
        "%s; the duplicate, %s, %s; the Object Table is read from the primary as it is" % (
            _name(pi), why, _name(di), dwhy)))
    return out

# CB-11 / CB-3 (1.14.0, the conformance batch): the checkpoint's roots 7 and 8 are the Container Table's failover pair,
# slot 0 and slot 1 (P11, read twice: 9444 / 17134 / Insider in WAVEC_READING_tables, 26100.9711
# `InitializeVolumeAllocator` :207565-207587 -> `CmsVolumeContainer::Initialize`, which gives the slots the
# identifiers 0xb and 0xc and opens them with `CmsFailoverBPlusTable::InitializeTables`, the rule N422 read for the
# Logfile Information Table: slot 0 unless it fails, then slot 1).
_CT_ROOT_PAIR = (7, 8)


def _root_flag_bit(page):
    """CB-3: the root descriptor's flags (+0x08, page +0x58) carry bit 0x8 (`_SYSTEM_TABLE_FLAG`), which refs.sys
    tests when it opens a failover copy (read once, CL-1 row 3: a statement here, never a switch)."""
    return bool(page[:4] == b"MSB+" and len(page) > 0x58 and page[0x58] & _SYSTEM_TABLE_FLAG)


def container_table_copy(f, ps, cs, chkp_raw, roots):
    """CB-11 (1.14.0): which copy of the Container Table this tool reads, and what it says about the other -- as
    `object_table_copy` does for the Object Table's pair. refs.sys opens root 7 (slot 0) and root 8 (slot 1) and uses
    slot 0 unless it fails; the tool's test of a copy is the read and the digest the checkpoint copy in use
    (`chkp_raw`) records for it (`_chkp_root_failures`, N205's test of these physical roots). Returns {"vlcns",
    "index", "state": 'primary' | 'duplicate' | 'neither', "text", "flags": [the statements of CB-3's bit]}:
      primary    root 7 passes, or cannot be checked here and its page reads: nothing is said
      duplicate  root 7 fails and root 8 does not: root 8 is read; the statement names the failed root (a finding)
      neither    both fail: root 7 is read as it is, and the statement names both (a finding)
    1.13.1 took the root whose page carries table id 0x0b. Measured 2026-11-05 (`fixes/CB_evidence/ct_census.jsonl`,
    117 ReFS volumes): on 110 root 7 carries 0x0b and both pass; on the
    three step5/testchecksums `..._corrupted*` volumes root 7 (0x0b) fails its digest and root 8 passes (1.13.1 read
    root 7, refs.sys reads root 8); on the four win11refs2tmillionsofactions volumes root 7 carries 0x0c, both fail
    their digest and both carry bit 0x8 (1.13.1 read root 8). The two copies' rows (each walked whole,
    `fixes/CB_evidence/ct_rows_census_v2.jsonl`): equal on 111 volumes; on 6 they differ in the u32 +0x14 only
    (bits 0x2000 / 0x4000, set in root 7 only): win10to11refs4g x2 55 of 63 rows (46 in 0x2000, 9 in 0x4000), the four
    millionsofactions 1 row (container 0xce3, 0x4000; `LD/evidence/ct_copy_flag_bits.txt`),
    so `refsanalysis containers -v` shows 0xce3 as allocated there since this change. Reads only; records nothing
    (`bootstrap` does)."""
    def _ref(idx):
        return roots[idx] if idx < len(roots) and roots[idx] else []

    def _page(idx):
        try:
            return _seek_read(f, ps + _ref(idx)[0] * cs, cs) if _ref(idx) else b""          # N371
        except Exception as _e:
            _skip_note("container_table_copy", "a container-table root page", _e)
            return b""
    pages = {i: _page(i) for i in _CT_ROOT_PAIR}
    flags = ["the Container Table's root %d page (PLCN 0x%x) has bit 0x8 set in its root descriptor's flags (page "
             "+0x58), a bit this tool does not decode; the copy is read as it is" % (i, _ref(i)[0])
             for i in _CT_ROOT_PAIR if _root_flag_bit(pages[i])]
    p0, p1 = _CT_ROOT_PAIR
    if chkp_raw is None:
        use = p0 if _ref(p0) and pages[p0][:4] == b"MSB+" else p1 if _ref(p1) else p0
        return {"vlcns": _ref(use), "index": use, "state": "primary" if use == p0 else "duplicate", "text": None,
                "flags": flags}

    def _check(idx):
        if not _ref(idx):
            return "fail", "has no reference in the checkpoint copy in use"
        uw = []
        fails = _chkp_root_failures(f, ps, cs, chkp_raw, None, uw, roots=(idx,), copy_words="the checkpoint copy in use")
        return ("fail", fails[0][1]) if fails else ("unchecked", uw[0][1]) if uw else ("ok", None)

    def _name(idx):
        return "root %d (PLCN 0x%x)" % (idx, _ref(idx)[0]) if _ref(idx) else "root %d" % idx

    def _absent(idx):
        # N548 (1.14.0): a copy whose page this metadata bundle does not carry reads as zeros -- said as that, not as a
        # copy that failed its check (the bundle lacks the bytes; nothing shows them damaged)
        return bool(_BUNDLE is not None and _ref(idx)
                    and _page_hole_state(f, ps, cs, _ref(idx), None) == "bundle-absent")

    def _fails(idx):
        return ("is not carried by this bundle (it reads as zeros)" if _absent(idx) else
                "fails its check against the checkpoint copy in use")
    out = {"vlcns": _ref(p0), "index": p0, "state": "primary", "text": None, "flags": flags, "absent": False}
    st, why = _check(p0)
    if st != "fail":
        return out
    dst, dwhy = _check(p1)
    if dst != "fail":
        # why each root fails is the checkpoint conditions' (N205 lists roots 7 and 8 of the copy in use with the same
        # test), so the statement says only which copy is read
        out.update(vlcns=_ref(p1), index=p1, state="duplicate", absent=_absent(p1), text=(
            "Container Table: its first copy, %s, %s; the table is read from its second copy, %s, as refs.sys "
            "reads it when the copy it opens first fails%s" % (
                _name(p0), _fails(p0), _name(p1), "" if dst == "ok" else " (that copy could not be checked: %s)" % dwhy)))
        return out
    a0, a1 = _absent(p0), _absent(p1)
    out.update(state="neither", absent=a0, text=(
        "Container Table: neither of its copies, %s nor %s, is carried by this bundle (each reads as zeros); the table "
        "is read from the first copy as it is" % (_name(p0), _name(p1)) if a0 and a1 else
        "Container Table: its first copy, %s, %s, and its second, %s, %s; the table is read from the first copy as it "
        "is" % (_name(p0), _fails(p0), _name(p1), _fails(p1)) if a0 or a1 else
        "Container Table: both of its copies, %s and %s, fail their check against the checkpoint copy in use; the table "
        "is read from the first copy as it is" % (_name(p0), _name(p1))))
    return out


def _ct_copy_rows(f, ps, cs, roots, idx):
    """M1-Q: one copy of the Container Table (root `idx`, physical LCNs) walked whole, its damage kept in the copy
    (`_DamageCapture`, as `_system_table_copy` keeps a pair copy's): the copy in use is read for the view by
    `container_table_read`, which records its damage. None when the copy has no reference or could not be read."""
    global _WALK_DAMAGE
    ref = roots[idx] if idx < len(roots) and roots[idx] else []
    if not ref:
        return None
    cap, saved = _DamageCapture(), _WALK_DAMAGE
    _WALK_DAMAGE = cap
    try:
        rows = list(walk_bplus(f, ps, cs, None, ref))
    except (OSError, OverflowError):
        return None
    except Exception as _e:
        # every command bootstraps: a walk that raises is a recorded skip (the copies are not compared), never a crash
        _WALK_DAMAGE = saved
        _skip_note("container_table_copies_differ", "the Container Table's root %d" % idx, _e)
        return None
    finally:
        _WALK_DAMAGE = saved
    if cap.notes and not rows:
        return None
    return {"idx": idx, "plcn": ref[0], "partial": bool(cap.notes),
            "rows": {(le64(kd, 0) if len(kd) >= 8 else bytes(kd)): bytes(vd) for kd, vd in rows}}


def _ct_copies_compare(a, b, read_from):
    """M1-Q: the rows of the Container Table's two copies `a` and `b` (`_ct_copy_rows`), compared by key as the
    system-table pairs' copies are (`_system_table_rows_differ`). None when they are equal, else (kind, text):
      'flags'  every row that differs is in both copies, with the same length, and differs only in the u32 flags word
               at +0x14 (N216: read twice, 17134 and 26100.9444)
      'rows'   any other difference; a row missing from a copy read in part is "not among the rows read" (C1-12)
    `read_from`: the words that say which copy the table is read from."""
    ra, rb = a["rows"], b["rows"]
    keys = sorted((k for k in set(ra) | set(rb) if ra.get(k) != rb.get(k)),
                  key=lambda k: (0, k, b"") if isinstance(k, int) else (1, 0, k))
    if not keys:
        return None

    def _nm(c):
        return "root %d (PLCN 0x%x)" % (c["idx"], c["plcn"])

    def _key(k):
        return "container 0x%x" % k if isinstance(k, int) else "key %s" % k.hex()
    more = ", and %d more" % (len(keys) - 3) if len(keys) > 3 else ""
    part = [_nm(c) for c in (a, b) if c["partial"]]
    over = " (compared over the rows read: %s %s read in part)" % (" and ".join(part), "was" if len(part) == 1 else
                                                                    "were") if part else ""
    if all(k in ra and k in rb and len(ra[k]) == len(rb[k]) >= 0x18 and ra[k][:0x14] == rb[k][:0x14]
           and ra[k][0x18:] == rb[k][0x18:] for k in keys):
        bits = 0
        for k in keys:
            bits |= le32(ra[k], 0x14) ^ le32(rb[k], 0x14)
        ex = ", ".join("%s (0x%x in root %d, 0x%x in root %d)" % (_key(k), le32(ra[k], 0x14), a["idx"],
                                                                  le32(rb[k], 0x14), b["idx"]) for k in keys[:3])
        return ("flags", "the Container Table's two copies, %s and %s, differ only in the flags word (+0x14) of %d "
                         "row(s), in bit(s) 0x%x: %s%s%s; %s" % (_nm(a), _nm(b), len(keys), bits, ex, more, over,
                                                                read_from))
    words = []
    for k in keys[:3]:
        va, vb = ra.get(k), rb.get(k)
        if va is None or vb is None:
            lack, have = (a, b) if va is None else (b, a)
            words.append(("%s is not among the rows read of %s, which was read in part" % (_key(k), _nm(lack)))
                         if lack["partial"] else "%s only in %s" % (_key(k), _nm(have)))
            continue
        fields = ["+0x%x: 0x%x in root %d, 0x%x in root %d" % (o, le64(va, o), a["idx"], le64(vb, o), b["idx"])
                  for o in range(0, min(len(va), len(vb)) - 7, 8) if va[o:o + 8] != vb[o:o + 8]][:3]
        words.append("%s (%s)" % (_key(k), "; ".join(fields)) if fields else
                     "%s (%s in root %d, %d in root %d)" % (_key(k), count_noun(len(va), "byte"), a["idx"], len(vb), b["idx"]))
    return ("rows", "the two copies of the Container Table, %s and %s, differ in %d row(s): %s%s%s; %s" % (
        _nm(a), _nm(b), len(keys), ", ".join(words), more, over, read_from))


def container_table_copies_differ(f, ps, cs, roots, ctc):
    """M1-Q (the maintainer's decision, 2026-11-06; the review M1): the Container Table's two copies, root 7 (slot 0)
    and root 8 (slot 1), compared row by row (`_ct_copies_compare`); `ctc` is `container_table_copy`'s result (which
    copy is read). None when they are equal, or when a copy has no reference or could not be read (that copy's state
    is `container_table_copy`'s and the checkpoint conditions'), else (kind, text):
      'flags'  the copies differ only in the flags word (+0x14) of their rows: an rc-NEUTRAL note of `summary`,
               `fastsummary`, `integrity` and refsanalysis `summary` (`_redundancy_notes`), nothing elsewhere. Measured
               (`fixes/CB_evidence/ct_rows_census_v2.jsonl`, 117 ReFS volumes; the bits per row `LD/evidence/ct_copy_flag_bits.txt`): on 6, bits 0x2000 / 0x4000
               set in root 7 only (win10to11refs4g x2 55 rows, the four millionsofactions 1 row); equal on the other 111
      'rows'   any other difference: V-a, as two system-table copies that differ -- a redundancy condition of those
               commands (`system_table_findings`, exit 2 there), a note on stderr in every command (`bootstrap`)."""
    p0, p1 = _CT_ROOT_PAIR
    a, b = _ct_copy_rows(f, ps, cs, roots, p0), _ct_copy_rows(f, ps, cs, roots, p1)
    if a is None or b is None:
        return None
    use = b if ctc.get("index") == p1 else a
    read_from = ("the table is read from root %d (PLCN 0x%x), %s" % (
        use["idx"], use["plcn"],
        "as refs.sys reads it when the copy it opens first fails" if use is b else
        "the copy refs.sys opens first, as it is (both copies fail their check)" if ctc.get("state") == "neither" else
        "the copy refs.sys opens first"))
    return _ct_copies_compare(a, b, read_from)


def _parse_ct_page(page, f, ps, cs, _depth=0, visited=None):
    # _depth guard: the Container Table is a shallow B+ tree; 64 bounds a circular/corrupt CT (never trips
    # on valid data) to prevent unbounded recursion. Defaulted kwargs — existing callers are unaffected.
    # review E10 (mirrors _walk): `visited` is a per-walk set of head child-LCNs — a self-referential/cyclic inner
    # page would otherwise fan out ~4^depth and re-read identical pages forever (audit 2.4: hangs every
    # subcommand via bootstrap). On a well-formed CT every child page is referenced exactly once, so this
    # NEVER skips a legitimate page and the output is byte-identical; a cyclic child is skipped, not looped.
    if visited is None: visited = set()
    if page[:4] != b"MSB+" or _depth > 64: return {}
    thoff = 0x50 + le32(page, 0x50)
    if thoff + 40 > len(page): return {}
    tbl = struct.unpack_from("<10I", page, thoff)
    is_inner = bool(tbl[3] & 0x100)
    astart, aend = tbl[4], tbl[8]
    if astart >= aend: return {}
    result = {}
    for i in range((aend - astart) // 4):
        aa = thoff + astart + i * 4
        if aa + 4 > len(page): break
        ro = thoff + le16(page, aa)
        if ro + 16 > len(page): break
        rh = struct.unpack_from("<I6H", page, ro)
        _, ko, kl, _, vo, vl, _ = rh
        if (kl and ro + ko + kl > len(page)) or (vl and ro + vo + vl > len(page)):
            continue     # audit 2.5: skip a row whose key/value runs past the page (no silent truncation)
        kd = page[ro+ko:ro+ko+kl] if kl > 0 else b""
        vd = page[ro+vo:ro+vo+vl] if vl > 0 else b""
        key = le64(kd, 0) if len(kd) >= 8 else 0
        if is_inner:
            if len(vd) >= 32:
                cls = [le64(vd, j*8) for j in range(4)]
                valid = [x for x in cls if x not in (0, 0xFFFFFFFFFFFFFFFF)]
                if valid:
                    head = valid[0]                          # review E10: key on the head child LCN (mirrors _walk)
                    if head in visited:
                        continue                             # already-read / cyclic child page — skip
                    visited.add(head)
                    cd = b""
                    for l in valid: cd += _seek_read(f, ps + l * cs, cs)       # N371
                    result.update(_parse_ct_page(cd, f, ps, cs, _depth + 1, visited))
        else:
            r = ct_row(kd, vd)
            if r["base"] is not None:
                result[key] = (r["base"], r["capacity"])
    return result


# N216 / A9 (1.14.0): a Container Table row as refs.sys reads it (`CreateContainerForCache`, `PinContainerRange`;
# read twice, 17134 and 26100.9444: WAVEC_READING_tables CL-2). The value: +0x10 a version byte, +0x14 u32 flags, +0x18
# u32 the container's capacity in clusters, +0x4c u32 the number of mapping ranges, and from +0x50 k 16-byte units
# (k fixed per volume) followed by `count` ranges {u64 start, u64 length}: the value is (k + 5 + count) x 16 bytes. The
# tools translate only through a row the driver would map linearly: one range, not compressed (flag 0x2), not
# compacted (0x8), not refused (0x800). Every other row is listed with the reason (`ct_row`'s `why`), and a
# translation into it is a recorded skip (`Translator.tr`). Reading compressed or compacted containers is not supported.
_CT_FLAG_COMPRESSED, _CT_FLAG_COMPACTED, _CT_FLAG_INDEX_ROW_MISSING = 0x2, 0x8, 0x800


def ct_row(kd, vd):
    """One Container Table row -> dict: id, version, flags, capacity, count, k (the units before the ranges), base and
    length (the FIRST range, which the driver's real-band map uses too), and `why` -- None when the tools translate
    through the row, else the reason they do not. The base is the first range's start whatever `why` says (`None` only
    when the value holds no range), so a listing can show it."""
    r = {"id": le64(kd, 0) if len(kd) >= 8 else None, "len": len(vd), "version": vd[0x10] if len(vd) > 0x10 else None,
         "flags": le32(vd, 0x14) if len(vd) >= 0x18 else 0, "capacity": le32(vd, 0x18) if len(vd) >= 0x1C else 0,
         "count": le32(vd, 0x4C) if len(vd) >= 0x50 else None, "k": None, "base": None, "length": None, "why": None}
    if r["id"] is None or r["count"] is None:
        r["why"] = "the row is %d bytes, too short for a Container Table row (0x50 bytes before its ranges)" % len(vd)
        return r
    units = (len(vd) - 0x50) // 16
    k = units - r["count"]
    if (len(vd) - 0x50) % 16 or k < 0:
        r["why"] = ("its %d bytes do not hold the %d mapping range(s) it records" % (len(vd), r["count"]))
        return r
    r["k"] = k
    if r["count"]:
        r["base"], r["length"] = le64(vd, 0x50 + 16 * k), le64(vd, 0x58 + 16 * k)
    if r["version"] != 1 and len(vd) < 0x58:
        r["why"] = "the row's version byte is 0x%x, not 1, in a row of %d bytes" % (r["version"], len(vd))   # C8: read once
    elif r["flags"] & _CT_FLAG_INDEX_ROW_MISSING and (r["flags"] & (_CT_FLAG_COMPRESSED | _CT_FLAG_COMPACTED)
                                                      or r["count"] != 1):
        r["why"] = "the Container Table marks it unreadable: a Container Index row it needs was not found"
    elif r["flags"] & _CT_FLAG_COMPRESSED:
        r["why"] = "it is compressed (reading compressed containers is not supported)"
    elif r["flags"] & _CT_FLAG_COMPACTED:
        r["why"] = "it is compacted: its clusters are found through the Container Index, which the tools do not read"
    elif r["count"] == 0:
        r["why"] = "its row has no mapping range"
    elif r["count"] != 1:
        r["why"] = "it is mapped by %d ranges (the tools translate a container of one range only)" % r["count"]
    if r["why"] is None and r["flags"] & _CT_FLAG_INDEX_ROW_MISSING:
        # the maintainer, 2026-11-06 (read what the driver would refuse, and say so): refs.sys refuses a container with
        # 0x800 (N216, read twice), but a row with one range, neither compressed nor compacted, maps linearly -- the
        # tools translate it, and `container_table_read` states the refusal (a condition of the view)
        r["refused"] = ("the Container Table marks it unreadable (flags 0x%x: a Container Index row it needs was not "
                        "found), so refs.sys refuses it; the tools read it through its one range" % r["flags"])
    return r


def container_table_read(f, ps, cs, ct_vlcns, cpc):
    """N216 / A9 (1.14.0): the Container Table, read once and checked the same way for every reader (`bootstrap`,
    refsanalysis `chkp` and `containers`). `ct_vlcns`: the table's root (real LCNs). -> dict:
      rows       {id: ct_row(...)}, every leaf row in table order (an id met twice: the later row, as before)
      map        {id: base} the containers the tools translate through
      skipped    {id: why} the containers they do not (listed by summary, integrity and refsanalysis containers)
      overlaps   [(id_a, id_b, base_a, base_b)] two translated containers whose clusters overlap
      conditions [text] the overlaps, worded once: a view condition (`bootstrap` records it; exit 2 in every command)
    A row whose k differs from the volume's other rows is skipped too: k is fixed per volume, so the row does not hold
    its ranges where they are (the most common k is taken as the volume's)."""
    rows = {}
    for kd, vd in walk_bplus(f, ps, cs, None, ct_vlcns) if ct_vlcns else []:
        r = ct_row(kd, vd)
        if r["id"] is not None:
            rows[r["id"]] = r
    ks = {}
    for r in rows.values():
        if r["k"] is not None:
            ks[r["k"]] = ks.get(r["k"], 0) + 1
    if len(ks) > 1:
        kv = max(sorted(ks), key=lambda x: ks[x])
        for r in rows.values():
            if r["k"] is not None and r["k"] != kv and r["why"] is None:
                r["why"] = ("its layout (%d units before its ranges) differs from the volume's other rows (%d), so its "
                            "ranges are not where they would be" % (r["k"], kv))
    m = {i: r["base"] for i, r in rows.items() if r["why"] is None}
    skipped = {i: r["why"] for i, r in rows.items() if r["why"] is not None}
    # A9: a translated container owns its clusters -- two whose clusters overlap mean at least one row is wrong, and
    # every address in either may be read from the other's clusters (a digest catches it only where a page is checked)
    overlaps, conditions = [], []
    # the maintainer's rule (2026-11-06): a container refs.sys refuses that the tools read anyway is said, every time
    for i in sorted(i for i in m if rows[i].get("refused")):
        conditions.append("container 0x%x: %s (physical start 0x%x)" % (i, rows[i]["refused"], m[i]))
    span = lambda i: max(1, min(rows[i]["length"] or cpc, cpc or rows[i]["length"] or 1))
    order = sorted(m, key=lambda i: (m[i], i))
    for a, b in zip(order, order[1:]):
        if m[b] < m[a] + span(a):
            overlaps.append((a, b, m[a], m[b]))
            conditions.append(
                "the Container Table maps containers 0x%x and 0x%x onto overlapping clusters (physical starts 0x%x and "
                "0x%x): at least one of the two rows is wrong, so an address in either container may be read from the "
                "other's clusters" % (a, b, m[a], m[b]))
    return {"rows": rows, "map": m, "skipped": skipped, "overlaps": overlaps, "conditions": conditions,
            "first_id": min(rows) if rows else None}


class ContainerNotTranslated(ValueError):
    """N216: an address in a container the tools do not translate (`ct_row`'s `why`), or in no container of the table."""


class Translator:
    def __init__(self, m, cpc, skipped=None, first_id=None):
        self.map = m; self.cpc = cpc
        self.skipped = dict(skipped or {})     # N216: {container id: why} -- listed, never translated
        self._said = set()
        self.ct = None                         # bootstrap: the `container_table_read` result the map came from
        # Q9: the shift is bit_length() (= log2(cpc)+1), NOT log2(cpc), and this is CORRECT — not an off-by-one.
        # The driver does exactly this: GetContainerIdFromRealRange adds 1 to the log2 width, and
        # IsValidContainerLcn guarantees the container-boundary bit is 0, so the extra shifted bit is always
        # clear. cpc is a power of two, so mask = cpc-1 recovers the in-container offset. (docs/structures/
        # container_table.md.) Do not "fix" this to bit_length()-1.
        self.shift = cpc.bit_length() if cpc > 0 else 0
        self.mask = cpc - 1 if cpc > 0 else 0
        self.misses = 0   # review E11: count VLCNs with no container mapping (unmapped => read as identity)
        # below this: not containerised. N216: the first id of the TABLE (a skipped row is still a container)
        _ids = list(self.map) + list(self.skipped)
        self._first_cid = first_id if first_id is not None else (min(_ids) if _ids else None)
    def tr(self, vlcn):
        cid = vlcn >> self.shift
        if cid in self.map:
            _off = vlcn & self.mask
            _row = ((self.ct or {}).get("rows") or {}).get(cid) or {}
            if _row.get("length") and _off >= _row["length"] and ("len", cid) not in self._said:
                # C3-3 (1.14.0): past the container's one range (refs.sys refuses it); read linearly as before, said
                # once per container -- a finding (exit 2), in words that say it was READ (the review N7: it was a skip
                # note, which said "skipped"); `_vlcn_mappable` refuses it where a reader asks
                self._said.add(("len", cid))
                _t = ("an address in container 0x%x lies past the container's range (offset 0x%x, range length 0x%x); "
                      "it is read linearly from the container's start, while refs.sys refuses such an address, so what "
                      "is read there may not be the volume's" % (cid, _off, _row["length"]))
                _finding("container translation", _t)
                print("[%s] WARNING: %s." % (PROG, _t), file=sys.stderr)
            return self.map[cid] + _off
        # Below the first container id the volume is not containerised: ids start at 2 (E74), so
        # keys 0 and 1 are never in the table and an address there is ALREADY physical. Identity is
        # the correct answer, not a fallback, and counting it as a miss made every v3.4 volume warn
        # that its output "may be incomplete" because of three large files that read perfectly.
        if self._first_cid is not None and cid < self._first_cid:
            return vlcn
        # review E11: an unmapped container (corrupt/truncated CT, or a wrong-mode read) falls back to identity
        # (VLCN read as PLCN). That silently loses evidence downstream; count it so callers can surface it.
        # N216 (1.14.0): a container the tools do not translate is the same case, and so is a recorded skip, said once
        # per container (exit 2): what is read at the identity address is not this container's data. A page read there
        # fails the walk's address check (`_walk`) and is not used; the extent decoders test `_vlcn_mappable` before they
        # accept a cover, while the CoW and carve readers translate without that test and read the identity address
        # after this recorded skip (RC-14, CONFORMANCE_BATCH).
        self.misses += 1
        if cid not in self._said:
            self._said.add(cid)
            _skip_note("container translation", "the clusters of container 0x%x" % cid, ContainerNotTranslated(
                self.skipped.get(cid, "the Container Table has no row for it")))
        return vlcn


_INTEGRITY_FAILED = []   # A3: names whose stored CRC-32C did not match the bytes delivered this run

_ALL_TRS = []   # audit 4.2: EVERY Translator built this run. Was a single _LAST_TR — but `--cow-before` builds a
                # SECOND Translator (the earlier image), and it silently overwrote the first, dropping that image's
                # unmapped-container caveat — the exact silent evidence-loss the 3.2 fix exists to prevent.

def _warn_translator(tr):
    """Surface unmapped-container misses (audit 3.2/4.2): 0 on a well-formed volume; non-zero => a corrupt/truncated
    container table forced identity-mapped (VLCN==PLCN) reads, so some rows may be missing or wrong. stderr ONLY
    — never alters stdout/JSON, so a valid volume is byte-unchanged — and at most once per translator (the
    `_warned` flag). Registered at-exit so EVERY command carries the caveat (not just fastsummary, 3.2), once per
    image (4.2: `--cow-before` builds a second Translator; the warning is labelled with which image it came from).
    Deliberately NOT suppressed by `-q/--quiet` — an evidence caveat is not progress output. NB: atexit does not
    fire on os._exit()/a signal, so the caveat is structurally slightly less reliable than the output it qualifies
    (neither path occurs in the current code)."""
    if tr is None or not getattr(tr, "misses", 0) or getattr(tr, "_warned", False):
        return
    tr._warned = True
    _img = getattr(tr, "_image", "")
    _where = f" [{_img}]" if _img else ""
    # N548 (1.14.0): the cause the bytes show -- over a bundle that does not carry the Container Table's page, that
    _cause = ("the Container Table is not carried by this bundle" if getattr(tr, "ct_absent", False) else
              "corrupt/truncated container table")
    print(f"[{PROG}] WARNING:{_where} {tr.misses} VLCN(s) had no container mapping — output may be incomplete "
          f"({_cause}).", file=sys.stderr)

atexit.register(lambda: [_warn_translator(t) for t in _ALL_TRS])
# Skipped work is reported at exit whatever the command did, for the same reason as the
# translator caveat above: an incomplete answer must not look like a complete one.
def _defer_summary():
    """One line if any content path declined. Separate from the skip summary: a SKIP is work not done,
    a DEFERRAL is an answer deliberately withheld, and a reader needs to tell them apart."""
    if _DEFERRALS:
        print(f"[{PROG}] {len(_DEFERRALS)} stream(s) were DECLINED rather than reassembled; "
              f"no bytes were written for them.", file=sys.stderr)


atexit.register(lambda: _skip_summary())
atexit.register(lambda: _walk_damage_summary())      # B3: an unreadable page is never silent
atexit.register(lambda: _defer_summary())

# ─── B+ tree walker ──────────────────────────────────────────────────
def walk_bplus(f, ps, cs, tr, vlcns, max_depth=5, oid=None, root_out=None):
    plcns = [tr.tr(v) for v in vlcns] if tr else vlcns
    page = b""
    for p in plcns: page += _seek_read(f, ps + p * cs, cs)               # N371
    if root_out is not None:
        # N422 (1.14.0): the root page as read, for a caller that tests it itself (`_system_table_copy`: the digest
        # and the root descriptor's flags of one copy of a system-table pair) -- no second read
        root_out["page"], root_out["plcns"] = page, list(plcns)
    # B1/A9 (RC2): when the caller names the object, verify this ROOT page against the digest the Object
    # Table recorded for it -- using the bytes just read, so the check costs a hash and no extra I/O.
    # (Verifying by re-reading cost 4.6x on winsider; this is the same check without the second read.)
    if oid is not None:
        verify_object_root(oid, page)
    elif root_out is None:
        # RC3 F4 (1.14.0): a walk that does not name its object is verified as the object whose root LCNs these are,
        # when the Object Table copy in use names one; `root_out`'s caller (`_system_table_copy`) tests each copy of a
        # pair itself and words what a failed copy means
        for _o in _OBJ_ROOT_BY_LCNS.get(tuple(vlcns), ()):
            verify_object_root(_o, page)
    return _walk(page, f, ps, cs, tr, max_depth, plcns=plcns, vlcns=vlcns)

# B3 (K044/K045/K048): a walk that cannot READ a page must not be indistinguishable from a table that
# is genuinely EMPTY. Every `return []` below used to be silent, so destroying one page's signature made
# `security --audit` print "Descriptors: 0 ... VERDICT: CLEAN" and `summary` print "0 rows" -- a destroyed
# table reported as a clean empty one. Damage is recorded here and surfaced by the commands that report
# a count as authoritative. Nothing is recorded on an undamaged volume, so output there is unchanged.
class _DamageList(list):
    """N336 (decision 27.5): the damage register. Its ENTRIES stop at 500 (`_walk_note_damage`: they are the examples
    the summary prints), but `total` counts every note recorded into this list, never capped. A reader that decides
    "unreadable" / "not read" by whether ITS walk recorded damage compares `_walk_damage_count()` before and after the
    walk -- compared with the list's length, past the cap a zeroed root read as rows again, and a zeroed 0x520 table as
    "USN journal inactive" -- and the printed number of unreadable pages is the count too (N336 widened: it printed
    500). The count belongs to the list object: `_walk_damage_reset` clears both (one definition), and a fresh register
    (`type(_WALK_DAMAGE)()`, as the in-process tests make one) starts at 0, so the two cannot drift apart.

    N368 (the lead's settlement, 2026-10-09): a count of pages is a count of DISTINCT pages. `pages` maps each page a
    note names (its head cluster) to the kind first recorded for it, never capped; a note that names no page counts as
    a page of its own. The printed numbers are `_walk_damage_pages()`; `total` stays the change detector (a walk that
    meets a page another walk already noted has still recorded damage), and only a page's first note is an example."""
    total = 0
    notes = None

    def __init__(self, *a):
        super().__init__(*a)
        self.pages = {}


class _DamageCapture(_DamageList):
    """N422 (1.14.0): the damage register while ONE copy of a system-table pair is read (`_system_table_copy`): every
    note is also kept whole in `notes` -- (kind, detail, page) -- so the copy's walk records nothing for the run while
    it is read (a copy that is not used is a redundancy condition, V-a, not damage of the view), and the notes of the
    copy that IS used are recorded afterwards with `_walk_note_damage` (`system_table_pair`)."""

    def __init__(self, *a):
        super().__init__(*a)
        self.notes = []


_WALK_DAMAGE = _DamageList()
# C1-3 / C1-4 (1.14.0, the conformance batch): what THIS view could not read -- ("damage", kind) for a page a walk could
# not read, ("skip", stage) for a skip that is a finding. `_WALK_DAMAGE` and `_SKIP_FINDING` are run registers (the exit
# code and the at-exit summary count every view of the run), so a test of "was this view read in full" made on them
# answered for the run: in a process that read two volumes (`--cow-before`'s earlier image, a library caller) one
# volume's damage made the other's lookups "not determined". A `view` register: emptied by `_new_view`.
_VIEW_INCOMPLETE = []


def _walk_note_damage(kind, detail, page=None):
    """Record that a walk could not read a page (or a subtree). `page`: the page's head cluster (physical LCN) when
    the walk knows it -- the same page met by two walks is one page (N368)."""
    _notes = getattr(_WALK_DAMAGE, "notes", None)
    if _notes is not None:
        _notes.append((kind, detail, page))
    else:
        _VIEW_INCOMPLETE.append(("damage", kind))     # C1-3 (a captured copy's notes count when recorded for the view)
    _WALK_DAMAGE.total += 1
    key = ("page", page) if page is not None else ("note", _WALK_DAMAGE.total)
    pages = getattr(_WALK_DAMAGE, "pages", None)
    if pages is not None:
        if key in pages:
            return
        pages[key] = kind
    if len(_WALK_DAMAGE) < 500:
        _WALK_DAMAGE.append((kind, detail))


def _page_address_mismatch(page, asked):
    """WC-5 (1.14.0, the conformance batch): A9's test of a page read for a reference -- the LCN tuple its header
    records (+0x20..+0x3F) against the LCNs `asked` (the reference's, virtual or physical as the reader asked):
    (own, asked) when they differ, else None (also when there is nothing to compare). One test for `_walk`,
    `_walk_btree_pages`, `verify_ref` and `_extent_leaf_rows`: until 1.14.0 only `_walk` made it."""
    if asked is None or len(page) < 0x40:
        return None
    _asked = [x for x in asked if x not in (0, 0xFFFFFFFFFFFFFFFF)]
    _own = [x for x in (le64(page, 0x20 + 8 * i) for i in range(4)) if x not in (0, 0xFFFFFFFFFFFFFFFF)]
    return (_own, _asked) if _asked and _own != _asked else None


def _page_address_text(own, asked, plcn=None):
    return ("the page%s records the address %s, not %s, the address it was read for"
            % (" at plcn 0x%x" % plcn if plcn is not None else "", ", ".join("0x%x" % x for x in own) or "none",
               ", ".join("0x%x" % x for x in asked)))


def _walk_damage_count():
    """N336: how many damage notes were recorded into the register -- never capped; cleared only with the list by
    `_walk_damage_reset`, which no command calls (a reset between a reader's two counts would hide that walk's damage).
    Compare it before and after a walk to know whether that walk recorded damage. The number PRINTED is
    `_walk_damage_pages()` (N368: distinct pages)."""
    return _WALK_DAMAGE.total


def _walk_damage_pages():
    """N368: how many DISTINCT pages the damage notes name (a note that names no page is one page) -- the number every
    "N metadata page(s) could not be read" prints. Never capped."""
    pages = getattr(_WALK_DAMAGE, "pages", None)
    return len(pages) if pages is not None else _WALK_DAMAGE.total


def _walk_damage_reset():
    del _WALK_DAMAGE[:]
    _WALK_DAMAGE.total = 0
    if getattr(_WALK_DAMAGE, "pages", None) is not None:
        _WALK_DAMAGE.pages.clear()


_WALK_DAMAGE_REPORTED = []


def _walk_damage_summary():
    """B3: say, once, that part of a tree could not be read -- silent when everything was read.

    Registered with atexit for the same reason `_skip_summary` is: EVERY command that walks a tree
    reports a count, and a count taken over a tree with an unreadable page is not a census. Without
    this, zeroing one directory page dropped its names from `files` with no message and exit 0
    (K045), and destroying a table root printed "0 rows"/"Descriptors: 0" (K044/K048). Written to
    stderr so it can never corrupt CSV or JSON on stdout.
    """
    if not _walk_damage_count() or _WALK_DAMAGE_REPORTED:
        return
    _WALK_DAMAGE_REPORTED.append(True)
    # N336 widened: the number recorded, not the list's length (which stops at 500); the lines below are examples.
    # N368: the number of DISTINCT pages (a page met by two walks counts once)
    print(f"[{PROG}] WARNING: {_walk_damage_pages()} metadata page(s) could not be read. Any count, "
          f"listing or verdict above is INCOMPLETE — rows stored only on those pages are missing and "
          f"their absence is NOT evidence they do not exist:", file=sys.stderr)
    for line in _walk_damage_lines():
        print(f"[{PROG}]          {line}", file=sys.stderr)


# The damage kind of a page in a hole, by its `_image_hole_state` word (`_walk`; `integrity`'s page check, N368)
_HOLE_DAMAGE_KIND = {"hole": "image-hole", "source-hole": "hole-in-source-image", "bundle-absent": "not-in-bundle"}
# N368 (the lead's settlement): the hole kinds' count says what it counted -- distinct pages this command read, wholly
# in which image's holes (C8 = B: the cause is in each example's sentence)
_DAMAGE_KIND_SCOPE = {
    "image-hole": "distinct page(s) that this command read are wholly in the image's holes",
    "hole-in-source-image": "distinct page(s) that this command read are wholly in the source image's holes",
    "not-in-bundle": "distinct page(s) that this command read are not carried by this bundle"}


def _walk_damage_lines():
    """One line per distinct damage kind, with a count of DISTINCT pages (N368) and the first examples. Empty list when
    the walk read everything."""
    if not _WALK_DAMAGE:
        return []
    agg = {}
    for kind, detail in _WALK_DAMAGE:
        agg.setdefault(kind, []).append(detail)
    npages = {}
    for kind in (getattr(_WALK_DAMAGE, "pages", None) or {}).values():
        npages[kind] = npages.get(kind, 0) + 1
    out = []
    for kind in sorted(agg):
        ds = agg[kind]
        n = npages.get(kind, len(ds))
        out.append("%s: %d %s — e.g. %s" % (kind, n, _DAMAGE_KIND_SCOPE.get(kind, "page(s)"), "; ".join(ds[:2])))
    return out


def _walk(page, f, ps, cs, tr, depth, visited=None, plcns=None, vlcns=None):
    # review E10: cycle/re-read protection. A corrupt inner node whose child pointers repeat an ancestor page
    # would otherwise fan out ~4^depth and re-read identical pages. `visited` is a per-walk set keyed on
    # (addressing-mode, head-PLCN) — the mode bit is essential so a translated VLCN and a physical LCN
    # sharing a numeric value are NOT merged (which would drop a real page). On a well-formed tree every
    # child page is referenced exactly once, so this NEVER skips a legitimate page (output unchanged).
    if visited is None: visited = set()
    _head = plcns[0] if plcns else None          # N368: the page a note names, so a page met twice counts once
    if depth <= 0:
        # a tree deeper than max_depth silently loses every row below this point
        _walk_note_damage("depth-limit-reached", "a subtree below the %d-level limit was not walked" % depth,
                          page=_head)
        return []
    if len(page) < 4:
        _walk_note_damage("unreadable", "short read (%d bytes) where a page was expected" % len(page), page=_head)
        return []
    if page[:4] != b"MSB+":
        # N44 / N132 (C8 = B): an all-zero page that the image stores as a hole is not the same statement as a page
        # whose zeros are written on the volume -- but a hole cannot tell a page that was not captured from one that
        # is zero on the disk, so it is stated as a hole with the cause left open, never as "an acquisition gap,
        # not damage". In bundle mode, a page the manifest lists in `source_holes` is a hole of the SOURCE image
        # (N368). Same distinction K187/A9 make; the check runs only on a page that already failed.
        _where = (" at plcn 0x%x" % plcns[0]) if plcns else ""
        if not any(page):
            _hs = _page_hole_state(f, ps, cs, list(plcns), None) if plcns else None
            if _hs is not None:
                _walk_note_damage(_HOLE_DAMAGE_KIND.get(_hs, "image-hole"),
                                  "page%s: %s" % (_where, _hole_sentence(_hs)), page=_head)
            else:
                # K188: the message names the PAGE and the cause; it used to blame a generic failure and
                # never say which page could not be read.
                _walk_note_damage("zeroed-page", "page%s reads as all zeros on this volume" % _where, page=_head)
        else:
            _walk_note_damage("not-a-node", "signature %r%s" % (page[:4], _where), page=_head)
        return []
    # A9 (1.14.0): the page must be the one the reference asked for. Its header's LCN tuple (+0x20..+0x3F) holds the
    # address it was written for -- the reference's (virtual) LCNs, which is what the reader asked for: equal on all
    # 66,153 pages read for the measurement (every checkpoint root's tree and up to 1,500 objects per volume, 117 ReFS
    # corpus volumes), translated or not (C3, fixes/C3_NOTES.md, KNOWLEDGE_INTAKE A76). A page that
    # carries another address was read from the wrong clusters (a wrong Container Table row, a reference that points
    # elsewhere): its rows are not this table's, so it is recorded and not used. `vlcns` is None where no reference
    # names the page.
    _mm = _page_address_mismatch(page, vlcns)                         # WC-5: the one test
    if _mm:
        _walk_note_damage("wrong-page", _page_address_text(_mm[0], _mm[1], plcns[0] if plcns else None), page=_head)
        return []
    thoff = 0x50 + le32(page, 0x50)
    if thoff + 40 > len(page):
        _walk_note_damage("malformed", "table header at 0x%x runs past the end of the page" % thoff, page=_head)
        return []
    tbl = struct.unpack_from("<10I", page, thoff)
    is_inner = bool(tbl[3] & 0x100)
    astart, aend = tbl[4], tbl[8]
    if astart >= aend: return []
    rows = []
    for i in range((aend - astart) // 4):
        aa = thoff + astart + i * 4
        if aa + 4 > len(page): break
        ro = thoff + le16(page, aa)
        if ro + 16 > len(page): break
        rh = struct.unpack_from("<I6H", page, ro)
        _, ko, kl, _, vo, vl, _ = rh
        if (kl and ro + ko + kl > len(page)) or (vl and ro + vo + vl > len(page)):
            continue     # audit 2.5: a row whose key/value runs past the page is corrupt — skip, don't let
                         # Python slicing return a SHORT buffer that becomes a plausible-but-wrong key
        kd = page[ro+ko:ro+ko+kl] if kl > 0 else b""
        vd = page[ro+vo:ro+vo+vl] if vl > 0 else b""
        if is_inner:
            if len(vd) >= 32:
                cvs = [le64(vd, j*8) for j in range(4)]
                cvld = [x for x in cvs if x not in (0, 0xFFFFFFFFFFFFFFFF)]
                cps = [tr.tr(v) for v in cvld] if tr else cvld
                head = (tr is not None, cps[0]) if cps else None
                if head is not None and head in visited:
                    continue                     # already-walked / cyclic child page — skip
                if head is not None:
                    visited.add(head)
                cp = b""
                for p in cps: cp += _seek_read(f, ps + p * cs, cs)          # N371
                # A9: opt-in. `_VERIFY_PAGES` is False by default, so this is one attribute read per
                # inner row on the fast path -- no CRC, no extra I/O, output unchanged.
                if _VERIFY_PAGES:
                    _verify_child_page(vd, cp, "plcn 0x%x" % cps[0])
                rows.extend(_walk(cp, f, ps, cs, tr, depth-1, visited, plcns=cps, vlcns=cvld))
        else:
            rows.append((kd, vd))
    return rows

# ─── Object Table ────────────────────────────────────────────────────
# B1/A9 (RC2): oid -> (digest_length, digest) for each object's ROOT page, filled by build_object_map.
# `_OBJ_ROOT_VERIFIED` remembers what has already been checked so a repeated walk costs one set lookup.
# N426 (1.14.0): both, and `_OBJ_ROOT_LCNS`, are facts of the Object Table copy the CURRENT view reads (`view` registers
# of `_MODULE_REGISTERS`): emptied when a view starts (`_new_view`) and when `build_object_map(register=True)` refills
# them, and put back by `_view_leave` after a view read inside another (`cow_compare`'s earlier image). Kept across
# volumes, an object verified on one volume went unchecked on the next, and the before-image's digests replaced the
# after-image's.
_OBJ_ROOT_REF = {}
_OBJ_ROOT_VERIFIED = set()
_OBJ_ROOT_FAILED = set()     # N609 (1.14.0): objects whose root page failed its digest (altered, or all zeros) in this view


def object_root_digest_matches(oid, data):
    """THE root-page digest test (single_source.tsv `object_root_digest`): does `data`, an object's root page as read,
    match the digest the Object Table copy in use records for that object (`_OBJ_ROOT_REF`: CRC64 or SHA-256)? True /
    False; None when no digest is recorded or nothing was read, or when `data` is not the whole page the digest covers
    (every LCN slot concatenated: a caller that read fewer slots than the Object Table names has not read that page, so
    a comparison would be meaningless). It records nothing: `verify_object_root` makes the finding of a page a walk
    uses; N422's `_system_table_copy` tests each copy of a pair with it and words what a failed copy means."""
    ref = _OBJ_ROOT_REF.get(oid)
    if ref is None or not data:
        return None
    clen, digest = ref
    _want = len(_OBJ_ROOT_LCNS.get(oid) or [])
    if _want and len(data) % _want:
        return None
    return (refs_crc64(data) == int.from_bytes(digest, "little")) if clen == 8 \
        else (hashlib.sha256(data).digest() == digest)


def _sd_root_failed_lines():
    """N609 (1.14.0): the security table's root-page failure, worded for `security --audit` ([] when it verified)."""
    return (["the root page of the Security Descriptor Stream (OID 0x530) does not match the digest the Object Table "
             "recorded for it"] if 0x530 in _OBJ_ROOT_FAILED else [])


def _fsmeta_root_failed_text():
    """N608 (1.14.0): the system metadata table's root-page failure, worded for `usn` (None when it verified)."""
    return ("the root page of the system metadata table (OID 0x520) does not match the digest the Object Table "
            "recorded for it" if OID_FS_METADATA in _OBJ_ROOT_FAILED else None)


def verify_object_root(oid, data):
    """Verify one object's root page against the digest the Object Table recorded for it.

    `data` is the page as the caller has ALREADY read it, so this adds a hash and no I/O. Returns True
    when it verifies or cannot be checked, False when the page has been ALTERED. An all-zero page is reported
    as all zeros, not as an alteration: whether it lies in an image hole is said by the walk that reads it
    (`_walk`, C8 = B), and zeros alone do not say how the page came to be zero (N132).
    """
    if _OBJ_ROOT_REF.get(oid) is None or oid in _OBJ_ROOT_VERIFIED or not data:
        return True
    _OBJ_ROOT_VERIFIED.add(oid)
    if object_root_digest_matches(oid, data) is not False:
        return True
    if not any(data):
        # N132: no hole check is made here, so no claim about the cause: the page reads as all zeros
        _finding("root page absent",
                 "the root page of object 0x%x reads as all zeros, so it does not match the digest the Object "
                 "Table recorded for it" % oid)
        _OBJ_ROOT_FAILED.add(oid)
        return True
    n = _finding("page-reference mismatch",
                 "the root page of object 0x%x does not match the digest the Object Table recorded "
                 "for it - it has been ALTERED since that digest was written" % oid)
    _OBJ_ROOT_FAILED.add(oid)
    if n <= 3:
        print("[%s] WARNING: metadata page for object 0x%x does not match its recorded checksum — "
              "the page has been altered since the checksum was written." % (PROG, oid), file=sys.stderr)
    return False


_OBJ_ROOT_LCNS = {}
# RC3 F4 (1.14.0, the auditor's RC2 check): the same objects keyed by their root LCNs, tuple(root LCNs) -> [oid, ...], so
# a walk that does not name its object (`walk_bplus` with no oid) still has its root page verified. `files` read the
# security table (0x530) through `build_security_map`, a walk without its oid, and printed an altered ACE with exit 0;
# the sweep (RC1D/rc3/sweep/matrix.tsv) found nine such callers.
_OBJ_ROOT_BY_LCNS = {}


class ObjectMap(dict):
    """LB68 (1.14.0): the object map `build_object_map` returns -- oid -> root LCNs, as before -- carrying how its
    Object Table walk went: `rows_read` (the rows the walk returned) and `walk_damaged` (the walk recorded a page it
    could not read, `_walk_note_damage`). A map is a fact of the walk that made it, so the state travels with it, not in
    a module register (N426's class).
    B2 (1.14.0): `root_vlcns` is the root the walk started from (build_object_map); `bootstrap` adds `root_index`, the
    checkpoint root that is, and `copy_state` ('primary' / 'duplicate' / 'neither', `object_table_copy`), so a reader
    of the Object Table's own pages (integrity's page references, refsanalysis `objects`) reads the copy in use."""
    rows_read = None
    walk_damaged = False
    root_vlcns = None
    root_index = None
    copy_state = None


def object_table_read_state(obj_map):
    """LB68 (1.14.0): None when the Object Table behind `obj_map` was read in full (or the map does not say: a plain
    dict, as the in-process tests build); 'none' when its walk recorded damage and returned no row; 'partial' when it
    recorded damage and returned some rows. Only with None may an absence from the map be stated as an absence from the
    Object Table: rows stored only on a page that could not be read are missing from the map (B3: their absence is not
    evidence they do not exist). `_metadata_incomplete()` (single_source.tsv `metadata_incomplete`) is the run-level
    sibling -- anything this run could not read before that point, a skip of `bootstrap` included -- which the
    summaries' counts use; this test is per walk, so an Object Table read in full is said to hold neither copy even
    when something else of the run was skipped (LB68: "only when the Object Table was read and holds neither")."""
    if not getattr(obj_map, "walk_damaged", False):
        return None
    return "partial" if obj_map.rows_read else "none"


# N358 / N427 / N445 (1.14.0; settlements Q10, Q11): the words for an object missing from a map whose Object Table was
# not read in full -- Q11's "not determined: the Object Table was read in part" -- and the one table of the structures a
# command cannot do its work without. Every statement of absence over the Object Table is worded from its walk's read
# state (`object_table_read_state`): absent only when the table was read in full.
_OT_UNREAD_WORDS = {"partial": "the Object Table was read in part", "none": "the Object Table could not be read"}


def object_absent_reason(obj_map, oid):
    """Why an object missing from `obj_map` is not determined: "the Object Table was read in part, and OID 0x530 is not
    among the rows read" or "the Object Table could not be read" -- None when the Object Table was read in full (then
    it is absent)."""
    st = object_table_read_state(obj_map)
    if st is None:
        return None
    return _OT_UNREAD_WORDS[st] + (", and OID 0x%x is not among the rows read" % oid if st == "partial" else "")


def object_absent_text(obj_map, oid, what):
    """N358 / N445: what may be said of `what` (OID `oid`), which is not in `obj_map`, as (state, text): state None when
    the Object Table was read in full -- "<what> (OID 0x530) is not in the Object Table, which was read in full" --,
    else 'partial' / 'none' with "<what> (OID 0x530): not determined: the Object Table was read in part, and OID 0x530
    is not among the rows read" / "...: not determined: the Object Table could not be read" (`object_absent_reason`)."""
    st = object_table_read_state(obj_map)
    if st is None:
        return None, "%s (OID 0x%x) is not in the Object Table, which was read in full" % (what, oid)
    return st, "%s (OID 0x%x): not determined: %s" % (what, oid, object_absent_reason(obj_map, oid))


def table_unread_text(what, damage_before, rows_read):
    """Q11's "the same for each table one level down": '<what> was read in part' (or 'could not be read' when the walk
    returned no row) when the walk since `damage_before` (`_walk_damage_count()` taken before it) recorded a page it
    could not read, else None -- so a reader that found nothing in that table says "not determined", not "none"."""
    if _walk_damage_count() <= damage_before:
        return None
    return "%s %s" % (what, "was read in part" if rows_read else "could not be read")


# N427 (Q10): the structures a command cannot do its work without -- key: (name, where, the commands that need it).
# `where` is the OIDs that hold it (a failover pair is missing only when neither copy is in the Object Table) or the
# checkpoint root index that refers to it. Missing from an Object Table read in full, or from the checkpoint copy in
# use, it is a finding of the volume: exit 2 -- the tool ran and the volume lacks what the command reads; 1.13.1 said
# "not found" with exit 1 ("cannot run"). Not among the rows of an Object Table read in part: not determined (exit 2).
REQUIRED_STRUCTURES = {
    "security": ("the Security Descriptor Stream", (0x530,), ("security",)),
    "root_directory": ("the root directory", (0x600,),
                       ("reparse", "dataruns", "extract", "export resident-all (their default start)", "files", "search",
                        "specials", "ads", "timestomp", "snapshots", "recyclebin", "refsanalysis files / attributes")),
    "upcase": ("the Upcase Table", (0x8, 0x7), ("refsanalysis upcase",)),      # C1-14: the driver's order (N422)
    "schema": ("the Schema Table", 3, ("refsanalysis schema",)),
    "parent_child": ("the Parent-Child Table", 4, ("refsanalysis parentchild",)),
}


_REQUIRED_SAID = set()     # C1-8: the REQUIRED_STRUCTURES keys whose absence this view has said (walk_directory_tree)


def required_structure_missing(key, obj_map=None, prog=None, pair=None):
    """N427 (Q10): structure `key` of REQUIRED_STRUCTURES is not there. Its statement -- worded from the read state:
    missing from an Object Table read in full (a finding, `_finding`), not determined over one read in part (the walk's
    damage already gives exit 2), or no reference in the checkpoint copy in use (a finding) -- is printed on stderr
    with `prog`'s name. Returns 2, the command's exit code (decision 26 / 27.1: never 1 for a readable volume).
    N422: `pair`, a failover pair (`system_table_pair`) the Object Table holds but no copy of which can be used -- the
    table could not be read (T-CL1 row 4: the open fails): a finding, its rows not determined."""
    name, where, _cmds = REQUIRED_STRUCTURES[key]
    if pair is not None:
        st = None
        text = "%s; this command needs it" % system_table_unread_text(pair)
    elif isinstance(where, tuple):
        oids = " / ".join("OID 0x%x" % o for o in where)
        st = object_table_read_state(obj_map)
        if st is None:
            text = ("%s (%s)%s in the Object Table, which was read in full; this command needs it"
                    % (name, oids, " is not" if len(where) == 1 else ": neither copy is"))
        else:
            text = "%s (%s): not determined: %s%s; this command needs it" % (
                name, oids, _OT_UNREAD_WORDS[st],
                (", and %s among the rows read" % ("it is not" if len(where) == 1 else "neither copy is"))
                if st == "partial" else "")
    else:
        st = None
        text = ("%s: the checkpoint copy in use holds no reference for its root (root %d); this command needs it"
                % (name, where))
    if st is None:
        _finding("required structure", text)
    print("[%s] WARNING: %s." % (prog or PROG, text), file=sys.stderr)
    return 2


def object_lookup_undetermined(obj_map, oid, prog=None):
    """N445's class (census N427: the user-OID lookups of `extract`, `dataruns`, `export resident-all` and `details`):
    OID `oid`, which the examiner asked for, is not in `obj_map`. Over an Object Table not read in full it prints
    "<prog>: OID 0x..: not determined: the Object Table was read in part, ..." on stderr and returns 2; over one read in
    full it returns None, and the caller's own not-found message and exit 1 stand (the table was read and holds no such
    object: a lookup that found nothing, not a condition of the volume)."""
    why = object_absent_reason(obj_map, oid)
    if why is None:
        return None
    print("%s: OID 0x%x: not determined: %s" % (prog or PROG, oid, why), file=sys.stderr)
    return 2


def build_object_map(f, ps, cs, tr, ot_vlcns, register=True):
    """oid -> root LCNs from the Object Table at `ot_vlcns`. With `register` (bootstrap's call), it also records each
    object's root-page digest (_OBJ_ROOT_REF/_OBJ_ROOT_LCNS) and the highest object LSN (_OT_MAX_LSN) for the copy in
    use, replacing everything an earlier call recorded, verified marks (_OBJ_ROOT_VERIFIED) included (N426). N248: a
    caller building ANOTHER checkpoint's table (`deleted`'s comparison) passes register=False, so the
    in-use copy's digests are not replaced by the older copy's.
    LB68 (1.14.0): the map is an `ObjectMap` that says whether this walk read every page it reached (the damage
    register's count before and after the walk, as `table_row_count` decides it), so a caller that finds an object
    absent can tell "the Object Table holds no such row" from "the Object Table could not be read"."""
    _before = _walk_damage_count()
    rows = list(walk_bplus(f, ps, cs, tr, ot_vlcns))
    objects = ObjectMap()
    objects.rows_read = len(rows)
    objects.walk_damaged = _walk_damage_count() > _before
    objects.root_vlcns = list(ot_vlcns)
    if register:
        # N426: the registers describe the copy whose map this call returns -- none of an earlier copy's digests or
        # verified marks survive a refill (an OID only that copy held kept its digest; a verified mark was never cleared)
        del _OT_MAX_LSN[:]
        _OBJ_ROOT_REF.clear()
        _OBJ_ROOT_LCNS.clear()
        _OBJ_ROOT_BY_LCNS.clear()
        _OBJ_ROOT_VERIFIED.clear()
        _OBJ_ROOT_FAILED.clear()
    _hi = 0
    for kd, vd in rows:
        if len(kd) < 16 or len(vd) < 64: continue
        oid = le64(kd, 8)
        # B7/K052: value+0x18 is the object's last-write LSN (E104). The highest of them is the log
        # position the volume actually reached; the checkpoint records the position it was flushed to.
        # Captured here because this walk already happens in every bootstrap -- it costs one comparison.
        _l = le64(vd, 0x18)
        if _l > _hi: _hi = _l
        lcns = [le64(vd, 0x20 + j*8) for j in range(4)]
        valid = [s for s in lcns if s not in (0, 0xFFFFFFFFFFFFFFFF)]
        objects[oid] = valid
        # B1/A9 (RC2): capture the page reference that binds this object's ROOT page, so the listing and
        # content paths can verify the page they are about to read. `--verify-pages` never covered this:
        # it checks CHILD pages inside _walk, while an object's root comes from the Object Table. A byte
        # flipped in a directory's root page was therefore listed and extracted silently, and only
        # `integrity --checksums` noticed. Captured here because this walk already happens in every
        # bootstrap -- the row is in hand, so it costs no extra I/O.
        _clen = le32(vd, 0x44) if len(vd) >= 0x48 else 0
        if register and valid and _clen in (8, 32) and 0x48 + _clen <= len(vd):
            _OBJ_ROOT_REF[oid] = (_clen, bytes(vd[0x48:0x48 + _clen]))
            _OBJ_ROOT_LCNS[oid] = list(valid)
            _OBJ_ROOT_BY_LCNS.setdefault(tuple(valid), []).append(oid)
    if register:
        _OT_MAX_LSN.append(_hi)
    return objects

# ─── Security Descriptor Table ────────────────────────────────────────
def build_security_map(f, ps, cs, tr, obj_map):
    """Build SecurityId → (Owner SID, Group SID) mapping from OID 0x530.

    SD table key (16 bytes): [val_size(4)] [pad(4)] [sid_high(4)] [sid_low(4)]
    SecurityId = (sid_high << 32) | sid_low
    SD table value: [hash(4)] [count(4)] [size(4)] [SECURITY_DESCRIPTOR_RELATIVE...]
    Within the SD (= value[12:]): owner_off u32 @SD+4, GROUP_OFF u32 @SD+8 (read
    identically to owner). Group verified on disk (H3, 2026-06-29): 2383/2383 SDs valid,
    distinct from owner ~56% of the time; group_off==0 (no group) handled but never occurs.
    Each value is (owner_sid_str, group_sid_str); '' = absent.
    """
    if 0x530 not in obj_map:
        return {}
    vlcns = obj_map[0x530]
    rows = walk_bplus(f, ps, cs, tr, vlcns)
    sd_map = {}
    for kd, vd in rows:
        # Extract SecurityId from key
        if len(kd) >= 16:
            sid_high = le32(kd, 8)
            sid_low = le32(kd, 12)
            sec_id = (sid_high << 32) | sid_low
        elif len(kd) >= 8:
            sec_id = le64(kd, 0)
        else:
            continue

        # SD value: 12-byte header then SECURITY_DESCRIPTOR_RELATIVE -- read by THE parser (N325, 1.14.0); it skipped a
        # descriptor of another revision here while `security` decoded it, and turned any DACL error into a blank
        SD_HDR = 12
        if len(vd) < SD_HDR + 20:
            continue
        try:
            sd = _parse_security_descriptor(vd[SD_HDR:])
        except Exception as _e:
            # a descriptor this parser cannot read leaves its files' owner blank -- said, never silent (N325)
            _skip_note("security descriptor", "SecurityId 0x%x" % sec_id, _e)
            continue
        if "error" in sd:
            continue
        owner_str, group_str = sd.get("owner") or "", sd.get("group") or ""
        # DACLSummary (P6): the first six ACEs of the DACL in `security`'s ACE text (K26), the count first
        aces = sd.get("dacl") or []
        parts = [ace_text(a) for a in aces[:6]]
        dacl_sum = (f"{len(aces)} ACE(s): " + "; ".join(parts) + ("; …" if len(aces) > 6 else "")) if parts else ""
        sd_map[sec_id] = (owner_str, group_str, dacl_sum)
    return sd_map

# ─── E-6 (1.14.0): `files --cow-before OLD` -- the comparison of two images of one volume ─────────────────────────
# The maintainer's answer (2026-10-29): with `--cow-before OLD`, `files` outputs the comparison of the two images, not
# the listing -- one row per object that differs, by ObjectRef (created / removed / changed, with the fields that
# differ, before and after); the two images must be of one volume (the superblock's volume GUID); an object is said
# created or removed only when both walks are complete (a missing object of an incomplete walk may sit on a page that
# was not read). 1.13.1 appended the changed DIRECTORIES of the earlier image to the current listing as
# `$COW_PREVIOUS/DIR_OID_0x...` rows -- named from no name row, sized from a child -- and every file created in such a
# directory took the `$COW_PREVIOUS` path as its CreationDir (12,481 of 12,598 rows of labFafterreboot).
COW_FIELDS = ["FullPath", "FileSize", "AllocatedSize", "Created", "Modified", "Changed", "Accessed", "FileAttributes",
              "SecurityId", "USN", "DataResidency", "RecordPlacement", "HardLinkCount", "ADSNames", "SnapshotCount",
              "ReparseTag", "ReparseTarget", "InternalFlags"]
COW_COLUMNS = (["Change", "ObjectRef", "IsDirectory", "FullPath", "ChangedFields"] +
               [w + f for f in COW_FIELDS for w in ("Before", "After")])


def _view_volume_guid(f, ps, cs):
    """The volume GUID of the superblock copy the CURRENT view is read from (`supb_volume_guid`), canonical text."""
    lcn = _SUPB_FELL_BACK.get("used_lcn") or SUPB_LCN
    return _guid_str(supb_volume_guid(_seek_read(f, ps + lcn * cs, cs), cs, lcn))


def _cow_objects(results):
    """{ObjectRef: {"IsDirectory", "FullPath": [paths], field: value}} from a walk: each field typed as `files --json`
    has it (`_csv_fields`), a hard-linked file's names folded into its one object (a field its names do not agree on
    is the list of their values, each as text). Rows with no identity are counted, not compared."""
    objs, unknown = {}, 0
    for r in results:
        d = _csv_fields(r, {}, "", None)
        ref = d["ObjectRef"]
        if not ref:
            unknown += 1
            continue
        o = objs.setdefault(ref, {"IsDirectory": bool(r.get("is_dir")), "_v": {f: {} for f in COW_FIELDS}})
        for fld in COW_FIELDS:
            v = d.get(fld)
            v = None if v == "" else (list(v) if isinstance(v, tuple) else v)
            o["_v"][fld][json.dumps(v, sort_keys=True)] = v          # each field typed as `files --json` has it
    for o in objs.values():
        for fld, vs in o.pop("_v").items():
            vs = [vs[k] for k in sorted(vs)]
            if fld == "FullPath":
                o[fld] = sorted(x for x in vs if x)
            elif len(vs) == 1:
                o[fld] = vs[0]
            else:                                                      # its names disagree: each value as text
                o[fld] = [csv_list_cell(x) if isinstance(x, list) else csv_bool(x) if isinstance(x, bool)
                          else "" if x is None else str(x) for x in vs]
    return objs, unknown


def _view_checkpoint_clock(f, ps, cs, chkp_lcns):
    """The virtual clock (+0x60) of the checkpoint copy the view is read from (`checkpoint_select`'s choice), or None."""
    try:
        iu = checkpoint_select(f, ps, cs, chkp_lcns, require_roots=True).get("in_use")
    except (OSError, ValueError, struct.error):
        return None
    return iu.get("vc") if iu else None


def _cow_same_volume(f, ps, cs, before_image, partition_start_before):
    """E-6: refuse (exit 1) when OLD is not an image of this volume -- the superblock's volume GUID -- before either
    image is walked. The earlier image is read as a view inside this one (`_view_enter` / `_view_leave`)."""
    guid_now = _view_volume_guid(f, ps, cs)
    _outer = _view_enter()
    try:
        try:
            fb, psb, csb, _trb, _rb, _objb, _vmj, _vmn, _ = bootstrap(before_image, partition_start_before)
        except (ValueError, OSError) as e:
            die("--cow-before: the earlier image cannot be read as a ReFS volume: %s" % e)
        try:
            guid_old = _view_volume_guid(fb, psb, csb)
        finally:
            fb.close()
    finally:
        _view_leave(_outer)
    if guid_old != guid_now or guid_now == _guid_str(b"\x00" * 16):
        die("--cow-before: the two images are not of one volume: volume GUID %s here, %s in %s (a comparison of two "
            "volumes would call every object created and removed)" % (guid_now, guid_old, os.path.basename(before_image)))


def cow_compare(f, ps, cs, results, complete, before_image, partition_start_before, depth, chkp_lcns=None):
    """E-6: the rows of the comparison (`COW_COLUMNS`) of this image's walk (`results`, `complete`) with OLD's (walked
    to the same `depth`), and the statements to print. Refuses (exit 1) when OLD is not an image of the same volume.
    A walk is complete when it recorded no damage, no skipped stage and no directory it did not enter."""
    guid_now = _view_volume_guid(f, ps, cs)
    _outer = _view_enter()
    try:
        try:
            fb, psb, csb, trb, _rb, objb, _vmj, _vmn, chkpb = bootstrap(before_image, partition_start_before)
        except (ValueError, OSError) as e:
            die("--cow-before: the earlier image cannot be read as a ReFS volume: %s" % e)
        try:
            guid_old = _view_volume_guid(fb, psb, csb)
            if guid_old != guid_now or guid_now == _guid_str(b"\x00" * 16):
                die("--cow-before: the two images are not of one volume: volume GUID %s here, %s in %s (a comparison "
                    "of two volumes would call every object created and removed)" % (
                        guid_now, guid_old, os.path.basename(before_image)))
            _d0, _s0, _u0 = _walk_damage_count(), len(_SKIP_FINDING), len(_WALK_UNWALKED)
            old = walk_directory_tree(fb, psb, csb, trb, objb, 0x600, depth, True)
            old_complete = (_walk_damage_count() == _d0 and len(_SKIP_FINDING) == _s0
                            and len(_WALK_UNWALKED) == _u0)
            vc_old = _view_checkpoint_clock(fb, psb, csb, chkpb)
        finally:
            fb.close()
    finally:
        _view_leave(_outer)
    now_o, n_unk = _cow_objects(results)
    old_o, o_unk = _cow_objects(old)
    lines = ["Comparison with %s (the same volume: GUID %s): %d objects before, %d now"
             % (os.path.basename(before_image), guid_now, len(old_o), len(now_o))]
    # what the two metadata states are: each image is read from one checkpoint; a change made after it is in the log
    vc_now = _view_checkpoint_clock(f, ps, cs, chkp_lcns) if chkp_lcns is not None else None
    if vc_now is not None and vc_now == vc_old:
        lines.append("Both images are read from a checkpoint with virtual clock %d: the metadata they commit is one "
                     "state -- a change made after that checkpoint is not in it (the log holds it: `mlog`)" % vc_now)
    elif vc_now is not None and vc_old is not None and vc_old > vc_now:
        lines.append("The earlier image (--cow-before) is read from the NEWER checkpoint (virtual clock %d; this "
                     "image %d): 'created' and 'removed' are as seen from this image" % (vc_old, vc_now))
    both_complete = complete and old_complete
    if not both_complete:
        lines.append("Created / removed objects are NOT stated: the walk of %s was not complete (pages it could not "
                     "read may hold them); the changed objects are listed" % (
                         " and ".join(x for x, ok in (("this image", complete), ("the earlier image", old_complete))
                                      if not ok)))
    if n_unk or o_unk:
        lines.append("%d name row(s) here and %d in the earlier image carry no ObjectRef and are not compared"
                     % (n_unk, o_unk))
    rows = []

    def row(change, ref, o_new, o_old, fields):
        r = {c: None for c in COW_COLUMNS}
        r.update({"Change": change, "ObjectRef": ref, "IsDirectory": (o_new or o_old)["IsDirectory"],
                  "FullPath": (o_new or o_old)["FullPath"], "ChangedFields": list(fields)})
        for fld in fields:
            if o_old is not None:
                r["Before" + fld] = o_old[fld]
            if o_new is not None:
                r["After" + fld] = o_new[fld]
        return r
    def _refkey(x):
        try:
            return tuple(int(h, 16) for h in x.split(":"))
        except ValueError:
            return (1 << 64, x)
    for ref in sorted(set(old_o) | set(now_o), key=_refkey):
        a, b = old_o.get(ref), now_o.get(ref)
        if a is None:
            if both_complete:
                rows.append(row("created", ref, b, None, [x for x in COW_FIELDS if b[x] not in (None, "", [])]))
        elif b is None:
            if both_complete:
                rows.append(row("removed", ref, None, a, [x for x in COW_FIELDS if a[x] not in (None, "", [])]))
        else:
            diff = [x for x in COW_FIELDS if a[x] != b[x]]
            if diff:
                rows.append(row("changed", ref, b, a, diff))
    lines.append("%d created, %d removed, %d changed" % tuple(sum(1 for r in rows if r["Change"] == c)
                                                            for c in ("created", "removed", "changed")))
    return rows, lines

def _collect_dir_entries(f, ps, cs, tr, obj_map, oid, parent_path, out, visited, depth, max_depth):
    """Helper: collect directory entry names from a tree (for checkpoint comparison)."""
    if depth > max_depth or oid in visited or oid not in obj_map:
        return
    visited.add(oid)
    vlcns = obj_map[oid]
    try:
        rows = walk_bplus(f, ps, cs, tr, vlcns)
    except Exception as _e:
        _skip_note("_collect_dir_entries", "a directory's rows", _e)
        return
    for kd, vd in rows:
        if len(kd) < 4 or le16(kd, 0) != 0x30: continue
        name = _row_name(kd, "directory entry")
        if name is None: continue
        full_path = f"{parent_path}/{name}" if parent_path else name
        child_oid = 0
        if len(vd) <= NON_RESIDENT_MAX_VALUE and len(vd) >= 0x10:
            child_oid = le64(vd, 0x08)
        out[(oid, name)] = {"name": name, "path": full_path, "oid": child_oid}
        if child_oid and len(vd) <= NON_RESIDENT_MAX_VALUE and len(vd) >= 0x44:
            if le32(vd, 0x40) & 0x10000000:
                _collect_dir_entries(f, ps, cs, tr, obj_map, child_oid, full_path, out, visited, depth+1, max_depth)


# ─── Inline reparse target extraction (for resident entries) ──────────
def extract_inline_reparse(vd):
    """Extract reparse target from a resident entry's embedded attributes."""
    SYMLINK_TAG = b"\x0c\x00\x00\xa0"
    MOUNT_TAG = b"\x03\x00\x00\xa0"
    LX_SYM_TAG = b"\x1d\x00\x00\xa0"

    for tag_bytes, tag_val in [(SYMLINK_TAG, 0xA000000C), (MOUNT_TAG, 0xA0000003), (LX_SYM_TAG, 0xA000001D)]:
        search_start = 0xA8
        idx = vd.find(tag_bytes, search_start)
        if idx < 0 or idx + 20 > len(vd):
            continue
        data_len = le16(vd, idx + 4)
        if data_len < 4:
            continue

        if tag_val == 0xA000000C:  # SYMLINK
            sub_off = le16(vd, idx + 8)
            sub_len = le16(vd, idx + 10)
            print_off = le16(vd, idx + 12)
            print_len = le16(vd, idx + 14)
            buf_start = idx + 20
            if print_len > 0 and buf_start + print_off + print_len <= len(vd):
                try:
                    return vd[buf_start+print_off:buf_start+print_off+print_len].decode("utf-16-le")
                except UnicodeDecodeError as _e:
                    _skip_note("reparse target decode", "extract_inline_reparse", _e)
            if sub_len > 0 and buf_start + sub_off + sub_len <= len(vd):
                try:
                    target = vd[buf_start+sub_off:buf_start+sub_off+sub_len].decode("utf-16-le")
                    if target.startswith("\\??\\"):
                        target = target[4:]
                    return target
                except UnicodeDecodeError as _e:
                    _skip_note("reparse target decode", "extract_inline_reparse", _e)
        elif tag_val == 0xA0000003:  # MOUNT_POINT/JUNCTION
            sub_off = le16(vd, idx + 8)
            sub_len = le16(vd, idx + 10)
            print_off = le16(vd, idx + 12)
            print_len = le16(vd, idx + 14)
            buf_start = idx + 16
            if print_len > 0 and buf_start + print_off + print_len <= len(vd):
                try:
                    return vd[buf_start+print_off:buf_start+print_off+print_len].decode("utf-16-le")
                except UnicodeDecodeError as _e:
                    _skip_note("reparse target decode", "extract_inline_reparse", _e)
        elif tag_val == 0xA000001D:  # LX_SYMLINK
            # review E5 fix: the LX_SYMLINK payload is u32 version(=2) + UTF-8 target; skip the 4-byte
            # version (idx+8 -> idx+12) so it does not prefix the target with "\x02\x00\x00\x00".
            try:
                return vd[idx+12:idx+8+data_len].decode("utf-8").rstrip("\x00")
            except UnicodeDecodeError as _e:
                _skip_note("reparse target decode", "extract_inline_reparse", _e)
        return REPARSE_TAGS.get(tag_val, f"0x{tag_val:08x}")
    return ""

def extract_reparse_from_backing(vd):
    """Validated REPARSE_DATA_BUFFER target path embedded in a NON-RESIDENT file's type-0x40
    backing record (v3.14). Scans for the symlink (0xa000000c) / junction (0xa0000003) buffer
    at its VARIABLE offset, decodes Print/Substitute name, and accepts only a real path; the
    +0x7c tag MIRROR (a bare tag dword, no valid buffer) is explicitly skipped so it is never
    mistaken for the buffer. Returns '' when no valid target embeds (e.g. v3.7-v3.10, whose
    live backing carries only the +0x7c mirror). H3-verified 2026-06-29: 100% on native v3.14,
    correctly empty on v3.7-v3.10. Caller selects the file's OWN backing via the verified
    hard-link resolution (home stream), which avoids the file_id-collision wrong-target bug."""
    for tag_bytes, has_flags in ((b"\x0c\x00\x00\xa0", True), (b"\x03\x00\x00\xa0", False)):
        pos = 0
        while True:
            idx = vd.find(tag_bytes, pos)
            if idx < 0:
                break
            pos = idx + 1
            if idx == 0x7C or idx + 0x10 > len(vd):   # 0x7C = the tag mirror, not the buffer
                continue
            sub_off = le16(vd, idx + 0x08); sub_len = le16(vd, idx + 0x0A)
            print_off = le16(vd, idx + 0x0C); print_len = le16(vd, idx + 0x0E)
            buf_start = idx + (0x14 if has_flags else 0x10)   # symlink has a 4-byte Flags field
            if print_len > 0 and buf_start + print_off + print_len <= len(vd):
                try:
                    t = vd[buf_start+print_off:buf_start+print_off+print_len].decode("utf-16-le")
                    if t and ("\\" in t or ":" in t):
                        return t
                except UnicodeDecodeError as _e:
                    _skip_note("reparse target decode", "extract_reparse_from_backing", _e)
            if sub_len > 0 and buf_start + sub_off + sub_len <= len(vd):
                try:
                    t = vd[buf_start+sub_off:buf_start+sub_off+sub_len].decode("utf-16-le")
                    if t.startswith("\\??\\"):
                        t = t[4:]
                    if t and ("\\" in t or ":" in t):
                        return t
                except UnicodeDecodeError as _e:
                    _skip_note("reparse target decode", "extract_reparse_from_backing", _e)
    return ""

# ─── Per-object $SI extraction ────────────────────────────────────────
def get_object_si(f, ps, cs, tr, vlcns, status=None):
    """Walk an object's B+ tree and extract $STANDARD_INFORMATION (type 0x10)."""
    try:
        rows = walk_bplus(f, ps, cs, tr, vlcns)
    except Exception as _e:
        # Indistinguishable from "this object has no $SI" unless the failure is recorded.
        _skip_note("$STANDARD_INFORMATION", "object tree", _e)
        return _outcome(status, None, _e)      # unreadable: NOT the same as "this object has no $SI"
    for kd, vd in rows:
        if len(kd) >= 2 and le16(kd, 0) == 0x10:
            result = {}
            if len(vd) >= 0x60:
                result["create_time"] = le64(vd, 0x28)
                result["modify_time"] = le64(vd, 0x30)
                result["change_time"] = le64(vd, 0x38)
                result["access_time"] = le64(vd, 0x40)
                result["file_attrs"] = le32(vd, 0x48)
                result["internal_flags"] = le32(vd, 0x4C)
                result["security_id"] = le64(vd, 0x50)
                # CORRECTED 2026-06-17 (disk-proven, errata E30 retracted / E45): the file's
                # USN-journal pointer is LastUsn at $SI+0x40 (value+0x68), NOT $SI+0x30 (value+0x58).
                # value+0x58 ($SI+0x30) is 0 on 0/32,629 own-rows corpus-wide — never a populated USN.
                # LastUsn = virtual byte offset of the file's most recent $UsnJrnl:$J record (OID 0x520).
                result["usn"] = le64(vd, 0x68) if len(vd) >= 0x70 else 0
                result["usn_journal_id"] = le64(vd, 0x70) if len(vd) >= 0x78 else 0
            return result
    return _outcome(status, None)

# ─── Embedded B+-tree row parser (shared by snapshot/ADS/file-size) ───
_B0_MARKER = b"\x02\x00\x00\x80"  # 0x80000002 little-endian (multi-instance)
_SI_MARKER = b"\x01\x00\x00\x80"  # 0x80000001 little-endian (single-instance)


def _descend_embedded_index(vd, base, ctx, _depth=0):
    """E73: the embedded attribute node is an INDEX node — its rows are child-page pointers, not attributes.

    A file whose attribute set outgrows one embedded node gets a real multi-level B+-tree: the node inside the
    type-0x30 value becomes an index node (descriptor+0x0c level != 0, +0x0d bit0 set) holding ONE row per child
    with an EMPTY separator key (key_offset 0x10 / key_size 0) whose value is a 48-byte node reference. The
    attributes ($DATA, ADS, $EA, $SNAPSHOT, $REPARSE ...) live in the child PAGE, not in the value. The driver
    does exactly this descent (`CmsEmbeddedComposite::FindIndexHeaderInPage` -> `CmsBPlusTable::BinarySearchIndex`).
    Returns the child rows in the same (key, value) shape as a leaf parse, so every caller is transparently fixed.
    """
    f, ps, cs, tr = ctx
    if _depth > 3:
        return []
    rows = []
    for lcns, val in _embedded_index_refs(vd, base):
        try:
            if _VERIFY_PAGES:
                # A6: --verify-pages checks the child page against the digest its reference carries, as `_walk`
                # checks an inner row's child (1.13.1 read it unchecked, K046); one more read, only under the option
                _pg = _read_full_page(f, ps, cs, list(lcns), tr)
                if _pg:
                    _verify_child_page(val, _pg, "embedded attribute index child, LCN 0x%x" % lcns[0])
            rows.extend(walk_bplus(f, ps, cs, tr, list(lcns)))
        except Exception as _e:
            _skip_note("_descend_embedded_index", "an embedded index node", _e)
            continue
    return rows


def _embedded_index_refs(vd, base):
    """E73: the child-page references of the embedded INDEX node at vd[base:] -- [(lcns, reference)], one per child
    page in row order (a reference is the 48-byte node reference: 4 LCN slots, the digest frame at +0x22..)."""
    astart = le32(vd, base + 0x10); aend = le32(vd, base + 0x20)
    if not (0 < astart < aend) or base + aend > len(vd):
        return []
    out = []; seen = set(); pos = base + astart
    while pos + 4 <= base + aend and pos + 4 <= len(vd):
        off = le16(vd, pos); pos += 4
        ab = base + off
        if ab + 16 > len(vd):
            continue
        _, ko, kl, _, vo, vl, _ = struct.unpack_from("<I6H", vd, ab)
        if vl < 32 or ab + vo + vl > len(vd):
            continue
        val = vd[ab + vo:ab + vo + vl]
        lcns = tuple(x for x in (le64(val, i * 8) for i in range(4))
                     if x not in (0, 0xFFFFFFFFFFFFFFFF))
        if not lcns or lcns in seen:
            continue
        seen.add(lcns)
        out.append((lcns, val))
    return out


def _is_v34_data_key(kd):
    """The v3.4 key of a file's $DATA attribute row: 14 bytes, `<id u64> | 80 00 | 00 00 00 00` -- the attribute type
    at key+0x08 and no instance marker (K098, E72). A volume formatted at v3.7 or later carries the marker form
    (0x80000002 at key+0x08, type 0x80 at key+0x0c, the sub-stream id at key+0x10); a volume upgraded from v3.4 keeps
    the v3.4 key on its old records. Its value is the v3.4 stream summary: the allocation at +0x34, the size at +0x3c,
    and, when the stream is in extents, the extent node at +0x88 -- a leaf, or an index whose rows name child pages
    (E86), measured on 39 + 43 + 1 + 1 index nodes of four v3.4 volumes."""
    return len(kd) == 14 and le32(kd, 8) == 0x80 and le16(kd, 0x0C) == 0


def _row_index_child_refs(vd, ctx):
    """A6 (K046): the child-page references a row's VALUE holds -- below its embedded attribute index (E73) and below
    the extent index of each of its streams in extent form (E86: every $DATA stream, the current one and every
    snapshot version's, in the v3.14 and the v3.4 key form, and any other stream whose summary is the extent form) --
    each carrying the digest of the page it names. These pages are part of the metadata tree (the driver descends into them), but
    no B+-tree walk reaches them: their references are in a leaf row's value, not in an inner row. `integrity
    --fullchecksums` verifies them through this."""
    out = []
    if len(vd) < 0xC0:
        return out
    base = le32(vd, 0)
    if 0x28 <= base < len(vd) - 0x28 and base + 0x24 <= len(vd) and (vd[base + 0x0D] & 0x01):
        out += [val for _l, val in _embedded_index_refs(vd, base)]
    try:
        attrs = parse_resident_btree_rows(vd, ctx)
    except Exception as _e:
        _skip_note("integrity: index child references", "a row's attributes", _e)
        attrs = []
    for akd, aval in attrs:
        # RC-1 (wave C's close): the v3.4 key form as well -- a v3.4 file's extent index has child pages too (39 on
        # win10refs8gsetintegristystreams1, none verified before) -- and any other stream whose value is the
        # extent-form stream summary (+0x00 = 0x88, +0x04 = 0x00010028), whatever its attribute key: no stream type is
        # left out (none but $DATA carries an index-level node on the volumes measured)
        if not (len(aval) > 0x88 and le32(aval, 0) == 0x88
                and ((len(akd) >= 0x10 and le32(akd, 8) == 0x80000002 and le16(akd, 0x0C) == 0x0080)
                     or _is_v34_data_key(akd) or le32(aval, 4) == 0x00010028)):
            continue
        level, offs = _extent_node_rows(aval, 0x88)
        if not level:
            continue                                     # a leaf extent node: its rows are extents, no child page
        for ro in offs:
            if ro + 0x10 > len(aval):
                continue
            _sz, _ko, _kl, _fl, vo, vl, _x = struct.unpack_from("<I6H", aval, ro)
            if vl >= 0x30 and ro + vo + vl <= len(aval):
                out.append(aval[ro + vo:ro + vo + vl])
    return out


def parse_resident_btree_rows(vd, ctx=None, salvage=False):
    """Parse embedded B+-tree row offset table in a resident directory entry value.

    Returns list of (key_bytes, value_bytes) tuples for all rows found.
    Row offset table is at the end of vd (4-byte entries: u16 offset + 0xffff marker).
    Base offset for the data area is le32(vd, 0).

    `ctx` = (f, ps, cs, tr). When supplied AND the embedded node is an INDEX node, the real attribute rows are
    in a child page and are fetched by descending (E73). Without `ctx` the behaviour is exactly as before —
    an index node yields no rows — so every existing caller is unchanged until it opts in.
    """
    if len(vd) < 0xC0:
        return []
    base = le32(vd, 0)
    if base < 0x28 or base >= len(vd) - 0x28:
        # NOT instrumented, deliberately (B4). A base of 0 simply means "this value carries no embedded
        # tree", which is the normal case for deleted and carved records -- an attempt to flag it as an
        # anomaly fired on healthy volumes because the census behind it only covered the live-directory
        # walk and never reached the deleted/carve path.
        return []
    if ctx is not None and base + 0x24 <= len(vd) and (vd[base + 0x0D] & 0x01):
        return _descend_embedded_index(vd, base, ctx)
    # K005 (RC2): TWO entry points, because the two callers want different things.
    #
    # LIVE enumeration (salvage=False, the default) is bounded by the node header's row count. The old
    # code walked BACKWARD from the end of the value while the u16 at pos+2 read 0xFFFF, and that word
    # is not a two-valued sentinel -- it is a B+-tree upper bound taking 38 distinct values over 689,639
    # entries (K101/K168). The scan therefore ran past the array start into free space, where slots from
    # an earlier state of the node still carry 0xFFFF and still address real rows, and the tool reported
    # ALTERNATE DATA STREAMS THAT DO NOT EXIST: 28 files, 44 fabricated names.
    #
    # SALVAGE (salvage=True) keeps the unbounded scan, and must. A deletion DECREMENTS the header's row
    # count while the slots below still address the old rows -- which is precisely how the carve path
    # recovers deleted content. Bounding it cost 99 carved files and 90 distinct content hashes on
    # win11refstestmftecmd when both paths shared one reader; that is why this is a parameter and not a
    # replacement.
    offsets = []
    _arr_lo = _cnt = _arr_hi = None
    if base + 0x24 <= len(vd):
        _arr_lo, _cnt, _arr_hi = le32(vd, base + 0x10), le32(vd, base + 0x14), le32(vd, base + 0x20)
    _hdr_ok = (not salvage
               and _arr_lo is not None
               and 0 < _arr_lo < _arr_hi
               and base + _arr_hi <= len(vd)
               and (_arr_hi - _arr_lo) % 4 == 0
               and (_arr_hi - _arr_lo) // 4 == _cnt
               and 0 < _cnt <= 8192)
    if _hdr_ok:
        for _i in range(_cnt):
            offsets.append(le16(vd, base + _arr_lo + _i * 4))
    else:
        pos = len(vd) - 4
        while pos >= base:
            if le16(vd, pos + 2) != 0xFFFF:
                break
            offsets.append(le16(vd, pos))
            pos -= 4
    rows = []
    for off in offsets:
        abs_off = base + off
        if abs_off + 16 > len(vd):
            continue
        rh = struct.unpack_from("<I6H", vd, abs_off)
        _, ko, kl, _, vo, vl, _ = rh
        if ko == 0 or kl == 0:
            continue
        key_abs = abs_off + ko
        val_abs = abs_off + vo
        if key_abs + kl > len(vd) or val_abs + vl > len(vd):
            continue
        rows.append((bytes(vd[key_abs:key_abs + kl]),
                      bytes(vd[val_abs:val_abs + vl])))
    return rows


def _b0_name_offset(kd):
    """Offset of the stream NAME in a 0xb0 embedded-attribute key, or None if this is not one.

    The key has TWO on-disk forms (E72). From v3.7 an instance marker sits at key+0x08, the attribute type
    at key+0x0c and the UTF-16 name from key+0x10. On v3.4 there is NO marker: the type is at key+0x08 and
    the name starts at key+0x0c. Matching only the marker form makes every v3.4 alternate data stream
    invisible — 176 live `hidden_*` streams on win10refs2tspecials alone, which the reader reported as
    "0 ADS" until this was fixed.
    """
    if len(kd) >= 14 and kd[8:12] in (_B0_MARKER, _SI_MARKER) and kd[12] == 0xB0 and kd[13] == 0x00:
        return 0x10
    if len(kd) >= 12 and kd[8] == 0xB0 and kd[9] == 0x00 and kd[10] == 0x00 and kd[11] == 0x00:
        return 0x0C          # v3.4, marker-less
    return None


def _b0_stream_name(kd):
    """UTF-16LE stream name from a 0xb0 key, whichever form it is in ("" if absent/undecodable)."""
    off = _b0_name_offset(kd)
    if off is None or len(kd) <= off:
        return ""
    try:
        return kd[off:].decode("utf-16-le").rstrip("\x00")
    except UnicodeDecodeError as _e:
        _skip_note("_b0_stream_name", "a stream name", _e)
        return ""


def _is_b0_snapshot_key(kd):
    """True if the B+-tree key is a 0xb0 embedded attribute, in either the marker or the v3.4 form."""
    return _b0_name_offset(kd) is not None


def _is_snapshot_value(vd):
    """True if the StreamSummary flags at val+0x10 == 2 (snapshot, not ADS).
    C11: the field is a u16 at 0x10 (0=ADS, 2=snapshot; +0x12 reserved-zero). The old le32!=0 read
    worked only by coincidence (0x12==0); le16==2 matches the doc and recover_snapshot_streams."""
    return len(vd) >= 0x14 and le16(vd, 0x10) == 2


def _snapshot_meta(vd, ctx=None):
    """(name, sub_id, ts) for each true snapshot 0xb0 sub-record in a resident value — the single source for
    both the count and the names. Name = the snapshotted stream name (0xb0 key bytes @+0x10, UTF-16LE);
    sub_id = value+0x44 (the data sub-id); ctime = value+0x4c. Same predicate as before (le16@+0x10 == 2)."""
    out = []
    for kd, vd_row in parse_resident_btree_rows(vd, ctx):
        if not (_is_b0_snapshot_key(kd) and _is_snapshot_value(vd_row)):
            continue
        name = _b0_stream_name(kd)                    # handles both key forms (E72)
        if not name:
            _off = _b0_name_offset(kd) or 0x10
            name = kd[_off:].hex() if len(kd) > _off else ""
        sub_id = le32(vd_row, 0x44) if len(vd_row) >= 0x48 else 0
        ts = le64(vd_row, 0x4C) if len(vd_row) >= 0x54 else 0
        out.append((name, sub_id, ts))
    return out

def count_snapshots_in_resident(vd, ctx=None):
    """Count true snapshot entries within a resident directory entry value."""
    return len(_snapshot_meta(vd, ctx))


# ─── Resident file-size extraction ───────────────────────────────────
def get_resident_file_size(vd, ctx=None, v34_key=True):
    """Extract file content size from the $DATA sub-record in a resident value.

    The $DATA row in the embedded B+-tree has key marker 0x80000001 + attr type 0x80.
    Stream size is at value offset 0x20.

    v34_key=False leaves out the v3.4-keyed row (K098) and answers the narrower question the B2 gate
    asks -- is there a marker-keyed $DATA row at the outer level? -- see _multilevel_extent_backed_size.
    """
    return _resident_data_sizes(vd, ctx, v34_key)[0]


def _resident_data_sizes(vd, ctx=None, v34_key=True):
    """(size, total_alloc, disk_alloc, form) of an embedded record's CURRENT $DATA stream, every number read
    from the ONE row that answers. An allocation is None where that row has no such field (the resident SI
    form, whose bytes are inline; disk_alloc on v3.4, E72); `form` names the row: "si", "v34", "holder",
    or None when no row answers (size 0). See _reported_alloc for why both allocations are returned."""
    for kd, vd_row in parse_resident_btree_rows(vd, ctx):
        if (len(kd) >= 14 and kd[8:12] == _SI_MARKER
                and kd[12] == 0x80 and kd[13] == 0x00):
            if len(vd_row) >= 0x28:
                return le64(vd_row, 0x20), None, None, "si"
        # K098: the v3.4 $DATA row has a different KEY -- 14 bytes, `<id u64> | 80 00 | 00 00 00 00`, the
        # attribute type at key+0x08 -- so the v3.14 marker test above never matched it and this function
        # returned 0 for every embedded v3.4 file (263/263 on win10refs2g; `refsanalysis details` printed
        # "File size: 0 bytes"). The row IS reachable at the outer level; its size is at value+0x3C, equal to
        # the name row's own +0x58 on 280/280 measured rows. On a volume FORMATTED at v3.7 or later key+0x08
        # is the marker 01 00 00 80 and this branch cannot match; a volume UPGRADED from v3.4 keeps the v3.4 key
        # on its old records and is read here too (win10to11refs4g, before and after the Win11 mount).
        # It is the v3.4 layout of the stream summary: total allocation at +0x34 (E72).
        if v34_key and _is_v34_data_key(kd) and len(vd_row) >= 0x44:
            return le64(vd_row, 0x3C), le64(vd_row, 0x34), None, "v34"
    # Fallback: a stream-snapshotted / CoW'd resident file has no live 0x80000001 $DATA row — its
    # live stream lives in the type-0x80 descriptor-0x10028 holder keyed by the CURRENT sub_id 0x1000
    # (older snapshots are 0x1001, 0x1002, ...). The current content byte size is at value+0x38, the file's
    # total allocation at +0x30.
    # (E2/RD: win11refs2tsnapshots — arg.txt=15, lasttest.txt=201, test.txt=5.)
    for kd, vd_row in parse_resident_btree_rows(vd, ctx):
        if (len(kd) >= 0x18 and kd[12] == 0x80 and kd[13] == 0x00
                and len(vd_row) >= 0x40 and le32(vd_row, 4) == SNAP_DATA_DESC
                and le64(kd, 0x10) == 0x1000):
            return (le64(vd_row, 0x38), le64(vd_row, 0x30),
                    le64(vd_row, 0x48) if len(vd_row) >= 0x50 else None, "holder")
    return 0, None, None, None


def _reported_alloc(vd, size, total, disk, form):
    """AllocatedSize for an EMBEDDED record, given what _resident_data_sizes read (K095).

    The name row's header carries a copy of the size (+0x58) and the allocation (+0x60). When that copy is
    CURRENT its allocation is the one to report: over the corpus it equals both descriptor fields on 77,800
    records, and where those two differ it follows disk_alloc on 53 (sparse) and total_alloc on 50
    (snapshotted, blocks shared) -- neither descriptor field reproduces it alone. But the copy can go STALE:
    3 records, all on real Windows installations (a SQLite WAL among them), carry a header size behind the
    descriptor's, and `files` then paired the descriptor's size with the header's allocation -- 3,271,312
    bytes in 3,211,264. On all 3 the two descriptor fields agree; the extent map covers exactly that
    (2/2 with extents). So a stale header's allocation is replaced by the descriptor's when the descriptor
    gives one answer, and reported as unknown (None) when it does not -- the inline form has no allocation
    field of its own, and the corpus shows that case too: one System32 log, stale on both winsider images
    (embedded on one, split on the other), is reported with a blank allocation rather than a number already
    known to be stale."""
    return _reported_alloc_from(le64(vd, 0x58), le64(vd, 0x60), size, total, disk, form)


def _reported_alloc_from(h58, h60, size, total, disk, form):
    """_reported_alloc on the header's two values -- shared by an embedded record and a split record's backing,
    whose header is the same cached pair (and went stale on 1 of 89,009+20,727 backings: `winsiderv2`, a
    System32 log whose inline data is 1,606 bytes under a header of 1,460). A form that has no allocation
    field of its own (the inline SI form) gives no single answer, so a stale header's allocation is unknown."""
    if form is not None and h58 != size:
        return total if (total is not None and total == disk) else None
    return h60


# ─── The two storage axes (E87) ───────────────────────────────────────
# "Resident" was one word for two independent properties, which is why this file used to
# decide `is_resident` twice: once from the name row's length (placement) and again from the
# $DATA descriptor (residency), overwriting the first with the second.
#
#   RECORD PLACEMENT  embedded in the name row, or split into a type-0x40 backing.
#                     key_flags at type-0x30 key+0x02: 0x01 embedded, 0x02 split.
#                     A move or a hard link forces the split -- and moves no data.
#   DATA RESIDENCY    where the bytes are. Read from the $DATA sub-record's own header.
#
# A 0-byte file is decided by descriptor form like any other: an inline-form record that
# happens to carry no bytes is `inline`; an extent-form one is `extents`.
# `unallocated`, not `sparse`: the residency state says the stream's range has NO allocation behind it.
# `sparse` already names something else here -- the FILE_ATTRIBUTE_SPARSE_FILE bit, which `--filter sparse`
# and `specials` report -- and one word meaning two things in the same output is how a reader is misled.
DATA_INLINE, DATA_EXTENTS, DATA_SNAPSHOT_SHARED, DATA_SPARSE, DATA_UNKNOWN = (
    "inline", "extents", "snapshot-shared", "unallocated", "unknown")


def _stream_data_form(rec, ctx=None):
    """DATA RESIDENCY of a file record's CURRENT stream. `rec` is the embedded name-row value
    or the type-0x40 backing -- the same test applies to both, which is the point.

    Returns one of DATA_*:
      inline           the descriptor is the resident form (summary_size@0x0c == 0x30,
                       StreamSummary flags@0x10 == 0); the bytes are at +0x3c, and there may be none.
      extents          the extent-bearing form (inner header 0x88 / descriptor 0x00010028),
                       with an allocation of its own.
      snapshot-shared  extent form owning NO allocation (disk_alloc@+0x48 == 0) while a
                       snapshot sub-record for the same stream exists -- the live bytes are
                       the snapshot's (E83).
      unallocated      extent form owning no allocation and NO snapshot row: nothing was ever
                       written. Measured on `bigsparse.dat` / `sparse.dat`; without this the
                       two are indistinguishable from the snapshot case. (Named `sparse` before
                       1.11.0; the constant is DATA_SPARSE for source compatibility.)
                       K004: reached only when the declared size is NON-ZERO. A 0-byte stream is
                       classified by DESCRIPTOR FORM like any other -- an extent-form one is
                       `extents` -- because "nothing was ever written" is not a distinguishable
                       state for a stream that has nothing to write. Documented as an exception.
      unknown          no $DATA row, or a shape that matches none of the above.
    """
    try:
        rows = parse_resident_btree_rows(bytes(rec), ctx)
    except (ValueError, struct.error, IndexError):
        return DATA_UNKNOWN
    live = None
    snapshot_rows = False
    v34 = None
    for kd, vr in rows:
        if len(kd) < 0x0E:
            continue
        mk, ty = le32(kd, 8), le16(kd, 0x0C)
        if ty == 0x0080 and mk in (0x80000001, 0x80000002):
            sub = le32(kd, 0x10) if len(kd) >= 0x14 else None
            if mk == 0x80000001 and live is None:
                live, v34 = bytes(vr), False
            elif sub == 0x1000 and live is None:
                live, v34 = bytes(vr), False
            elif sub is not None and sub > 0x1000:
                snapshot_rows = True
        elif _is_v34_data_key(kd) and live is None:
            live, v34 = bytes(vr), True          # v3.4 key: no marker, type u32 at +0x08
    if live is None:
        return DATA_UNKNOWN
    if len(live) >= 0x14 and le32(live, 0x0C) == 0x30 and le32(live, 0x10) == 0:
        return DATA_INLINE
    if len(live) >= 8 and le32(live, 0) == 0x88 and le32(live, 4) == 0x00010028:
        size = le64(live, 0x3C if v34 else 0x38) if len(live) >= 0x44 else 0
        if not v34 and size > 0 and len(live) >= 0x50 and le64(live, 0x48) == 0:
            return DATA_SNAPSHOT_SHARED if snapshot_rows else DATA_SPARSE
        return DATA_EXTENTS
    return DATA_UNKNOWN


# ─── Skipped work is reported, never swallowed (Phase 1.3) ────────────────
# A swallowed exception is indistinguishable from "nothing was there", which is how a reader
# returns a confident wrong answer: E73's outer-level-only parse returned [] and every consumer
# reported "no attributes". Anything that gives up on part of the volume says so, once per kind,
# with a count -- and anything that would otherwise emit BYTES raises instead (never invent data).
_SKIP_NOTES = {}
_SKIP_EXPECTED = {}   # expected=True notes (a data condition, not skipped work) -- counted here only, never in _SKIP_NOTES
_VERSION_CONTRADICTED = []  # K051: the boot sector's version is implausible or contradicted by the
                            # checkpoint / $VOLUME_INFORMATION. The VBR is the easiest structure to edit.
_OT_MAX_LSN = []          # B7/K052: highest per-object last-write LSN seen in the Object Table
_CHKP_STALE = []          # A1/K035: the active checkpoint was unusable and an OLDER one was used, or a
                          # copy's two clocks disagree. Drives the exit status and is reported by `summary`.
                          # N426: a fact of the CURRENT view (a `view` register, reset by `_new_view`; an earlier
                          # view's conditions stay findings of the run, `_CHKP_EARLIER_VIEW`).
# ---------------------------------------------------------------------------------------------------
# S1 (RC2): ONE place a finding is recorded, and the only place a verdict or an exit code may read.
#
# The defect this exists to end: `_pr["failed"]` -- the Object-Table page-reference mismatch counter --
# occurred exactly ONCE in this file, on the line that printed it. A flipped byte in a directory's root
# page therefore printed "Mismatched: 1" and, three lines later, "VERDICT: all N checksummed pages
# VERIFIED - no tampering/corruption", PASS, rc 0. The same shape gave a zeroed primary superblock rc 2
# from `summary` and rc 0 from `files`, because that finding was wired into one command.
#
# Plan v12 section 4 names this class first -- "a check that computes a failure and a verdict that
# ignores it" -- and it survived because every previous fix added ANOTHER counter (_SKIP_FINDING,
# _WALK_DAMAGE, _CHKP_STALE, backup_warn) instead of a sink. Counters are per-site; a sink is not.
#
# `_finding()` is the only way to record one, `_findings()` the only way to read them, and the gate
# `check_finding_reachability.py` asserts no counter is print-only.
_FINDINGS = []            # [(kind, text)] -- every finding, whatever produced it
# N426 (1.14.0): the findings recorded while the CURRENT volume view is the one read -- a `view` register, reset when a
# view starts (`_new_view`). `_FINDINGS` is the run's sink (the exit code); a statement about the view (integrity's page
# verdict, refsanalysis supb's NOTE) reads this list, so a finding of an earlier volume is never said of this one.
_VIEW_FINDINGS = []       # [(kind, text)]


# D3b (1.14.0): while a HELD reading runs (`_held_reading`) -- one that only uses what it reads, for a value another
# command states -- the findings and skip notes it would record are kept here instead, one list per reading
_HELD = []


def _finding(kind, text):
    """Record a finding: in the run's sink (`_FINDINGS`, the exit code) and in the current view's list
    (`_VIEW_FINDINGS`, N426). Returns the running count for this kind in the run, so a caller can still print a
    number. During a held reading (`_HELD`) it is kept in that reading's list instead."""
    if _HELD:
        _HELD[-1].append(text)
        return 0
    _FINDINGS.append((kind, text))
    _VIEW_FINDINGS.append((kind, text))
    return sum(1 for k, _ in _FINDINGS if k == kind)


def _findings(kind=None):
    """The run's findings (of one kind): every volume view this run read."""
    return [t for k, t in _FINDINGS if kind is None or k == kind]


def _view_findings(kind=None):
    """N426 (1.14.0): the findings (of one kind) recorded while the current volume view is the one read -- what a
    statement about THIS view may read. `_findings` is the run's list, which holds every earlier view's too."""
    return [t for k, t in _VIEW_FINDINGS if kind is None or k == kind]


_SKIP_FINDING = []        # B4: stages whose skip makes the output incomplete (drives the exit status)
_CAPTURE_INTEGRITY_VD = []    # B2/K071: truthy while `integrity` asks the walk for integrity-file records
_INTEGRITY_VD_CAPTURE = []    # (path, value_record) pairs collected under that flag
_JOURNAL_TAIL_DESTROYED = []  # B3/K069: journal records destroyed after the last surviving one,
                              # proven by a per-file LastUsn pointer that outlives them.
_JOURNAL_WIPE_SUSPECT = []   # B5/K068: $J allocated but holding no record and no non-zero byte
_WALK_UNWALKED = []          # E-6: directories walk_directory_tree listed but did not enter (cow_compare's completeness)


# ---------------------------------------------------------------------------------------------------
# N426 (1.14.0): every module register of this tool -- module state that outlives the call that fills it -- with its
# owner and where it is reset. A register filled for one volume and read as a fact of another was the defect: in one
# process over two volumes (`files --cow-before`, refsanalysis `bootedit repair`, every in-process caller) an object
# verified on the first volume went unchecked on the second, the before-image's root-page digests replaced the
# after-image's, and `integrity` / refsanalysis `supb` reported an earlier volume's condition as this one's.
#   view    a fact of one volume VIEW: one image read through one superblock copy and one checkpoint copy. Reset when a
#           view starts (`_new_view`, the first step of `parse_supb`: `bootstrap` and refsanalysis supb / chkp /
#           containers); what the replaced view found that decides the exit code stays a finding of the run
#           (`_view_carry`), so every exit code is what it was. A view read INSIDE another (`cow_compare`'s
#           before-image) is entered with `_view_enter` and left with `_view_leave`, which put the outer view's back.
#   volume  a fact of the image the run was given, whichever copy of it is read.
#   run     accumulates over every view the run reads: the exit code (`rc_escalate`), the at-exit summaries, and counts
#           a caller takes before and after one call of its own. Never reset.
# `_new_view` / `_view_enter` / `_view_leave` act on every `view` row of this table, so a register added as a view
# fact is reset with the others; the RED test `test_1132_red_c1_state` lists the registers from the source and fails on
# one that has no row here.
_MODULE_REGISTERS = {
    # run, per command -- N276: `cmd_deleted` sets it, and puts None back, around its report sent to stderr
    "_RECORDS_STDOUT": ("run", "the real stdout while a command's report goes to stderr (cmd_deleted, N276); "
                               "_emit_records and _Utf8Out write the records there"),
    # run -- N538 / decision 56: set once, by `_install_pipe_guards` (the command line) or `_PartialFile` (an output FILE)
    "_OUTPUT_ELSEWHERE": ("run", "non-empty once the run's output goes to a FILE or a directory; `_PipeGuard` then "
                                 "silences a closed stdout pipe (it carries only messages) and the run goes on"),
    # view -- reset by `_new_view`; saved and put back around a nested view
    "_SUPB_FELL_BACK": ("view", "the superblock copy the view is read from when it is not the primary (parse_supb); "
                                "carried into the run as _SUPB_EARLIER_VIEW"),
    "_CHKP_STALE": ("view", "the checkpoint conditions that change what the view reads (_view_conditions); carried "
                            "into the run as _CHKP_EARLIER_VIEW; integrity's page verdict, rc_escalate, "
                            "_escalation_texts"),
    "_OBJ_ROOT_REF": ("view", "root-page digest per object of the Object Table copy in use (build_object_map with "
                              "register=True, which empties it first); verify_object_root"),
    "_OBJ_ROOT_LCNS": ("view", "root-page LCNs of those objects (build_object_map with register=True)"),
    "_OBJ_ROOT_BY_LCNS": ("view", "the same objects keyed by their root LCNs (build_object_map with register=True); "
                                  "walk_bplus verifies the root page of a walk that names no object (RC3 F4)"),
    "_OBJ_ROOT_VERIFIED": ("view", "objects whose root page verify_object_root checked in this view (emptied with "
                                   "_OBJ_ROOT_REF)"),
    "_OBJ_ROOT_FAILED": ("view", "objects whose root page failed its digest in this view, altered or all zeros (emptied "
                                 "with _OBJ_ROOT_REF); security --audit (N609)"),
    "_OT_MAX_LSN": ("view", "the highest object LSN of the Object Table copy in use (build_object_map with "
                            "register=True); _redundancy_findings"),
    "_VIEW_FINDINGS": ("view", "the findings recorded while this view is current (_finding; each also in "
                               "_FINDINGS); _view_findings: integrity's page verdict, parse_supb, refsanalysis supb"),
    "_INTEGRITY_FAILED": ("view", "names of the files whose stored CRC-32C failed while extract read them; "
                                  "_emit_checked, for the file it writes"),
    "_CAPTURE_INTEGRITY_VD": ("view", "set while _verify_volume_integrity_streams walks the view, emptied when it "
                                      "returns"),
    "_INTEGRITY_VD_CAPTURE": ("view", "the integrity-stream records of that walk, emptied before and after it"),
    "_JOURNAL_WIPE_SUSPECT": ("view", "the view's $J is allocated and holds no record (_usn_journal_report); "
                                      "_journal_unreadable_or_wiped"),
    "_WALK_UNWALKED": ("view", "(why, oid) of each directory walk_directory_tree listed and did not enter (no Object "
                               "Table entry, no OID, past the depth limit); cow_compare's completeness"),
    # volume
    "_BUNDLE": ("volume", "the export-metadata bundle the run reads as its image (_bundle_open, from the command "
                          "line, once per run); never reset"),
    # run -- never reset
    "_FINDINGS": ("run", "every finding of every view (the sink); rc_escalate, _escalation_texts"),
    "_ORPHAN_MAGIC_SAID": ("view", "the orphan-page scans that said the volume's format magic is not known (WC-6)"),
    "_REQUIRED_SAID": ("view", "the required structures whose absence this view has said (walk_directory_tree, C1-8)"),
    "_VIEW_INCOMPLETE": ("view", "what this view could not read: a walk's damage note or a finding skip "
                                 "(_metadata_incomplete, _journal_lookup_was_incomplete; C1-3, C1-4)"),
    "_SKIP_FINDING": ("run", "stages whose skip makes the output incomplete; rc_escalate, _escalation_texts, "
                             "_metadata_incomplete, counts taken before and after one call"),
    "_SKIP_NOTES": ("run", "count per (stage, exception type) of skipped work; _skip_summary at exit, the journal "
                           "lookup tests (_journal_lookup_was_incomplete, _journal_unreadable_or_wiped)"),
    "_SKIP_EXPECTED": ("run", "count per kind of expected data-condition notes; _skip_summary at exit"),
    "_SKIP_SUMMARY_DONE": ("run", "set once _skip_summary has printed"),
    "_WALK_DAMAGE": ("run", "pages a walk could not read (N336: the count is never capped); rc_escalate, the at-exit "
                            "summary, _metadata_incomplete, counts taken before and after one walk; _walk_damage_reset "
                            "is called by no command"),
    "_WALK_DAMAGE_REPORTED": ("run", "set once _walk_damage_summary has printed"),
    "_REDUNDANCY_FINDING": ("run", "the redundancy findings summary listed; rc_escalate, _escalation_texts"),
    "_VERSION_CONTRADICTED": ("run", "the version contradictions the run's version tests found; rc_escalate, "
                                     "_escalation_texts"),
    "_JOURNAL_TAIL_DESTROYED": ("run", "missing journal tails found; rc_escalate, _escalation_texts"),
    "_ALL_TRS": ("run", "the last four Translators the run built (bootstrap), for the at-exit container caveat"),
    "_DEFERRALS": ("run", "content paths that declined to answer; the at-exit summary, counts taken before and after "
                          "one file"),
    "_MARKER_SCAN_WINS": ("run", "extent maps the heuristic marker scan produced; the at-exit note"),
    "_CONTENT_HOLES": ("run", "(what, bytes) of each output stream that drew from image holes; the at-exit summary, "
                              "marks taken around one stream (_hole_mark)"),
    "_CONTENT_UNDET": ("run", "streams whose hole coverage could not be determined; marks taken around one stream"),
    "_HOLE_UNCHECKED": ("run", "N208: the run could not check image holes (the reason; said once, a finding)"),
    "_HOLE_STREAMS": ("run", "the bulk export's streams that drew from holes; _bulk_hole_finish, which empties the "
                             "three lists when the export is done (C1-6)"),
    "_UNDET_STREAMS": ("run", "the bulk export's streams whose hole coverage could not be determined; "
                              "_bulk_hole_finish"),
    "_HOLE_REFUSALS": ("run", "the bulk export's destinations --refuse-holes withheld; _bulk_hole_finish"),
    "_PAGE_VERIFY": ("run", "--verify-pages' counts of the child pages the run read; the at-exit report"),
    "_VERIFY_PAGES": ("run", "the --verify-pages option (_arm_page_verification)"),
    "_REFUSE_HOLES": ("run", "the --refuse-holes option, set by the command that writes content"),
    "_CSV_GUARD": ("run", "the --csv-safe option (main)"),
    "_CSV_FORMULA_SEEN": ("run", "formula-lead cells written unguarded; the at-exit warning"),
    "_usn_nonv3_warned": ("run", "set once the non-V3 USN record warning has printed"),
    "_HELD": ("run", "D3b: one list per held reading in progress (_held_reading; empty between them): _finding, "
                     "_skip_note and _journal_finding keep that reading's notes there instead of the run's"),
    "_TRUNCATION_SAID": ("run", "the (image, partition start) pairs whose truncated-image note has printed "
                                "(_say_volume_truncation, B3); once per run"),
    "_BOOT_SECTOR_COPY": ("volume", "the boot-sector copy each (image, partition start) is read from (boot_sector_copy, "
                                    "N344); decided again by parse_vbr at every volume read, reused while the primary's "
                                    "bytes are the same"),
    "_BOOT_SECTOR_SAID": ("run", "the N344 statements this run has printed (_say_boot_sector_copy); once per run"),
}


def _run_state_mark(tr):
    """1.14.0: a mark of everything a decode can record -- every register of `_MODULE_REGISTERS` but
    `_OBJ_ROOT_VERIFIED`, and the translator's miss count and the containers it has spoken of -- taken before and after
    one decode. Equal marks: the decode recorded nothing (no note, skip, finding, damaged page, page-verification count,
    translation miss, marker-scan map), so decoding the same bytes again records nothing either, and its result may be
    reused (`_analyze_dir_extents`' `home_cache`) without changing a count the run prints. A list, set or dict is marked
    by its object and length; the count dicts by their counts too; a scalar by its value. `_OBJ_ROOT_VERIFIED` is left
    out: a root page is verified once per view, so a walk repeated after that finds it verified and records nothing; a
    failed verification is a finding, which the mark sees."""
    g = globals()
    m = []
    for n in _MODULE_REGISTERS:
        if n == "_OBJ_ROOT_VERIFIED":
            continue
        v = g.get(n)
        if isinstance(v, _DamageList):
            m.append((id(v), v.total, len(v), len(v.pages), len(v.notes or ())))
        elif n in ("_SKIP_NOTES", "_SKIP_EXPECTED"):
            m.append((id(v), len(v), sum(v.values())))
        elif n == "_PAGE_VERIFY":
            m.append((id(v),) + tuple(len(x) if isinstance(x, (list, set, dict)) else x for x in v.values()))
        elif n == "_HELD":
            m.append((id(v),) + tuple(len(x) for x in v))
        elif isinstance(v, (list, set, frozenset, dict, tuple)):
            m.append((id(v), len(v)))
        else:
            m.append(v if isinstance(v, (bool, int, str, type(None))) else id(v))
    m.append((getattr(tr, "misses", 0), len(getattr(tr, "_said", None) or ())))
    return tuple(m)


def _view_registers():
    """N426: [(name, register)] of every `view` row of `_MODULE_REGISTERS`, looked up when called (so a register a
    caller has replaced -- a test's fresh value -- is the one reset)."""
    g = globals()
    return [(n, g[n]) for n, row in _MODULE_REGISTERS.items() if row[0] == "view"]


def _view_carry():
    """N426: what the current view found that decides the exit code, recorded as findings of the run before the view's
    registers are reset, so a run that read a volume from a backup superblock (decision 27.2) or through a checkpoint
    view condition (decision 21: every command exits 2) still exits 2 whatever it reads next (N425 / LB64's reading
    R2, applied to both).
    - `_SUPB_FELL_BACK` (N425 / LB64): under `_SUPB_EARLIER_VIEW` with `_escalation_texts`' sentence -- unless it is
      decision 27.1's fallback (a signed backup read although no copy is valid, `none_valid`; B15: until then keyed on
      `cksum_ok` False, which a backup that fails another superblock test does not have), whose finding
      `_SUPB_NONE_VERIFIES` is already in the run's sink. Measured before N425's fix: 56 of the 120 corpus volumes read
      after win11refsmini_aftercorruption in one process named its backup LCN 0x7bffd as their copy in use
      (fixes/waveB_fix_evidence/part3d/).
    - `_CHKP_STALE` (N426): each text under `_CHKP_EARLIER_VIEW`.
    Every other `view` register holds no finding (the findings themselves are in `_FINDINGS` already)."""
    if _SUPB_FELL_BACK and not _SUPB_FELL_BACK.get("none_valid"):
        _t = _supb_fell_back_text(_SUPB_FELL_BACK)
        if _t not in _findings(_SUPB_EARLIER_VIEW):
            _finding(_SUPB_EARLIER_VIEW, _t)
    for _t in list(_CHKP_STALE):
        if _t not in _findings(_CHKP_EARLIER_VIEW):
            _finding(_CHKP_EARLIER_VIEW, _t)


def _view_clear():
    for _n, reg in _view_registers():
        if isinstance(reg, list):
            del reg[:]
        else:
            reg.clear()


def _new_view():
    """N426 (1.14.0): a volume view starts (`parse_supb`'s first step): the current view's exit-relevant conditions
    become findings of the run (`_view_carry`), then every `view` register is emptied."""
    _view_carry()
    _view_clear()


def _view_enter():
    """N426: enter a view read INSIDE the current one (`cow_compare`'s earlier image): the current view's registers are
    taken out -- returned, the registers left empty, nothing carried (that view is not over) -- for `_view_leave`."""
    saved = [(n, type(reg)(reg)) for n, reg in _view_registers()]
    _view_clear()
    return saved


def _view_leave(saved):
    """N426: leave the inner view: what it found stays a finding of the run (`_new_view`), and the outer view's
    registers taken out by `_view_enter` are put back."""
    _new_view()
    back = dict(saved)
    for n, reg in _view_registers():
        if n in back:
            if isinstance(reg, list):
                reg.extend(back[n])
            else:
                reg.update(back[n])



class IncompleteEvidence(Exception):
    """A decode failed on a path whose caller would otherwise fill the gap with a default.

    Raised instead of returning a partial answer, so the caller can DEFER rather than emit bytes,
    a size or a verdict that the volume does not support. Distinct from a parse error the caller is
    entitled to ignore: this one says "what I return would be wrong, not merely incomplete".
    """


_DEFERRALS = []


def _defer_note(where, reason):
    """Record that a CONTENT path declined to answer, and say so.

    Deferring is correct -- it is how the reassembler avoids emitting bytes the volume does not support.
    But a deferral that only shows up as a missing file is the silent-default class wearing another hat:
    the caller exits 0, no file appears, and nothing says which file or why. Callers that were ASKED for a
    specific file (extract / export) report these and exit 2.
    """
    _DEFERRALS.append((where, reason))
    print(f"[{PROG}] WARNING: declined to reassemble {where}: {reason} — no bytes written for it.",
          file=sys.stderr)
    return len(_DEFERRALS)


# A2-R: "absent" and "could not tell" are different answers, and four helpers returned None for both.
# A caller that cannot separate them reports a missing thing as a thing that is not there -- the same
# class as the hole check reporting "I cannot say" as "clean". The helpers still return None, so no call
# site changes; a caller that CARES passes a `status` dict and reads the outcome out of it.
ABSENT = "absent"                # the object genuinely has no such record
UNREADABLE = "unreadable"        # the lookup failed; whether it exists is unknown


def _outcome(status, value, why=None):
    """Record how a lookup ended. Returns `value` so callers can `return _outcome(status, None)`."""
    if status is not None:
        status["outcome"] = UNREADABLE if why is not None else ABSENT
        if why is not None:
            status["reason"] = str(why)[:200]
    return value


def _row_name(kd, where, off=4):
    """Decode a directory row's UTF-16 filename, or return None RECORDING why it could not be read.

    Every call site used to be `try: name = kd[4:].decode(...) / except UnicodeDecodeError: continue`,
    which removes the entry from whatever is being built -- a listing, a census, a path resolution, an ADS
    scan -- and says nothing. A file that vanishes from a listing because its name would not decode is
    indistinguishable from a file that is not there, which is the class this project has already been bitten
    by twice (a census that lost 72 % of one image's rows; `verify_claim --regress` reporting 20/20 while an
    image it could not open simply never became "applicable").

    Not one of these fires on the 106-image corpus -- measured, not assumed, by instrumenting every handler
    and exercising nine commands per image. They guard damaged and truncated input, which is what a forensic
    tool meets and this corpus does not contain, so the point of recording is for the volume that is not
    here yet. See analysis/reports/M3_3_silent_skip_split.md.
    """
    try:
        return kd[off:].decode("utf-16-le").rstrip("\x00")
    except UnicodeDecodeError as exc:
        _skip_note("filename decode", where, exc)
        return None


def _skip_note(stage, where, exc, limit=3, expected=False):
    """Record and report a skipped unit of work. Returns the running count for this kind.

    B4: a skip is a FINDING by default -- work the tool could not do is missing from the output, and the
    exit status must say so. `expected=True` marks a normal DATA condition that is not a failure to read
    (three call sites: unwritten USN ring space, an empty journal, and clusters at VLCN 0 left as zeros by the stream
    reader),
    so a healthy volume is never reported as having a finding.
    """
    if _HELD:                                     # D3b: a held reading keeps it (`_held_reading`)
        if not expected:
            _HELD[-1].append("%s: %s: %s" % (stage, where, exc))
        return 0
    key = (stage, type(exc).__name__)
    if expected:
        # A property of the DATA, not work that went missing: said as a note, in full, every time, and counted
        # on its own. Sharing the (stage, exception) count with real skips let a note use up the print budget
        # of the real skips that followed it, so a real skip could print nothing.
        _SKIP_EXPECTED[key] = _SKIP_EXPECTED.get(key, 0) + 1
        print(f"[{PROG}] note: {stage}: {where}", file=sys.stderr)
        return _SKIP_EXPECTED[key]
    _SKIP_FINDING.append(stage)
    _VIEW_INCOMPLETE.append(("skip", stage))          # C1-3 / C1-4
    n = _SKIP_NOTES.get(key, 0) + 1
    _SKIP_NOTES[key] = n
    if n <= limit:
        print(f"[{PROG}] WARNING: {stage} skipped {where}: {type(exc).__name__}: {exc}",
              file=sys.stderr)
    elif n == limit + 1:
        print(f"[{PROG}] WARNING: {stage}: further {type(exc).__name__} skips suppressed "
              f"(count reported at exit)", file=sys.stderr)
    return n


_SKIP_SUMMARY_DONE = []


def _skip_summary():
    """One line per kind of skipped work, for the end of a run. Silent when nothing was skipped.

    Idempotent: registered with atexit, so an explicit call must not double-report."""
    if not (_SKIP_NOTES or _SKIP_EXPECTED) or _SKIP_SUMMARY_DONE:
        return
    _SKIP_SUMMARY_DONE.append(True)
    # An expected=True note is a normal data condition, not work that went missing, so it is not in this
    # count; it is reported on its own line instead.
    if _SKIP_NOTES:
        print(f"[{PROG}] WARNING: {sum(_SKIP_NOTES.values())} unit(s) of work were skipped and are NOT reflected "
              f"in the output above:", file=sys.stderr)
        for (stage, exc), n in sorted(_SKIP_NOTES.items()):
            print(f"[{PROG}]          {stage}: {n} x {exc}", file=sys.stderr)
    if _SKIP_EXPECTED:
        print(f"[{PROG}] note: {sum(_SKIP_EXPECTED.values())} condition(s) reported above describe the data, "
              f"not work the tool skipped: " + ", ".join(sorted({st for st, _e in _SKIP_EXPECTED})), file=sys.stderr)


def _journal_finding(kind, text):
    """N403 (1.14.0): a finding about the change journal's DATA -- zeros where records were, a record whose USN is not
    its offset, an empty $J that files point into, a declared length that disagrees with the allocation -- recorded
    (exit 2, `_finding`) and said as a finding: 'WARNING: USN journal: <the finding>.' Until 1.14.0 these went through
    `_skip_note`, whose template says 'USN journal skipped <finding>: ValueError: ...' and whose exit summary counts
    them as 'unit(s) of work were skipped and are NOT reflected in the output above' -- work the tool did not skip.
    Work the tool DID skip (a read that failed, records it refused to decode) keeps `_skip_note`."""
    if _HELD:                                     # D3b: a held reading keeps it (`_held_reading`)
        _HELD[-1].append(text)
        return
    _finding(kind, text)
    print("[%s] WARNING: USN journal: %s." % (PROG, text.rstrip(".")), file=sys.stderr)


def _split_file_attrs(vd):
    """A split file's attributes: its OWN record's, the backing's +0x48 (K006). The name row caches a copy at
    +0x40 that drops the EA bit and lags the Archive bit; the change journal reports the backing's (47/47 on
    `win11refstestmftecmd`). One definition, so `files` and `dataruns` cannot disagree again."""
    return le32(vd, 0x48) if len(vd) >= 0x4C else 0


def _t40_record_tuple(vd, ctx=None):
    """The per-object facts carried by a type-0x40 backing record, as one tuple.

    Shared by the directory walk and by the on-demand home-tree lookup (E89) so the two cannot
    drift: the walk only sees backings in directories it traverses, and a file whose HOME object
    is never traversed would otherwise get none of this -- losing its residency, USN, SecurityId,
    EA bit and allocated size, and reporting it non-resident with the data sitting in the record.
    Layout: alloc @+0x60, size @+0x58, LastUsn @+0x68, journal @+0x70, SecurityId @+0x50,
    internal flags @+0x4c, reparse tag mirror @+0x7c (bit31), file attrs @+0x48.
    """
    _a = le64(vd, 0x60) if len(vd) >= 0x68 else 0
    _s = le64(vd, 0x58) if len(vd) >= 0x60 else 0
    _u = le64(vd, 0x68) if len(vd) >= 0x70 else 0
    _j = le64(vd, 0x70) if len(vd) >= 0x78 else 0
    _sid = le64(vd, 0x50) if len(vd) >= 0x58 else 0
    _if = le32(vd, 0x4C) if len(vd) >= 0x50 else None      # B1 (1.14.0): None = not read, never a 0 that was not read
    _tag = le32(vd, 0x7C) if len(vd) >= 0x80 else 0
    if not (_tag >> 31) & 1:
        _tag = 0
    _tgt = extract_reparse_from_backing(vd) if _tag in (0xA000000C, 0xA0000003) else ""
    _bfa = _split_file_attrs(vd)
    _inl = _backing_inline_data(vd, ctx) is not None
    _form = _stream_data_form(vd, ctx)
    # T9 / MD_ADS_RA_005: a named stream on a SPLIT record lives HERE, in the backing, not in the type-0x30
    # name row -- so the enumeration that reads only the name row never sees it. Appended last so every
    # existing rec[N] index is unchanged.
    _ads = detect_ads_in_resident(vd, ctx)[1]
    _adsst = _ads_storage_map(vd, ctx) if _ads else {}
    # K095: the $DATA stream's own (size, total, disk, form) -- the header pair above is a cached copy
    _dsz = _resident_data_sizes(vd, ctx)
    # N166 (1.14.0): a split file's stream snapshots live here too -- RefsCreateStreamSnapshot inserts its 0xB0 rows
    # into the file's own table, which RefsLinkFileToSelf re-parents under the backing key (26100.9549, Insider 29574;
    # RC1D/rc3/N166_DRIVER_READING.md). Appended last, as the named streams were.
    _snaps = _snapshot_meta(vd, ctx)
    return (_a, _s, _u, _j, _sid, _if, _tag, _tgt, _bfa, _inl, _form, _ads, _adsst, _dsz, _snaps)


def _backing_inline_data(vd, ctx=None, salvage=False, quiet=False):
    """Inline `$DATA` bytes of a type-0x40 backing record, or None when the stream is extent-backed (E82).

    A file whose record was SPLIT OUT of its name row (`key_flags 0x02`) can still keep its data **inside that
    record**. Record placement and data residency are independent (E77): the split is what a move or a hard
    link forces, and it says nothing about where the bytes live. When the data stayed inline, the backing's
    main `$DATA` sub-record is the **resident** form — single-instance marker 0x80000001 + type 0x80, with
    `summary_size@0x0c == 0x30` and `StreamSummary flags@0x10 == 0` — carrying the byte count at `+0x20` and the
    bytes at `+0x3c`. (The extent-bearing form is the other one: `inner_hdr@0x00 = 0x88`, `summary_size` 0x200
    on v3.14+ / 0x1a0 on v3.4-v3.10, extents at `+0x88`.)

    Matching the single-instance marker matters: an ADS is a *multi-instance* 0x80 row, so accepting any 0x80
    row returns a stream that is not the file's data.

    Measured over the corpus: 16,191 of 83,176 index-entry files keep their data this way, on 26 images
    (14,580 on one real Windows volume); the two forms are mutually exclusive — no record carries both.
    Before this, such a file was reported non-resident and `extract` failed with "no extents decoded" while
    its bytes sat in the record already held.

    `salvage` / `quiet` (N165, 1.14.0): for a backing recovered in slack -- read as a remnant (K005), and a backing
    that does not parse is not a finding about the volume."""
    try:
        rows = (parse_resident_btree_rows(bytes(vd), ctx, salvage=True) if salvage
                else parse_resident_btree_rows(bytes(vd), ctx))
    except (ValueError, struct.error, IndexError) as _e:
        if not quiet:
            _skip_note("_backing_inline_data", "a backing record's inline data", _e)
        return None
    for kd, vr in rows:
        if len(kd) >= 14 and kd[8:12] == _SI_MARKER and kd[12] == 0x80 and kd[13] == 0x00:
            v = bytes(vr)
            if len(v) < 0x28 or le32(v, 0x0C) != 0x30 or le32(v, 0x10) != 0:
                return None                      # extent-bearing (or an unexpected shape) -> not inline
            sz = le64(v, 0x20)
            if sz == 0:
                # A genuinely EMPTY resident stream: the inline form is present (summary 0x30 /
                # storage 0) and simply carries no bytes. Returning None here made it look
                # extent-backed, so the file was reported non-resident and `extract` failed with
                # "file not found" for every empty hard-linked name (772 rows / 11 images).
                return b""
            if 0x3C + sz > len(v):
                return None
            return v[0x3C:0x3C + sz]
    return None


def get_resident_data_content(vd, ctx=None, salvage=False):
    """Q7: inline bytes of the main $DATA stream of a resident file, or None.

    The $DATA row (key marker 0x80000001 + attr type 0x80) carries the SAME stream descriptor as an ADS
    row (see _parse_ads_from_value): locate it by the 0x0c/0x30 signature (hdr=scan-4), read storage_type
    at hdr+0x0c, stream size at hdr+0x1c, and inline content at hdr+0x38. Only storage_type==0 is inline
    (verified on desktop.ini: content '[.ShellClassInfo]...' at hdr+0x38). Returns None for a non-inline
    ($DATA descriptor pointing to extents) or malformed row — the caller falls back to the extent path."""
    for kd, vrow in parse_resident_btree_rows(vd, ctx, salvage=salvage):
        if not (len(kd) >= 14 and kd[8:12] == _SI_MARKER and kd[12] == 0x80 and kd[13] == 0x00):
            continue
        hdr = None
        for scan in range(0, len(vrow) - 8):
            if le32(vrow, scan) == 0x0C and le32(vrow, scan + 4) == 0x30:
                hdr = scan - 4
                break
        if hdr is None or hdr < 0 or hdr + 0x24 > len(vrow):
            return None
        if le32(vrow, hdr + 0x0C) != 0:          # storage_type != 0 => non-inline (extent-backed)
            return None
        stream_size = le64(vrow, hdr + 0x1C)
        content_off = hdr + 0x38
        if content_off + stream_size <= len(vrow) and stream_size <= 0x100000:
            return bytes(vrow[content_off:content_off + stream_size])
        return None
    return None


def _current_stream_extent_backed(vd, ctx=None, salvage=False):
    """F5: True when a file's CURRENT $DATA stream lives in on-disk extents (so the file is NON-RESIDENT even
    though its type-0x30 value is 'long' > 84 B). The live stream is the sub_id-0x1000 holder whose descriptor
    is 0x00010028 (le32 @ holder value+0x04); its on-disk allocation is disk_alloc @ holder value+0x48. Older
    sub_ids (0x1001+) are CoW snapshots and are ignored. A genuine inline/resident file has no such holder
    (its $DATA is a single-instance 0x80000001 descriptor) or disk_alloc==0. (structure_reference §C.6;
    calibrated on win11refs8g.raw: bigsparse/rangefile/stomp_nonres disk_alloc>0 => non-resident,
    test.txt current-stream disk_alloc==0 => resident.)"""
    for kd, vrow in parse_resident_btree_rows(vd, ctx, salvage=salvage):
        if (len(kd) >= 0x18 and kd[12] == 0x80 and kd[13] == 0x00
                and le64(kd, 0x10) == 0x1000 and len(vrow) >= 8 and le32(vrow, 4) == 0x00010028):
            return len(vrow) >= 0x50 and le64(vrow, 0x48) > 0
    return False


def _multilevel_extent_backed_size(vd, cs, ctx=None):
    """B2: on v3.4/v3.9/upgraded framing a 'long' (>84 B) resident type-0x30 value can be a MULTI-LEVEL
    embedded B+-tree — parse_resident_btree_rows reaches only the OUTER level, so no inline $DATA row is
    found (get_resident_file_size == 0) even though the file has on-disk data. Such a file is actually
    NON-RESIDENT / extent-backed; its true FileSize is at value+0x58 and its allocated size at value+0x60.
    Returns the true file_size when the pattern holds, else None.
    Gate: no marker-keyed $DATA row at the outer level AND alloc (value+0x60) is a whole number of clusters
    (alloc>0 and alloc % cs == 0 — extents allocate whole clusters) AND 0<size<=alloc. The cluster-alignment
    check is what distinguishes a real extent-backed file (alloc = N*cluster, e.g. xbpt_delta 209311/212992)
    from a small resident file whose value is merely unparseable (e.g. multibig_*.bin 300/304, alloc NOT a
    cluster multiple — NOT extent-backed). A genuine resident file on a v3.7+ format has a marker-keyed
    $DATA row, so it never reaches this.
    The v3.4-keyed $DATA row (K098) is left out of the first test on purpose: it carries the stream size
    whatever the residency (it equals value+0x58), so its presence says nothing about where the data is.
    Counting it switched this gate off on every v3.4 volume and every volume upgraded from one. Measured over
    the 121-image corpus: the gate fires on 2,453 records -- 1,939 on v3.4, 514 on the two upgraded volumes,
    none on a v3.7+ format -- and _stream_data_form classifies every one of them `extents`."""
    if len(vd) < 0x68 or cs <= 0:
        return None
    alloc = le64(vd, 0x60)
    if alloc == 0 or alloc % cs != 0 or get_resident_file_size(vd, ctx, v34_key=False) != 0:
        return None
    size = le64(vd, 0x58)
    if 0 < size <= alloc:
        return size
    return None


# ─── Resident ADS detection ─────────────────────────────────────────
def detect_ads_in_resident(vd, ctx=None):
    """Detect Alternate Data Streams in a resident directory entry value.

    ADS appear as 0xb0 entries (marker 0x80000002) with StreamSummary flags=0
    at val[0x10] in the embedded B+-tree. Stream name is in the key at offset 16+.
    Returns (has_ads, ads_names). (B13, 1.14.0: the unreachable `detect_ads`, which read an object's own tree, is
    deleted -- nothing called it.)
    """
    ads_names = []
    for kd, vd_row in parse_resident_btree_rows(vd, ctx):
        if _is_b0_snapshot_key(kd) and not _is_snapshot_value(vd_row):
            if True:
                try:
                    name = _b0_stream_name(kd)
                    if name:
                        ads_names.append(name)
                except UnicodeDecodeError:
                    pass
    return len(ads_names) > 0, ads_names


# ─── Extended Attributes ($EA) + WSL/Linux metadata ──────────────────────────
# VERIFIED 2026-06-29 (E2 + RD, report wsl_ea_verification_2026-06-29.md). EAs live as TWO embedded
# single-instance sub-records (marker 0x80000001) in the resident value's B+-tree: $EA_INFORMATION
# (type 0xD0, val[0x0C]=PackedEaSize) + $EA (type 0xE0, FILE_FULL_EA_INFORMATION chain at val+0x0C).
# refs.sys (RefsQueryLxMetadataEa) recognises EXACTLY four $LX EAs; all other EA values are opaque
# (name+size+raw only). NEVER source PackedEaSize from the value+0x78 mirror (stale on upgraded vols)
# or read device numbers from the reparse buffer (it has none).
def parse_ea_chain(data):
    """Parse a FILE_FULL_EA_INFORMATION chain -> [{'name','value','flags'}].
    Entry: NextEntryOffset u32@0, Flags u8@4, EaNameLength u8@5, EaValueLength u16@6,
    Name(ASCII)@8 (+1 null), Value@(8+nameLen+1). 0 NextEntryOffset = last."""
    eas = []
    off = 0
    for _ in range(256):
        if off + 8 > len(data):
            break
        nxt = le32(data, off)
        flags = data[off + 4]
        nlen = data[off + 5]
        vlen = le16(data, off + 6)
        name_end = off + 8 + nlen
        if name_end > len(data):
            break
        try:
            name = bytes(data[off + 8:name_end]).decode("ascii")
        except UnicodeDecodeError:
            name = bytes(data[off + 8:name_end]).decode("ascii", "replace")
        vstart = name_end + 1
        vend = vstart + vlen
        if vend > len(data):
            break
        eas.append({"name": name, "value": bytes(data[vstart:vend]), "flags": flags})
        if nxt == 0:
            break
        off += nxt
    return eas

def fetch_t40_backing(f, ps, cs, tr, obj_map, dir_oid, file_id, file_size=None, status=None):
    """Raw value bytes of the type-0x40 backing record for (dir_oid, file_id), or None. A non-resident
    file's EAs live in this backing. The per-dir file_id can COLLIDE (hard-link ordinal reuse); when
    several records share it, disambiguate by the file's size (val+0x58) — the same collision-safe rule
    the directory walk uses (#340). (The PackedEaSize==Σ oracle in the caller is the final guard.)"""
    if dir_oid not in obj_map:
        return _outcome(status, None)
    cands = []
    try:
        for kd, vd in walk_bplus(f, ps, cs, tr, obj_map[dir_oid], oid=dir_oid):
            if len(kd) >= 0x10 and le16(kd, 0) == 0x40 and le64(kd, 0x08) == file_id:
                cands.append(bytes(vd))
    except Exception as _e:
        # `None` below also means "no such backing", a legitimate answer. A walk FAILURE returning the
        # same value makes the two indistinguishable -- and this record feeds residency, USN, SecurityId
        # and the attribute flags for the file.
        _skip_note("type-0x40 backing", f"dir 0x{dir_oid:x} file_id {file_id}", _e)
        return _outcome(status, None, _e)      # the walk failed: "no backing" has not been established
    if not cands:
        return _outcome(status, None)
    if file_size is not None and len(cands) > 1:
        for vd in cands:
            if len(vd) >= 0x60 and le64(vd, 0x58) == file_size:
                return vd
    return cands[0]

def extract_eas_from_value(vd, ctx=None):
    """(ea_list, packed_ea_size) from a resident value's embedded $EA/$EA_INFORMATION sub-records,
    or (None, None) if the file has no EAs ($EA_INFORMATION 0xd0 absent = the gate). packed_ea_size
    is read from the 0xd0 sub-record val[0x0c] (authoritative; never the +0x78 mirror)."""
    ea_info = None
    ea_chain = None
    for kd, vr in parse_resident_btree_rows(vd, ctx):
        if len(kd) >= 14 and kd[8:12] == _SI_MARKER and kd[13] == 0x00:
            if kd[12] == 0xD0 and len(vr) >= 0x10:
                ea_info = vr
            elif kd[12] == 0xE0 and len(vr) >= 0x0C:
                ea_chain = vr
    if ea_info is None:
        return None, None
    # N159 (1.14.0): PackedEaSize is a u16, followed by the u16 NeedEaCount and the u32 unpacked size (26100.9444
    # RefsReplaceFileEas writes the three, :398815-398830; the load path reads the u16, :471084); the u32 read here
    # added NeedEaCount << 16 for a file with a FILE_NEED_EA entry
    packed = le16(ea_info, 0x0C)
    eas = parse_ea_chain(ea_chain[0x0C:]) if ea_chain is not None else []
    return eas, packed

def wsl_metadata(vd, ctx=None):
    """N329 (1.14.0): the one WSL decoder (`details`, `reparse`, refsanalysis `attributes`). From the record that holds a
    file's EAs (its embedded name row, or a split file's backing): {'eas', 'packed', 'reconciled', 'wsl'}, or None when
    the record has no $EA_INFORMATION. `wsl` holds the four $LX values at the exact lengths refs.sys requires
    (`decode_wsl_eas`; uid / gid / mode / dev, and mode_decoded), only when PackedEaSize reconciles with the EA list
    (the oracle `details` applies: a mismatch means the record was mis-resolved, so nothing is shown). `reparse` had
    its own scan from +0xa0 with `>=` length gates and no oracle, refsanalysis another."""
    eas, packed = extract_eas_from_value(vd, ctx)
    if eas is None:
        return None
    ok = sum(5 + len(e["name"]) + len(e["value"]) for e in eas) == packed
    wsl = dict(decode_wsl_eas(eas)) if ok else {}
    if "mode" in wsl:
        wsl["mode_decoded"] = decode_lx_mode(wsl["mode"])
    return {"eas": eas, "packed": packed, "reconciled": ok, "wsl": wsl}


def ea_record(f, ps, cs, tr, obj_map, r):
    """The record that holds a walk row's EAs: an embedded row's own value; a split file's type-0x40 backing (by its
    home, then its parent, and its file id), as `details` fetches it. None when it cannot be found."""
    if r.get("record_embedded") or r.get("is_dir"):
        return r.get("raw_value")
    _fsz = r.get("file_size")
    return (fetch_t40_backing(f, ps, cs, tr, obj_map, r.get("home_oid") or 0, r.get("file_id") or 0, _fsz)
            or fetch_t40_backing(f, ps, cs, tr, obj_map, r.get("parent_oid") or 0, r.get("file_id") or 0, _fsz))


# Linux S_IFMT file types (mode & 0o170000) — verified vs lab mknod/chmod ground truth.
_LX_IFMT = {0o140000: "socket", 0o120000: "symlink", 0o100000: "regular", 0o060000: "block",
            0o040000: "directory", 0o020000: "char", 0o010000: "fifo"}

def decode_lx_mode(mode):
    """Decode a Linux mode_t (from $LXMOD) -> 'regular rwxr-xr-x (0o755)' with setuid/setgid/sticky."""
    ft = _LX_IFMT.get(mode & 0o170000, "unknown(0o%o)" % (mode & 0o170000))
    perms = "".join(("r" if (mode >> s) & 4 else "-") + ("w" if (mode >> s) & 2 else "-")
                    + ("x" if (mode >> s) & 1 else "-") for s in (6, 3, 0))
    extra = "".join(t for b, t in ((0o4000, " setuid"), (0o2000, " setgid"), (0o1000, " sticky")) if mode & b)
    return f"{ft} {perms} (0o{mode & 0o7777:04o}){extra}"

def decode_wsl_eas(eas):
    """Decode the FOUR driver-recognised $LX EAs (gated on the exact value lengths refs.sys requires:
    4 for UID/GID/MOD, 8 for DEV). Returns {uid,gid,mode,dev=(major,minor)} for those present."""
    wsl = {}
    for ea in eas:
        n, v = ea["name"], ea["value"]
        if n == "$LXUID" and len(v) == 4: wsl["uid"] = le32(v, 0)
        elif n == "$LXGID" and len(v) == 4: wsl["gid"] = le32(v, 0)
        elif n == "$LXMOD" and len(v) == 4: wsl["mode"] = le32(v, 0)
        elif n == "$LXDEV" and len(v) == 8: wsl["dev"] = (le32(v, 0), le32(v, 4))
    return wsl

# $SI+0x24 internal-flags labels — ONLY the bits with verified semantics (E25/E29/E43). Bit 0x04 has a known FCB source
# (bit 11) but no confident semantic name, so it is left UNLABELLED (shown only in the raw hex) rather than guessed.
# N156 (1.14.0): bit 0x02 marks a case-sensitive directory -- RefsComputeStandardInformationInternalFromFcb stores FCB
# bit 0x400000 (set by RefsSetCaseSensitiveInfo, read by RefsQueryCaseSensitiveInfo) as $SI+0x24 bit 0x02, and
# RefsUpdateFcbInfoFromDisk reads it back (26100.9444 :157017-157019, :404549, :403134-403138, :470855-470860; the same
# on 26100.8115 :157907); 17134 has no case-sensitive directories and reads only bit 0x01. "Dedup/CoW" had no driver
# reading behind it.
# Q-A (the labs-and-driver batch, 1.14.0): bit 0x08 = the default data stream is held in the record (FCB+0x08 bit 31):
# set by `RefsCreateNewFile` -> `RefsInitializeFcbStdInfo` when the file is built from table template 2 (created only
# above 3.10), read by `RefsOpenAllDataStreamSets` / `RefsDeleteAllMinstoreStreams` (each skips the data stream set),
# cleared by `RefsConvertToNonResident` (read twice: 26100.8115, .9711). Set on 586,574 of the 586,574 inline files of the
# corpus, on none of its 263,526 other files and on no directory (LD/evidence/q5_bit8_census.jsonl).
_INTERNAL_FLAG_LABELS = {0x01: "DeleteDisposition", 0x02: "CaseSensitive", 0x08: "DataInRecord", 0x20: "RedirectionTrust"}

# Checkpoint (CHKP+0x78) flag bits — meanings for the summary decode (Q4). Any bit NOT here is labelled
# 'unknown (uncatalogued)' so a new/unexpected flag is never silently dropped. (structure_reference §A.4a.)
# N221 (1.14.0): the driver's names (26100.8115, and read again on 26100.9444: MsEnableDedup / MsIsDedupEnabled 0x010,
# MsIsWeakReferenceEnabled 0x020, MsSetDeveloperVolume 0x040, MsEnableDirtyStateTracking / MsIsDirtyStateTracking-
# Enabled 0x100, each on the SmsCheckpointRecord's +0x78); "dedup-bit8" was not dedup.
# 0x400: `FormatCheckpointRecord` sets it when the volume version is 3.13 or later, and the record then carries the
# rollback-protection fields (E158; N554 below). Set on every 3.14 volume of the corpus (106, upgraded ones included)
# and on none formatted at 3.4-3.10 (14) (KNOWLEDGE_INTAKE A140); 1.13.1 called it "metadata-checksum", a meaning
# never read -- on 17134 a page is checked against its reference's checksum type, and on 26100.8115 / .9444 / .9711
# and Insider 29574 the volume's type comes from the boot sector (A139, E136).
_CHKP_FLAG_BITS = {
    0x002: "always-set",
    0x010: "dedup enabled",
    0x020: "weak references enabled",
    0x040: "developer volume",
    0x080: "native-Win11-format (ReFS 3.10+)",
    0x100: "dirty-state tracking enabled",
    0x200: "indirect-root-list",
    # N554 (1.14.0): E158 / E159 -- each flag marks one of the record's optional areas, located by an (offset, length)
    # u32 pair; `FormatCheckpointRecord` sets 0x400 when the volume version is 3.13 or later (VersionCheck(0x30d)),
    # 0x2000 with Insider's attestation HMAC (CmsVolumeAttestation::CreateEmptyHmacStructure)
    0x400: "rollback-protection fields (+0x9c offset / +0xa0 length; ReFS 3.13+)",
    0x2000: "attestation HMAC (+0xa4 offset / +0xa8 length; Insider 29574 / 29659 / 29683)",
}

def chkp_flags_decoded(flags):
    """List of 'bit = meaning' strings for a CHKP flags value, incl. any uncatalogued residual bit."""
    out = [f"0x{b:x} = {name}" for b, name in sorted(_CHKP_FLAG_BITS.items()) if flags & b]
    # OR-fold the catalogued bits into one mask (D7). `sum()` would over-count if any two flags ever
    # shared a bit or a flag became multi-bit; `|` is correct for any bit layout.
    catalogued = 0
    for _b in _CHKP_FLAG_BITS:
        catalogued |= _b
    residual = flags & ~catalogued
    if residual:
        out.append(f"0x{residual:x} = unknown (uncatalogued bit)")
    return out

def internal_flags_str(flags):
    """$SI+0x24 in TEXT output: `flag_text` -- `0x28 (RedirectionTrust|DataInRecord)`, `0x4`, `0x0 (none set)`; ''
    when the word was not read (None). Q-B answered B1 (1.14.0): every value read is printed, an unnamed bit (0x04) as
    its hex. Bit 0x08 is `DataInRecord` (Q-A, the labs-and-driver batch: `_INTERNAL_FLAG_LABELS`); 1.13.1 hid it."""
    if flags is None:
        return ""
    return flag_text(flags, _INTERNAL_FLAG_LABELS)


def resolve_path(f, ps, cs, tr, obj_map, path):
    """Resolve a '/dir/sub/file' path to (parent_oid, key, value) of its type-0x30 row.
    Case-insensitive (ReFS default), but an EXACT spelling always wins: a directory carrying the per-directory
    case-sensitivity flag (`fsutil file setCaseSensitiveInfo`) can hold two names that differ only by case, and
    taking the first case-insensitive hit served one file's bytes under the other's name. Files have no OID —
    they are found by name in the parent directory's tree. Returns (None, None, None) if not found."""
    parts = [p for p in path.replace("\\", "/").split("/") if p and p != "."]
    if not parts:
        return (None, None, None)
    oid = 0x600
    for i, part in enumerate(parts):
        if oid not in obj_map:
            return (None, None, None)
        found = None
        try:
            rows = walk_bplus(f, ps, cs, tr, obj_map[oid], oid=oid)
        except Exception as _e:
            # "Unreadable" is not "absent". Returning the not-found tuple silently turns a
            # damaged directory into a confident wrong answer for every caller.
            _skip_note("path resolution (directory unreadable)", "oid 0x%x" % oid, _e)
            return (None, None, None)
        for kd, vd in rows:
            if len(kd) < 4 or le16(kd, 0) != 0x30:
                continue
            nm = _row_name(kd, "path resolution")
            if nm is None: continue      # a name that will not decode cannot be the one asked for
            if nm == part:
                found = (kd, vd)      # exact spelling wins outright
                break
            if found is None and nm.lower() == part.lower():
                found = (kd, vd)      # remember the first case-insensitive hit, keep looking for an exact one
        if found is None:
            return (None, None, None)
        kd, vd = found
        if i == len(parts) - 1:
            return (oid, kd, vd)
        # descend into a child directory: val+0x08 is the child's own OID only when the directory bit is
        # set. A non-resident FILE has the home-dir backref there (a different object), not an OID, so an
        # intermediate path component that is a file (not a directory) is not descendable -> no such path.
        if len(vd) <= NON_RESIDENT_MAX_VALUE and len(vd) >= 0x44 and (le32(vd, 0x40) & 0x10000000):
            oid = le64(vd, 0x08)
        else:
            return (None, None, None)
    return (None, None, None)


def count_snapshots_from_btree(f, ps, cs, tr, vlcns):
    """Count true snapshot entries in an object's B+-tree."""
    try:
        rows = walk_bplus(f, ps, cs, tr, vlcns)
    except Exception as _e:
        # "0 snapshots" is a statement about the object, not about the walk. Callers print it as a count.
        _skip_note("snapshot count", "object tree", _e)
        return 0
    count = 0
    for kd, vd in rows:
        if _is_b0_snapshot_key(kd) and _is_snapshot_value(vd):
            count += 1
    return count


# ── Snapshot content recovery (CoW prior-content) ───────────────────────
# Chain (E2: SetResidentStreamSummary/RefsCreateStreamSnapshot; RD-verified):
#   snapshot 0xB0 sub-record  val[0x44] = data_sub_id, val[0x20] = stream size
#     -> DATA 0x80 sub-record whose key+0x10 == data_sub_id  (descriptor 0x10028)
#         val[0x00] = inner-header offset (0x88); val[0x48] = on-disk alloc (0 = inline)
#         extent_count = val[ihdr+0x14]; 24-byte extents at val[ihdr+0x28]:
#           +0x00 VLCN(u64)  +0x0C file_vcn(u32)  +0x14 run_length(u32)
#     -> translate VLCN->PLCN (Container Table) -> read run_length clusters -> trim.
# The CURRENT version is data_sub_id 0x1000. Same 24-byte extent format as type-0x40.
SNAP_DATA_DESC = 0x10028

# Inline per-cluster integrity checksum (structure_reference §C.6 / MD_DATA_RA_007; Phase-2 spec 2026-08-06,
# static+disk confirmed). On a v3.14 4K-cluster CRC32-C integrity stream, a checksummed cluster is its own
# run==1 extent carrying flag 0x1C00D0, immediately followed by an 8-byte element = [CRC32-C(cluster):le32@+0]
# [reserved:le32@+4] (32-byte stride). CRC32-C = Castagnoli, reflected poly 0x82F63B78; unit = one 4096-byte
# cluster. SHA-256 / 64K-cluster / v3.4 volumes carry NO inline element (checksums are out-of-line or absent).
INTEGRITY_EXTENT_FLAG = 0x1C00D0        # KEPT for the changelog's migration note; see _extent_row_crcs below

# ─── A3: how an extent row declares its per-cluster CRC-32C ──────────────────────────────────────
# `INTEGRITY_EXTENT_FLAG = 0x1C00D0` was never a flag value. The u32 at row+0x08 is
# `flags(u16) | row_size(u16) << 16` (E86), so 0x1C00D0 means "flags 0x00D0 AND row_size 28" -- and
# row_size 28 is 24 + 4*1, i.e. `run == 1`. The shipped test `flag == 0x1C00D0 and run == 1` therefore
# says `run == 1` twice, and every integrity extent of two or more clusters went unverified in silence.
# Measured on lab314_main: `small500.bin` (run 1, row_size 28) is checked; `big10k.bin` (run 3,
# row_size 36, three stored CRC-32C values that all verify when recomputed by hand) is not, and
# `extract` prints nothing about it. The wrong stride compounds it: a 36-byte row advanced 24 bytes,
# so the parse landed inside the CRC array and every later row in that record was lost too.
#
# TWO independent discriminators exist, and this project has been burned by silently choosing the
# weaker one (E65). So: the row's own declared SIZE is the rule -- either the checksum bytes are
# present or they are not -- and flags bit 0x80 is carried as a CROSS-CHECK, not as a second opinion.
# When they disagree the row is reported, never quietly resolved.
EXT_FLAG_HAS_CRC = 0x80                 # flags@+0x08 low half: 0x00D0 = 0x0050 | 0x80 on integrity rows
# S10 (RC3a X; RC3b item 7): flags 0x100 = a CRC64 per cluster. 17134 `CmsCrc64::InitChecksumBlobStream` sets it, 26100.9444
# `InsertRun` sets 0x80 for a stream checksum type 1 and 0x100 otherwise, and the driver reads both (mask 0x180;
# `GetChecksumType`, `GetChecksumSizeInBytes`). No corpus extent row carries 0x100 (register CT_DRNT_002): such a
# row is stepped over by its own declared size (24 + 8 x run) and its clusters are counted as NOT verified -- this tool
# verifies CRC-32C only. Until RC3 it ended the extent walk as a row that "declares no legal size".
EXT_FLAG_HAS_CRC64 = 0x100


def _extent_row_is_crc64(v, off):
    """True when the row's flags declare a CRC64 per cluster (0x100 without 0x80; S10)."""
    return off + 0x0A <= len(v) and (le16(v, off + 8) & (EXT_FLAG_HAS_CRC | EXT_FLAG_HAS_CRC64)) == EXT_FLAG_HAS_CRC64


def _extent_row_size(v, off, run):
    """The row's OWN declared length, from `row_size` at +0x0a: 24 for a plain run, 24 + 4*run when the
    row carries one CRC-32C per cluster, 24 + 8*run when its flags declare a CRC64 per cluster (0x100; S10).
    Returns 0 when the field declares none of these (a misparse), so a caller can stop instead of striding
    blindly through the rest of the record."""
    if off + 0x0C > len(v) or run <= 0:
        return 0
    rs = le16(v, off + 0x0A)
    if rs == 24 + 8 * run and _extent_row_is_crc64(v, off):
        return rs
    return rs if rs in (24, 24 + 4 * run) else 0


def _extent_walk_stop(walker, v, off):
    """WD-1 (1.14.0, the conformance batch): an extent row that declares no legal size (`_extent_row_step` 0) ends the
    walk, as B13 ends `_decode_inline_extents` -- recorded (a skip, exit 2), never stepped over by 24 bytes (the `or 24`
    of three walkers: a guess at where the next row starts). Used by the two walks of a table they were handed
    (`_stream_extent_records`, `_usn_scan_extent_tables`; on the corpus 4,418 + 1,054 steps, each by the row's own size,
    CB_evidence/g8_census.jsonl). The third, `_find_extents_in_subrecord`, is a scan of candidate headers: there such a
    row declines the candidate instead (it is not a damaged walk)."""
    _skip_note(walker, "the extent rows from offset 0x%x on: the row there declares no legal size (+0x0a = %d)"
               % (off, le16(v, off + 0x0A) if off + 0x0C <= len(v) else -1), ValueError("extent row size"))


def _extent_row_step(v, off, run):
    """The distance from this extent row to the NEXT one: its declared length rounded UP to 8.

    Size and step are different things. Rows are 8-byte aligned (extent_descriptors.md), so a checksummed
    one-cluster row is 28 bytes long and the next row starts 32 bytes later; a three-cluster one is 36 long
    with the next at 40. 1.13.0 (A3) stepped by the SIZE: after every 28-byte row it landed 4 bytes short of
    the next real row. `integrity` then verified 127 of 142 CRC-bearing clusters on win11refstestmftecmd and
    printed "every checksummed file cluster matches", and the carve path read the misaligned bytes as a
    broken map and refused files whose live twins were byte-identical to what 1.12.3 had recovered.

    Every loop that walks extent rows steps with THIS function (gate: single_source.tsv). Returns 0 when the
    row declares no legal size, so the caller chooses what to do -- never a silent guess (`_decode_inline_extents`
    stops there, B13).
    """
    rs = _extent_row_size(v, off, run)
    return (rs + 7) & ~7 if rs else 0


def _extent_row_crcs(v, off, run):
    """The per-cluster CRC-32C values this row carries, in cluster order, or [] when it carries none.
    Returns (crcs, disagreement) where `disagreement` names a row whose declared size and whose
    flags bit 0x80 tell different stories -- reported by the caller, never silently resolved."""
    if off + 0x0C > len(v) or run <= 0:
        return ([], None)
    rs = le16(v, off + 0x0A)
    flagged = bool(le16(v, off + 8) & EXT_FLAG_HAS_CRC)
    sized = rs == 24 + 4 * run
    dis = None
    if flagged != sized:
        dis = "row at +0x%x: flags bit 0x80=%s but row_size=%d (24+4*%d would be %d)" % (
            off, flagged, rs, run, 24 + 4 * run)
    if not sized or off + rs > len(v):
        return ([], dis)
    return ([le32(v, off + 24 + 4 * i) for i in range(run)], dis)

# ─── THE hole predicate (A1; E65 re-scoped) ──────────────────────────────────────────────────────
# One place decides that an extent row describes a SPARSE HOLE rather than clusters to read. Every
# decoder routes through it, because the project has already shipped the other outcome: when the rule
# was `vlcn == 0`, hole rows whose VLCN is non-zero were read as real data and `extract` delivered the
# volume's own SUPB / MSB+ pages inside user files (K001 — reproduced on win11refs2tsnapshots: a 99 MB
# file came back with 6,973,680 bytes of bootstrap metadata in it).
#
# THE RULE IS THE FLAG. A hole row sets bit 0x20 in flags@+0x08 and its VLCN *mirrors its FVCN*
# (e.g. `fvcn=1 vlcn=0x1 run=25343 flags=0x180060`), so it is not zero and `vlcn == 0` never fires.
# Measured over all six decoders on four volumes (P0.6, 8,864 accepted rows): the flag is a strict
# SUPERSET of `vlcn == 0`, with 0 counterexamples. Two volumes carry holes with BOTH discriminators and
# two carry holes with ONLY the flag — which is exactly how a corpus weighted to the first kind made
# `vlcn == 0` look like a rule.
#
# `vlcn == 0` is NOT folded into the same test, and the first cut of this fix got that wrong. Two
# different questions were being asked with one predicate:
#
#   1. IS THIS ROW A HOLE? — does it belong in the map, with its range zero-filled? That is the FLAG,
#      and only the flag. An UNFLAGGED `vlcn == 0` row is not a hole; it is a malformed row, and the
#      honest answer is to reject it so the cover guard fails cleanly. Admitting it as a hole would let
#      a bogus map pass the cover check and serve clusters of zeros as a file's content.
#      (`test_zero_run_and_zero_vlcn_rejected` pins exactly this, and is what caught the mistake.)
#   2. MAY ITS CLUSTERS BE READ? — there `vlcn == 0` IS a floor, because VLCN 0 translates to PLCN 0,
#      the boot region, which is never file content. That is `_extent_never_read`.
#
# The census measured the two discriminators as coincident on every row it saw (0 counterexamples in
# either direction), so separating them costs nothing there — and it is what keeps a malformed row
# malformed instead of promoting it to a legitimate hole.
#
# flags@+0x08 is read as a u32 whose HIGH half is `row_size` at +0x0A (E86), so the value looks like
# 0x180060 rather than 0x60. Bit 0x20 lives in the low half, so the mask is unaffected.
EXT_FLAG_SPARSE_HOLE = 0x20

# N63 / LAB-E: a SECOND condition decides whether a run's bytes are the file's. `0x10` means the run has
# been WRITTEN. ReFS allocates clusters on SetLength (and on pre-allocation) without zeroing them, so an
# allocated-but-never-written run still holds whatever the volume put there before -- and Windows returns
# zeros for it regardless. Reading those clusters serves FOREIGN BYTES into a user file.
#
# Measured three ways before this was applied:
#   * LAB-E, whose expected SHA-256s were produced on Windows: 6/7 byte-exact WITHOUT this rule
#     (`e1_setlength_4096k.bin` came back carrying 130,915 bytes of BitLocker `FVE-EOWBM` metadata),
#     and 7/7 WITH it.
#   * A real installation (winsider): of the known-unwritten runs, 693 hold NON-ZERO foreign bytes --
#     in `edbres00001.jrs`/`edbres00002.jrs` (ESE reserve logs, allocated full-size and never written),
#     `edb.log`, `ActivationStore.dat`. One leaks readable text belonging to another file.
#   * The inverse is guarded by LAB-E's `e5` control, whose zeros were genuinely WRITTEN (flags carry
#     0x10) and must therefore be READ from disk, not synthesised. A tool that simply emits zeros for
#     zero-looking runs passes e1 and fails e5.
#
# `flags == 0` is NOT treated as unwritten. The heuristic marker-scan decoder does not recover flags and
# returns 0 (with `vlcn` sometimes the $DATA descriptor constant 0x000E0080 read as an address), so
# zeroing on "no flags" would destroy real data in exactly the files whose map is least trustworthy.
# Only a POSITIVELY KNOWN flags word with 0x10 clear means unwritten.
EXT_FLAG_WRITTEN = 0x10


def _extent_never_written(flags):
    """True iff the flags positively say this run was allocated but never written (N63).

    Conservative on purpose: unknown flags (0) mean "read it", because the alternative is silently
    replacing a file's real content with zeros.
    """
    return bool(flags) and not (flags & EXT_FLAG_WRITTEN)


def _extent_is_hole(flags, vlcn=None):
    """True iff this extent row IS a sparse hole — it belongs in the map and its range is zero-filled.
    The flag decides; `vlcn` is accepted and ignored so call sites read naturally. See above."""
    return bool(flags & EXT_FLAG_SPARSE_HOLE)


def _extent_never_read(flags, vlcn):
    """The read-time floor: no cluster is read for a hole, for a run never written (N63), nor for
    VLCN 0 (PLCN 0 = the boot region, which is never a file's content). Deliberately separate from
    `_extent_is_hole` — see above."""
    return _extent_is_hole(flags) or _extent_never_written(flags) or not vlcn


def _ext_skip_read(e):
    """The same read-time floor, for a decoded extent dict."""
    return (bool(e.get("is_hole")) or _extent_never_written(e.get("flags", 0))
            or not e.get("vlcn", e.get("plcn", 0)))


_INTEGRITY_UNSET = 0xABBAFFFE          # driver's unset / match-all placeholder — an unwritten checksum, not a mismatch
_CRC32C_TABLE = None


def _crc32c(data):
    """CRC32-C (Castagnoli), reflected poly 0x82f63b78, init/final 0xffffffff. Canonical check:
    _crc32c(b'123456789') == 0xe3069283. (NOT zlib.crc32, which is CRC-32/ISO-HDLC.)"""
    global _CRC32C_TABLE
    if _CRC32C_TABLE is None:
        t = []
        for n in range(256):
            c = n
            for _ in range(8):
                c = (c >> 1) ^ (0x82F63B78 & -(c & 1))
            t.append(c & 0xFFFFFFFF)
        _CRC32C_TABLE = t
    crc = 0xFFFFFFFF
    for b in data:
        crc = (crc >> 8) ^ _CRC32C_TABLE[(crc ^ b) & 0xFF]
    return crc ^ 0xFFFFFFFF


def _decode_inline_extents(v, ncl, max_fvcn=None, tr=None, with_flags=False, rows=None, stop=None):
    """Single source of truth for decoding the inline 24-byte extent records inside a 0x10028 holder.
    The rows are the ones the extent node's key index names when its header is valid; otherwise they are read by
    position from +0x28, each stepped by its own declared size (`_extent_row_step`: 24, or 24 + 4 x run rounded up
    to 8 when it carries one CRC-32C per cluster), and a row that declares no legal size ends the walk (B13). Returns
    [(file_vcn, vlcn, run_length)] sorted by file_vcn; stops at the first record that cannot be validated
    (the caller applies any coverage gate). `ncl` (volume cluster count) bounds plausibility; `max_fvcn`
    optionally tightens the file_vcn bound (recover path passes size_cl). A SPARSE HOLE is a record carrying
    flags bit 0x20 (E98); its VLCN mirrors its file VCN and is usually non-zero, and this decoder normalises
    it to 0 so the tuple consumers downstream can test it as one — it is KEPT in the list and reassembly zero-fills it; it is never disk-read.
    (structure_reference §C.6; Phase-0 SPEC 2026-08-02, disk-verified.)

    `rows`, when a list is given, receives one dict per accepted row -- file_vcn, vlcn (0 for a hole), clusters, flags,
    crcs (the CRC-32C per cluster the row carries, or None) -- for the carve plan (B5, B6); `stop`, when a list is
    given, receives why the walk stopped before the last row, for a stop the plan refuses on (a malformed row). `ncl`
    None bounds no run (a caller without the volume's size)."""
    if len(v) < 0x50:
        return []
    ihdr = le32(v, 0)
    if ihdr + 0x18 > len(v):
        return []
    ecount = le32(v, ihdr + 0x14)
    if ncl is None:
        ncl = 1 << 62
    fvcn_bound = max_fvcn if max_fvcn is not None else ncl

    def _plausible_vlcn(vlcn):
        """A VLCN is VIRTUAL: the container table maps it to a physical cluster, and the virtual address
        space is wider than the physical one (it starts at `first_container_id << shift` and runs roughly
        twice as far — E74). Bounding it by the PHYSICAL cluster count therefore rejects every extent that
        lives in the upper half of the virtual space: on win11bidule that is 583 of 629 files, each failing
        `extract` with "inline-holder-overflow" although the extents are intact and translate cleanly.
        When a translator is available, the authoritative test is whether the container table can map it."""
        if vlcn == 0:
            # N217 (b) (1.14.0): a hole is the FLAG (E98), and `_ext` takes a flagged hole before it asks this; an
            # UNFLAGGED row at VLCN 0 is malformed, and was zero-filled as a hole here
            _last[0] = "an extent row at VLCN 0 without the sparse-hole flag (a malformed row)"
            return False
        if tr is not None:
            # Ask the container table whether it MAPS this address, and ask without translating:
            # `tr.tr()` does not raise on a miss -- it falls back to identity and increments the
            # miss counter -- so probing with it both accepted unmappable addresses (identity can
            # land inside the physical range) and produced spurious "unmapped VLCN" warnings from
            # a test that was never a real read. Translation happens only once a cover is accepted.
            return _vlcn_mappable(tr, vlcn)
        return 0 < vlcn < ncl           # no translator: physical range is all we have

    _last = [None]                      # why the last row asked about was refused (a malformed row), for `stop`

    def _ext(off):
        _last[0] = None
        if off < 0 or off + 24 > len(v):
            return None
        # N654 (S8, 1.14.0 RC3b): the file VCN is a u64 at +0x0C (`CmsStream::InsertRun` writes it, `LookupAllocation`
        # reads it; 26100.9444, 17134); eight extent readers took a u32 until RC3, dropping the high half
        vlcn = le64(v, off); run = le32(v, off + 0x14); fvcn = le64(v, off + 0x0C)
        flags = le32(v, off + 8)
        # A1: ask the chokepoint FIRST. A hole row's VLCN mirrors its FVCN, so it is a non-zero address
        # that the container table cannot map -- `_plausible_vlcn` rejected it, which both truncated the
        # extent list at the first hole and (when it did survive) sent the reader to real clusters. A hole
        # is normalised to VLCN 0 here so every downstream `vlcn == 0` test means exactly "hole".
        if _extent_is_hole(flags, vlcn):
            if 0 < run <= ncl and fvcn < fvcn_bound:
                return (fvcn, 0, run)
            return None
        if 0 < run <= ncl and fvcn < fvcn_bound and _plausible_vlcn(vlcn):
            return (fvcn, vlcn, run)
        return None

    exts = []; pos = ihdr + 0x28
    # N217 (a) (1.14.0): a holder whose extent node has a valid header is read through its KEY INDEX -- the rows the
    # node names, in key order -- as `_extent_leaf_rows` reads it for the CRC check. Read by position from +0x28, a
    # node whose first slot holds a superseded row (outside the index) gave that row and dropped the last indexed one
    # (22 of 180 slack nodes on the critic's sample, 0 of 33 live ones). An INDEX node holds child references, not
    # extents: its runs are in child pages, which this disk-free decoder does not read. A holder whose node header does
    # not validate is read by position, as before -- N486 (1.14.0): also one whose index array names no row of the node
    # (a remnant's zeroed index), unless the header says it is an index node.
    _lvl, _offs, _hwhy = _extent_node_header(v, ihdr)
    if _hwhy == "index" and v[ihdr + 0x0C]:
        return []
    if _hwhy is None:
        if _lvl:
            return []
        for off in _offs:
            rec = _ext(off)
            if rec is None:
                if stop is not None and _last[0]:
                    stop.append(_last[0])
                break
            exts.append(rec + (le32(v, off + 8),) if with_flags else rec)
            if rows is not None:
                rows.append(dict(zip(("file_vcn", "vlcn", "clusters"), rec), flags=le32(v, off + 8),
                                 crcs=_extent_row_crcs(v, off, rec[2])[0] or None))
        exts.sort(key=lambda e: e[0])
        if rows is not None:
            rows.sort(key=lambda r: r["file_vcn"])
        return exts
    for i in range(ecount):
        rec = _ext(pos)
        if rec is None:
            if stop is not None and _last[0]:
                stop.append(_last[0])
            break
        # 1.13.1: `with_flags` keeps the row's flags word. Without it a consumer cannot tell an UNWRITTEN run
        # (N63: never read -- it can hold another file's bytes) from a written one, and the carve read them.
        exts.append(rec + (le32(v, pos + 8),) if with_flags else rec)
        if rows is not None:
            rows.append(dict(zip(("file_vcn", "vlcn", "clusters"), rec), flags=le32(v, pos + 8),
                             crcs=_extent_row_crcs(v, pos, rec[2])[0] or None))
        if i == ecount - 1:
            break
        # A3: the row declares its own length at +0x0A (24, or 24 + 4*run when it carries one CRC-32C per
        # cluster), and the next row starts at that length rounded up to 8.
        # B13 (1.14.0): a row whose size field declares neither ends the walk, said in `stop`: where the next row starts
        # is not known. Until 1.14.0 two probes guessed it (+24, then +32, kept when a row validated there); on the
        # corpus they never fired (fixes/WAVED_CLOSE_evidence/b13_census.jsonl: 221,056 decodes on 141 volumes, 3,206
        # by position, none of them past its first row), and a guessed place is not a reading.
        _step = _extent_row_step(v, pos, le32(v, pos + 0x14))
        if not _step:
            if stop is not None:
                stop.append("an extent row whose size field is neither 24 nor 24 + 4 x its cluster count "
                            "(a malformed row)")
            break
        pos += _step
    exts.sort(key=lambda e: e[0])
    if rows is not None:
        rows.sort(key=lambda r: r["file_vcn"])
    return exts


def parse_snapshot_data_entry(v, ncl=None, tr=None, with_flags=False, rows=None, stop=None):
    """Parse an embedded type-0x80 DATA entry -> (stream_size, disk_alloc, extents)
    where extents = [(file_vcn, vlcn, run_length), ...] sorted by file_vcn (+ flags with `with_flags`), decoded by
    `_decode_inline_extents` (the node's key index when its header is valid; interleaved CRC-32C skipped by the rows'
    own size). `ncl` (the volume's cluster count) bounds each run; None bounds none. N217 (1.14.0): the separate
    fixed-24-stride decode used when `ncl` was None is gone -- its one caller, the old verdict predicate, now reads the
    carve plan (`_carve_plan`), and it read a node by position as the stride decode did. `rows`: see
    `_decode_inline_extents`."""
    if len(v) < 0x50:
        return (0, 0, [])
    return (le64(v, 0x38), le64(v, 0x48),
            _decode_inline_extents(v, ncl, tr=tr, with_flags=with_flags, rows=rows, stop=stop))


def _unwritten_as_zero(entry):
    """N128 (1.14.0): a `parse_snapshot_data_entry(..., with_flags=True)` result as the 3-tuple form, with every run the
    row marks never written (N63, flags 0x10 clear) given VLCN 0 -- the read-time floor every tuple reader already
    keeps (zeros, never read), as a hole is. The snapshot readers took the tuples without the flags, so a version's
    unwritten run was read and the clusters' current bytes (another file's, or image holes) became its content."""
    size, alloc, exts = entry
    return (size, alloc, [(fv, 0 if _extent_never_written(fl) else vl, run) for fv, vl, run, fl in exts])


def recover_cow_current_content(f, ps_off, cs, tr, vd, _content_what=None):
    """Q7/CoW: recover the LIVE content of a resident file whose current stream (sub_id 0x1000) is a 0x10028
    holder with disk_alloc==0 and no own extents — i.e. UNMODIFIED since the last snapshot, so its bytes are
    shared with the newest snapshot. Returns bytes (trimmed to size) or None. STRICTLY the safe case only:
    if the current stream has its OWN allocation (disk_alloc>0 / own extents) this returns None (that is the
    F5 large-non-resident / possibly-sparse case, deferred to `dataruns`). Verified on win11refs2tsnapshots
    (test.txt current 5B == snapshot 0x1004; lasttest.txt 201B == 0x1002)."""
    ncl = _volume_ncl(f, ps_off, cs)       # integrity-robust extent decode (skip interleaved CRC32-C)
    holders = {}   # sub_id -> (stream_size, disk_alloc, extents)
    for k, v in parse_resident_btree_rows(vd, (f, ps_off, cs, tr)):
        if (len(k) >= 0x18 and k[12] == 0x80 and k[13] == 0x00
                and len(v) >= 0x50 and le32(v, 4) == SNAP_DATA_DESC):
            holders[le64(k, 0x10)] = _unwritten_as_zero(parse_snapshot_data_entry(v, ncl, tr, with_flags=True))
    cur = holders.get(0x1000)
    if cur is None:
        return None
    cur_size, cur_alloc, cur_exts = cur
    if cur_alloc != 0 or cur_exts:
        return None   # own allocation => not the safe CoW case (F5 / sparse) — leave to dataruns
    if cur_size == 0:
        return b""
    # the current bytes are the newest snapshot with real extents AND the SAME size (don't guess otherwise).
    candidates = [sid for sid, d in holders.items()
                  if sid > 0x1000 and d[2] and d[0] == cur_size]
    if not candidates:
        return None
    _ssz, _salloc, exts = holders[max(candidates)]
    alloc = max((fv + run) for fv, _vl, run in exts) * cs
    if alloc > 64 * 1024 * 1024:   # CoW resident streams are small; guard anyway
        return None
    # NB on `bytes(memoryview(buf)[:N])` here and in the other reassemblers: the slice is LOAD-BEARING
    # (buf is allocated at `alloc`, the cluster-rounded size, and N is the logical size), so it cannot be
    # dropped the way `_recover_inline_extent_content`'s could -- that one allocated at exactly its slice
    # bound. Taking the slice through a memoryview avoids the intermediate bytearray copy, so the peak is
    # one copy of the file instead of two: measured 400 -> 200 MiB on a 200 MiB buffer.
    buf = bytearray(alloc)
    _runs = []
    for fvcn, vlcn, run in sorted(exts, key=lambda e: e[0]):
        if not vlcn:
            # a hole, or (N128, 1.14.0) a run the snapshot's row marks never written: zeros, never read. 1.13.1 read both
            # -- VLCN 0 as PLCN 0, the boot region, and an unwritten run's clusters, which can hold another file's bytes
            continue
        for j in range(run):
            try:
                plcn = tr.tr(vlcn + j)
            except Exception:
                plcn = vlcn + j
            off = (fvcn + j) * cs
            _runs.append((plcn, 1, off))
            chunk = _seek_read(f, ps_off + plcn * cs, cs)                # N371
            buf[off:off + len(chunk)] = chunk   # K007: length-safe -- a short read must not RESIZE buf
    # These bytes become OUTPUT (cmd_extract emits them as "snapshot-shared with the latest snapshot"),
    # so the clusters behind them must be present in the image. A punched cluster here produced five
    # zero bytes under that label with rc=0 -- see analysis/reports/d13_gap_2026-09-09/.
    if _content_what:
        # Only when the caller says these bytes will be EMITTED. The directory walk precomputes
        # cow_content for every file to fill a column; running a hole scan there would cost a syscall
        # sweep per file for a check nobody reads. Extract asks again, by name, for the one file.
        content_holes(f, ps_off, cs, _runs, _content_what, stream_size=cur_size)
    return bytes(memoryview(buf)[:cur_size])


def _snapshot_shared_blocks(vd, ctx, ncl, exclude=0x1000, older_than=None):
    """Map file-VCN -> VLCN for the blocks a stream does not own itself but SHARES with stream snapshots.

    ReFS stream snapshots are copy-on-write: a block is duplicated only when it is about to be overwritten, so
    every block not yet modified since a snapshot stays **shared** — physically present once, listed in the
    snapshot's extent table and absent from the current stream's. That is why a snapshotted file's current
    stream can report `total_alloc` for the whole file while its own `disk_alloc` covers only the few clusters
    written since the last snapshot (E83).

    This resolves those blocks to the real clusters that hold them. Nothing is reconstructed or synthesised —
    every VCN is answered with an actual on-disk cluster; the alternative (what the reader did before) was to
    leave them zero-filled, which invents bytes that exist nowhere on the volume.

    `exclude` is the stream being assembled. `older_than` restricts the search to snapshots strictly older than
    a given sub_id, which is what reconstructing a PRIOR version needs: a newer snapshot may hold content
    written *after* the version being recovered. For the current stream (`older_than=None`) the newest snapshot
    holding a VCN wins, since a block only leaves the current stream's table when it has not changed since.
    """
    streams = {}
    tr = ctx[3] if ctx and len(ctx) > 3 else None      # the translator, for virtual-LCN plausibility (E85)
    try:
        rows = parse_resident_btree_rows(vd, ctx)
    except (ValueError, struct.error, IndexError) as _e:
        # `return {}` here is indistinguishable from "this file shares no blocks", and the callers
        # reassemble content from the result: every shared VCN would silently come back zero. Same
        # defect as the per-stream failure below, reached one level earlier.
        _skip_note("snapshot shared blocks", "row decode", _e)
        raise IncompleteEvidence("snapshot rows did not decode") from _e
    for k, v in rows:
        if len(k) < 0x18 or le16(k, 0x0C) != 0x80:
            continue
        v = bytes(v)
        if len(v) < 0x50 or le32(v, 4) != SNAP_DATA_DESC:
            continue
        sub = le64(k, 0x10)
        if sub == exclude or not (0x1000 <= sub <= 0xFFFF):
            continue
        if older_than is not None and sub >= older_than:
            continue
        try:
            streams[sub] = parse_snapshot_data_entry(v, ncl, tr, with_flags=True)
        except (ValueError, struct.error, IndexError) as _e:
            # Dropping this stream would SHRINK the shared-block map, and both callers reassemble file
            # content from it: every VCN this stream would have supplied then stays zero in the output.
            # That is E83's defect (snapshot CoW blocks read as holes) arriving through an exception
            # path. The map is all-or-nothing, so say so and let the caller defer.
            _skip_note("snapshot shared blocks", f"sub-stream 0x{sub:x}", _e)
            raise IncompleteEvidence(f"snapshot sub-stream 0x{sub:x} did not parse") from _e
    shared = {}
    for sub in sorted(streams, reverse=True):        # newest first; an older snapshot never overrides it
        for fv, vlcn, run, fl in (streams[sub][2] or []):
            if not vlcn:
                continue
            for j in range(run):
                # N128 (1.14.0): a run that snapshot's row marks never written is a block of ZEROS in it (0 here: no
                # cluster to read), not the clusters' current bytes -- 1.13.1 offered them as the shared content
                shared.setdefault(fv + j, 0 if _extent_never_written(fl) else vlcn + j)
    return shared


def _recover_inline_extent_content(f, ps, cs, tr, vd, _defer_ctx=None):
    """Reassemble the LIVE content of a NON-RESIDENT file whose CURRENT $DATA stream (sub_id 0x1000) holds its
    extent map INLINE in a 0x10028 holder — the F5 'extent-backed' case (disk_alloc>0) that
    `recover_cow_current_content` deliberately defers. Returns the bytes (trimmed to stream_size), or None to
    DEFER (never wrong output). SAFE by a coverage gate: reassemble only when the decoded extents account for
    EVERY allocated cluster exactly once and start within the file — otherwise defer (large/overflow holders with
    a different extent-table format, or any decode anomaly). Sparse-aware: holes (alloc < size) are zero-filled.
    Integrity-stream CRC32-C checksums carried by a row are stepped over by the row's own declared size
    (`_decode_inline_extents`). SEPARATE from the snapshot path (`parse_snapshot_data_entry`)
    which is left byte-identical. (structure_reference §C.6; Phase-0 SPEC 2026-08-02, disk-verified.)"""
    v = None
    for k, hv in parse_resident_btree_rows(vd, (f, ps, cs, tr)):
        if (len(k) >= 0x18 and k[12] == 0x80 and k[13] == 0x00
                and len(hv) >= 0x50 and le32(hv, 4) == SNAP_DATA_DESC and le64(k, 0x10) == 0x1000):
            v = hv; break
    if v is None:
        return None
    ihdr = le32(v, 0)
    if ihdr + 0x18 > len(v):
        return None
    ecount = le32(v, ihdr + 0x14)
    stream_size = le64(v, 0x38)
    alloc_cl = le64(v, 0x48) // cs
    if stream_size == 0:
        return b""
    if alloc_cl <= 0 or ecount <= 0:
        return None
    if stream_size > 4 * 1024 * 1024 * 1024:        # 4 GiB safety cap (matches the extent-extract path)
        return None
    size_cl = (stream_size + cs - 1) // cs
    ncl = _volume_ncl(f, ps, cs)            # volume cluster count (plausibility bound)

    # validated-greedy decode (shared with the snapshot/carve paths); size_cl tightens the file_vcn bound.
    # N128 (1.14.0): with the flags, so a run never written (N63) is zeros and never read -- 1.13.1 read its clusters
    exts = [(fv, 0 if _extent_never_written(fl) else vl, run)
            for fv, vl, run, fl in _decode_inline_extents(v, ncl, max_fvcn=size_cl, tr=tr, with_flags=True)]

    # COVERAGE GATE (the safety guarantee): every allocated cluster accounted for, exactly once, within the file.
    covered = set()
    for fv, _vl, run in exts:
        for j in range(run):
            covered.add(fv + j)
    if sum(run for _fv, _vl, run in exts) != alloc_cl or len(covered) != alloc_cl:
        return None
    if any(fv + run > size_cl for fv, _vl, run in exts):
        return None

    # E83: blocks this stream does not own may be SHARED with a stream snapshot rather than being sparse
    # holes. Resolve those to the clusters that actually hold them; a VCN no stream owns stays zero-filled,
    # which is the genuine sparse case. Empty (and therefore a no-op) for a file without snapshots.
    _runs = []                          # every PHYSICAL cluster whose bytes end up in `buf`
    try:
        shared = _snapshot_shared_blocks(vd, (f, ps, cs, tr), ncl)
    except IncompleteEvidence as _e:
        _defer_note(_defer_ctx or "a stream", f"snapshot shared-block map incomplete ({_e})")
        return None                     # defer: a truncated shared map would be emitted as zero blocks
    if shared:
        for fv in range(size_cl):
            if fv in covered or fv not in shared:
                continue
            if not shared[fv]:
                continue                    # N128: a shared block a snapshot never wrote is zeros, nothing to read
            off = fv * cs
            try:
                plcn = tr.tr(shared[fv]) if tr else shared[fv]
                _runs.append((plcn, 1, off))
            except Exception as _e:
                # This VCN never reaches `exts`, so the buffer below leaves it ZERO and the file is
                # emitted anyway -- fabricated content, in a function that promises to defer instead.
                _skip_note("shared block translate", f"vcn {fv}", _e)
                _defer_note(_defer_ctx or "a stream",
                            f"shared block at VCN {fv} could not be translated ({type(_e).__name__})")
                return None
            chunk = _seek_read(f, ps + plcn * cs, cs)                    # N371
            if len(chunk) < min(cs, stream_size - off):
                _skip_note("shared block read", f"vcn {fv}", IOError("short read"))
                _defer_note(_defer_ctx or "a stream", f"short read on the shared block at VCN {fv}")
                return None
            exts = exts + [(fv, shared[fv], 1)]

    buf = bytearray(stream_size)            # holes stay zero (sparse)
    for fv, vlcn, run in exts:
        if vlcn == 0:
            # A hole reaches this tuple path already normalised to 0 by the decoder (E98); 0 is also the
            # read-time floor, since PLCN 0 is the boot region and is never a file's content.
            continue
        for j in range(run):
            off = (fv + j) * cs
            if off >= stream_size:
                continue
            try:
                plcn = tr.tr(vlcn + j) if tr else (vlcn + j)
            except Exception as _e:
                _skip_note("_recover_inline_extent_content", "an inline extent map", _e)
                return None
            _runs.append((plcn, 1, off))
            chunk = _seek_read(f, ps + plcn * cs, cs)                    # N371
            n = min(cs, stream_size - off)
            if len(chunk) < n:
                return None
            buf[off:off + n] = chunk[:n]
    if _defer_ctx:
        # Only when these bytes are destined for OUTPUT. `files` calls this for residency classification
        # on every record; a hole sweep there would cost syscalls for an answer nobody reads.
        content_holes(f, ps, cs, _runs, _defer_ctx, stream_size=stream_size)
    # `bytes(buf)`, not `bytes(buf[:stream_size])`: buf is allocated at exactly stream_size and every
    # write above is bounded by it (`off >= stream_size` skipped, `n = min(cs, stream_size - off)`), so
    # the slice can only ever copy the whole buffer. It made a large reassembly hold THREE copies of the
    # file at once -- on a 2,556 MiB stream that is ~7.6 GiB, which is what took a verification worker
    # over the limit on a 7 GiB host. Same bytes, one copy fewer.
    return bytes(buf)


def _verify_inline_integrity(f, ps, cs, tr, vd, expect_crc=False, why=None):
    """Verify a NON-RESIDENT file's INLINE per-cluster CRC32-C integrity checksums (the 0x1000 / 0x10028 holder).
    Each checksummed cluster is a run==1 extent with flag 0x1c00d0, immediately followed by an 8-byte element
    whose le32@+0 == CRC32-C(that 4096-byte cluster). Reads each checksummed cluster and recomputes CRC32-C.

    Returns None when the file carries NO inline element (SHA-256 / 64K-cluster / non-integrity / v3.4 / the
    large-overflow or complex holder formats) — i.e. nothing inline to verify. Otherwise returns
    {'checked': int, 'ok': int, 'unset': int, 'bad': [(file_vcn, vlcn, plcn, stored_crc, actual_crc), ...],
     'bad_count': int}. Never raises: a read error on a cluster is skipped (not counted). Purely on-disk read-only
    (the stored checksum is the ground truth; a mismatch is genuine corruption/tampering, surfaced non-fatally).
    (structure_reference §C.6; Phase-2 spec 2026-08-06, poly 0x82f63b78, static+disk confirmed on 391/391 clusters.)"""
    v = None
    for k, hv in parse_resident_btree_rows(vd, (f, ps, cs, tr)):
        # N462 (wave C's close): the v3.4 $DATA row as well (`_is_v34_data_key`). v3.4 extent rows carry the same
        # inline CRC-32C (flags 0xD0, row size 24 + 4 x run): 3,929 of 3,929 clusters match on
        # win10refs8gsetintegristystreams1. Until 1.14.0 no v3.4 file was verified, and `integrity --checksums` said
        # "No file on this volume carries an integrity stream" on a volume whose 262 files all carry one.
        if (((len(k) >= 0x18 and k[12] == 0x80 and k[13] == 0x00 and le64(k, 0x10) == 0x1000) or _is_v34_data_key(k))
                and len(hv) >= 0x50 and le32(hv, 4) == SNAP_DATA_DESC):
            v = hv; break
    if v is None:
        return None
    ihdr = le32(v, 0)
    if ihdr + 0x18 > len(v):
        return None
    ncl = _volume_ncl(f, ps, cs)
    res = {"checked": 0, "ok": 0, "unset": 0, "bad": [], "bad_count": 0,
           "clusters_with_crc": 0, "disagreements": [], "rows_unreadable": 0, "no_crc_clusters": 0,
           "no_crc_never_written": 0, "no_crc_written": 0, "crc64_clusters": 0}
    inline = False
    # 1.13.1 (the corpus-golden accounting): the rows are the ones the node's KEY INDEX names, read through the
    # same walk extraction uses. This loop walked the node's slots in physical order for `count` slots, so a
    # superseded row in a slot the index no longer names used up an iteration and the live CRC row after it
    # was never reached -- 189 of the volume's 3,820 CRC clusters checked on win1122h2test, "every ... matches". And it
    # bounded the VIRTUAL cluster number by the PHYSICAL cluster count, which stopped the walk at the first
    # row stored above it: two CRC-carrying files dropped without a word on win11refs2g_setintegritystreams1,
    # and a third reported "not verified" for rows that carry no CRC.
    _lost = []
    for b, pos in _extent_leaf_rows(v, ihdr, f, ps, cs, tr, lost=_lost):
        if pos + 0x18 > len(b):
            res["rows_unreadable"] += 1
            continue
        vlcn = le64(b, pos); run = le32(b, pos + 0x14); fvcn = le64(b, pos + 0x0C)
        flags_u32 = le32(b, pos + 8)
        if 0 < run <= ncl and _extent_row_is_crc64(b, pos) and not _extent_is_hole(flags_u32, vlcn):
            res["crc64_clusters"] += run                  # S10 / RC3b item 7: a CRC64 per cluster, not verified here
            continue
        # A3: every cluster of the run, not just a run of one. The row says how many CRCs it carries.
        crcs, dis = _extent_row_crcs(b, pos, run) if 0 < run <= ncl else ([], None)
        if dis:
            res["disagreements"].append(dis)
        if not crcs and 0 < run <= ncl and not _extent_is_hole(flags_u32, vlcn):
            # N463 (wave C's close): a data run whose row carries no CRC-32C (flags without 0x80, row size 24). Most
            # integrity files of the corpus have such runs beside their checksummed ones (204 of 209 files on
            # win11refs2g_setintegritystreams1); their clusters are not verified, and the statement says how many.
            res["no_crc_clusters"] += run
            # N582 (1.14.0, the auditor's RC1 check O5): split by what the row says. A run marked never written (N63:
            # no data, read as zeros -- `_extent_never_read`) has nothing to verify; a written run without a CRC-32C
            # is not verified. On the corpus every such run is marked never written (670,385 clusters of 2,469 files
            # on 10 images, flags 0x40; RC1D/rc1check/o5, 2026-11-18)
            if _extent_never_written(flags_u32):
                res["no_crc_never_written"] += run
            else:
                res["no_crc_written"] += run
        if not crcs or _extent_is_hole(flags_u32, vlcn):
            continue
        inline = True
        res["clusters_with_crc"] += len(crcs)
        if not vlcn or not _vlcn_mappable(tr, vlcn):
            # The row carries checksums for clusters whose address cannot be translated: coverage lost, and
            # counted per checksummed CLUSTER -- the unit the verdict speaks in.
            res["rows_unreadable"] += len(crcs)
            continue
        for _j, stored in enumerate(crcs):
            if stored == _INTEGRITY_UNSET:
                res["unset"] += 1
                continue
            try:
                plcn = tr.tr(vlcn + _j) if tr else (vlcn + _j)
                data = _seek_read(f, ps + plcn * cs, cs)                 # N371
            except Exception:
                data = b""
            if len(data) != cs:
                # A cluster the volume vouches for that could not be READ is not "nothing to say":
                # it is coverage the verdict must not claim. Counted, and surfaced by the callers.
                res["rows_unreadable"] += 1
                continue
            res["checked"] += 1
            actual = _crc32c(data)
            if actual == stored:
                res["ok"] += 1
            else:
                res["bad_count"] += 1
                if len(res["bad"]) < 64:
                    res["bad"].append((fvcn + _j, vlcn + _j, plcn, stored, actual))
    if _lost and expect_crc:
        # An integrity file whose extent map could not be walked in full: the CRC rows in what was left out are
        # unknown in number, so each lost subtree is counted as a row not verified -- and a coverage-short
        # verdict follows. Without this, a lost subtree lowered "carrying" and "checked" by the same amount and
        # "every ... matches" still held (the corpus-golden critic's finding; 0 occurrences on the corpus).
        inline = True
        res["rows_unreadable"] += len(_lost)
        res["lost_subtrees"] = _lost
    if not inline and why is not None:
        # WC-7's leftover (1.14.0): no CRC-32C row was read -- the rows whose flags and declared size disagree are why,
        # and the callers say so (1.13.2-dev dropped the text with the result)
        why.extend(res["disagreements"])
    return res if inline else None


def _integrity_unverified_said(target, iv, prog=None, why=None):
    """N462 (wave C's close): `extract` of a file that carries an integrity stream (attribute 0x8000) and has extents,
    when the verifier found no CRC-32C row it reads (`iv` None): the bytes are written but NOT verified -- said, and
    recorded as lost coverage (exit 2), as `integrity` records a file it did not examine. Silence read as a clean
    result: until 1.14.0 every v3.4 integrity file was extracted this way without a word."""
    if iv is not None or not (target.get("file_attrs", 0) & 0x8000) or not target.get("extents"):
        return
    pr = prog or PROG
    print(f"[{pr}] WARNING: '{target['name']}' carries an integrity stream, but no CRC-32C row this tool reads was "
          f"found in its extent map%s: the bytes written are NOT verified against the volume's checksums."
          % (" (%s)" % "; ".join(why[:3]) if why else ""), file=sys.stderr)                     # WC-7
    _finding("integrity coverage", "'%s': an integrity stream whose checksums were not read" % target["name"])


def _integrity_report(iv, name, prog=None):
    """A3: the ONE place an inline CRC-32C result is turned into words. Returns True when the volume's own
    checksums say the bytes are wrong -- the caller turns that into exit 2. Printed to stderr so stdout
    stays the file.

    Previously each call site phrased its own verdict, and only ONE branch of `extract` called the verifier
    at all -- so a file whose bytes reached the operator by the other branch carried no integrity statement
    of any kind, clean or otherwise. Silence is not a clean result."""
    pr = prog or PROG
    if iv is None:
        return False
    if iv.get("disagreements"):
        print(f"[{pr}] NOTE: {len(iv['disagreements'])} integrity row(s) of '{name}' declare a size and a "
              f"flag that disagree; they were read by the declared size: {iv['disagreements'][0]}",
              file=sys.stderr)
    if iv.get("rows_unreadable"):
        print(f"[{pr}] WARNING: {iv['rows_unreadable']} checksummed row(s)/cluster(s) of '{name}' could not "
              f"be read, so they are NOT covered by the result below.", file=sys.stderr)
        _finding("integrity coverage", "'%s': %d row(s)/cluster(s) not verified" % (name, iv["rows_unreadable"]))
    # N582 (O5): the clusters without a CRC-32C, by what their row says
    _nw, _nv = iv.get("no_crc_never_written") or 0, iv.get("no_crc_written") or 0
    _nct = ((f"; {_nw} more cluster(s) of the file are in runs marked never written (no data: written as zeros, "
             f"nothing to verify)" if _nw else "")
            + (f"; {_nv} more cluster(s) are in written extent rows that carry no CRC-32C and are NOT verified"
               if _nv else "")
            + (f"; {iv['crc64_clusters']} more cluster(s) carry a CRC64 per cluster (extent flags 0x100), which this "
               f"tool does not verify" if iv.get("crc64_clusters") else ""))
    if iv["bad_count"] == 0:
        if iv["checked"] or iv.get("unset"):
            extra = f", {iv['unset']} unset" if iv["unset"] else ""
            print(f"[{pr}] integrity: {iv['ok']}/{count_noun(iv['checked'], 'cluster')} CRC32-C-verified{extra}{_nct}.",
                  file=sys.stderr)
        return False
    print(f"[{pr}] WARNING: INTEGRITY MISMATCH — {iv['bad_count']} of {count_noun(iv['checked'], 'checksummed cluster')} "
          f"FAILED CRC32-C (possible corruption/tampering; bytes still extracted){_nct}:", file=sys.stderr)
    for _fv, _vl, _pl, _st, _ac in iv["bad"][:8]:
        print(f"[{pr}]   file_vcn={_hx(_fv)} vlcn={_hx(_vl)} plcn={_hx(_pl)} stored=0x{_st:08x} actual=0x{_ac:08x}",   # K9
              file=sys.stderr)
    if iv["bad_count"] > 8:
        print(f"[{pr}]   ... and {iv['bad_count'] - 8} more", file=sys.stderr)
    return True


def recover_snapshot_streams(f, ps_off, cs, tr, vd):
    """Recover snapshot + current stream content from a resident type-0x30 row.
    Returns a list of {name, sub_id, stream_size, ts, content|None, inline, n_extents}.
    content is None when inline (disk_alloc==0; bytes live in the main 0x30 body) or
    when the referenced DATA entry is absent. The current file version is sub_id 0x1000."""
    ncl = _volume_ncl(f, ps_off, cs)       # integrity-robust extent decode (skip interleaved CRC32-C)
    snaps = []   # (name, sub_id, stream_size, ts)
    data = {}    # sub_id -> (stream_size, disk_alloc, extents)
    for k, v in parse_resident_btree_rows(vd, (f, ps_off, cs, tr)):
        if len(k) < 0x10:
            continue
        typ = le16(k, 0x0C)
        if typ == 0xB0 and len(v) >= 0x50:
            sub_id = le32(v, 0x44)
            # K027: the single-source discriminator, StreamSummary flags @+0x10 == 2 (0 = ADS). A second
            # clause, `0x1000 <= sub_id <= 0xFFFF`, admitted ADS too -- an ADS's sub_id sits in that range --
            # so `snapshots --show/--extract` listed `testads.txt:adstest` as a recovered "current version". Over
            # five volumes the clause admitted 6 rows beyond the flags test, all 6 ADS and 0 snapshots; the other
            # five (on lab314_main, a volume with no snapshots) never reached the command's output.
            is_snap = _is_snapshot_value(v)
            if not is_snap:
                continue
            name = ""
            if len(k) > 0x10:
                try:
                    name = k[0x10:].decode("utf-16-le").rstrip("\x00")
                except Exception:
                    name = k[0x10:].hex()
            snaps.append((name, sub_id, le64(v, 0x20), le64(v, 0x4C)))
        elif typ == 0x80 and len(v) >= 0x50 and le32(v, 4) == SNAP_DATA_DESC:
            data[le64(k, 0x10)] = parse_snapshot_data_entry(v, ncl, tr, with_flags=True)

    def _read_extents(stream_size, exts, sub_id=None, name_for_msg=None):
        """Assemble one version, placing every block at its own file VCN.

        E83: a version owns only the blocks that were copied out for it; the rest it SHARES with OLDER
        snapshots, which is why concatenating its own extents produced a short, offset-shifted file. Missing
        VCNs are resolved from snapshots strictly older than this one — never newer, which could hold content
        written after the version being recovered. A VCN no stream owns stays zero (a genuine sparse hole)."""
        try:
            shared = (_snapshot_shared_blocks(vd, (f, ps_off, cs, tr), ncl, exclude=sub_id, older_than=sub_id)
                      if sub_id else {})
        except IncompleteEvidence as _e:
            _skip_note("recover_snapshot_streams", "a snapshot stream", _e)
            return None                 # defer: same reason as the live-stream path
        nblocks = (stream_size + cs - 1) // cs
        blocks = {}
        for fvcn, vlcn, run, fl in exts:
            for j in range(run):
                if vlcn and _extent_never_written(fl):
                    # N128 (1.14.0): this version's own run, never written (N63): ZEROS in this version, resolved and
                    # never read -- 1.13.1 read the clusters (another file's bytes, or image holes: the C14 exit 2)
                    blocks.setdefault(fvcn + j, 0)
                elif vlcn:
                    blocks.setdefault(fvcn + j, vlcn + j)
        for fvcn in range(nblocks):
            if fvcn not in blocks and fvcn in shared:
                blocks[fvcn] = shared[fvcn]
        # Only hand back content when EVERY block position resolves to a real cluster. A partially resolved
        # version would have to be zero-padded, and inventing bytes that are not on the volume is exactly the
        # failure this change exists to remove — so an incomplete version is reported as not recovered
        # instead. (A stream with no extents at all is the inline/CoW-resident case, handled elsewhere.)
        if len(blocks) < nblocks:
            return b""
        buf = bytearray(stream_size)
        _runs = []
        for fvcn in range(nblocks):
            vlcn = blocks.get(fvcn)
            if not vlcn:
                continue
            try:
                plcn = tr.tr(vlcn)
            except Exception:
                plcn = vlcn
            off = fvcn * cs
            _runs.append((plcn, 1, off))
            chunk = _seek_read(f, ps_off + plcn * cs, cs)                # N371
            n = min(cs, stream_size - off)
            if len(chunk) < n:
                return b""
            buf[off:off + n] = chunk[:n]
        # Snapshot VERSIONS are output too. Punching one cluster behind a version produced a 5-byte
        # all-zero `test.txt__last` sitting beside five correct versions -- which reads as "the file was
        # zeroed in its last version", a forensic conclusion invented by the reader.
        content_holes(f, ps_off, cs, _runs,
                      f"snapshot version '{name_for_msg}' (0x{sub_id or 0:x})" if name_for_msg
                      else f"snapshot version 0x{sub_id or 0:x}", stream_size=stream_size)
        return bytes(buf)

    out = []
    for name, sub_id, ssize, ts in sorted(snaps, key=lambda s: s[1]):
        d = data.get(sub_id)
        if d is None:
            out.append({"name": name, "sub_id": sub_id, "stream_size": ssize,
                        "ts": ts, "content": None, "inline": False, "n_extents": 0})
            continue
        _ds, disk_alloc, exts = d
        if disk_alloc == 0:
            out.append({"name": name, "sub_id": sub_id, "stream_size": ssize,
                        "ts": ts, "content": None, "inline": True, "n_extents": 0})
        else:
            # _holes_mark is taken BEFORE this version is assembled, so the writer can tell which
            # version drew from holes: every version is produced here, long before any is written.
            _hm = _hole_mark()          # N208 (widening): both registers, so an unchecked range is seen too
            out.append({"name": name, "sub_id": sub_id, "stream_size": ssize, "ts": ts,
                        "content": _read_extents(ssize, exts, sub_id, name), "inline": False,
                        "n_extents": len(exts), "_holes_mark": _hm})
    return out

