# N359 (1.14.0): the exit contract, stated in every help entry and in the overview
_EXIT_CODE_LINES = (("0", "the command ran and flagged nothing"),
                    ("1", "a usage error, an image that cannot be read as a ReFS volume, or a file or object named that "
                     "is not on it"),
                    ("2", "a finding, or work the command could not complete; the output says which"))

# PLAN 10.2 A3 (1.14.0; the maintainer, 2026-11-11 and 2026-11-15): prose is wrapped at about 100 characters with a
# hanging indent; data rows (listings, tables, entries, records, CSV, JSON) never, and stderr's WARNING / note lines
# stay one line per condition. `_wprint` is print for a prose line: a line longer than `_WRAP` is broken at spaces,
# the continuation indented under the text after the line's leading label ("  Coverage:   ", "  VERDICT: ") or, with
# no label, under the line's own indent; a word longer than the room is never broken.
_WRAP = 100
_WRAP_TOLERANCE = 110          # "about 100": a line up to 110 is left as written (no two-word tail); a longer one wraps
_WRAP_LABEL = re.compile(r"^(\s*)((?:\[[A-Z]+\](?: [^:\s]+){0,3}:|\[[A-Z]+\]|[A-Za-z$][^:\s]*(?: [^:\s]+){0,4}:|·|•|↳|-|\*|"
                         r"\d+(?=\s{2})|[\w$.-]+(?=\s{2}))\s+)?")


def _wrap_lines(line, width=None):
    """The lines `_wprint` prints for one line of text."""
    width = width or _WRAP
    if len(line) <= max(width, _WRAP_TOLERANCE):
        return [line]
    import textwrap
    m = _WRAP_LABEL.match(line)
    head = m.group(0) if m else ""
    hang = len(head) if len(head) <= width // 2 else len(m.group(1) if m else "")
    body = line[hang:]
    parts = textwrap.wrap(body, width - hang, break_long_words=False, break_on_hyphens=False) or [body]
    return [line[:hang] + parts[0]] + [" " * hang + p for p in parts[1:]]


def _opt_lines(flag, desc, col=31):
    """A help option row: the flag in 26 columns, its description wrapped at `_WRAP` under column `col` (a longer flag
    pushes the first line's description right; the continuation stays under `col`)."""
    import textwrap
    head = f"    {flag:26} "
    if len(head + desc) <= _WRAP_TOLERANCE:
        return [head + desc]
    room = _WRAP - max(len(head), col)
    parts = textwrap.wrap(desc, max(room, 20), break_long_words=False, break_on_hyphens=False) or [""]
    out = [head + parts[0]]
    rest = textwrap.wrap(" ".join(parts[1:]), _WRAP - col, break_long_words=False, break_on_hyphens=False)
    return out + [" " * col + p for p in rest]


def _wprint(*args, **kw):
    """print() for prose: each line wrapped by `_wrap_lines` (A3) -- on stdout only: a line written to stderr (the
    statements of an export on stdout, `deleted`'s report beside records on stdout) or into a buffer stays one line."""
    sep, end = kw.pop("sep", " "), kw.pop("end", "\n")
    text = sep.join(str(a) for a in args)
    if (kw.get("file") or sys.stdout) is sys.stdout and sys.stdout is not sys.stderr:
        text = "\n".join(x for ln in text.split("\n") for x in _wrap_lines(ln))
    print(text, end=end, **kw)


# PLAN 10.2 G1 (1.14.0; the maintainer, 2026-11-11 third answers, 2026-11-15 the draft): what each command's output is,
# beside the core / secondary / experimental groups; `extract`, `export` and `verify-bundle` get data out or check a
# bundle, and have no output group
_OUTPUT_INFERRED = "inferred or recovered -- corroborate before relying on it."
_OUTPUT_LINES = {"timeline": _OUTPUT_INFERRED, "timestomp": _OUTPUT_INFERRED, "deleted": _OUTPUT_INFERRED,
                 "mlog": "read from the volume; the actions of --parse are inferred -- corroborate before relying on "
                         "them."}
_NO_OUTPUT_GROUP = ("extract", "export", "verify-bundle")


def _output_group_lines():
    return ["What the output is:",
            "  read from the volume       every subcommand not named below",
            "  inferred or recovered      mlog --parse, timeline, timestomp, deleted -- corroborate before relying on it"]


def _render_cmd_help(cmd):
    h = CMD_HELP.get(cmd)
    if not h:
        print(f"{PROG}: no help for {cmd!r}. Run `{PROG} --help`.", file=sys.stderr); return
    # N541 (1.14.0): a command whose input is not an image names its own (`verify-bundle`: the bundle directory)
    inp, exin = h.get("input", "<image>"), h.get("example_input", "disk.raw")
    _wprint(f"{PROG} v{VERSION} {inp} {cmd} — {h['tag']}\n")
    print(f"  usage: {PROG} {inp} {cmd} [options]" if h["opts"] else f"  usage: {PROG} {inp} {cmd}")
    if cmd not in _NO_OUTPUT_GROUP:
        _wprint("  Output: " + _OUTPUT_LINES.get(cmd, "read from the volume."))      # G1
    print()
    for line in h["desc"]:
        _wprint(f"  {line}")
    if h["opts"]:
        print("\n  Options:")
        for flag, desc in h["opts"]:
            for x in _opt_lines(flag, desc):              # A3: a description wrapped under its column
                print(x)
    print("\n  Examples:")
    for ex, note in h["ex"]:
        print(f"    {PROG} {exin} {ex}")
        _wprint(f"        {note}")
    if h.get("notes"):
        # N375 (O1): an entry's notes are printed too (verify-bundle's said what it does not check and where to look)
        import textwrap
        print("\n  Notes:")
        for note in h["notes"]:
            print(textwrap.fill(note, _WRAP, initial_indent="    ", subsequent_indent="    "))
    # N359 (1.14.0): every entry states its exit codes (the contract of `docs/tools/forefst.md`, "Exit codes")
    print("\n  Exit codes:")
    for code, what in _EXIT_CODE_LINES:
        _wprint(f"    {code}  {what}")
    print()

def _print_overview():
    print(f"{PROG} v{VERSION} — ReFS forensic analysis tool\n")
    print(f"usage: {PROG} <image> [subcommand] [options]")
    print(f"       {PROG} <image>                 # defaults to `summary`")
    print(f"       {PROG} <image> <cmd> --help    # detailed help for one subcommand")
    print(f"       {PROG} list                    # one-line index of all subcommands\n")
    print("Core subcommands:")
    for k, v in SUBCOMMANDS.items():
        _wprint(f"  {k:12} {v}")
    print("\nSecondary subcommands:")
    for k in FORENSIC_SUBCOMMANDS:
        if k in EXPERIMENTAL_SUBCOMMANDS:
            continue
        _wprint(f"  {k:12} {CMD_HELP[k]['tag']}")
    print("\nExperimental / informational  (suggestive output — corroborate before relying on it):")
    for k in EXPERIMENTAL_SUBCOMMANDS:
        if k in FORENSIC_SUBCOMMANDS:
            _wprint(f"  {k:12} {CMD_HELP[k]['tag']}")
    print()
    for _ln in _output_group_lines():                     # PLAN 10.2 G1
        print(_ln)
    print()
    _wprint(f"{GLOBAL_HELP}\n")
    print("Exit codes (every subcommand):")                     # N359
    for code, what in _EXIT_CODE_LINES:
        _wprint(f"  {code}  {what}")
    print()
    print("Examples (grouped by what you want to do):")
    _EXAMPLE_GROUPS = (
        ("List / inventory", (
            ("files --csv listing.csv",     "full inventory -> CSV"),
            ("find report --regex",         "find files by name (alias of `search`)"),
            ("details /dir/file.txt",       "everything about ONE file (or 0xOID)"),
        )),
        ("Special files", (
            ("specials",                    "count table of every special type"),
            ("specials ads",                "list all files with alternate data streams"),
            ("specials hardlink",           "list hard-linked files, grouped"),
        )),
        ("Get data out", (
            ("export ads \"file:stream\"",    "extract one alternate data stream"),
            ("export resident-all out/",    "dump every file whose data is inline"),
            ("export snapshots out/",       "extract all stream-snapshot versions"),
        )),
        ("Deleted / recovery", (
            ("deleted",                     "list deleted files + a recoverability verdict (slack by default)"),
            ("export deleted out/ --carve", "recover them: an index + content/ + the carved extent data"),
            ("recyclebin",                  "report the Windows $RECYCLE.BIN"),
        )),
        ("Timeline / anomalies", (
            ("timeline --fast --limit 50",  "USN+MLog+$SI merged super-timeline"),
            ("timestomp",                   "flag backdated / anomalous timestamps"),
            ("summary",                     "volume summary (version, checkpoint, flags)"),
        )),
    )
    for title, rows in _EXAMPLE_GROUPS:
        print(f"  {title}:")
        for ex, note in rows:
            _wprint(f"    {PROG} disk.raw {ex:30}  # {note}")                      # PLAN 10.2 A3
    _wprint(f"\n{VERSION_NOTE}")

# Every option that consumes the FOLLOWING token as its value (across argparse + the forensic commands).
# Used so a help token that is actually a value (e.g. `extract --path --help`) is NOT mistaken for a
# help request.
_VALUED_OPTS = {"-o", "--output", "--oid", "--path", "--filter", "--depth", "--partition-start",
                "--cow-before", "--btree-mode", "--csv", "--extract", "--file", "--limit",
                "--margin-days", "--max-pages", "--max-scan", "--min", "--out", "--scan-range",
                "--search", "--sid", "--source", "--tag", "--what"}

def _help_requested(toks):
    """True if -h/--help appears as a real help request — i.e. NOT as the value of a valued option."""
    for i, t in enumerate(toks):
        if t in ("-h", "--help") and not (i > 0 and toks[i - 1] in _VALUED_OPTS):
            return True
    return False

def main():
    # Full-depth walks (4.D / audit 5.3): a modest recursion-limit raise. Real ReFS trees are shallow (corpus max
    # = 40 levels), so this is never hit legitimately; it is kept comfortably C-stack-SAFE (4000, ~100x the corpus
    # max) so a crafted/corrupt tree deeper than this raises a CATCHABLE RecursionError — which walk_directory_tree
    # turns into a clean error — rather than the 40000 setting's outcome on a small C stack: an uncatchable
    # SIGSEGV / rc=137 that converts a reportable error into an unreportable process death.
    sys.setrecursionlimit(max(sys.getrecursionlimit(), 4000))
    utf8_console()                                                                     # N489
    # `--csv-safe` (opt-in spreadsheet formula-injection guard) is a GLOBAL modifier that must apply to every
    # CSV-emitting command (files/usn/timeline/timestomp/mlog/deleted), so detect+strip it here before any
    # dispatch or argparse. Default stays OFF = filenames written byte-faithfully.
    # A bundle is a DIRECTORY; an image is a FILE. The tool already refused a directory outright, so
    # nothing has to be disambiguated -- only added. Resolved here, before either image-validation site,
    # so every downstream path sees an ordinary regular file and no command needs bundle-awareness.
    # `verify-bundle` inspects the bundle ITSELF, so it is handled before argparse and before any
    # auto-open: opening dies on a bad seal, and the point of the command is to REPORT what is wrong.
    # It still honours the shared CLI contract the tier-2 tests freeze -- `help <cmd>` prints help, an
    # unknown flag is diagnosed before the path is read, and a missing path exits 1 saying "not found".
    if len(sys.argv) > 2 and sys.argv[1] == "verify-bundle" and not _help_requested(sys.argv[2:]):
        # PLAN 10.2 G5 (1.14.0): the bundle comes first, as an image does -- argparse printed its whole usage text
        print(f"{PROG}: error: the bundle comes first: {PROG} <bundle-dir> verify-bundle", file=sys.stderr)
        sys.exit(1)                                      # (main's own `die` is defined below; exit 1 as it does)
    if len(sys.argv) > 2 and sys.argv[2] == "verify-bundle":
        _rest = sys.argv[3:]
        if "-h" in _rest or "--help" in _rest or sys.argv[1] in ("help", "-h", "--help"):   # N382: `--help verify-bundle`
            _render_cmd_help("verify-bundle")            # N541 (1.14.0): one text for the three help forms
            sys.exit(0)
        for _a in _rest:
            if _a.startswith("-"):
                print(f"{PROG}: error: unrecognized argument: {_a}", file=sys.stderr); sys.exit(1)
            _stray_argument(_a, 0)          # N147: verify-bundle takes the bundle and nothing else
        if not os.path.exists(sys.argv[1]):
            print(f"{PROG}: error: file not found: {sys.argv[1]}", file=sys.stderr); sys.exit(1)
        sys.exit(rc_escalate(cmd_verify_bundle(sys.argv[1])))
    if len(sys.argv) > 1 and _is_bundle(sys.argv[1]):
        _bundle_open(sys.argv[1])
    global _CSV_GUARD
    if "--csv-safe" in sys.argv:
        _CSV_GUARD = True
        sys.argv = [a for a in sys.argv if a != "--csv-safe"]
    # Global `--partition-start N` works in ANY position: relocate it to the END of argv so a flag placed
    # BEFORE the subcommand (e.g. `IMG --partition-start 0 integrity`) confuses neither the forensic dispatch
    # (which keys on argv[2]) nor argparse (which mishandles an optional between the image/command positionals).
    # No-op when it is already last; only the first occurrence is moved.
    for _pi in range(2, len(sys.argv) - 1):
        if sys.argv[_pi] == "--partition-start":
            sys.argv = sys.argv[:_pi] + sys.argv[_pi + 2:] + [sys.argv[_pi], sys.argv[_pi + 1]]
            break
    _ALL_CMDS = set(SUBCOMMANDS) | set(HIDDEN_SUBCOMMANDS) | set(FORENSIC_SUBCOMMANDS)
    # Resolve a command-token alias (e.g. `find` -> `search`) to canonical BEFORE any dispatch/help, so all
    # downstream (help, argparse, forensic routing) sees the real name. The alias applies to the subcommand
    # token, which is sys.argv[2] (sys.argv[1] is the image).
    # Case-insensitive SUBCOMMAND and OPTION NAMES (values are left exactly as typed — a path, a stream name
    # or a --filter category is case-sensitive data, not a keyword). Normalising here means every downstream
    # consumer — help, argparse, forensic routing — sees the canonical spelling.
    if len(sys.argv) >= 3:
        _lc = sys.argv[2].lower()
        if sys.argv[2] not in _ALL_CMDS and _lc in _ALL_CMDS:
            sys.argv[2] = _lc
        elif sys.argv[2] not in SUBCOMMAND_ALIASES and _lc in SUBCOMMAND_ALIASES:
            sys.argv[2] = _lc
    # Long option NAMES only. A token is skipped when it is the VALUE of a valued option, so a path or a
    # stream name that happens to start with "--" is never touched. Every option whose canonical spelling has
    # capitals (--ID / --OID / --FileRef) also has a lowercase form registered, so lowercasing always lands on
    # a real option.
    for _i in range(2, len(sys.argv)):
        _a = sys.argv[_i]
        if not _a.startswith("--") or _a == "--":
            continue
        if _i > 0 and sys.argv[_i - 1] in _VALUED_OPTS:
            continue                                    # this token is a value, not an option name
        _name, _sep, _val = _a.partition("=")
        if _name.lower() != _name:
            sys.argv[_i] = _name.lower() + _sep + _val if _sep else _name.lower()
    if len(sys.argv) >= 3 and sys.argv[2] in SUBCOMMAND_ALIASES:
        sys.argv[2] = SUBCOMMAND_ALIASES[sys.argv[2]]
    _argv = sys.argv
    # ── help handling (before any dispatch / argparse) ──
    if len(_argv) == 1 or (len(_argv) >= 2 and _argv[1] in ("-h", "--help", "help")):
        if len(_argv) >= 3 and _argv[2] in _ALL_CMDS:
            _render_cmd_help(_argv[2])
        else:
            _print_overview()
        return
    # `forefst <image> help [<cmd>]` → general overview, or targeted per-command help when a command
    # follows (`forefst disk.raw help mlog`, `… help details`). `help` here is the subcommand token
    # (sys.argv[2]); sys.argv[1] is the image. Mirrors the `forefst help <cmd>` (no-image) form above.
    if len(_argv) >= 3 and _argv[2] == "help":
        _hcmd = _argv[3] if len(_argv) >= 4 else None
        if _hcmd in SUBCOMMAND_ALIASES:
            _hcmd = SUBCOMMAND_ALIASES[_hcmd]
        if _hcmd and _hcmd in _ALL_CMDS:
            _render_cmd_help(_hcmd)
        elif _hcmd:
            print(f"[{PROG}] no such subcommand: '{_hcmd}' — showing the overview.\n")
            _print_overview()
        else:
            _print_overview()
        return
    # `forefst <image> [<cmd>] --help/-h` → per-command or overview help (but not when -h/--help is the
    # value of a valued option, e.g. `extract --path --help`)
    if len(_argv) >= 3 and _help_requested(_argv[2:]):
        _cmd = next((a for a in _argv[2:] if a in _ALL_CMDS), None)
        if _cmd:
            _render_cmd_help(_cmd)
        else:
            _print_overview()
        return

    # `forefst list` / `--list` / `-l`: list subcommands (no image needed). The bare word is accepted for the
    # same reason `help` is: a user who types one expects the other to work the same way.
    if len(sys.argv) >= 2 and sys.argv[1] in ("list", "--list", "-l"):
        print(f"{PROG} v{VERSION} — subcommands (usage: {PROG} <image> <subcommand> [options]):\n")
        print("core subcommands:")
        for _k, _v in SUBCOMMANDS.items():
            _wprint(f"  {_k:13} {_v}")
        print("\nsecondary subcommands:")
        for _k, _v in FORENSIC_SUBCOMMANDS.items():
            if _k in EXPERIMENTAL_SUBCOMMANDS:
                continue
            _wprint(f"  {_k:13} {_v}")
        print("\nexperimental / informational subcommands  (suggestive output — corroborate before relying on it):")
        for _k in EXPERIMENTAL_SUBCOMMANDS:
            if _k in FORENSIC_SUBCOMMANDS:
                _wprint(f"  {_k:13} {FORENSIC_SUBCOMMANDS[_k]}")
        print()
        for _ln in _output_group_lines():                 # PLAN 10.2 G1
            print(_ln)
        _wprint(f"\n{VERSION_NOTE}")
        return

    # Delegated forensic subcommands: parse like refsanalysis (raw remaining args + own flags),
    # since they use options argparse doesn't model (--parse/--raw-scan/--no-si/--source/...).
    if len(sys.argv) >= 3 and sys.argv[2] in FORENSIC_HANDLERS:
        image = sys.argv[1]
        subcmd = sys.argv[2]
        remaining = sys.argv[3:]
        part_start = None
        filtered = []
        i = 0
        while i < len(remaining):
            if remaining[i] == "--partition-start":
                if i + 1 >= len(remaining):
                    # audit 2.9: --partition-start IS a known option missing its value — say so, don't let
                    # _parse_args report it as "unknown option". (Exit stays 1, matching the invalid-value
                    # path below; the usage-vs-runtime exit-code contract is a separate, deferred change.)
                    print(f"{PROG}: error: option --partition-start requires a value "
                          f"(a byte offset, e.g. 0 or 0x100000)", file=sys.stderr)
                    sys.exit(1)
                try:
                    part_start = int(remaining[i + 1], 0)
                except ValueError:
                    print(f"{PROG}: error: invalid --partition-start value: {remaining[i + 1]}", file=sys.stderr)
                    sys.exit(1)
                i += 2
            elif remaining[i] == "--verify-pages":
                # A9: a GLOBAL flag, like --partition-start. The forensic subcommands parse their own
                # options and reject anything they do not know, so it is consumed here and armed for all
                # of them -- otherwise `extract --verify-pages` would die with "unknown option".
                _arm_page_verification()
                i += 1
            else:
                filtered.append(remaining[i]); i += 1
        if not os.path.exists(image):
            print(f"{PROG}: error: file not found: {image}", file=sys.stderr); sys.exit(1)
        if not os.path.isfile(image):
            print(f"{PROG}: error: not a regular file: {image}", file=sys.stderr); sys.exit(1)
        # G3: the delegated subcommands took a different route from the native ones and never printed the
        # opening banner, so the tool version was invisible on 14 of the 20 commands. stderr only (as on the
        # native path), so piped stdout / --csv output is unaffected.
        if not ({"-q", "--quiet"} & set(remaining)):          # match the native path, which honours -q
            print(f"[{PROG} v{VERSION}] Opening {_display_image(image)}...", file=sys.stderr)   # N275
        # audit 2.8: do NOT validate the image here. The handler parses its own flags FIRST (via _parse_args /
        # _check_unknown_flags), so a typo'd flag is reported before the image is read; its bootstrap() then
        # validates/aborts with the SAME clean ValueError the `files` path already surfaces (audit 2.3 — one
        # acceptance policy, one error message, for every command). Mirror the argparse path's catch.
        try:
            sys.exit(rc_escalate(FORENSIC_HANDLERS[subcmd](image, filtered, part_start)))
        except BrokenPipeError:
            raise           # N194 (widened): a closed stdout is N171's quiet exit 0 (`__main__`), not an image error
        except ValueError as e:
            print(f"{PROG}: error: {e}", file=sys.stderr); sys.exit(1)
        except OSError as e:
            print(f"{PROG}: error: {_oserror_text(e, image)}", file=sys.stderr); sys.exit(1)

    ap = _UsageExit1Parser(prog=PROG,
                           description="ReFS forensic file lister",
                           epilog=VERSION_NOTE)
    ap.add_argument("--version", action="version", version=f"forefst.py v{VERSION} — ReFS forensic file lister")
    ap.add_argument("image", help="Path to disk image")
    ap.add_argument("command", nargs="?", choices=list(SUBCOMMANDS) + list(HIDDEN_SUBCOMMANDS), default=None,
                    help="subcommand (default: summary); run `forefst --list` to see all")
    ap.add_argument("target", nargs="?", default=None,
                    help="search PATTERN, or details /path | 0xOID")
    ap.add_argument("-o", "--output", help="Output file (default: stdout); or use --csv/--json/--jsonl FILE")
    ap.add_argument("--body", nargs="?", const="-", metavar="FILE",
                    help="files: body-file (mactime) output; bare = stdout, or give a FILE")
    ap.add_argument("--csv-safe", action="store_true",
                    help="CSV output: prefix a cell starting with = + - @ with a quote to neutralise spreadsheet "
                         "formula injection. OFF by default so filenames are written byte-faithfully; enable this "
                         "only if you will open the CSV in Excel/LibreOffice (applies to all CSV-emitting commands)")
    # --csv/--json/--jsonl now accept an OPTIONAL FILE (bare = stdout, `--json FILE` = write file + count),
    # standardizing files/summary/search/details with the forensic commands. Put the search/details TARGET
    # BEFORE these flags (`search foo --json`), so the pattern isn't consumed as the format's FILE.
    ap.add_argument("--csv", nargs="?", const="-", default=None, metavar="FILE",
                    help="CSV output to stdout, or to FILE")
    ap.add_argument("--json", nargs="?", const="-", default=None, metavar="FILE",
                    help="JSON output (array) to stdout, or to FILE")
    ap.add_argument("--jsonl", nargs="?", const="-", default=None, metavar="FILE",
                    help="JSON Lines output to stdout, or to FILE")
    ap.add_argument("--hash-image", action="store_true",
                    help="summary: include SHA-256 hash of the full disk image")
    # PLAN section 10.2 A1 (1.14.0): `summary` reads the MLog only when asked (`--mlog`, or `-v`)
    ap.add_argument("--mlog", action="store_true", help="summary: also read the MLog (one pass over the log)")
    ap.add_argument("-v", "--verbose", action="store_true", help="summary: the same as --mlog")
    ap.add_argument("--path", default=None,
                    help="details: address the object by path (e.g. /dir/file.txt)")
    ap.add_argument("--id", "--ID", "--FileRef", "--fileref", "--oid", "--OID", dest="id", default=None,
                    help="details/export: address the object by identity — an OID (e.g. 0x703) or a FileRef "
                         "HomeOID:FileID (e.g. 0x703:0x2e). --FileRef/--OID are aliases of --id.")
    ap.add_argument("--regex", action="store_true",
                    help="search: treat PATTERN as a regular expression")
    ap.add_argument("--filter", default=None, metavar="CATEGORY",
                    help="files: subset by attribute category — " + "/".join(FILE_FILTERS))
    ap.add_argument("--depth", type=int, default=DEFAULT_DEPTH, help="Max directory recursion depth (default: full)")
    ap.add_argument("--partition-start", type=lambda x: int(x, 0), default=None,
                    help="Override partition start offset in bytes")
    ap.add_argument("--cow-before", metavar="IMAGE",
                    help="files: an earlier image of the same volume -- output the comparison of the two images")
    ap.add_argument("--cow-partition-start", type=lambda x: int(x, 0), default=None,
                    help="files: partition offset for the --cow-before image (default: auto-detect its own "
                         "GPT). C16: use when the before-image has a DIFFERENT layout than the main image "
                         "(otherwise both auto-detect). NOTE: the CoW-recovery path is lightly tested.")
    ap.add_argument("--verify-pages", action="store_true",
                    help="Check every metadata page read against the digest in its parent page reference "
                         "(Merkle chain). SLOWER: about 1.3x on a command that walks the tree — measured on a "
                         "real Windows installation, `files` 113 s -> 141 s and `summary` 98 s -> 128 s; commands "
                         "that do not walk the tree are unaffected. Off by default; without it no page "
                         "digest is checked, and nothing in the output claims one was.")
    ap.add_argument("-q", "--quiet", action="store_true", help="Suppress progress to stderr")
    # WE-5 (N496, 1.14.0): a stray word is refused by the one rule (`_stray_argument`) whatever its place --
    # `files --csv a.csv extra` got argparse's "unrecognized arguments" and a usage dump, `files extra --csv a.csv`
    # the one rule's message. An unknown OPTION is still argparse's error.
    args, _extra = ap.parse_known_args()
    _unknown_opts = [a for a in _extra if a.startswith("-") and a != "-"]
    if _unknown_opts:
        ap.error("unrecognized arguments: %s" % " ".join(_unknown_opts))
    if args.command is None:
        # Phase 3 (4.A): a bare `forefst <image>` gives the volume SUMMARY (orientation first); run
        # `forefst <image> files` for the full CSV listing.
        args.command = "summary"
    if args.command != "summary" and (args.mlog or args.verbose):
        # PLAN section 10.2 A1 (1.14.0): --mlog and -v are `summary`'s; another native command refuses them as it
        # refused them before they existed (argparse's message, exit 1). Review F6: decided from the PARSED values, so
        # an abbreviation (--ml, --verb), a combined flag (-qv) or an option before the image is refused too, and a
        # search for the name "-v" after "--" is not
        _given = [t for t in sys.argv[1:] if t == "--" or t.startswith("--ml") or t.startswith("--verb")
                  or (t.startswith("-") and not t.startswith("--") and "v" in t[1:])]
        _given = _given[:_given.index("--")] if "--" in _given else _given
        ap.error("unrecognized arguments: %s" % (" ".join(_given) or ("--mlog" if args.mlog else "-v")))
    if args.target is not None and args.command not in ("details", "search"):
        _stray_argument(args.target, 0)     # N147 (1.14.0): `files extra` listed the volume and exited 0
    if _extra:
        _stray_argument(_extra[0], 1 if args.command in ("details", "search") else 0)       # WE-5

    def log(msg):
        if not args.quiet:
            print(msg, file=sys.stderr)

    def die(msg):
        print(f"{PROG}: error: {msg}", file=sys.stderr)
        sys.exit(1)

    # A9. Arming this is what makes every metadata page read get checked against its parent's digest.
    # The warning is printed BEFORE the work starts, not after: a user who did not expect a minute of
    # CRC should be able to stop it, and one who did should see that it is running.
    if args.verify_pages:
        _arm_page_verification()

    # Output format mutual exclusion (--csv/--json/--jsonl accept an optional FILE, so they are None-or-str)
    fmt_count = sum(1 for v in (args.body, args.csv, args.json, args.jsonl) if v is not None)
    if fmt_count > 1:
        die("--csv, --json, --jsonl and --body are mutually exclusive")
    # N162 (1.14.0): a format the command does not write is refused -- `summary --csv FILE`, `search --body` and
    # `details --body` printed the text, wrote nothing and exited 0 -- and so is `-o FILE` where it names nothing:
    # `-o` is the destination of the selected machine format, and summary, search and details print text by default
    _fmts = _NATIVE_FORMATS.get(args.command, ())
    for _n in ("csv", "json", "jsonl", "body"):
        if getattr(args, _n, None) is not None and _n not in _fmts:
            die(f"`{args.command}` has no --{_n} output; it writes text, or " + " / ".join("--" + x for x in _fmts))
    if getattr(args, "output", None) and not fmt_count and args.command in _NATIVE_TEXT_DEFAULT:
        die(f"-o FILE names where a machine format goes, and `{args.command}` writes text by default: give the "
            f"format and its file (`{args.command} --json FILE`), or redirect the text (`> FILE`)")

    # Input validation
    if not os.path.exists(args.image):
        die(f"file not found: {args.image}")
    if not os.path.isfile(args.image):
        die(f"not a regular file: {args.image}")
    if args.depth < 1:
        die(f"--depth must be >= 1 (got {args.depth})")
    if args.partition_start is not None and args.partition_start < 0:
        die(f"--partition-start must be >= 0 (got {args.partition_start})")
    if args.cow_before:
        if not os.path.isfile(args.cow_before):
            die(f"--cow-before: file not found: {args.cow_before}")
        if os.path.abspath(args.cow_before) == os.path.abspath(args.image):
            die("--cow-before image must be different from the main image")
        if args.command != "files":
            die("--cow-before is only valid with the 'files' subcommand")
        if getattr(args, "body", None) is not None:
            die("--cow-before writes the comparison as CSV, JSON or JSONL, not a bodyfile")
    # -o/--output on a LISTING command means "write the current format here", so the same flag produces CSV,
    # JSON or a bodyfile depending on other flags — the format is invisible at the call site, which is why
    # each format now carries its own destination (`--csv FILE`, `--json FILE`, ...). Refusing -o outright
    # was the wrong correction: it broke every documented example and every script that used it, against a
    # release note promising the old spellings keep working. It is accepted as an alias for the selected
    # format's destination (CSV by default) -- `_resolve_out_fmt` already implements exactly that -- with a
    # deprecation note, and a warning when it is given ALONGSIDE an explicit destination, where it is ignored.
    if getattr(args, "output", None) and args.command in SUBCOMMANDS:
        _explicit = next((f"--{n} {v}" for n, v in (("csv", getattr(args, "csv", None)),
                                                    ("json", getattr(args, "json", None)),
                                                    ("jsonl", getattr(args, "jsonl", None)),
                                                    ("body", getattr(args, "body", None)))
                          if isinstance(v, str) and v not in ("", "-")), None)
        if _explicit:
            print(f"[{PROG}] WARNING: both `{_explicit}` and `-o {args.output}` given — the format flag's "
                  f"destination wins and -o is ignored.", file=sys.stderr)
        else:
            _sel = next((n for n in ("json", "jsonl", "body", "csv") if getattr(args, n, None) is not None), "csv")
            print(f"[{PROG}] note: -o/--output is deprecated for `{args.command}`; it still works and writes "
                  f"the selected format. Prefer naming the format's own destination: "
                  f"`{PROG} <image> {args.command} --{_sel} {args.output}`.", file=sys.stderr)   # N162: the format given
    # Subcommand flag scoping (clean break: these belong to specific subcommands)
    if (args.id is not None or args.path) and args.command != "details":
        die("--oid/--path are only valid with the 'details' subcommand")
    if args.filter is not None:
        if args.command not in ("files", "search"):
            die("--filter is only valid with the 'files' or 'search' subcommand")
        if args.cow_before:
            die("--filter and --cow-before do not combine: --cow-before compares every object of the two images")
        if args.filter == "resident":
            # N161: the word the user typed is echoed, not tool vocabulary
            die(f"--filter: the category {args.filter!r} was removed in 1.14.0 -- use 'inline' (the files whose data "
                "is inline in the record, DataResidency inline)")
        if args.filter not in FILE_FILTERS:
            die(f"--filter: unknown category {args.filter!r}. Choices: {', '.join(sorted(FILE_FILTERS))}")

    # Help-on-empty (4.C): a bare `details` (no target/OID/path/id) shows its help instead of opening the image.
    if args.command == "details" and args.target is None and not args.path and not args.id:
        # audit 2.12: when a MACHINE format was explicitly requested, a missing target is a usage error, not
        # help. Help-on-stdout is invalid JSON in a pipe AND exits 0 (a silent pipeline failure); instead emit
        # the error to stderr and exit non-zero (the existing error convention — the usage-vs-runtime exit-code
        # split is the separately-deferred change). The friendly help stays for the interactive case.
        if any(getattr(args, _f, None) is not None for _f in ("json", "jsonl", "csv")):
            die("details: a target is required (a /path, --oid, or --id) when --json/--jsonl/--csv is requested")
        _render_cmd_help("details")
        return

    # Bootstrap
    log(f"[{PROG} v{VERSION}] Opening {_display_image(args.image)}...")   # A1: version on the first line; N275
    try:
        f, ps, cs, tr, roots, obj_map, vmaj, vmin, chkp_lcns = bootstrap(args.image, args.partition_start)
    except ValueError as e:
        die(str(e))
    except OSError as e:
        die(f"cannot read image: {e}")
    if args.cow_before and args.command == "files":
        _cow_same_volume(f, ps, cs, args.cow_before, args.cow_partition_start)    # E-6: refused before any walk
    version_str = f"{vmaj}.{vmin}"
    usn_active = False
    _usn_unknown = False
    _usn_why = "could not read the system metadata tree"
    if 0x520 in obj_map:
        _dmg0, _skp0 = _walk_damage_count(), len(_SKIP_FINDING)    # N336: the monotonic count, not the capped list
        try:
            for kd, _vd in walk_bplus(f, ps, cs, tr, obj_map[0x520], oid=0x520):
                if len(kd) >= 4 and le16(kd, 0) == 0x30:
                    nm = _row_name(kd, "USN presence check")
                    if nm is None:
                        _usn_unknown = True          # a name we could not read may be the one we look for
                    elif nm == "Change Journal":
                        usn_active = True
                        break
        except Exception as _e:
            # "no USN" and "could not look" printed the same banner. The banner is the first thing an
            # examiner reads about the volume, so it now says which of the two this is.
            _skip_note("USN presence check", "system metadata tree", _e)
            _usn_unknown = True
        # N246: a zeroed root page raises nothing -- the walk records it and returns no rows
        if not usn_active and (_walk_damage_count() > _dmg0 or len(_SKIP_FINDING) > _skp0):
            _usn_unknown = True
    else:
        # N246: no OID 0x520 in the object map -- nothing was there to read, so the state is not known either
        _usn_unknown = True
        _usn_why = ("the object map is incomplete and holds no system metadata table" if _metadata_incomplete()
                    else "no system metadata table in the object map")
    usn_tag = (" | USN: active" if usn_active
               else (" | USN: unknown (%s)" % _usn_why if _usn_unknown else ""))
    log(f"[{PROG}] ReFS {version_str} | {count_noun(len(obj_map), 'object')} | cluster_size={cs}{usn_tag}")
    if (vmaj, vmin) < (3, 14):
        log(f"[{PROG}] note: ReFS {version_str} (<3.14) — some enriched fields may be incomplete (see --list)")

    # summary / fastsummary subcommands (both extended-by-default)
    if args.command in ("summary", "fastsummary"):
        is_fast = (args.command == "fastsummary")
        is_plus = True
        log(f"[{PROG}] Running {'fast ' if is_fast else ''}summary...")
        # `plus_mode` is True for BOTH commands, so it cannot gate this: the page-reference verification
        # belongs to `summary` only. It reads ~385 metadata pages, which took `fastsummary` from 0.36 s to
        # 36.70 s on a real Windows volume -- a 100x regression on the command whose contract is speed.
        # N306 (1.14.0): one builder for the document, so refsanalysis `summary` states the same facts (it builds on it)
        fast_data, _red, walk_summary, combined = summary_document(
            f, ps, cs, tr, roots, obj_map, vmaj, vmin, chkp_lcns, args.image, is_fast=is_fast, plus=is_plus,
            depth=args.depth, hash_image=args.hash_image, log=log, mlog=bool(args.mlog or args.verbose))
        if is_fast:
            if args.json is not None:
                _emit_json_obj(fast_data, _native_fmt_dest(args)[1], "fast summary", keys=_SUMMARY_KEYS)
            else:
                _print_fastsummary(fast_data, plus_mode=is_plus)
                _print_redundancy_findings(_red)
            if _red:
                _REDUNDANCY_FINDING.extend(_red)
            f.close()
            return
        if args.json is not None:
            _emit_json_obj(combined, _native_fmt_dest(args)[1], "summary", keys=_SUMMARY_KEYS)
        else:
            _print_summary(walk_summary, fast_data, plus_mode=is_plus)
            _print_redundancy_findings(_red)
            print("=" * 78)                              # PLAN 10.2 A10: `summary` ends as it begins
        if _red:
            _REDUNDANCY_FINDING.extend(_red)
        f.close()
        return

    # details subcommand — inspect ONE object by OID, path, or reference (--id HomeOid:FileId)
    if args.command == "details":
        det_oid, det_path = None, None
        # Two ways in: by PATH or by IDENTITY. `--id` (aliases --oid/--OID/--FileRef) takes either an OID or a
        # FileRef, so there is no longer a separate --oid flag to confuse with it.
        if args.id is not None and args.path:
            die("details: give --id (or --oid/--FileRef) OR --path, not both")
        if args.target is not None and (args.id is not None or args.path):
            die("details: give a target OR --id/--path, not both")
        if args.id is not None:
            _hoid, _fid = _parse_id_ref(args.id)
            if _fid == 0:
                det_oid = _hoid
            else:
                _ent = _resolve_id_entry(f, ps, cs, tr, obj_map, _hoid, _fid)
                if _ent is None:
                    _not_found_exit(f, f"no object for --id {args.id}")           # N339: exit 2 after a skip
                det_path = _ent["path"]
        elif args.path:
            det_path = args.path
        elif args.target is not None:
            t = args.target
            if t.startswith("/"):
                det_path = t
            elif t[:2].lower() == "0x":
                try:
                    det_oid = int(t, 16)
                except ValueError:
                    die(f"details: invalid OID {t!r}")
            else:
                die("details: target must start with '/' (path) or '0x' (OID), or use --path/--oid")
        else:
            die("details: provide a /path, a 0xOID, or --path/--oid")
        if det_oid is None:
            # path mode: a directory has its own OID (-> OID detail below); a FILE has none, so we
            # show its full record (F6) by walking to the matching entry (full enrichment, consistent
            # with `files`). Sub-directories keep the richer OID/$SI view.
            _poid, _pkd, _pvd = resolve_path(f, ps, cs, tr, obj_map, det_path)
            if _pkd is None:
                _not_found_exit(f, f"path not found: {det_path}")           # N348
            # A directory is ALWAYS non-resident (value <= 84 B) with the dir-bit at value+0x40.
            # A resident entry (>84 B) is always a FILE — its +0x40 is access_time, not file_attrs,
            # so the dir-bit must NOT be tested there (that mis-routed resident files as dirs).
            if (len(_pvd) <= NON_RESIDENT_MAX_VALUE and len(_pvd) >= 0x44
                    and (le32(_pvd, 0x40) & 0x10000000)):
                det_oid = le64(_pvd, 0x08)
            else:
                # FILE by path (F6): find the enriched entry in the walk, print/JSON its detail.
                log(f"[{PROG}] Resolving file {det_path}...")
                results = walk_directory_tree(f, ps, cs, tr, obj_map, 0x600, args.depth, True)
                # B9 (c) (1.14.0): the walk record of the row resolve_path RESOLVED (its directory and its own name),
                # not of the typed string -- a path typed in another letter case, or with '//' or '/./', which
                # resolve_path accepts, matched no record; and on a case-sensitive directory the exact name, never a
                # sibling that differs only by case (resolve_path's own rule, E94)
                _rname = _row_name(_pkd, "details") if _pkd is not None and len(_pkd) > 4 else None
                match = next((r for r in results if not r.get("is_dir") and r.get("parent_oid") == _poid
                              and r.get("name") == _rname), None)
                if match is None:
                    _not_found_exit(f, f"path not found: {det_path}")       # N348
                _journal_moves_said(f, ps, cs, tr, obj_map, results, log,    # D3b: IsMoved as `files` reads it
                                    args.depth >= DEFAULT_DEPTH)
                sd_map = build_security_map(f, ps, cs, tr, obj_map)
                oid2path = _build_oid2path(results)   # CreationDir (HomeOID → path), same as `files`
                # EA source: an EMBEDDED record's value carries its $EA sub-records; a SPLIT record's EAs are in its
                # type-0x40 backing (fetched by home/parent + file_id). B9 (c): by the record's placement -- the raw
                # `is_resident` flag ("embedded AND inline") sent an embedded record whose data is in extents to the
                # backing fetch
                if _record_placement(match) == "embedded":
                    ea_src = _pvd
                else:
                    _fsz = match.get("file_size")
                    ea_src = (fetch_t40_backing(f, ps, cs, tr, obj_map, match.get("home_oid") or 0, match.get("file_id") or 0, _fsz)
                              or fetch_t40_backing(f, ps, cs, tr, obj_map, match.get("parent_oid") or 0, match.get("file_id") or 0, _fsz))
                if args.json:
                    rec = _build_record(match, sd_map, version_str, oid2path)
                    eas, packed = extract_eas_from_value(ea_src) if ea_src is not None else (None, None)
                    # N303 (1.14.0): the `files` record (O7: the CSV row, typed) and, after it, what `details` adds --
                    # the EA list, PackedEaSize, the WSL metadata, the file's own journal id
                    if eas is not None:
                        rec["PackedEASize"] = packed
                        # oracle gate (see _print_file_detail): only emit the list/WSL when it reconciles.
                        if sum(5 + len(e["name"]) + len(e["value"]) for e in eas) == packed:
                            rec["ExtendedAttributes"] = [{"Name": e["name"], "Length": len(e["value"]),
                                                          "ValueHex": e["value"].hex()} for e in eas]
                            wsl = decode_wsl_eas(eas)
                            if wsl:
                                wj = dict(wsl)
                                if "mode" in wsl: wj["mode_decoded"] = decode_lx_mode(wsl["mode"])
                                rec["WSL"] = wj
                        else:
                            rec["ExtendedAttributes"] = None
                    if match.get("usn_journal_id"):
                        # N195: the file's own journal id, as `details` prints it (a `details` field: the `files`
                        # CSV and its JSON carry no journal-id column -- decision 30 keeps the CSV columns)
                        rec["USNJournalID"] = "0x%016x" % match["usn_journal_id"]
                    _emit_json_obj(rec, _native_fmt_dest(args)[1], "record")
                elif args.csv is not None or args.jsonl is not None:
                    # D7: one row in the `files` schema — same columns, so a details row can sit alongside a
                    # files export without reshaping.
                    _fmt = "csv" if args.csv is not None else "jsonl"
                    _dest = _native_fmt_dest(args)[1]
                    _row = _csv_fields(match, sd_map, version_str, oid2path)
                    _emit_records([_row], CSV_COLUMNS, _fmt, _dest or "-", "record")
                else:
                    _print_file_detail(match, sd_map, version_str, raw_value=ea_src, oid2path=oid2path)
                f.close()
                return
        log(f"[{PROG}] Looking up OID 0x{det_oid:x}...")
        # Resolve the directory's own path so its detail can lead with the same identity block a file gets.
        try:
            _oid_path = build_oid_path_map(f, ps, cs, tr, obj_map).get(det_oid)
        except Exception:
            _oid_path = None
        try:
            _oid_sd = build_security_map(f, ps, cs, tr, obj_map)   # so a directory resolves owner/group too
        except Exception:
            _oid_sd = None
        detail = cmd_oid_detail(f, ps, cs, tr, obj_map, vmaj, vmin, det_oid, log_fn=log)
        if detail is None and det_oid not in obj_map:
            # N427 / N445's class: an OID missing from an Object Table read in part is not determined (exit 2); "not
            # found in object table" only when the table was read in full
            _u = object_lookup_undetermined(obj_map, det_oid)
            if _u is not None:
                f.close()
                sys.exit(2)
        if detail is None:
            print(f"OID 0x{det_oid:x} not found in object table ({count_noun(len(obj_map), 'object')}).", file=sys.stderr)
            print("Use `forefst <image> search <name>` to find files by name.", file=sys.stderr)
            f.close()
            sys.exit(1)
        if "error" in detail:
            print(f"Error reading OID 0x{det_oid:x}: {detail['error']}", file=sys.stderr)
            f.close()
            sys.exit(1)
        if args.json is not None:
            # N303 (1.14.0): the directory's identity first, as the text view leads with it (ObjectRef, the path, the
            # owner, group and DACL, the number of names), then the on-disk structure
            _sid = None
            try:
                _sid = int(str(((detail.get("attributes", {}).get("0x10", {}).get("entries") or [{}])[0].get("si")
                                or {}).get("security_id") or ""), 0)
            except ValueError:
                _sid = None
            _sdv = ((_oid_sd or {}).get(_sid) or ("", "", "")) if _sid else ("", "", "")
            _ident = {"ObjectRef": "0x%x:0x0" % det_oid, "FullPath": _oid_path or "",
                      "IsDirectory": True, "OwnerSid": _sid_display(_sdv[0]), "GroupSid": _sid_display(_sdv[1]),
                      "DACLSummary": _sdv[2],
                      "ChildEntries": detail.get("attributes", {}).get("0x30", {}).get("count")}
            _emit_json_obj(dict(_ident, **{"Structure": detail}), _native_fmt_dest(args)[1], "detail")
        elif args.csv is not None or args.jsonl is not None:
            # D7: a directory row in the `files` schema, so --csv/--jsonl mean the same thing for a directory
            # as for a file. Resolved from the same walk `files` uses, rather than reshaping the structural
            # detail, so every column is populated identically.
            _fmt = "csv" if args.csv is not None else "jsonl"
            _res = walk_directory_tree(f, ps, cs, tr, obj_map, 0x600, args.depth, True)
            _journal_moves_said(f, ps, cs, tr, obj_map, _res, log,          # D3b: IsMoved as `files` reads it
                                args.depth >= DEFAULT_DEPTH)
            _m = next((r for r in _res if r.get("is_dir") and r.get("oid") == det_oid), None)
            if _m is None:
                print(f"OID 0x{det_oid:x} is not a directory in the tree — use --json for its structure.",
                      file=sys.stderr); f.close(); sys.exit(1)
            _row = _csv_fields(_m, _oid_sd or {}, version_str, _build_oid2path(_res))
            _emit_records([_row], CSV_COLUMNS, _fmt, _native_fmt_dest(args)[1] or "-", "record")
        else:
            _print_oid_detail(detail, path=_oid_path, sd_map=_oid_sd)
        f.close()
        return

    # search subcommand
    if args.command == "search":
        pattern = args.target
        if not pattern:
            die("search: provide a PATTERN (forefst <image> search PATTERN)")
        log(f"[{PROG}] Searching for \"{pattern}\"...")
        # Deleted/Trash objects are surfaced by the `deleted` command (use `deleted --search PATTERN`);
        # `search` covers the live tree only.
        matches = cmd_search(f, ps, cs, tr, obj_map, vmaj, vmin, pattern,
                             regex_mode=args.regex, filter_cat=args.filter)
        if isinstance(matches, dict) and "error" in matches:
            print(matches["error"], file=sys.stderr)
            f.close()
            sys.exit(1)
        _sfmt, _sdest = _native_fmt_dest(args)
        if args.json is not None or args.jsonl is not None or args.csv is not None:
            # N302 (1.14.0): one column list in every format, `files`' names and values -- ObjectRef first (the value
            # `details --id` takes), the data residency word, both times (the CSV had no name, created time or
            # residency word, only the retired is_resident; JSON dumped the match dict)
            _rows = [{"ObjectRef": m["id"], "FullPath": m["path"], "FileName": m["name"],
                      "IsDirectory": m["type"] == "Dir", "FileSize": m["file_size"],
                      "DataResidency": "" if m["type"] == "Dir" else m["data"], "Created": m["created"] or "",
                      "Modified": m["modified"] or "", "ParentOID": m["parent_oid"] or ""} for m in matches]
            _emit_records(_rows, SEARCH_COLUMNS, _sfmt, _sdest or "-", "matches")
        else:
            _print_search(matches, pattern)
        f.close()
        return

    # Build security descriptor map — always: SecurityId->Owner SID is part of the standard listing now
    # (the former --enrich-only resolution is unconditional; see walk_directory_tree enrichment).
    log(f"[{PROG}] Building security descriptor map...")
    sd_map = build_security_map(f, ps, cs, tr, obj_map)
    _sd_st, _sd_txt = object_absent_text(obj_map, 0x530, "Security descriptors") \
        if 0x530 not in obj_map else (None, None)
    if _sd_st is not None:
        # N358 (Q11): the table was not read because the Object Table was read in part -- not "0 ... loaded"; an
        # evidence statement, so not silenced by -q (the progress line it replaces is)
        print(f"[{PROG}] {_sd_txt}", file=sys.stderr)
    else:
        log(f"[{PROG}] {count_noun(len(sd_map), 'security descriptor')} loaded")
    if 0x530 in _OBJ_ROOT_FAILED:
        # RC3 F4 (1.14.0; decision 72, option 2): the values are kept -- they are what the page holds now -- and the
        # listing says where they come from; the finding (verify_object_root) makes the exit 2. Not silenced by -q.
        print(f"[{PROG}] the security table's root page (object 0x530) does not match the digest the Object Table "
              f"recorded for it: SecurityId, OwnerSid, GroupSid and DACLSummary in this listing come from that page",
              file=sys.stderr)

    # Deleted-file recovery lives solely in the `deleted` command; the files listing walks the LIVE tree only (N555,
    # 1.14.0: an object waiting in the Trash is out of its directory already, so the walk cannot mark one)

    # Walk directory tree
    log(f"[{PROG}] Walking directory tree...")
    results = walk_directory_tree(f, ps, cs, tr, obj_map, 0x600, args.depth, True)
    ndirs = sum(1 for r in results if r["is_dir"])
    nfiles = sum(1 for r in results if not r["is_dir"])
    # C1/K096: this line counted `is_resident` -- the walk's RECORD-PLACEMENT flag -- while `summary`,
    # `files --csv` and `search` all report DATA residency under the very same words. On lab314_main that
    # printed "4041 inline + 627 extent-backed" here against "4049 + 619" everywhere else: two correct
    # answers to two DIFFERENT questions (E87/E88 -- a move or a hard link flips placement and never
    # touches where the bytes are), shown as one question with two answers. It now uses the same helper
    # the CSV column does, so the surfaces cannot drift apart again.
    # C3 / N149 (1.14.0): the files counted once each, by every residency category (the not-inline ones were all
    # called extent-backed), and the names this listing has a row for. The hard-link/special counts go on their own
    # line below so nothing looks like a partition it isn't.
    _pf = _one_row_per_file(results)
    _rc = collections.Counter(_data_residency(r) for r in _pf)
    log(f"[{PROG}] {count_noun(ndirs, 'dir')}, {count_noun(len(_pf), 'file')}" + (f" under {count_noun(nfiles, 'name')}" if nfiles != len(_pf) else "")
        + f" ({residency_counts_text(_rc)})"
        + (" -- counted over the metadata that could be read" if _metadata_incomplete() else ""))     # C1-9 (d)
    # Special-file categories — SAME predicates as `specials` (A3 consistency), so the counts always agree.
    _spc = {name: sum(1 for r in results if pred(r)) for name, _d, pred in SPECIALS_TYPES}
    _hlg = len({tuple(sorted(r.get("hard_link_names") or [f"oid:{r.get('oid')}"]))
                for r in results if r.get("hard_link_count", 1) > 1})
    # E1 close (review RE1-8; N277's form): each category in objects, with its names when a hard link makes them more --
    # the bare counts were names (ADS 254 where `summary` and `specials` say 123 objects)
    def _on(name):
        o, n, _d = _objects_and_names([r for r in results if _SPECIALS_BY_NAME[name][2](r)])
        return count_noun(o, "object") + (" (%s)" % count_noun(n, "name") if n != o else "")       # N596
    log(f"[{PROG}] hard-linked: {count_noun(_hlg, 'file')} sharing {_spc['hardlink']} names · ADS: {_on('ads')}"
        f" · reparse: {_on('reparse')} · WSL: {_on('wsl')} · sparse: {_on('sparse')}"
        f" · encrypted: {_on('encrypted')} · compressed: {_on('compressed')}"
        f" · integrity: {_on('integrity')} · EA: {_on('ea')} · snapshots: {_on('snapshot')}")
    # D3b (decision 51): IsMoved read from the change journal where it decides (`_journal_moves`)
    _journal_moves_said(f, ps, cs, tr, obj_map, results, log, args.depth >= DEFAULT_DEPTH)

    # E-6 (1.14.0): with --cow-before, the output is the comparison of the two images (`cow_compare`), not the listing
    if args.cow_before:
        _complete = not _walk_damage_count() and not _SKIP_FINDING and not _WALK_UNWALKED
        _rows, _lines = cow_compare(f, ps, cs, results, _complete, args.cow_before, args.cow_partition_start,
                                    args.depth, chkp_lcns)
        for _l in _lines:
            print(f"[{PROG}] {_l}", file=sys.stderr)
        fmt, dest = _native_fmt_dest(args)
        _emit_records(_rows, COW_COLUMNS, fmt, dest or "-", "differing objects")
        f.close()
        return

    # F13: --filter — subset the listing by attribute category (after deleted/CoW so the filter
    # applies to the full set). Output stays the normal files format, just the matching rows.
    if args.filter:
        _pred = FILE_FILTERS[args.filter]
        results = [r for r in results if _pred(r)]
        log(f"[{PROG}] --filter {args.filter}: {count_noun(len(results), 'matching entry', 'matching entries')}")

    # Output — --csv/--json/--jsonl [FILE] (bare=stdout), --body, or -o; resolved uniformly.
    fmt, dest = _native_fmt_dest(args)
    _pf, _close = _native_out(dest)
    out = _pf.fh if _close else _pf
    _ok = False
    try:
        if fmt == "body":
            emit_body(results, out)
        elif fmt == "json":
            emit_json(results, sd_map, version_str, out)
        elif fmt == "jsonl":
            emit_jsonl(results, sd_map, version_str, out)
        else:
            emit_csv(results, sd_map, version_str, out)
        _ok = True
    except Exception as _e:
        _stream_failed(_e, dest)
        raise
    finally:
        if _close:
            _pf.close(_ok)
        f.close()

    if dest:
        # A3/K039: an EMPTY listing produced over metadata the tool could not read is a READ FAILURE, not
        # an empty volume -- and "Wrote 0 entries" states the second. On a volume whose Object-ID root
        # page had been zeroed this line was the headline result, with the damage note far below it in
        # the log stream. Say it on the line that carries the count.
        # N336 widened: the number recorded, not the list's length (which stops at 500); N368: distinct pages
        if not results and _walk_damage_count():
            # Lead with the failure: a line that OPENS with a count reads as a successful empty result
            # no matter what follows it.
            print(f"LISTING FAILED — 0 entries written to {dest}: {_walk_damage_pages()} metadata "
                  f"page(s)/table(s) could not be read, so this is NOT an empty volume. See the warnings "
                  f"below for what was unreadable.")
        elif _walk_damage_count():
            print(f"Wrote {count_noun(len(results), 'entry', 'entries')} to {dest} — INCOMPLETE: {_walk_damage_pages()} metadata "
                  f"page(s)/table(s) could not be read, so entries may be missing.")
        else:
            print(f"Wrote {count_noun(len(results), 'entry', 'entries')} to {dest}")
    log(f"[{PROG}] Done. {count_noun(len(results), 'entry', 'entries')} -> {fmt.upper()} {dest or '(stdout)'}")

def _escalation_registers():
    """N360 (1.14.0): THE registers the exit rule escalates on -- one list, read by `rc_escalate`, by
    `_escalation_texts` (which names them) and by `integrity`'s verdict, so a register added here is in all three (a
    second list in `_escalation_texts` could miss one and say a generic line, and `integrity` could print PASS with
    exit 2)."""
    return (_FINDINGS, _SKIP_FINDING, _WALK_DAMAGE, _REDUNDANCY_FINDING, _CHKP_STALE, _JOURNAL_TAIL_DESTROYED,
            _VERSION_CONTRADICTED, _SUPB_FELL_BACK)


def rc_escalate(rc):
    """THE exit rule (A11: single_source.tsv row `rc_escalate`): every command's exit code passes through
    here, in forefst.py and in refsanalysis.py (which imports it). check_single_source.py fails on any
    `sys.exit(<non-constant>)` that does not, and on a `__main__` block that drops main()'s return value.

    B4 / audit K049: exit 2 when the run could not do all its work and the command would otherwise
    report success. K049 was "recorded skips never change exit status or verdicts, while the code claims
    skipped work is reported" -- the claim is now true because the skip registers below drive the status.

    A count, listing or verdict produced over metadata the tool could not read is incomplete, and a
    script that branches on the exit status must be able to see that. Only a SUCCESS code is escalated:
    a usage error (1) and an existing finding (2) are left alone.
    """
    # S1 (RC2): `_FINDINGS` is the sink every new finding goes to, so this list stops growing. The six
    # named registers are the pre-RC2 ones, kept because they are gate-verified; `_SUPB_FELL_BACK` was
    # NOT among them, which is why a zeroed primary superblock exited 2 from `summary` and 0 from
    # `files` and `integrity` (B7). An enumeration is what made that possible -- a sink is not.
    try:
        if rc == 0 and any(_escalation_registers()):                                    # N360: one list
            return 2
    except NameError:
        # A register that does not exist is a programming error in THIS function, not a data condition;
        # it must not be swallowed into a clean exit. Anything else propagates.
        raise
    return rc


def _escalation_texts():
    """N347: the findings recorded in this run that `rc_escalate` escalates on, as text, for a command whose own result
    is a success while the run recorded a finding about the volume (`verify-bundle`: the bundle is whole, and reading
    its bootstrap structures recorded a finding -- N363: only those, not the redundancy checks). It decides nothing --
    the exit code stays rc_escalate's; a caller asks rc_escalate(0) whether there is anything to name, and names a
    generic finding if this list misses a register."""
    out = []

    def add(t):
        if t and t not in out:
            out.append(t)
    for t in _CHKP_STALE:
        add(t)
    for _k, t in _FINDINGS:
        add(t)
    # N426: decision 27.1's fallback (no copy valid, the first signed backup read: `none_valid`, B15) is said by its
    # `_SUPB_NONE_VERIFIES` finding above; tested on the view's own record -- the run's list also holds earlier views'
    if _SUPB_FELL_BACK and not _SUPB_FELL_BACK.get("none_valid"):
        add(_supb_fell_back_text(_SUPB_FELL_BACK))
    if _walk_damage_count():
        add("%d metadata page(s) could not be read" % _walk_damage_pages())          # N368: distinct pages
    if _SKIP_FINDING:
        add("work was skipped and is not reflected in the output (%s)" % ", ".join(sorted(set(_SKIP_FINDING))))
    for t in list(_VERSION_CONTRADICTED) + list(_REDUNDANCY_FINDING):
        add(str(t))
    if _JOURNAL_TAIL_DESTROYED:
        add("the change journal's records end before a USN that a file on this volume still points at (journal "
            "tail missing)")
    if not out and any(_escalation_registers()):
        add("a finding was recorded in a register this list does not word")         # N360: never a bare PASS
    return out


# The name before 1.13.2. Kept so a caller written against it keeps working; the call-site lint accepts
# only `rc_escalate`, so no tool site may use this one.
_escalate_rc = rc_escalate


# N194 (1.14.0): the errors only a WRITE gives -- a full disk, a file-size limit, a read-only output, a quota
_WRITE_ERRNOS = tuple(getattr(errno, n) for n in ("EFBIG", "ENOSPC", "EROFS", "EDQUOT") if hasattr(errno, n))


def _oserror_text(e, image):
    """N194 (1.14.0): an OSError that ended a command, in words that name what failed. 1.13.1 said "cannot read image"
    for every one, also for a write to a read-only output directory (Errno 13) or past a file-size limit (Errno 27):
    the message blamed the evidence image for a problem with the output. A write-only errno, or a file named in the
    error that is not the image, is said as such."""
    fn = getattr(e, "filename", None)
    if e.errno in _WRITE_ERRNOS:
        return "cannot write the output%s: %s" % (" (%s)" % fn if fn else "", e.strerror or e)
    if fn and os.path.abspath(str(fn)) != os.path.abspath(image):
        return "%s: %s (not the image)" % (fn, e.strerror or e)
    return "cannot read image: %s" % e


def _output_goes_elsewhere(words):
    """N538 / decision 56 (1.14.0): whether a run's output goes to a FILE or a directory, read from its command line: the
    word `export`; `-o` / `--output` / `--extract` with a value other than `-`; `--csv` / `--json` / `--jsonl` /
    `--body` followed by a FILE (`_extract_output_fmt`'s reading). Then stdout carries only messages. A word read as a
    FILE that is not one only lets a run whose stdout reader closed the pipe finish instead of stopping."""
    ws = list(words)
    for i, w in enumerate(ws):
        nxt = ws[i + 1] if i + 1 < len(ws) else None
        if w == "export":
            return True
        if w in ("-o", "--output", "--extract") and nxt not in (None, "-"):
            return True
        if w in ("--csv", "--json", "--jsonl", "--body") and nxt is not None and nxt != "-" and not nxt.startswith("-"):
            return True
    return False


class _PipeGuard(object):
    """N538 / decision 56 (1.14.0; the maintainer, 2026-11-15): a standard stream whose reader may close the pipe. A
    write or flush that meets a closed pipe (`BrokenPipeError`) when `silence()` holds -- always for stderr; for stdout
    once the run's output goes to a FILE or a directory (`_OUTPUT_ELSEWHERE`) -- points the descriptor at devnull and
    drops the text: the pipe carried only messages, and the run goes on to write its output. Otherwise the error goes up
    and the run stops: the pipe carried the output (`__main__`: the exit code of what the run recorded). 1.14.0-dev
    stopped every run at the first line written after the close -- `files --csv FILE 2>&1 | head -1` never wrote FILE --
    and a closed stderr failed at the interpreter's exit (exit 120). Writes through `.buffer` (machine output on stdout,
    `extract` to stdout) are not wrapped: a closed pipe there stops the run."""

    def __init__(self, stream, fd, silence):
        self._s, self._fd, self._silence, self._gone = stream, fd, silence, False

    def _drop(self):
        self._gone = True
        try:
            nul = os.open(os.devnull, os.O_WRONLY)
            os.dup2(nul, self._fd)
            os.close(nul)
        except OSError:
            pass
        try:
            self._s.flush()        # what the failed write left in the buffer goes to devnull
        except (OSError, ValueError):
            pass

    def write(self, text):
        if self._gone:
            return len(text)
        try:
            return self._s.write(text)
        except BrokenPipeError:
            if not self._silence():
                raise
            self._drop()
            return len(text)

    def flush(self):
        if self._gone:
            return
        try:
            self._s.flush()
        except BrokenPipeError:
            if not self._silence():
                raise
            self._drop()

    def __getattr__(self, name):
        return getattr(self._s, name)


def _install_pipe_guards(words):
    """N538 / decision 56: `_PipeGuard` on stdout and stderr, from both tools' `__main__` (`words` = the command line)."""
    if _output_goes_elsewhere(words):
        _OUTPUT_ELSEWHERE[:] = [True]
    try:
        fo, fe = sys.stdout.fileno(), sys.stderr.fileno()
    except (AttributeError, OSError, ValueError):
        return              # a stream without a descriptor (an embedding host): left as it is
    sys.stdout = _PipeGuard(sys.stdout, fo, lambda: bool(_OUTPUT_ELSEWHERE))
    sys.stderr = _PipeGuard(sys.stderr, fe, lambda: True)


def _quiet_closed_pipe():
    """A downstream reader closed the pipe early (e.g. `| head`, or `| more` then `q`). Redirect stdout to devnull so the
    interpreter's flush-on-exit does not raise a second BrokenPipeError + traceback. N171: forefst.py's and
    refsanalysis.py's __main__ both call it, so `refsanalysis <image> forefst <cmd>` ends on a closed pipe as
    `forefst.py <cmd>` does (no traceback, exit 0); the passthrough died with a BrokenPipeError traceback, exit 1."""
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except Exception:
        pass


def _flush_stdout():
    """Flush stdout. Returns None, or the OSError of a failed flush -- after pointing stdout at devnull, so that the
    interpreter's own flush at exit cannot fail a second time on the bytes still buffered (it then prints 'Exception
    ignored' and exits 120 over the exit code given). A closed pipe is N171's case; a stdout the command closed itself
    (`files`' CSV writer) has nothing left to flush."""
    try:
        if not sys.stdout.closed:
            sys.stdout.flush()
    except BrokenPipeError:
        _quiet_closed_pipe()
    except OSError as e:
        _quiet_closed_pipe()
        return e
    except ValueError:
        pass
    return None


def _exit_flushed(code, prog):
    """Final check F2 (1.14.0): flush stdout before the exit, inside the handlers. A text output small enough to stay in
    the buffer (`summary > /dev/full`, a full disk) failed only in the interpreter's flush at exit: forefst exited 0
    with nothing written, refsanalysis's `files` with an 'Exception ignored' trace and exit 120. A write failure here
    ends as one during the command does (N194: the error line, exit 1); a reader that closed the pipe as N171's,
    keeping the command's own exit code."""
    e = _flush_stdout()
    if e is not None:
        print(f"{prog}: error: {_oserror_text(e, sys.argv[1] if len(sys.argv) > 1 else '')}", file=sys.stderr)
        sys.exit(1)
    sys.exit(rc_escalate(code))     # THE exit rule (A11); the callers' code is escalated already: a second pass is a no-op


if __name__ == "__main__":
    _install_pipe_guards(sys.argv[1:])                  # N538 / decision 56
    try:
        _main_rc = main()
        _exit_code = rc_escalate(0 if _main_rc is None else _main_rc)
    except SystemExit as _se:
        # A message (a str code) is left alone by rc_escalate, which escalates only a success code.
        _exit_code = rc_escalate(0 if _se.code is None else _se.code)
    except BrokenPipeError:
        # N171; N538 / decision 56 (1.14.0): the reader closed the pipe that carries the output (`| head`): stop quietly,
        # with the exit code of what the run recorded before it -- 2 for a finding or a skip, else 0 (it was 0 always)
        _quiet_closed_pipe()
        sys.exit(rc_escalate(0))
    except OSError as _oe:
        # review S5: the native commands (files / summary / search / details) end a write failure as the dispatched
        # ones do (N194: the error line, exit 1), not with a traceback
        print(f"{PROG}: error: {_oserror_text(_oe, sys.argv[1] if len(sys.argv) > 1 else '')}", file=sys.stderr)
        _flush_stdout()             # final check F2: the text already printed, or stdout pointed at devnull
        sys.exit(1)
    except KeyboardInterrupt:
        sys.exit(130)
    _exit_flushed(_exit_code, PROG)
